//! # ⭐ `#110` 的两条**端到端基线**是改动前实测
//!
//! 对象 ＝ 一份单轨工程（一个 `key=60` 的音符）经**产品路径**
//! （`EngineSnapshot::from_project` → `with_sfz` → `EngineRuntime::process_quantum`）
//! 渲染 **16 量子 ＝ 2048 帧**的输出（左后右，FNV-1a 64 逐位）：
//!
//! | 夹具 | 帧数 | 非零样本 | 峰值 | 指纹 |
//! | :--- | :--- | :--- | :--- | :--- |
//! | 区域**不带** `<control>`（可闻） | 2048 | 4030 | 0.70710677 | `0xec4ca6ac0fe2b1e9` |
//! | 区域**带**`<control>set_cc1=64`（当时被静默忽略） | 2048 | 0 | 0 | `0x9c1bda7f8c872325` |
//!
//! ⭐ 第二行就是本单要闭合的缺口；⭐ 第一行是**保命不变量**的基线（S87）。两条都由本线在
//! **改动任何源码之前**于 base `4a6b862c`、`git status --porcelain` 为空时用一次性探针
//! 测得（探针随后删除，见本文件的交付报告）。同理，它们不是规范常数 ⇒ 同平台硬红、
//! 异平台如实跳过（[`check_fingerprint`]）。
//!
//! # S5 的指纹是**接线前**的实测值
//!
//! 三个 u64 由本线在**改动任何源码之前**于 HEAD `3ad1bda7`（`aarch64/macos`、
//! 同一个夹具、同一条产品路径）测得：
//!
//! | 夹具 | 帧数 | 非零样本 | 峰值 | 指纹（FNV-1a 64，逐位） |
//! | :--- | :--- | :--- | :--- | :--- |
//! | 两个音符、无设备链 | 2560 | 5052 | 0.5478619 | `0x71dca4dc55b44df5` |
//! | 两个音符、`cutoff_hz = 800` / `resonance = 0.3` | 2560 | 5052 | 0.32756245 | `0x6eee378072730521` |
//!
//! ⚠ 这两个字面值**不是**规范常数，而是本机 libm/LLVM 的一次实现读数：它们的作用是
//! **跨提交对账**（接线前 vs 接线后同一个夹具给出同一个数），⛔ 不是"跨架构必须相等"
//! （跨架构对账是 `ARCH-DET-002` 的独立票）。形态照
//! `tests/drums_instrument.rs` 的 `check_fingerprint_on`：**同平台硬红、异平台如实跳过
//! 并点名原因**（跳过 **不是** 通过）。

