use yeban_sfz::CcGate;

/// ⭐ 步 2 **实测**（本机 `aarch64/macos`、HEAD `6ae70ef8` 的 `prepare` 广播路径）：
/// span-free 夹具 [`TWO_MATCH_ONE_MISS`] 在 `(60, 127)`、512 帧上的 FNV-1a 指纹。
/// ⚠ 它的作用是**跨提交对账**（步 2 vs 步 3 的同一条广播路径逐位不变），⛔ 不是规范常数。
const BROADCAST_STEP2_FINGERPRINT: u64 = 0xa933_ddab_286b_df5e;

/// ⭐ **改动前实测**（任务 `#91` 的 §4.4）：既有夹具 [`TWO_MATCH_ONE_MISS`]（**不带任何
/// `loop_*`**）经 `render_track` **实时路径**渲染 512 帧 @ `(60,127)` 的 FNV-1a 指纹。
///
/// 测法与测后处置见 [`s33_a_fixture_without_any_loop_fields_renders_bit_identically`]
/// 的文档：在 HEAD `5ac570eb`、**工作树干净**时用一次性探针测得，探针随后删除。
/// ⚠ 与 [`BROADCAST_STEP2_FINGERPRINT`]（摊平路径）同值 —— 两条独立来路的交叉印证
/// （`S1` 曾把"引擎逐样本 == 摊平逐样本"钉成 `max|Δ| = 0`）。
const NO_LOOP_FIXTURE_FINGERPRINT: u64 = 0xa933_ddab_286b_df5e;

/// FNV-1a 64（逐位；把每个 `f32` 的 4 个字节按小端卷进哈希）。
fn fnv1a_64(samples: &[f32]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for sample in samples {
        for byte in sample.to_bits().to_le_bytes() {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }
    hash
}

/// S5 夹具：两个音符（1 tick = 25 样本）。⭐ 本夹具与**接线前**测指纹时**一字不差**。
const SFZ_NOTES: [NoteSpec; 2] = [
    NoteSpec::at(0, 480, 60, 100),
    NoteSpec::at(960, 480, 64, 90),
];

/// S6（端到端）夹具：两个起音都落在 20 个量子的窗口内（⇒ 两条区域都会发声）。
const E2E_NOTES: [NoteSpec; 2] = [NoteSpec::at(0, 480, 60, 100), NoteSpec::at(48, 480, 64, 90)];

/// S6 的 SFZ：两条区域各管一个音高（⇒ 两个起音各触发一条）。
const E2E_SFZ: &str = "<region> sample=a.wav key=60 pitch_keycenter=60\n\
                       <region> sample=b.wav key=64 pitch_keycenter=60 volume=-6\n";

/// S5 夹具的渲染量子数（20 × 128 = 2560 帧，覆盖两个起音）。
const SFZ_QUANTA: usize = 20;

/// **接线前**实测：无设备链（见模块头）。
const BASELINE_PLAIN: u64 = 8_204_613_887_399_841_269;
/// **接线前**实测：`cutoff_hz = 800` / `resonance = 0.3`（见模块头）。
const BASELINE_TUNED: u64 = 7_993_387_413_444_691_233;

/// 指纹的**测量平台**（`[ARCH-DET-001]` 的 L1 只承诺"相同 OS ＋ CPU 架构 ＋
/// 纯 Rust libm"下的逐位一致）。
const MEASURED_PLATFORM: &str = "aarch64/macos";

/// 本机（**编译期事实**）是否就是那个测量平台。
const ON_MEASURED_PLATFORM: bool = cfg!(target_arch = "aarch64") && cfg!(target_os = "macos");

/// 同平台**硬红** / 异平台**如实跳过并点名原因**（跳过 **不是** 通过）。
///
/// 形态照 `tests/drums_instrument.rs` 的 `check_fingerprint_on`（那条判据的
/// 同一条理由：字面值是某台机器上的实现读数，不是规范常数）。
fn check_fingerprint(label: &str, actual: u64, expected: u64) -> bool {
    if ON_MEASURED_PLATFORM {
        assert_eq!(
            actual, expected,
            "{label}: 同平台（本机 == {MEASURED_PLATFORM}）⇒ 指纹必须逐位等于**接线前**\
             实测值 0x{expected:016x}（实得 0x{actual:016x}）；不同就是真缺陷"
        );
        return true;
    }
    println!(
        "[engine-sfz/S5] SKIP（未判定，不是通过）：{label} 的字面值 0x{expected:016x} \
         实测于 {MEASURED_PLATFORM}；跨架构的位级差异属 L2（max|Δ| < 1e-6），不是本判据的失败"
    );
    false
}

/// 步 1 的"多匹配"夹具：**两条 `key=60` 的区域都匹配**（第二条另有 `volume=-6`），
/// 外加一条 `key=72` 的不命中区域（反向对照）。
const TWO_MATCH_ONE_MISS: &str = "<region> sample=a.wav key=60 pitch_keycenter=60\n\
                                  <region> sample=b.wav key=60 pitch_keycenter=60 volume=-6\n\
                                  <region> sample=c.wav key=72 pitch_keycenter=60\n";

/// 摊平用的内存样本长度（帧）：极短 ⇒ 一块 512 帧内就播完。
const SAMPLE_FRAMES: usize = 480;

/// 块长（帧）：**比样本长** ⇒ 一块之内就能观察到"样本自然结束 ⇒ 退休"。
const BLOCK: usize = 512;

/// ⭐ S1 第二条腿用的**量子长**（帧；= `block::DEFAULT_BLOCK_FRAMES`）。
const QUANTUM: usize = 128;

/// ⭐ S1 第二条腿用的**量子数**：`8 × 128 = 1024` 帧 > 样本 480 帧 ⇒ 真的跨块。
const MULTI_BLOCKS: usize = 8;

/// 摊平一条 SFZ 文本（控制侧；**允许分配**）。
fn prepare(text: &str) -> PreparedSfz {
    let sfz = SfzInstrument::load(text.to_owned(), &Default::default()).expect("SFZ 必须解析成功");
    let sample = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    PreparedSfz::prepare(&sfz, &sample, 48_000.0).expect("摊平必须成功")
}

/// 造一台已经武装好 `track` 的合成器（48 kHz）。
fn engine_with_track(track: EntityId) -> SynthEngine {
    let mut engine = SynthEngine::new(48_000);
    engine.begin_snapshot(48_000, &[track], [], []);
    engine
}

/// 两个声道的位模式（"逐位相同"的判定量）。
fn bits(samples: &[f32]) -> Vec<u32> {
    samples.iter().map(|sample| sample.to_bits()).collect()
}

/// S1：**引擎声部路径与摊平表逐样本差 ＝ 0**，且两侧都真的出声。
///
/// ⚠ 这条 ==0 的**强度**在于接线（触发哪些区域／速率／增益／终点），⛔ 不在于"两段
/// 逐样本循环"：那一段是**同一个函数**（`sfz_instrument::mix_span_into`），
/// 因为本仓的机械纪律是"全仓不许两份实现"（两份在 binary32 下无法维持逐位相同）。
#[test]
fn s1_engine_voices_match_the_flattened_table_sample_by_sample() {
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    assert_eq!(prepared.region_count(), 3, "三条区域都要摊平进来");
    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    // 力度 127（`support::scheduled` 的口径）⇒ 与下面摊平表的 `(60, 127)` 同参数。
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);

    let mut engine_out = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut engine_out);

    let mut flat = vec![0.0f32; BLOCK];
    let flat_written = prepared.render_block_into(60, 127, &mut flat);

    let max_abs_diff = engine_out
        .iter()
        .zip(flat.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max);
    println!(
        "[engine-sfz/S1] 逐样本最大绝对差 = {max_abs_diff:e}；摊平写入 {flat_written} 帧；\
         引擎非零 = {}；摊平非零 = {}；引擎活声部 = {:?}；丢弃 = {}",
        engine_out.iter().filter(|s| **s != 0.0).count(),
        flat.iter().filter(|s| **s != 0.0).count(),
        engine.sfz_active_voices(track),
        engine.sfz_voice_drops(),
    );
    assert_eq!(
        max_abs_diff, 0.0,
        "⭐ 引擎声部路径必须与 `PreparedSfz::render_block_into` **逐样本相同**\
         （两条 `key=60` 的区域都匹配 ⇒ 两侧都必须叠加两条）"
    );
    // 反向对照：两侧都必须真的出声（⛔ 不能"两边都全零"也算一致）。
    assert!(
        engine_out.iter().any(|s| *s != 0.0),
        "引擎侧必须真的出声（否则上面的等号是空转）"
    );
    assert!(flat.iter().any(|s| *s != 0.0), "摊平侧必须真的出声");

    // --- ⭐ S1 第二条腿（任务单 `#66` 补做 2）：**逐块拼接的整音符** ---
    //
    // 为什么必须补（注入实测）：上面那条腿只跨**一块**（512 帧 ≥ 样本 480 帧）
    // ⇒ `written == remaining` 永不发生 ⇒ "声部是否跨量子延续"**没有被量到**。
    // 实测：把 `written < remaining` 改成 `<=`（提前退休）时上一条腿**逐位不变**，
    // 只有把尺度**跨过"样本长"**才看得见 —— 那种注入会让输出腰斩
    // （端到端非零 1716 → 508、㉙ 总能量 2999.164 → 780.073）而**无人知**。
    //
    // 判定量：8 个 128 帧量子（= 1024 帧）拼起来的整段，与摊平表**一次性 1024 帧**
    // 调用的**逐样本最大绝对差**；外加"真的有 ≥ 2 个块出声"（跨块见证，⛔ 防空转）。
    let mut engine_multi = engine_with_track(track);
    let mut joined = vec![0.0f32; QUANTUM * MULTI_BLOCKS];
    let mut blocks_with_sound = 0usize;
    for block in 0..MULTI_BLOCKS {
        let mut out = vec![0.0f32; QUANTUM];
        engine_multi.render_track(track, Some(&schedule), Some(&prepared), &mut out);
        if out.iter().any(|s| *s != 0.0) {
            blocks_with_sound += 1;
        }
        joined[block * QUANTUM..(block + 1) * QUANTUM].copy_from_slice(&out);
        engine_multi.advance(QUANTUM);
    }
    let mut flat_joined = vec![0.0f32; QUANTUM * MULTI_BLOCKS];
    let flat_joined_written = prepared.render_block_into(60, 127, &mut flat_joined);
    let joined_diff = joined
        .iter()
        .zip(flat_joined.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max);
    println!(
        "[engine-sfz/S1b] 逐块拼接（{MULTI_BLOCKS} × {QUANTUM} = {} 帧）：逐样本最大绝对差 = \
         {joined_diff:e}；有声块 = {blocks_with_sound}；摊平一次性写入 {flat_joined_written} 帧；\
         引擎非零 = {}；摊平非零 = {}",
        QUANTUM * MULTI_BLOCKS,
        joined.iter().filter(|s| **s != 0.0).count(),
        flat_joined.iter().filter(|s| **s != 0.0).count(),
    );
    assert_eq!(
        joined_diff, 0.0,
        "⭐ 逐块拼接的整音符必须与摊平表的一次性调用**逐样本相同**\
         （声部跨量子延续、且样本只播**一遍**）"
    );
    assert!(
        blocks_with_sound >= 2,
        "⭐ 夹具必须真的**跨块**（有声块 = {blocks_with_sound}）—— 否则这条腿量不到'跨量子延续'\
         （进程内自检：注入'提前退休'时必须在这里变红）"
    );
    assert!(
        flat_joined_written > 0,
        "摊平表的整段调用必须真的写入（否则等号是空转）"
    );
}

/// S2：**终点口径 ＝ 样本自然结束**（⛔ 无包络）。
///
/// 一块 512 帧 > 样本 480 帧 ⇒ 这一块内源采样就播完了：声部**退休**
/// （`active == 0`），下一块**逐位静音**。
///
/// 反向对照（关键）：摊平表的 `render_block_into` 是**无状态**的，它每一块都从源
/// 位置 `0.0` 重播 ⇒ 第二块**不是**静音。这条对照把"第二块静音"从"整条链没接线"
/// 里区分出来。
#[test]
fn s2_the_voice_retires_when_the_sample_runs_out() {
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);

    let mut first = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut first);
    let after_first = engine.sfz_active_voices(track);

    engine.advance(BLOCK);
    let mut second = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut second);

    let mut flat_again = vec![0.0f32; BLOCK];
    let flat_written = prepared.render_block_into(60, 127, &mut flat_again);

    println!(
        "[engine-sfz/S2] 第一块非零 = {}；播完后活声部 = {after_first:?}；第二块非零 = {}；\
         摊平表第二块写入 = {flat_written}（非零 = {}）",
        first.iter().filter(|s| **s != 0.0).count(),
        second.iter().filter(|s| **s != 0.0).count(),
        flat_again.iter().filter(|s| **s != 0.0).count(),
    );
    assert!(first.iter().any(|s| *s != 0.0), "第一块必须出声");
    assert_eq!(
        after_first,
        Some(0),
        "⭐ 样本播完 ⇒ 声部必须退休（`active == 0`）；`min(end_sample, 样本播完)` 的\
         诚实占位就是这一条"
    );
    assert!(
        second.iter().all(|s| *s == 0.0),
        "退休之后下一块必须**逐位静音**"
    );
    assert!(
        flat_again.iter().any(|s| *s != 0.0),
        "反向对照：摊平表是无状态的一次性调用 ⇒ 第二块**仍然出声**（否则'第二块静音'\
         可能只是整条链没接线）"
    );
}

/// S3：⭐ **显式 `span` 终点两侧同口径**（步 3 把离线/摊平侧补齐 ⇒ sfz-needs-4 **闭合**）。
///
/// `end=200`（含端点）⇒ 半开区间 `[0, 201)` ⇒ 三条路都写到 `floor(pos) + 1 >= 201`
/// 为止 ＝ **200 帧**；摊平表**不再**继续到样本末尾（步 2 时它继续 ⇒ 那是已登记的口径分叉）。
///
/// 反向对照：把 `end` 改成 `400` ⇒ **写入帧数变**（证明不是"恒定截断在 200"这种假口径）。
#[test]
fn s3_an_explicit_span_end_stops_the_voice_at_the_same_frame_on_both_sides() {
    let prepared = prepare("<region> sample=a.wav key=60 pitch_keycenter=60 end=200\n");
    let span = prepared.regions()[0].span().expect("span 必须已摊平");
    assert_eq!(
        prepared.regions()[0].source_end(SAMPLE_FRAMES),
        Some(201),
        "`end=200`（含端点）⇒ 半开 [0, 201)"
    );
    assert_eq!(span.end, Some(201), "摊平表的口径（步 1）");

    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);
    let mut engine_out = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut engine_out);

    let mut flat = vec![0.0f32; BLOCK];
    let flat_frames = prepared.render_block_into(60, 127, &mut flat);

    let engine_written = engine_out.iter().filter(|s| **s != 0.0).count();
    let flat_written = flat.iter().filter(|s| **s != 0.0).count();
    // ⭐ 判定量是**逐样本**而不是"数非零"：正弦在 0 相位处就是 0.0（夹具的第 0 个样本），
    // 数非零会把"写了 200 帧"读成 199。
    let max_abs_diff = engine_out
        .iter()
        .zip(flat.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0f32, f32::max);
    println!(
        "[engine-sfz/S3] 引擎非零 = {engine_written}；摊平非零 = {flat_written}；\
         摊平写入帧数 = {flat_frames}；整块逐样本最大绝对差 = {max_abs_diff:e}"
    );
    assert_eq!(
        max_abs_diff, 0.0,
        "⭐ 步 3 之后：`span` 起点/终点两侧**逐样本相同**（不再是'只覆盖触发量子'）"
    );
    assert_eq!(
        flat_frames, 200,
        "⭐ `end=200`（半开 [0,201)）⇒ 摊平表必须也停在 **200** 帧（线性插值要两个样本）"
    );
    assert!(
        engine_out[..200].iter().any(|s| *s != 0.0),
        "两侧在 span 内必须真的出声"
    );
    assert!(
        engine_out[200..].iter().all(|s| *s == 0.0),
        "⭐ 引擎必须在 span 终点（第 200 帧）停：之后**一帧不出**"
    );
    assert!(
        flat[200..].iter().all(|s| *s == 0.0),
        "⭐ 摊平表**也**必须停在同一帧（步 2 时它继续出声 ⇒ 口径分叉已闭合）"
    );

    // --- 反向对照：改 `end` ⇒ 帧数必须跟着变（⛔ 挡"恒定截断"的假口径） ---
    let longer = prepare("<region> sample=a.wav key=60 pitch_keycenter=60 end=400\n");
    let mut longer_out = vec![0.0f32; BLOCK];
    let longer_frames = longer.render_block_into(60, 127, &mut longer_out);
    println!("[engine-sfz/S3] 反向对照 `end=400`：摊平写入帧数 = {longer_frames}");
    assert_eq!(longer_frames, 400, "`end=400` ⇒ 写 400 帧（半开 [0,401)）");
    assert_ne!(
        longer_frames, flat_frames,
        "⭐ 两个不同的 `end` 必须给出不同的写入帧数（否则上面的 200 可能是常数）"
    );
}

/// S4：⭐ `end=-1`（`SampleEnd::Silent`）的区域**不产生采样输出**（三条路同口径）。
///
/// 引擎⛔ 不建声部、一帧不写；⭐ **摊平表也一帧不写**（步 3 补齐；步 2 时它仍出声 —— 那是
/// 已登记的口径分叉）。
///
/// 反向对照（关键）：去掉 `end=-1` 之后**同一份夹具**必须出声 ⇒ 上面的静音不是"夹具坏了"。
#[test]
fn s4_a_silent_span_never_gets_a_voice_nor_any_sample() {
    let prepared = prepare("<region> sample=a.wav key=60 pitch_keycenter=60 end=-1\n");
    assert_eq!(
        prepared.regions()[0].span(),
        None,
        "`end=-1` ⇒ `SampleEnd::Silent` ⇒ 不产生采样输出"
    );
    assert_eq!(prepared.regions()[0].source_end(SAMPLE_FRAMES), None);
    assert_eq!(prepared.regions()[0].source_start(SAMPLE_FRAMES), None);

    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);
    let mut engine_out = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut engine_out);

    let mut flat = vec![0.0f32; BLOCK];
    let flat_frames = prepared.render_block_into(60, 127, &mut flat);

    println!(
        "[engine-sfz/S4] 引擎非零 = {}；活声部 = {:?}；摊平非零 = {}；摊平写入 = {flat_frames}",
        engine_out.iter().filter(|s| **s != 0.0).count(),
        engine.sfz_active_voices(track),
        flat.iter().filter(|s| **s != 0.0).count(),
    );
    assert!(
        engine_out.iter().all(|s| *s == 0.0),
        "⭐ `end=-1` 的区域不得产生任何样本"
    );
    assert_eq!(
        engine.sfz_active_voices(track),
        Some(0),
        "⭐ 一条声部都不该建出来"
    );
    assert!(
        flat.iter().all(|s| *s == 0.0),
        "⭐ 摊平表**也**必须静音（步 3：三条路共用 `reduce_span` 的 `None` 口径）"
    );
    assert_eq!(flat_frames, 0, "摊平表写入帧数必须是 0");

    // --- 反向对照：去掉 `end=-1` ⇒ 同一夹具必须出声 ---
    let normal = prepare("<region> sample=a.wav key=60 pitch_keycenter=60\n");
    let mut normal_out = vec![0.0f32; BLOCK];
    let normal_frames = normal.render_block_into(60, 127, &mut normal_out);
    println!("[engine-sfz/S4] 反向对照（无 `end=-1`）：摊平写入帧数 = {normal_frames}");
    assert!(
        normal_frames > 0 && normal_out.iter().any(|s| *s != 0.0),
        "⭐ 反向对照必须出声（否则上面的静音可能只是夹具坏了）"
    );
}

/// S5：⭐ **反向对照（关键）**：**不给 `sfz`** 时端到端输出与**接线前**逐位相同。
///
/// 两条臂（无设备链 / 带音色）的指纹都必须等于**改动源码之前**实测的字面值。
/// 同平台硬红、异平台如实跳过（见 [`check_fingerprint`]）。
#[test]
fn s5_without_sfz_the_output_is_bit_identical_to_before_the_wiring() {
    let plain = note_project(&SFZ_NOTES);
    let rendered = render(&plain.project, SFZ_QUANTA);
    println!(
        "[engine-sfz/S5] 无设备链: 帧={} 非零={} 峰值={} 指纹={} (0x{:016x})",
        rendered.frames(),
        rendered.nonzero(),
        rendered.peak(),
        rendered.fingerprint(),
        rendered.fingerprint(),
    );
    assert!(rendered.nonzero() > 0, "夹具必须真的出声（否则等号是空转）");
    let plain_checked = check_fingerprint("无设备链", rendered.fingerprint(), BASELINE_PLAIN);

    let tuned = tuned_project(&SFZ_NOTES, MixSpec::tone(800.0, 0.3));
    let rendered_tuned = render(&tuned.project, SFZ_QUANTA);
    println!(
        "[engine-sfz/S5] 音色(800, 0.3): 帧={} 非零={} 峰值={} 指纹={} (0x{:016x})",
        rendered_tuned.frames(),
        rendered_tuned.nonzero(),
        rendered_tuned.peak(),
        rendered_tuned.fingerprint(),
        rendered_tuned.fingerprint(),
    );
    let tuned_checked = check_fingerprint(
        "音色(800, 0.3)",
        rendered_tuned.fingerprint(),
        BASELINE_TUNED,
    );

    // ⚠ 两条臂必须在**同一平台判定**下：不能一条硬红一条跳过（那说明平台判定漂了）。
    assert_eq!(
        plain_checked, tuned_checked,
        "两条臂的平台判定必须一致（否则本判据的读数不可比）"
    );
}

/// S6：`with_sfz` 是**唯一**的绑定入口（模型⛔ 不给），且端到端真的非静音、
/// 真的换了音源（指纹与"不给 SFZ"不同）。
#[test]
fn s6_the_snapshot_only_carries_the_sfz_a_caller_injected_and_it_is_audible() {
    let fixture = note_project(&E2E_NOTES);
    let track = fixture.track;

    // ① `from_project` **不**绑 SFZ（模型层今天没有轨↔SFZ 绑定）。
    let bare = EngineSnapshot::from_project(&fixture.project, 1).expect("快照");
    assert!(
        bare.sfz().is_empty(),
        "⛔ `from_project` 不得凭空绑一份 SFZ（模型语义不由引擎发明）"
    );
    assert!(bare.sfz_plan(&track).is_none());

    // ② 同一份快照 + 显式注入 ⇒ 表里正好一条，且只有那条轨。
    let plan = SfzPlan::prepare(
        &SfzInstrument::load(E2E_SFZ.to_owned(), &Default::default()).expect("SFZ 必须解析成功"),
        &InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES),
        48_000.0,
    )
    .expect("摊平必须成功");
    println!(
        "[engine-sfz/S6] 摊平表：区域 {}、内存 {} 字节",
        plan.region_count(),
        plan.memory_bytes()
    );
    let armed = EngineSnapshot::from_project(&fixture.project, 1)
        .expect("快照")
        .with_sfz(track, plan);
    assert_eq!(armed.sfz().len(), 1, "注入一次 ⇒ 表里一条");
    assert!(armed.sfz_plan(&track).is_some(), "注入的那条轨必须在表里");
    assert!(
        armed.sfz_plan(&fixture.master).is_none(),
        "⛔ 母线上不该有 SFZ"
    );

    // ③ 端到端（产品路径：快照槽 → 渲染量子 → 声相 → 母线限制器）：
    //    SFZ 臂必须非静音，且指纹与"不给 SFZ"的**不同**（真的换了音源）。
    let with_sfz = render_snapshot(armed, SFZ_QUANTA);
    let without = render(&fixture.project, SFZ_QUANTA);
    println!(
        "[engine-sfz/S6] SFZ 臂: 非零={} 峰值={} 指纹=0x{:016x}；对照臂: 非零={} 峰值={} 指纹=0x{:016x}",
        with_sfz.nonzero(),
        with_sfz.peak(),
        with_sfz.fingerprint(),
        without.nonzero(),
        without.peak(),
        without.fingerprint(),
    );
    assert!(
        with_sfz.nonzero() > 0 && with_sfz.peak() > 0.0,
        "⭐ 端到端必须**非静音**（非零 = {}）",
        with_sfz.nonzero()
    );
    assert_ne!(
        with_sfz.fingerprint(),
        without.fingerprint(),
        "⭐ 注入 SFZ 之后指纹必须与对照臂不同（否则 SFZ 支路根本没接上）"
    );
}

/// S7：分派次序 ＝ **鼓机 ＞ SFZ ＞ 复音**（一条轨至多一件音源）。
///
/// ① 鼓机 ＋ SFZ 同轨 ⇒ 输出对"只有鼓机"**逐位相同**（SFZ 池被释放、⛔ 不叠加）；
/// ② 反向对照：同一份 SFZ 在没有鼓机的轨上**真的出声**（⇒ ① 的等号不是"两边都哑"）。
/// ③ "SFZ ＞ 复音"由 S1 覆盖：那台槽的复音合成器本来会出声，而 S1 的逐样本差为 0
///    ⇒ 复音**没有**被叠加进去。
#[test]
fn s7_drums_win_over_sfz_which_wins_over_polyphony() {
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let track = EntityId::new();
    // 键位映射里**包含** key 60 ⇒ 同一条音符在鼓机分支里也有鼓件可打。
    let device = DeviceDefinition {
        id: EntityId::new(),
        name: "Yeban Drums".to_owned(),
        kind: DeviceKind::InternalInstrument,
        bypassed: false,
        params: [
            ("kick_note", 60.0),
            ("snare_note", 38.0),
            ("closed_hat_note", 42.0),
            ("open_hat_note", 46.0),
            ("clap_note", 39.0),
        ]
        .iter()
        .map(|(name, value)| ParameterValue {
            name: (*name).to_owned(),
            value: *value,
            unit: None,
        })
        .collect(),
        latency_samples: 0,
    };
    let params = DrumsParams::from_devices(&[device]).expect("五个键位名写全 ⇒ 识别为鼓机");
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);

    let mut with_sfz = SynthEngine::new(48_000);
    let mut only_drums = SynthEngine::new(48_000);
    let mut only_sfz = SynthEngine::new(48_000);
    with_sfz.begin_snapshot(48_000, &[track], [], [(&track, &params)]);
    only_drums.begin_snapshot(48_000, &[track], [], [(&track, &params)]);
    only_sfz.begin_snapshot(48_000, &[track], [], []);

    let mut a = vec![0.0f32; 128];
    let mut b = vec![0.0f32; 128];
    let mut c = vec![0.0f32; 128];
    with_sfz.render_track(track, Some(&schedule), Some(&prepared), &mut a);
    only_drums.render_track(track, Some(&schedule), None, &mut b);
    only_sfz.render_track(track, Some(&schedule), Some(&prepared), &mut c);

    println!(
        "[engine-sfz/S7] 鼓机+SFZ 非零 = {}；只有鼓机 非零 = {}；只有 SFZ 非零 = {}；\
         鼓机臂的 SFZ 活声部 = {:?}",
        a.iter().filter(|s| **s != 0.0).count(),
        b.iter().filter(|s| **s != 0.0).count(),
        c.iter().filter(|s| **s != 0.0).count(),
        with_sfz.sfz_active_voices(track),
    );
    assert!(b.iter().any(|s| *s != 0.0), "鼓机臂必须真的出声");
    assert_eq!(
        bits(&a),
        bits(&b),
        "⭐ 鼓机 ＞ SFZ：同轨两件音源时，输出必须与'只有鼓机'**逐位相同**\
         （⛔ SFZ 不得叠加进去）"
    );
    assert_eq!(
        with_sfz.sfz_active_voices(track),
        Some(0),
        "鼓机分支必须**释放** SFZ 池（⛔ 不留上一件音源的尾巴）"
    );
    assert!(
        c.iter().any(|s| *s != 0.0),
        "反向对照：没有鼓机的同一份 SFZ 必须真的出声（否则上面的等号可能只是两边都哑）"
    );
}

/// S8：池满（> [`SFZ_VOICES_PER_TRACK`] 条区域同时匹配）⇒ ⭐ **窃取**（⛔ 不是丢弃）。
///
/// # 判定量（`sfz-needs-2` 的落地）
///
/// * 17 条**全部匹配** ⇒ `created == 16`（窃取占的是**别人**的槽，⛔ 不计入"新建"）、
///   `stolen == 1`、`dropped == 0`（⭐ 池满不再是丢弃）；
/// * 33 条 ⇒ 挂起者还没轮到发声就被**再一次**换掉 ⇒ 那是**真丢弃**：
///   `stolen == 17` ＋ `dropped == 16`（⛔ 不静默 —— 这条腿保住"丢弃计数"的语义）；
/// * 反向对照：15 条（未满）⇒ `stolen == 0` ＋ `dropped == 0`。
///
/// ⚠ 本判据的**旧期望**是 `dropped == 1`（丢弃口径）；本单把它改成窃取口径
/// —— 注入"改回丢弃"时它当场变红（读数见提交报告）。
#[test]
fn s8_a_full_pool_steals_instead_of_silently_dropping_the_overflow() {
    let mut text = String::new();
    for _ in 0..=SFZ_VOICES_PER_TRACK {
        text.push_str("<region> sample=a.wav key=60 pitch_keycenter=60\n");
    }
    let prepared = prepare(&text);
    assert_eq!(
        prepared.region_count(),
        SFZ_VOICES_PER_TRACK + 1,
        "夹具必须是 16 + 1 条**全部匹配**的区域"
    );

    let mut pool = SfzVoicePool::empty();
    // ⭐ 轨增益门 = 1.0（单位）：本判据量的是**池容量**，⛔ 不掺轨增益。
    let created = pool.trigger_note(&prepared, 60, 100, 12_000, 1.0, None);
    println!(
        "[engine-sfz/S8] 17 条：建出声部 = {created}；活声部 = {}；窃取 = {}；真丢弃 = {}；挂起 = {}",
        pool.active_count(),
        pool.stolen(),
        pool.dropped(),
        pool.pending_count(),
    );
    assert_eq!(created, SFZ_VOICES_PER_TRACK, "池只能装 16 个空槽");
    assert_eq!(pool.active_count(), SFZ_VOICES_PER_TRACK);
    assert_eq!(
        pool.stolen(),
        1,
        "⭐ 第 17 条区域必须**窃取**一个槽（⛔ 不是丢弃）"
    );
    assert_eq!(pool.dropped(), 0, "⭐ 窃取**不是**丢弃");
    assert_eq!(pool.pending_count(), 1, "⭐ 新声部挂在 victim 的槽里等接管");

    // ⭐ 33 条：挂起者被**再一次**窃取换掉 ⇒ 真丢弃（计数仍在，⛔ 不静默）。
    let mut many = String::new();
    for _ in 0..(2 * SFZ_VOICES_PER_TRACK + 1) {
        many.push_str("<region> sample=a.wav key=60 pitch_keycenter=60\n");
    }
    let many_prepared = prepare(&many);
    let mut many_pool = SfzVoicePool::empty();
    let many_created = many_pool.trigger_note(&many_prepared, 60, 100, 12_000, 1.0, None);
    println!(
        "[engine-sfz/S8] 33 条：建出声部 = {many_created}；窃取 = {}；真丢弃 = {}；挂起 = {}",
        many_pool.stolen(),
        many_pool.dropped(),
        many_pool.pending_count(),
    );
    assert_eq!(many_created, SFZ_VOICES_PER_TRACK);
    assert_eq!(many_pool.active_count(), SFZ_VOICES_PER_TRACK);
    assert_eq!(
        many_pool.stolen(),
        17,
        "⭐ 33 条 ⇒ 17 次窃取（第 17..33 条各一次）"
    );
    assert_eq!(
        many_pool.dropped(),
        16,
        "⭐ 被换掉的挂起者（第 17..32 条）是真丢弃 ⇒ 必须计数（⛔ 不静默）"
    );

    // 反向对照：15 条区域时**不**该有窃取或丢弃（否则上面那些数可能是常数）。
    let mut under = String::new();
    for _ in 0..(SFZ_VOICES_PER_TRACK - 1) {
        under.push_str("<region> sample=a.wav key=60 pitch_keycenter=60\n");
    }
    let under_prepared = prepare(&under);
    let mut under_pool = SfzVoicePool::empty();
    assert_eq!(
        under_pool.trigger_note(&under_prepared, 60, 100, 12_000, 1.0, None),
        SFZ_VOICES_PER_TRACK - 1
    );
    assert_eq!(under_pool.dropped(), 0, "未满时不得计数");
    assert_eq!(under_pool.stolen(), 0, "未满时不得窃取");
}

/// S9：**尺寸照打** ＋ `EngineRuntime` 的 192 KiB 门槛（与
/// `tests/synth_rt_zero_alloc.rs:2570` 同一口径）。
///
/// 定长声部池的代价必须落在尺寸读数上：`SynthEngine` / `EngineRuntime` 都是
/// **按值搬进回调**的对象 ⇒ 这道门槛是"有没有把大件塞进实时对象"的机械防线。
#[test]
fn s9_sizes_are_printed_and_the_runtime_stays_under_192_kib() {
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    let cc_state = core::mem::size_of::<yeban_engine::cc_state::ControlChangeState>();
    println!(
        "[engine-sfz/S9] size_of: SfzVoice={voice} SfzVoicePool={pool} \
         SfzPlan={} PreparedSfz={} SynthEngine={} EngineSnapshot={} EngineRuntime={runtime} \
         ControlChangeState={cc_state} \
         （门槛 192 KiB = {}；余量 = {}）",
        core::mem::size_of::<SfzPlan>(),
        core::mem::size_of::<PreparedSfz>(),
        core::mem::size_of::<SynthEngine>(),
        core::mem::size_of::<EngineSnapshot>(),
        192 * 1024,
        192 * 1024 - runtime,
    );
    // ⚠ 钉住声部的**定长**形状：`SfzVoice` 只含 `f32`/`u8`/`bool`/`u16`/`u64`，
    // ⛔ 无指针、⛔ 无 `Vec`。
    // ⭐ 步 3 的代价：`sample_index: u16` 进了声部 ⇒ 32 B → **40 B**（对齐到 8）。
    // ⭐ **本单（`sfz-needs-2`）的代价**：池里多了 16 槽 ×（挂起声部 40 ＋ 淡出 16 ＋
    // 触发序号 8）＋ 挂起标志 16 ＋ 两个计数器（丢弃/窃取/序号舵）⇒ 池 648 → **1712**、
    // `SynthEngine` 91984 → **109152**、`EngineRuntime` 162832 → **180000**
    // （仍 < 192 KiB，余量 16608 字节）。
    // ⭐ **本单（循环接线 `#91`）的代价 ＝ 0 字节**：声部只多一个 `region_index: u16`
    // （循环窗口由**区域**拥有，见 [`SfzVoice::region_index`]），它落在**既有尾部填充**里
    // ⇒ `SfzVoice` 仍 **40 B**、池仍 **1712**、`EngineRuntime` 仍 **180000**（余量仍 16608）。
    // ⚠ 涨价的是**摊平表**：`PreparedRegion` 2624 → **2632 B**（+8；三个循环字段），
    // 它按**区域数**计（`S25` 的预算读数跟着走），⛔ 不进实时对象。
    // ⭐ **本单（`#107`：MIDI CC 进实时通路）的代价**：`EngineRuntime` 多一张**定长** CC 表
    // （`ControlChangeState` ＝ `[u8; 128]` ＋ 128 位"收到过"位图 ＝ **144 B**）
    // ⇒ `EngineRuntime` 180000 → **180144**（余量 16608 → **16464** ≥ 8192）；
    // ⛔ `SfzVoice` 仍 **40 B**（＋0）、⛔ 池仍 **1712**（＋0）、⛔ 摊平表仍 **4232**（＋0）。
    // ⭐ **本单（`#108`：交叉淡化的 CC 轴）的代价**：`PreparedRegion` 多一张**定长**
    // CC 段数组（`[Crossfade; CC_CROSSFADE_CAP ＝ 256]`，`size_of::<Crossfade>() ＝ 6`）
    // ⇒ `PreparedRegion` 4232 → **5768**（＋**1536**；条数 `u16` 落在既有填充里 ⇒ 0 B）。
    // ⛔ `SfzVoice` 仍 **40 B**（＋0）、⛔ 池仍 **1712**（＋0）、
    // ⛔ `EngineRuntime` 仍 **180144**（＋0，余量仍 16464 ≥ 8192 —— 摊平表⛔ 不进实时对象）。
    // ⭐ **本单（`#109`：CC 区域门控 `loccN`/`hiccN`）的代价**：`PreparedRegion` 多一张
    // **定长**门控数组（`[CcGate; CC_GATE_CAP ＝ 128]`，`size_of::<CcGate>() ＝ 3`）
    // ⇒ `PreparedRegion` 5768 → **6152**（＋**384**；条数 `cc_gate_count: u8` ＋ 尾部对齐
    // 共 6 B —— ⭐ 现值由 `size_of` 现读：见判据 `S85`）。
    let gate_bytes = CC_GATE_CAP * std::mem::size_of::<CcGate>();
    assert!(
        (5768 + gate_bytes..=5768 + gate_bytes + 8)
            .contains(&std::mem::size_of::<PreparedRegion>()),
        "⭐ `#109` 的每区域代价 ＝ `CC_GATE_CAP × size_of::<CcGate>()`（＝ {gate_bytes} B）         ＋ 条数 `u8` ＋ 尾部对齐（≤ 8 B）"
    );
    // ⚠ `SfzVoice::gain` 本片**改了名**（→ `SfzVoice::track_gain`）而**⛔ 没有加字段**：
    // 它只存**引擎层**那一份，乐器层（含 CC 轴交叉淡化）由逐块路径现算 —— 见判据 `S68`／`S71`。
    assert_eq!(voice, 40, "一个 SFZ 声部 = 40 字节（定长、全 `Copy`）");
    assert_eq!(
        cc_state, 144,
        "`#107` 的会话运行态 CC 表 = `[u8; 128]` ＋ `[u64; 2]`（128 位\"收到过\"位图）\
         ＝ 144 字节（定长、全 `Copy`、⛔ 无 `Vec`／`HashMap`）"
    );
    assert_eq!(
        pool, 1712,
        "声部池 = 16 槽 ×（声部 40 ＋ 挂起 40 ＋ 淡出 16 ＋ 序号 8）＋ 挂起标志 16 \
         ＋ 计数器 28（序号舵 8 ＋ 丢弃 8 ＋ 窃取 8 ＋ 淡出帧数 4）⇒ 对齐到 1712"
    );
    assert!(
        runtime < 192 * 1024,
        "`EngineRuntime` = {runtime} 字节 ≥ 192 KiB（{})—— 定长声部池把实时对象撑爆了",
        192 * 1024
    );
}

/// S10（任务单 `#66` **补做 2**）：**换音源 / 定位必须释放 SFZ 池**。
///
/// # 为什么补它（注入实测的缺口，逐字读数见补做报告）
///
/// `slot.sfz.silence()` 的**三处调用**（`synth.rs:1483` 的 `seek`／`:1831` 的鼓机分支／
/// `:1841` 的复音分支）在 S1~S9 里**零覆盖**：把三处全删掉之后，`S1~S9` 与
/// `rt_zero_alloc` ㉙ **全绿**（9 passed / 73 通过），而**临时探针**量到注入确实活着 ——
/// 换音源后 `sfz_active_voices` 仍是 `Some(1)`、`seek` 后仍是 `Some(1)`，
/// 且**切回 SFZ 时陈旧声部从旧源位置复活、写出 128 个非零样本**（还原态三处全是
/// `Some(0)` / `0`）。那是**用户可见的错**：换掉音源（或定位）之后仍听到上一件音源的尾巴。
///
/// # 判定量
///
/// * `SynthEngine::sfz_active_voices`（声部数）：触发后必须 **2**（前置见证）、
///   换音源后与 `seek` 后必须 **0**；
/// * 换音源那一个量子的**复音非零样本数** > 0（证明那个量子**真的**走了复音分支，
///   ⛔ 不是"整条链没跑"）；
/// * 切回 SFZ 那一个量子的**非零样本数** ＝ **0**（逐位静音，⛔ 不得复活）。
#[test]
fn s10_changing_the_source_or_seeking_releases_the_sfz_pool() {
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let track = EntityId::new();
    // 音符 A：key 60（两条区域都匹配）⇒ 第一量子建 **2** 个 SFZ 声部；
    // 音符 B：在**第二量子**起音、音高 67（三条区域都不匹配）⇒ 换音源那一个量子由
    // **复音**发声 ⇒ 那个量子是"真的走了复音分支"的见证。
    let schedule = NoteSchedule::from_sorted(vec![
        support::scheduled(0, 12_000, 60, 1.0, 48_000.0),
        support::scheduled(QUANTUM as u64, 3_000, 67, 1.0, 48_000.0),
    ]);

    // --- 臂 A：换音源（`sfz = None` ⇒ 复音分支）必须释放池 ---
    let mut engine = engine_with_track(track);
    let mut out = vec![0.0f32; QUANTUM];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut out);
    let after_sfz = engine.sfz_active_voices(track);
    engine.advance(QUANTUM);
    engine.render_track(track, Some(&schedule), None, &mut out);
    let poly_nonzero = out.iter().filter(|s| **s != 0.0).count();
    let after_swap = engine.sfz_active_voices(track);
    engine.advance(QUANTUM);
    let mut back = vec![0.0f32; QUANTUM];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut back);
    let back_nonzero = back.iter().filter(|s| **s != 0.0).count();

    // --- 臂 B：`seek`（定位）也必须释放池 ---
    let mut engine_seek = engine_with_track(track);
    engine_seek.render_track(track, Some(&schedule), Some(&prepared), &mut out);
    let before_seek = engine_seek.sfz_active_voices(track);
    engine_seek.seek(0);
    let after_seek = engine_seek.sfz_active_voices(track);

    println!(
        "[engine-sfz/S10] 触发后活声部 = {after_sfz:?}；换音源那一块复音非零 = {poly_nonzero}；\
         换音源后活声部 = {after_swap:?}；切回 SFZ 的非零 = {back_nonzero}；\
         seek 前 = {before_seek:?}、seek 后 = {after_seek:?}"
    );
    assert_eq!(
        after_sfz,
        Some(2),
        "⭐ 前置见证：两条 `key=60` 的区域都匹配 ⇒ 触发后必须有 **2** 个声部在飞\
         （否则下面的 `Some(0)` 是空转）"
    );
    assert!(
        poly_nonzero > 0,
        "⭐ 换音源那一个量子必须由**复音**发声（非零 = {poly_nonzero}）—— 这是'真的换了音源'的见证"
    );
    assert_eq!(
        after_swap,
        Some(0),
        "⭐ 换音源（`sfz = None`）⇒ SFZ 池必须被**释放**（`slot.sfz.silence()`）"
    );
    assert_eq!(
        back_nonzero, 0,
        "⭐ 切回 SFZ 时陈旧声部⛔ 不得复活（该量子必须逐位静音）—— 注入实测：不释放时会\
         从旧源位置写出 128 个非零样本"
    );
    assert_eq!(
        before_seek,
        Some(2),
        "⭐ 前置见证：`seek` 前必须也有 2 个声部在飞"
    );
    assert_eq!(
        after_seek,
        Some(0),
        "⭐ `seek`（定位）⇒ SFZ 池必须被释放（⛔ 不留上一段采样）"
    );
}

/// 用**一条区域**的 SFZ 离线渲染 `note`（参照臂：证明"某区域 + 某份样本"该出什么）。
///
/// ⚠ 它**解析**（⇒ 分配）⇒ 只用于判据的离线参照臂（与 `PreparedSfz` 的构造期同一条边）。
fn offline_one(path: &str, key: u8, sample: &InMemorySample, note: u8, out: &mut [f32]) -> usize {
    let sfz = SfzInstrument::load(
        format!("<region> sample={path} key={key} pitch_keycenter=60\n"),
        &Default::default(),
    )
    .expect("单区域 SFZ 必须解析成功");
    sfz.render_note_into(sample, note, 127, out, 48_000.0)
        .expect("离线渲染不得报错")
}

/// S11（步 3）：⭐ **多采样 —— 两条区域各播自己那份内容**。
///
/// # 判定量
///
/// * 每条区域的摊平输出与"**单独一条 SFZ ＋ 它自己那份样本**"的离线渲染**逐位相同**；
/// * 两条之间**指纹不同**（⛔ 不是只断言"非静音"）；
/// * 反向对照 1：把提供表里两份样本**对调** ⇒ 指纹变（证明真的按 `sample_path` 取内容）；
/// * 反向对照 2：**广播**重载（`prepare`）在 key=64 上播的是 `a.wav` 的内容
///   （与"`a.wav` 的 key=64 离线渲染"逐位相同）⇒ 这就是 `sample_content=broadcast(1)` 的
///   **音色内容错**的机械证据。
///
/// ⚠ 本判据里的 "WAV" 是**已解码**的 [`InMemorySample`]（两条不同频率的正弦 ⇒ 内容不同）：
/// 真读 PCM WAV 文件的那一步在控制侧（`crates/yeban-app/src/sfz_load.rs`），⛔ 引擎不做 I/O。
#[test]
fn s11_two_regions_with_two_samples_each_play_their_own_content() {
    const TWO_KEYS: &str = "<region> sample=a.wav key=60 pitch_keycenter=60\n\
                            <region> sample=b.wav key=64 pitch_keycenter=60\n";
    let sfz = SfzInstrument::load(TWO_KEYS.to_owned(), &Default::default()).expect("解析必须成功");
    let a = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    let b = InMemorySample::sine(660.0, 48_000.0, SAMPLE_FRAMES);
    let provided = vec![
        ("a.wav".to_owned(), a.clone()),
        ("b.wav".to_owned(), b.clone()),
    ];
    let prepared =
        PreparedSfz::prepare_with_samples(&sfz, &provided, 48_000.0).expect("多采样摊平必须成功");

    assert_eq!(prepared.region_count(), 2, "两条区域都要摊平进来");
    assert!(!prepared.is_broadcast(), "多采样路径⛔ 不是广播");
    assert_eq!(prepared.sample_count(), 2, "两条不同路径 ⇒ 两份样本");
    assert_eq!(prepared.regions()[0].sample_index(), 0, "`a.wav` ⇒ 第 0 份");
    assert_eq!(prepared.regions()[1].sample_index(), 1, "`b.wav` ⇒ 第 1 份");

    // ① 各播自己：摊平输出 == "单独一条 + 它自己那份样本"的离线渲染（逐位）
    let mut flat60 = vec![0.0f32; BLOCK];
    prepared.render_block_into(60, 127, &mut flat60);
    let mut ref60 = vec![0.0f32; BLOCK];
    let ref60_frames = offline_one("a.wav", 60, &a, 60, &mut ref60);

    let mut flat64 = vec![0.0f32; BLOCK];
    prepared.render_block_into(64, 127, &mut flat64);
    let mut ref64 = vec![0.0f32; BLOCK];
    let ref64_frames = offline_one("b.wav", 64, &b, 64, &mut ref64);

    println!(
        "[engine-sfz/S11] key=60: 摊平指纹 = 0x{:016x}／离线(a) 指纹 = 0x{:016x}（帧 {ref60_frames}）；\
         key=64: 摊平指纹 = 0x{:016x}／离线(b) 指纹 = 0x{:016x}（帧 {ref64_frames}）",
        fnv1a_64(&flat60),
        fnv1a_64(&ref60),
        fnv1a_64(&flat64),
        fnv1a_64(&ref64),
    );
    assert_eq!(
        bits(&flat60),
        bits(&ref60),
        "⭐ `key=60` 的区域必须播 `a.wav` 那份内容（与离线参照**逐位相同**）"
    );
    assert_eq!(
        bits(&flat64),
        bits(&ref64),
        "⭐ `key=64` 的区域必须播 `b.wav` 那份内容（与离线参照**逐位相同**）"
    );
    assert!(flat60.iter().any(|s| *s != 0.0), "key=60 必须真的出声");
    assert!(flat64.iter().any(|s| *s != 0.0), "key=64 必须真的出声");
    assert_ne!(
        fnv1a_64(&flat60),
        fnv1a_64(&flat64),
        "⭐ 两份不同内容 ⇒ 两条区域的指纹必须**不同**（⛔ 不是只断言'非静音'）"
    );

    // ② 反向对照 1：对调提供表 ⇒ 内容跟着换（指纹变），且等于对调后的离线参照
    let swapped = vec![
        ("a.wav".to_owned(), b.clone()),
        ("b.wav".to_owned(), a.clone()),
    ];
    let swapped_plan = PreparedSfz::prepare_with_samples(&sfz, &swapped, 48_000.0).expect("摊平");
    let mut swapped60 = vec![0.0f32; BLOCK];
    swapped_plan.render_block_into(60, 127, &mut swapped60);
    let mut ref_swapped60 = vec![0.0f32; BLOCK];
    offline_one("a.wav", 60, &b, 60, &mut ref_swapped60);
    println!(
        "[engine-sfz/S11] 对调提供表：key=60 指纹 = 0x{:016x}（原 = 0x{:016x}）",
        fnv1a_64(&swapped60),
        fnv1a_64(&flat60),
    );
    assert_eq!(
        bits(&swapped60),
        bits(&ref_swapped60),
        "对调之后 `a.wav` 那份槽位里放的是 `b` 的内容 ⇒ 输出必须跟着换"
    );
    assert_ne!(
        fnv1a_64(&swapped60),
        fnv1a_64(&flat60),
        "⭐ 对调提供表必须改变输出（否则'各播自己'可能是空转）"
    );

    // ③ 反向对照 2：**广播**重载在 key=64 上播的是 `a.wav` 的内容（内容错的机械证据）
    let broadcast = PreparedSfz::prepare(&sfz, &a, 48_000.0).expect("广播摊平");
    assert!(broadcast.is_broadcast());
    assert_eq!(broadcast.sample_content_label(), "broadcast(1)");
    assert_eq!(
        broadcast.regions()[1].sample_index(),
        0,
        "广播 ⇒ 全指第 0 份"
    );
    let mut bcast64 = vec![0.0f32; BLOCK];
    broadcast.render_block_into(64, 127, &mut bcast64);
    let mut ref_a_at_64 = vec![0.0f32; BLOCK];
    offline_one("a.wav", 64, &a, 64, &mut ref_a_at_64);
    println!(
        "[engine-sfz/S11] 广播在 key=64：指纹 = 0x{:016x}（多采样 = 0x{:016x}）",
        fnv1a_64(&bcast64),
        fnv1a_64(&flat64),
    );
    assert_eq!(
        bits(&bcast64),
        bits(&ref_a_at_64),
        "⚠ 广播路径在 key=64 上播的是 `a.wav`（**音色内容错**）—— 这正是已登记的局限"
    );
    assert_ne!(
        fnv1a_64(&bcast64),
        fnv1a_64(&flat64),
        "⭐ 广播与多采样在 key=64 上必须**不同**（否则多采样没生效）"
    );
}

/// S12（步 3）：⭐ **同一样本引两次只 materialize／解码一次**。
///
/// # 判定量
///
/// * `sample_count()`（＝摊平期的样本 clone 次数，"解码次数"的机械读数）与
///   `pcm_bytes()`（＝ PCM 字节数）；
/// * 反向对照：两条**不同**路径 ⇒ 计数与字节都翻倍；
/// * 提供表里同一路径出现**两份** ⇒ 首个为准（内容仍是第一份）。
#[test]
fn s12_the_same_sample_referenced_twice_is_materialized_once() {
    const SAME_TWICE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60\n\
                              <region> sample=a.wav key=64 pitch_keycenter=60\n";
    const TWO_PATHS: &str = "<region> sample=a.wav key=60 pitch_keycenter=60\n\
                             <region> sample=c.wav key=64 pitch_keycenter=60\n";
    let a = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    let c = InMemorySample::sine(660.0, 48_000.0, SAMPLE_FRAMES);
    let provided = vec![("a.wav".to_owned(), a.clone())];
    let once = SfzInstrument::load(SAME_TWICE.to_owned(), &Default::default()).expect("解析");
    let twice = SfzInstrument::load(TWO_PATHS.to_owned(), &Default::default()).expect("解析");

    let deduped =
        PreparedSfz::prepare_with_samples(&once, &provided, 48_000.0).expect("摊平必须成功");
    let two_provided = vec![
        ("a.wav".to_owned(), a.clone()),
        ("c.wav".to_owned(), c.clone()),
    ];
    let doubled =
        PreparedSfz::prepare_with_samples(&twice, &two_provided, 48_000.0).expect("摊平必须成功");

    let one_copy = SAMPLE_FRAMES * core::mem::size_of::<f32>();
    println!(
        "[engine-sfz/S12] 同一路径引两次：sample_count = {}、pcm_bytes = {}（一份 = {one_copy}）；\
         两条不同路径：sample_count = {}、pcm_bytes = {}",
        deduped.sample_count(),
        deduped.pcm_bytes(),
        doubled.sample_count(),
        doubled.pcm_bytes(),
    );
    assert_eq!(
        deduped.region_count(),
        2,
        "两条区域都在（去重的是**样本**，⛔ 不是区域）"
    );
    assert_eq!(deduped.regions()[0].sample_index(), 0);
    assert_eq!(
        deduped.regions()[1].sample_index(),
        0,
        "⭐ 同一路径引两次 ⇒ 两条区域都指第 0 份（**只解码一次**）"
    );
    assert_eq!(deduped.sample_count(), 1, "⭐ 解码次数 ＝ 1");
    assert_eq!(
        deduped.pcm_bytes(),
        one_copy,
        "⭐ PCM 字节 ＝ **一份**（480 × 4 = {one_copy}）"
    );
    assert_eq!(doubled.sample_count(), 2, "反向对照：两条不同路径 ⇒ 2");
    assert_eq!(doubled.pcm_bytes(), 2 * one_copy, "反向对照：字节翻倍");
    assert_ne!(doubled.sample_count(), deduped.sample_count());

    // 提供表里同一路径两份（**内容不同**）⇒ 首个为准（⛔ 不静默合并内容）
    let second_a = InMemorySample::sine(880.0, 48_000.0, SAMPLE_FRAMES);
    let duplicated = vec![
        ("a.wav".to_owned(), a.clone()),
        ("a.wav".to_owned(), second_a),
    ];
    let first_wins =
        PreparedSfz::prepare_with_samples(&once, &duplicated, 48_000.0).expect("摊平必须成功");
    assert_eq!(
        first_wins.sample_count(),
        1,
        "同一路径两份 ⇒ 仍只 materialize 一份"
    );
    let mut out = vec![0.0f32; BLOCK];
    first_wins.render_block_into(60, 127, &mut out);
    let mut reference = vec![0.0f32; BLOCK];
    offline_one("a.wav", 60, &a, 60, &mut reference);
    assert_eq!(
        bits(&out),
        bits(&reference),
        "⭐ 提供表里同一路径出现两份时**首个为准**（内容不是第二份）"
    );
    // ⭐ 反向对照：第二份内容**确实不同**（否则上面的"首个为准"是空转）
    let mut second_reference = vec![0.0f32; BLOCK];
    offline_one(
        "a.wav",
        60,
        &InMemorySample::sine(880.0, 48_000.0, SAMPLE_FRAMES),
        60,
        &mut second_reference,
    );
    assert_ne!(
        fnv1a_64(&reference),
        fnv1a_64(&second_reference),
        "两份提供样本的内容必须真的不同（否则本条无鉴别力）"
    );
}

/// S13（步 3）：⭐ **`start`（`offset`）与 `end` 真正应用** —— 离线/摊平/实时三条路逐样本 0。
///
/// # 判定量
///
/// * 离线 vs 摊平**整块逐样本最大绝对差 ＝ 0**；
/// * `offset=10 end=200` ⇒ 写入帧数 **190**（半开 [10,201)），且输出第 0 帧
///   **逐位等于** `源[10] × gain_at(60,127)`；
/// * 反向对照：`offset=50` ⇒ 第 0 帧变成 `源[50] × gain` 且指纹不同（⛔ 证明起点真的进了循环）。
#[test]
fn s13_offset_and_end_are_applied_on_all_three_paths() {
    let a = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    let provided = vec![("a.wav".to_owned(), a.clone())];
    let span_sfz = SfzInstrument::load(
        "<region> sample=a.wav key=60 pitch_keycenter=60 offset=10 end=200\n".to_owned(),
        &Default::default(),
    )
    .expect("解析必须成功");
    let prepared =
        PreparedSfz::prepare_with_samples(&span_sfz, &provided, 48_000.0).expect("摊平必须成功");
    let region = &prepared.regions()[0];
    let gain = region.gain_at(60, 127);

    assert_eq!(
        region.source_start(SAMPLE_FRAMES),
        Some(10.0),
        "起点＝`offset`"
    );
    assert_eq!(
        region.source_end(SAMPLE_FRAMES),
        Some(201),
        "终点＝半开 [10,201)"
    );

    // ① 离线 vs 摊平：整块逐样本 0
    let mut offline = vec![0.0f32; BLOCK];
    span_sfz
        .render_note_into(&a, 60, 127, &mut offline, 48_000.0)
        .expect("离线渲染不得报错");
    let mut flat = vec![0.0f32; BLOCK];
    let flat_frames = prepared.render_block_into(60, 127, &mut flat);
    let diff = offline
        .iter()
        .zip(flat.iter())
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max);

    // ② 实时声部也要在同一帧停、且与摊平逐样本 0
    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);
    let mut engine_out = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut engine_out);
    let engine_diff = engine_out
        .iter()
        .zip(flat.iter())
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max);

    let expected_first = a.pcm[10] * gain;
    println!(
        "[engine-sfz/S13] offset=10 end=200：摊平写入 = {flat_frames} 帧；离线 vs 摊平差 = {diff:e}；\
         引擎 vs 摊平差 = {engine_diff:e}；输出[0] = {}（源[10]×gain = {expected_first}）",
        flat[0]
    );
    assert_eq!(diff, 0.0, "⭐ 离线 vs 摊平必须逐样本相同（`span` 同口径）");
    assert_eq!(engine_diff, 0.0, "⭐ 引擎声部 vs 摊平必须逐样本相同");
    assert_eq!(flat_frames, 190, "半开 [10,201) ⇒ 190 帧");
    assert_eq!(
        flat[0].to_bits(),
        expected_first.to_bits(),
        "⭐ **起点真正应用**：输出第 0 帧必须逐位等于 `源[10] × gain`"
    );
    assert!(
        flat[190..].iter().all(|s| *s == 0.0),
        "⭐ `end` 真正应用：第 190 帧之后一帧不出"
    );

    // ③ 反向对照：换一个 `offset` ⇒ 起点与指纹都变
    let moved = SfzInstrument::load(
        "<region> sample=a.wav key=60 pitch_keycenter=60 offset=50 end=200\n".to_owned(),
        &Default::default(),
    )
    .expect("解析必须成功");
    let moved_plan =
        PreparedSfz::prepare_with_samples(&moved, &provided, 48_000.0).expect("摊平必须成功");
    let mut moved_out = vec![0.0f32; BLOCK];
    let moved_frames = moved_plan.render_block_into(60, 127, &mut moved_out);
    let expected_moved = a.pcm[50] * moved_plan.regions()[0].gain_at(60, 127);
    println!(
        "[engine-sfz/S13] 反向对照 offset=50：写入 = {moved_frames} 帧、输出[0] = {}（期望 {expected_moved}）",
        moved_out[0]
    );
    assert_eq!(
        moved_frames, 150,
        "半开 [50,201) ⇒ 151 个源采样 − 1（线性插值要两个样本）＝ 150 帧"
    );
    assert_eq!(
        moved_out[0].to_bits(),
        expected_moved.to_bits(),
        "⭐ `offset=50` ⇒ 起点必须跟着换"
    );
    assert_ne!(
        fnv1a_64(&moved_out),
        fnv1a_64(&flat),
        "⭐ 两个不同的 `offset` 必须给出不同波形（否则起点没进循环）"
    );
}

/// S14（步 3）：⭐ **单样本重载（广播）与步 2 逐位相同**。
///
/// 判定量：span-free 夹具 [`TWO_MATCH_ONE_MISS`] 的 `prepare`（广播）输出在
/// `(60, 127)`、512 帧上的 **FNV-1a 指纹** ＝ **步 2 实测** [`BROADCAST_STEP2_FINGERPRINT`]
/// （本机 `aarch64/macos` 上硬判；异平台如实跳过并点名原因）。
///
/// ⭐ 另附读数：`is_broadcast()` / `sample_content_label() == "broadcast(1)"`
/// ⇒ 报告里的 `sample_content=broadcast(1)` 有机械根据。
#[test]
fn s14_the_broadcast_overload_is_bit_identical_to_step_two() {
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let mut out = vec![0.0f32; BLOCK];
    let frames = prepared.render_block_into(60, 127, &mut out);
    println!(
        "[engine-sfz/S14] 广播路径 512 帧 @ (60,127)：写入 = {frames}、非零 = {}、\
         指纹 = 0x{:016x}（步 2 实测 = 0x{:016x}）、sample_content = {}",
        out.iter().filter(|s| **s != 0.0).count(),
        fnv1a_64(&out),
        BROADCAST_STEP2_FINGERPRINT,
        prepared.sample_content_label(),
    );
    assert!(out.iter().any(|s| *s != 0.0), "夹具必须真的出声");
    let _checked = check_fingerprint(
        "步 3 的广播重载 vs 步 2",
        fnv1a_64(&out),
        BROADCAST_STEP2_FINGERPRINT,
    );
    assert!(prepared.is_broadcast(), "`prepare` 必须标为广播");
    assert_eq!(
        prepared.sample_content_label(),
        "broadcast(1)",
        "⭐ 报告里的 `sample_content=broadcast(1)` 必须来自机械读数"
    );
    assert_eq!(prepared.sample_count(), 1);
    assert_eq!(prepared.silent_region_count(), 0);
    assert!(prepared.missing_sample_paths().is_empty());
    assert!(prepared.regions().iter().all(|r| r.sample_index() == 0));
}

/// S15（⭐ 本单改写，归属裁决见台账 R711）：⭐ **缺样本 ⇒ 静音 ＋ 计数**（⛔ 不静默、⛔ 不发明内容）。
///
/// # ⚠ 旧期望固化了**错内容**（如实说明）
///
/// 步 3 的 S15 断言的是"缺 `missing.wav` ⇒ 回退到 `samples[0]`，输出与'用 `a.wav` 播那个键'
/// **逐位相同**" ⇒ ⭐ 它把"缺样本的区域去播**别人的采样**"这条**内容错**钉成了期望值。
/// R711 裁决：**引擎出静音并计数**、**合成替代内容是控制侧的决定** ⇒ 本判据改为断言
/// **零输出 ＋ 计数正确**（新期望比旧期望**强**：旧的在"错内容"与"静音"之间分不出来）。
///
/// # 判定量（三条）
///
/// * 提供表**非空**但缺 `missing.wav` ⇒ 该区域 `NO_SAMPLE`：`silent_region_count() == 1`、
///   `missing_sample_paths() == ["missing.wav"]`、`sample_content_label() == "distinct(1)+silent(1)"`，
///   ⭐ 该键**一帧不写**（`render_block_into(64, 127)` 返回 **0** 且整块逐位 0）；
/// * 反向对照 ①：**同一份表**把 `missing.wav` 补上 ⇒ 同一个键**真的出声**且指纹 ≠ 0
///   （⇒ 上面那个 0 不是"这条区域本来就不响"）；
/// * 反向对照 ②：缺少的**只有** `missing.wav` ⇒ `a.wav` 那条区域（key=60）**照常出声**
///   （⇒ 静音的作用域**只到缺样本的那条区域**，⛔ 不是整条轨哑掉）；
/// * 提供表**为空** ⇒ `silent_region_count() == 2`、全部 `NO_SAMPLE`、**一帧不写**。
#[test]
fn s15_a_missing_sample_is_silent_and_is_counted() {
    const ONE_MISSING: &str = "<region> sample=a.wav key=60 pitch_keycenter=60\n\
                               <region> sample=missing.wav key=64 pitch_keycenter=60\n";
    let sfz = SfzInstrument::load(ONE_MISSING.to_owned(), &Default::default()).expect("解析");
    let a = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    let b = InMemorySample::sine(660.0, 48_000.0, SAMPLE_FRAMES);

    // ① 非空提供表 + 缺一份 ⇒ **静音** ＋ 计数（⛔ 不去播 `samples[0]`）
    let missing =
        PreparedSfz::prepare_with_samples(&sfz, &[("a.wav".to_owned(), a.clone())], 48_000.0)
            .expect("摊平必须成功");
    assert_eq!(missing.silent_region_count(), 1, "⭐ 缺样本的区域计数");
    assert_eq!(
        missing.missing_sample_paths().to_vec(),
        vec!["missing.wav".to_owned()],
        "⭐ 缺失路径必须**具名**登记（⛔ 不静默）"
    );
    assert_eq!(
        missing.sample_content_label(),
        "distinct(1)+silent(1)",
        "读数必须如实写出静音（⛔ 再没有 `+fallback(...)` 这一档）"
    );
    assert_eq!(
        missing.regions()[1].sample_index(),
        PreparedRegion::NO_SAMPLE,
        "⭐ 缺样本 ⇒ `NO_SAMPLE`（⛔ 不是回退到 `samples[0]`）"
    );
    assert!(
        !missing.regions()[1].has_sample(),
        "缺样本的区域必须**没有**样本可播"
    );
    let mut missing_out = vec![0.0f32; BLOCK];
    let missing_frames = missing.render_block_into(64, 127, &mut missing_out);
    // 反向对照 ② 的前置：**只有**缺样本的那条区域哑掉，key=60 那条照常出声。
    let mut sibling = vec![0.0f32; BLOCK];
    let sibling_frames = missing.render_block_into(60, 127, &mut sibling);
    println!(
        "[engine-sfz/S15] 缺样本：silent = {}、missing = {:?}、sample_content = {}、\
         key=64 写入 = {missing_frames}（整块非零 = {}）、key=60 写入 = {sibling_frames}",
        missing.silent_region_count(),
        missing.missing_sample_paths(),
        missing.sample_content_label(),
        missing_out.iter().filter(|s| **s != 0.0).count(),
    );
    assert_eq!(missing_frames, 0, "⭐ 缺样本 ⇒ **一帧不写**（引擎出静音）");
    assert!(
        missing_out.iter().all(|s| *s == 0.0),
        "⭐ 缺样本的区域必须**逐位静音**（⛔ 不许播别人的采样）"
    );
    assert!(
        sibling_frames > 0 && sibling.iter().any(|s| *s != 0.0),
        "反向对照②：缺的**只有** `missing.wav` ⇒ `a.wav` 那条区域必须照常出声"
    );

    // 反向对照 ①：把缺失那份补上 ⇒ 同一个键**真的出声**、指纹 ≠ 0
    let complete = PreparedSfz::prepare_with_samples(
        &sfz,
        &[
            ("a.wav".to_owned(), a.clone()),
            ("missing.wav".to_owned(), b.clone()),
        ],
        48_000.0,
    )
    .expect("摊平必须成功");
    let mut complete_out = vec![0.0f32; BLOCK];
    let complete_frames = complete.render_block_into(64, 127, &mut complete_out);
    assert!(
        complete.silent_region_count() == 0,
        "补上之后不得再有缺样本的区域"
    );
    assert!(complete.missing_sample_paths().is_empty());
    assert_ne!(
        complete_frames, 0,
        "⭐ 补上内容之后同一个键必须真的出声（否则上面那个 0 是空转）"
    );
    let mut reference = vec![0.0f32; BLOCK];
    offline_one("missing.wav", 64, &b, 64, &mut reference);
    assert_eq!(
        bits(&complete_out),
        bits(&reference),
        "补上的那一份必须**逐位**是它自己的内容（`b`，⛔ 不是 `a`）"
    );

    // ③ 空提供表 ⇒ 全部 NO_SAMPLE ＋ 计数 ＋ 一帧不写
    let empty = PreparedSfz::prepare_with_samples(&sfz, &[], 48_000.0).expect("摊平必须成功");
    let mut empty_out = vec![0.0f32; BLOCK];
    let empty_frames = empty.render_block_into(64, 127, &mut empty_out);
    println!(
        "[engine-sfz/S15] 空提供表：silent = {}、missing = {:?}、写入帧数 = {empty_frames}、\
         sample_content = {}",
        empty.silent_region_count(),
        empty.missing_sample_paths(),
        empty.sample_content_label(),
    );
    assert_eq!(empty.silent_region_count(), 2);
    assert!(empty.regions().iter().all(|r| !r.has_sample()));
    assert_eq!(empty_frames, 0, "没有样本 ⇒ 一帧不写");
    assert!(empty_out.iter().all(|s| *s == 0.0));
    assert_eq!(
        empty.missing_sample_paths().to_vec(),
        vec!["a.wav".to_owned(), "missing.wav".to_owned()],
        "缺失路径排序 ＋ 去重（确定性顺序）"
    );
}

/// S16（步 3）：⭐ **绑定注入 API 经公开路径可用（多采样）**。
///
/// 路径（全在集成测试里 ⇒ 只用 `pub` API）：
/// `SfzInstrument::referenced_sample_paths` →（控制侧解码 ⇒ 调用方）→
/// [`SfzPlan::prepare_with_samples`] → [`EngineSnapshot::with_sfz`] →
/// `render_snapshot`（快照槽 → 量子 → 声相 → 母线）。
///
/// 判定量：SFZ 臂非静音 ＋ 指纹 ≠ "不给 SFZ"；反向对照：**广播** plan 的端到端指纹与
/// 多采样版**不同**（⇒ 注入的多采样内容真的进了音频线程）。
#[test]
fn s16_the_multi_sample_binding_api_is_reachable_through_the_public_path() {
    let fixture = note_project(&E2E_NOTES);
    let track = fixture.track;
    let sfz =
        SfzInstrument::load(E2E_SFZ.to_owned(), &Default::default()).expect("SFZ 必须解析成功");

    // ① 控制侧：先查引用路径，再"解码"（判据里用内存样本；真读文件在 app 侧）
    let referenced = sfz.referenced_sample_paths().expect("路径查询");
    println!("[engine-sfz/S16] 引用路径 = {referenced:?}");
    assert_eq!(referenced, ["a.wav".to_owned(), "b.wav".to_owned()]);
    let a = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    let b = InMemorySample::sine(660.0, 48_000.0, SAMPLE_FRAMES);
    let plan = SfzPlan::prepare_with_samples(
        &sfz,
        &[
            ("a.wav".to_owned(), a.clone()),
            ("b.wav".to_owned(), b.clone()),
        ],
        48_000.0,
    )
    .expect("多采样摊平必须成功");
    assert_eq!(plan.prepared().sample_count(), 2);
    assert!(!plan.prepared().is_broadcast());

    // ② 注入（唯一公开绑定路径）＋ 端到端渲染
    let bare = EngineSnapshot::from_project(&fixture.project, 1).expect("快照");
    assert!(bare.sfz().is_empty(), "⛔ `from_project` 不得凭空绑 SFZ");
    let armed = EngineSnapshot::from_project(&fixture.project, 1)
        .expect("快照")
        .with_sfz(track, plan);
    let with_sfz = render_snapshot(armed, SFZ_QUANTA);
    let without = render(&fixture.project, SFZ_QUANTA);
    println!(
        "[engine-sfz/S16] 多采样臂: 非零={} 峰值={} 指纹=0x{:016x}；对照臂（不给 SFZ）: \
         非零={} 指纹=0x{:016x}",
        with_sfz.nonzero(),
        with_sfz.peak(),
        with_sfz.fingerprint(),
        without.nonzero(),
        without.fingerprint(),
    );
    assert!(with_sfz.nonzero() > 0, "⭐ 端到端必须非静音");
    assert_ne!(
        with_sfz.fingerprint(),
        without.fingerprint(),
        "⭐ 注入之后指纹必须不同（否则 SFZ 支路没接上）"
    );

    // ③ 反向对照：**广播** plan（只给 `a.wav`）⇒ 端到端指纹必须不同
    let broadcast_plan = SfzPlan::prepare(&sfz, &a, 48_000.0).expect("广播摊平");
    assert_eq!(
        broadcast_plan.prepared().sample_content_label(),
        "broadcast(1)"
    );
    let armed_broadcast = EngineSnapshot::from_project(&fixture.project, 1)
        .expect("快照")
        .with_sfz(track, broadcast_plan);
    let broadcast = render_snapshot(armed_broadcast, SFZ_QUANTA);
    println!(
        "[engine-sfz/S16] 广播臂: 非零={} 峰值={} 指纹=0x{:016x}",
        broadcast.nonzero(),
        broadcast.peak(),
        broadcast.fingerprint(),
    );
    assert!(
        broadcast.nonzero() > 0,
        "广播臂也必须出声（否则②的比较是空转）"
    );
    assert_ne!(
        broadcast.fingerprint(),
        with_sfz.fingerprint(),
        "⭐ 多采样 vs 广播的端到端指纹必须不同（`key=64` 那条区域换了内容）"
    );
}

// =====================================================================================
// ⭐ 归属裁决 `R711` 的两条落地判据（本单新增）：S17 = 轨推子（`needs-1`）、S18 = 防双重计。
// =====================================================================================

/// ⭐ S17／S18 用的**鼓机设备**：五个键位名写全 ⇒ `DrumsParams::from_devices` 认它是鼓机
/// （口径与 S7 的那个设备、与 `crates/yeban-engine/src/drums.rs` 的识别一致）。
fn drum_kit_device() -> DeviceDefinition {
    DeviceDefinition {
        id: EntityId::new(),
        name: "Yeban Drums".to_owned(),
        kind: DeviceKind::InternalInstrument,
        bypassed: false,
        params: [
            ("kick_note", 60.0),
            ("snare_note", 38.0),
            ("closed_hat_note", 42.0),
            ("open_hat_note", 46.0),
            ("clap_note", 39.0),
        ]
        .iter()
        .map(|(name, value)| ParameterValue {
            name: (*name).to_owned(),
            value: *value,
            unit: None,
        })
        .collect(),
        latency_samples: 0,
    }
}

/// ⭐ S17 的轨参数夹具：`volume_db` ＋ `mute` ＋ "**另一条轨在独奏**"（可闻门的三个自变量）。
///
/// `drums = true` ⇒ 本轨挂鼓机设备（分派次序 ＝ 鼓机 ＞ SFZ ⇒ 该臂走鼓机）；
/// `drums = false` ⇒ 不挂任何设备（该臂可由调用方注入 SFZ 摊平表）。
/// ⚠ 两个臂的**音符、推子、静音/独奏**逐字相同 ⇒ 差异**只有音源**。
fn fader_fixture(
    volume_db: f32,
    mute: bool,
    solo_elsewhere: bool,
    drums: bool,
) -> support::Fixture {
    let mut fixture = tuned_project(&E2E_NOTES, MixSpec::volume(volume_db));
    let track = fixture.track;
    {
        let entry = fixture
            .project
            .tracks
            .get_mut(&track)
            .expect("夹具必须有那条 MIDI 轨");
        entry.mute = mute;
        if drums {
            entry.devices = vec![drum_kit_device()];
        }
    }
    if solo_elsewhere {
        let other = EntityId::new();
        fixture.project.tracks.insert(
            other,
            TrackV3 {
                id: other,
                name: "Solo".to_owned(),
                kind: TrackKind::Midi,
                solo: true,
                ..TrackV3::default()
            },
        );
        fixture.project.routing_graph.nodes.push(other);
    }
    fixture
}

/// 判据窗口（帧）：`E2E_NOTES` 的两个起音（0 与 48 tick = **1200** 帧）都落在窗口内。
const FADER_FRAMES: usize = 2560;

/// 本轨的**单声道时域输出**（`render_track` ⇒ **声相与母线之前**）。
///
/// # ⚠ 量什么（先说再跑）
///
/// 量的是**本轨的样本序列**（单位：线性幅度，48 kHz 单声道，2560 帧）。
///
/// ⚠ **为什么⛔ 不量端到端**：母线限制器是**非线性**器件 ⇒ 它会给出一个与轨增益无关的
/// 因子，把"轨增益的线性"测糊。本判据要证的是"轨增益乘了一次、且两件音源乘的是**同一个**值"
/// ⇒ 必须在这一级量。
///
/// 路径：`EngineSnapshot::from_project` → `SynthEngine::arm_from_snapshot`（**产品路径**，
/// 含 `set_track_gain_scales`）→ `render_track`。
fn track_output(fixture: &support::Fixture, sfz: Option<&PreparedSfz>) -> Vec<f32> {
    let track = fixture.track;
    let snapshot = EngineSnapshot::from_project(&fixture.project, 1).expect("夹具工程必须成快照");
    let mut engine = SynthEngine::new(48_000);
    engine
        .arm_from_snapshot(&snapshot)
        .expect("武装最小工程不得报错");
    let schedule = snapshot
        .schedules()
        .get(&track)
        .cloned()
        .expect("本轨必须有调度表");
    let mut out = vec![0.0f32; FADER_FRAMES];
    engine.render_track(track, Some(&schedule), sfz, &mut out);
    out
}

/// ⭐ 一个档的**两臂峰值** ＋ 两臂的时域缓冲：(SFZ 臂, 鼓机臂)。
fn two_arm_outputs(
    volume_db: f32,
    mute: bool,
    solo_elsewhere: bool,
    prepared: &PreparedSfz,
) -> (Vec<f32>, Vec<f32>) {
    let sfz_arm = track_output(
        &fader_fixture(volume_db, mute, solo_elsewhere, false),
        Some(prepared),
    );
    let drum_arm = track_output(&fader_fixture(volume_db, mute, solo_elsewhere, true), None);
    (sfz_arm, drum_arm)
}

/// 峰值（绝对值最大；单位：线性幅度）。
fn peak(samples: &[f32]) -> f32 {
    samples.iter().fold(0.0f32, |acc, s| acc.max(s.abs()))
}

/// S17（⭐ 本单新增；归属裁决 `R711` 的 `needs-1` 落地）：⭐ **轨推子变化 N dB ⇒
/// SFZ 与鼓机输出同比例变**。
///
/// # 判定量（三条腿，都可机械判定）
///
/// 1. **推子 −6 dB**：`peak(−6) / peak(0)` 在**两臂**上都等于 [`track_gain`]`(−6.0)`
///    （相对误差 ≤ `1e-5`），且两臂的比值**互相**相等 ⇒ ⭐ "同径、同一个算子"；
/// 2. **静音**（`mute = true`）：两臂**逐位**为 `0.0`（⇒ 可闻门真的到了声部上）；
/// 3. **另一条轨独奏**（`any_solo = true` 且本轨既不 solo 也不 solo_safe）：两臂**逐位** `0.0`
///    （⇒ 独奏与静音走的是**同一个** `track_is_audible` 门）。
///
/// # 怎么变红
///
/// 让 SFZ 那条支路不再乘轨增益（把 `trigger_note` 的 `region.gain_at(...) * track_gain`
/// 改回 `region.gain_at(...)`）⇒ 腿 ① 的 SFZ 比值变回 `1.0`、腿 ②/③ 的 SFZ 臂**不再全零**。
/// ⚠ 腿 ① 本身⛔ 不能证明"鼓机也吃了推子"：那由**同一个** `track_gain_scale` 在
/// `snapshot::project_schedules` 里的一次调用保证（鼓机读含轨门的 `note.gain`）。
#[test]
fn s17_a_track_fader_scales_the_sfz_and_the_drums_arm_by_the_same_ratio() {
    let prepared = prepare(E2E_SFZ);

    // ③ 前置：**两臂都必须真的出声**（否则"同比例"可能是 0/0 那种空话）。
    let (sfz_0, drum_0) = two_arm_outputs(0.0, false, false, &prepared);
    let (sfz_6, drum_6) = two_arm_outputs(-6.0, false, false, &prepared);
    let (sfz_mute, drum_mute) = two_arm_outputs(0.0, true, false, &prepared);
    let (sfz_solo, drum_solo) = two_arm_outputs(0.0, false, true, &prepared);

    let expected = track_gain(-6.0);
    let sfz_ratio = peak(&sfz_6) / peak(&sfz_0);
    let drum_ratio = peak(&drum_6) / peak(&drum_0);
    println!(
        "[engine-sfz/S17] 峰值：SFZ 臂 0 dB = {:.9} / −6 dB = {:.9} / 静音 = {:.9} / 别轨独奏 = {:.9}；\
         鼓机臂 0 dB = {:.9} / −6 dB = {:.9} / 静音 = {:.9} / 别轨独奏 = {:.9}；\
         比值 SFZ = {sfz_ratio:.9} vs 鼓机 = {drum_ratio:.9}（期望 track_gain(−6 dB) = {expected:.9}）",
        peak(&sfz_0),
        peak(&sfz_6),
        peak(&sfz_mute),
        peak(&sfz_solo),
        peak(&drum_0),
        peak(&drum_6),
        peak(&drum_mute),
        peak(&drum_solo),
    );

    assert!(
        peak(&sfz_0) > 0.0 && peak(&drum_0) > 0.0,
        "0 dB 档两臂都必须真的出声（SFZ = {} / 鼓机 = {}）",
        peak(&sfz_0),
        peak(&drum_0)
    );
    assert!(
        peak(&sfz_6) > 0.0 && peak(&drum_6) > 0.0,
        "−6 dB 档两臂都必须仍然出声（⇒ 比值不是 0/0）"
    );
    // ① 推子比例：两臂各自 == `track_gain(-6)`，且两臂**互相**相等。
    let rel = |a: f32, b: f32| (a - b).abs() / b.abs();
    assert!(
        rel(sfz_ratio, expected) <= 1e-5,
        "⭐ SFZ 臂的推子比例必须 ＝ `track_gain(-6 dB)`：实得 {sfz_ratio} vs {expected}"
    );
    assert!(
        rel(drum_ratio, expected) <= 1e-5,
        "⭐ 鼓机臂的推子比例必须 ＝ `track_gain(-6 dB)`：实得 {drum_ratio} vs {expected}"
    );
    assert!(
        rel(sfz_ratio, drum_ratio) <= 1e-5,
        "⭐ ⭐ **同径**：SFZ 与鼓机的推子比例必须一致（{sfz_ratio} vs {drum_ratio}）"
    );
    // ② 静音档：两臂**逐位** 0（⛔ 不是"很小"）。
    assert!(
        sfz_mute.iter().all(|s| *s == 0.0) && drum_mute.iter().all(|s| *s == 0.0),
        "⭐ 静音轨 ⇒ 两臂都必须**逐位**静音（SFZ 峰值 = {}、鼓机峰值 = {}）",
        peak(&sfz_mute),
        peak(&drum_mute)
    );
    // ③ 独奏档：同一道可闻门。
    assert!(
        sfz_solo.iter().all(|s| *s == 0.0) && drum_solo.iter().all(|s| *s == 0.0),
        "⭐ 另一条轨独奏 ⇒ 本轨两臂都必须**逐位**静音（SFZ 峰值 = {}、鼓机峰值 = {}）",
        peak(&sfz_solo),
        peak(&drum_solo)
    );
}

/// S18（⭐ 本单新增；归属裁决 `R711` 的**防双重计**腿）：⭐ **引擎层只乘轨增益，
/// ⛔ 绝不替乐器层再乘一次力度**。
///
/// # 判定量
///
/// 每个力度 `v ∈ {0, 32, 64, 100, 127}`：**引擎声部路径**与**摊平表（乐器层）一次性渲染**
/// **逐位相同**。手工调度表里 `ScheduledNote::gain` 显式写成 `velocity_gain(v)`
/// （＝"如果引擎把力度也交给 SFZ，就会多乘一次"的那一份）⇒ 只要两侧逐位相同，
/// 就证明引擎**没有**碰力度、只乘了轨增益（本档轨增益 ＝ 默认 `1.0`）。
///
/// # ⚠ 反向对照：为什么必须用**中段**力度
///
/// `velocity_gain(127) == 1.0` 是**恒等** ⇒ 在 127 上"多乘一次力度"看不出来。
/// S1 那条腿正是 127 ⇒ ⭐ **S1 抓不住双重计**，本判据补的正是这个盲区（下面两条断言钉住它）。
///
/// # 怎么变红
///
/// 在 `SfzVoicePool::trigger_note` 里把增益改成
/// `region.gain_at(note, velocity) * track_gain * velocity_gain(velocity)` ⇒
/// `v ∈ {32, 64, 100}` 三条腿当场**逐位不等**（`v = 127` 那条仍绿 ⇒ 盲区真实存在）。
#[test]
fn s18_the_engine_never_applies_a_second_velocity_gain() {
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let mut rows = Vec::new();
    for velocity in [0u8, 32, 64, 100, 127] {
        let track = EntityId::new();
        let mut engine = engine_with_track(track);
        // ⚠ 手工调度表：轨增益门 ＝ `NoteSchedule::from_sorted` 的默认 **1.0**（单位）；
        //    逐音符 `gain` 显式写成 `velocity_gain(v)`（见判据文档）。
        let schedule = NoteSchedule::from_sorted(vec![ScheduledNote::new(
            0,
            12_000,
            60,
            velocity,
            support::yeban_dsp_note_to_hz(60),
            velocity_gain(velocity),
            48_000.0,
        )]);
        let mut engine_out = vec![0.0f32; BLOCK];
        engine.render_track(track, Some(&schedule), Some(&prepared), &mut engine_out);
        let mut flat = vec![0.0f32; BLOCK];
        prepared.render_block_into(60, velocity, &mut flat);
        rows.push(format!(
            "v={velocity}: 引擎 = {:#010x} / 摊平 = {:#010x}",
            fnv1a_64(&engine_out),
            fnv1a_64(&flat)
        ));
        assert_eq!(
            bits(&engine_out),
            bits(&flat),
            "⭐ 力度 {velocity}：引擎声部路径必须与**乐器层**一次性渲染**逐位相同**             （⇒ 引擎⛔ 没有替乐器层再乘一次力度）"
        );
    }
    println!("[engine-sfz/S18] 逐位对账 ⇒ {}", rows.join("；"));

    // 反向对照：`velocity_gain(127) == 1.0`（恒等）⇒ 127 那条腿对"双重计"**没有牙**；
    // 中段力度才有（下面这条断言就是 S18 必须存在、而 S1 不够的理由）。
    assert_eq!(velocity_gain(127), 1.0, "127 的力度增益必须是**恒等**");
    assert!(
        velocity_gain(64) > 0.0 && velocity_gain(64) < 1.0,
        "中段力度必须既非 0 也非恒等（实得 {}）",
        velocity_gain(64)
    );
    assert_ne!(
        velocity_gain(64),
        1.0,
        "⭐ 中段力度是**恒等**的话，本判据就没有鉴别力了"
    );
}

/// ⭐ S19 的夹具：`regions` 条 `key` 的区域 ＋ 一份**常数 PCM**（全 `1.0`）。
///
/// 常数 PCM 的理由：淡出是**逐帧增益**，常数源 ⇒ 输出**就是那条增益曲线**
/// （`out[k] == gain × fade_gain(k)`），读数可以直接与 `FLOOR^(n/N)` 对账。
fn constant_plan(regions: usize, key: u8) -> PreparedSfz {
    let mut text = String::new();
    for _ in 0..regions {
        text.push_str(&format!(
            "<region> sample=a.wav key={key} pitch_keycenter=60\n"
        ));
    }
    let sfz = SfzInstrument::load(text, &Default::default()).expect("SFZ 必须解析成功");
    let sample = InMemorySample {
        pcm: vec![1.0f32; SAMPLE_FRAMES],
        sample_hz: 48_000.0,
    };
    PreparedSfz::prepare(&sfz, &sample, 48_000.0).expect("摊平必须成功")
}

/// ⭐ S19（本单新增；`sfz-needs-2`）：⭐ **池满 ⇒ 窃取最旧的声部 ＋ 3 ms 指数淡出**。
///
/// # 夹具（为什么要三次触发）
///
/// * 第 1 次：**只**触发 1 条区域（`key=60`，终点 `LATE`）⇒ 槽 0、触发序号最小；
/// * 第 2 次：触发 15 条区域（`key=60`，终点 `EARLY = 64`）⇒ 填满槽 1..15；
/// * 第 3 次：触发 1 条区域（`key=64`）⇒ 池满 ⇒ **窃取最旧的**（槽 0）。
///
/// 从 `position = 64` 起只有槽 0 还在响（其余 15 个的引擎终点已过 ⇒ 渲染时如实退休）
/// ⇒ 本判据量的**就是被窃取者那条淡出曲线**。
///
/// # 判定量
///
/// * 窃取读数：`created == 0`（没有空槽）、`stolen == 1`、`dropped == 0`；
/// * `fade_remaining_at(0) == 144`（3 ms @ 48 kHz，与复音**同一把舵**）；
/// * 淡出窗口里槽 0 仍宣称**被窃取者**（`note == 60`）；走完 144 帧后**就地换成**
///   新声部（`note == 64`）且仍是活声部 ⇒ "被换掉"可读；
/// * **输出读数**：`out[143] / out[0] == FLOOR^(143/144)`（逐位对账）；
/// * **硬窃取对照臂**（`set_steal_fade_frames(0)`）：同一次触发 ⇒ 槽 0 **立刻**是
///   `note == 64`、输出**无衰减**（`out[143] == out[0]` 逐位）⇒ 两条臂指纹不同
///   （⇒ ②"淡出确实生效"不是空转）。
///
/// ⚠ 本判据的**旧行为**是"第 3 次直接丢弃"⇒ 池仍是 16 个 `note == 60` 的声部、
/// `dropped == 1`、`stolen == 0` ⇒ 本判据当场变红（注入读数见提交报告）。
#[test]
fn s19_a_full_pool_steals_the_oldest_voice_behind_a_three_millisecond_fade() {
    const LATE: u64 = 12_000;
    const EARLY: u64 = 64;
    let one = constant_plan(1, 60);
    let fifteen = constant_plan(SFZ_VOICES_PER_TRACK - 1, 60);
    let stealer = constant_plan(1, 64);

    let mut pool = SfzVoicePool::empty();
    assert_eq!(pool.steal_fade_frames(), 144, "3 ms @ 48 kHz");
    assert_eq!(pool.trigger_note(&one, 60, 100, LATE, 1.0, None), 1, "槽 0");
    assert_eq!(
        pool.trigger_note(&fifteen, 60, 100, EARLY, 1.0, None),
        SFZ_VOICES_PER_TRACK - 1,
        "填满槽 1..15"
    );
    assert_eq!(pool.active_count(), SFZ_VOICES_PER_TRACK);

    // ③ 池满 ⇒ 窃取最旧的（槽 0 的触发序号最小）。
    let created = pool.trigger_note(&stealer, 64, 100, LATE, 1.0, None);
    println!(
        "[engine-sfz/S19] 池满触发：新建 = {created}；窃取 = {}；丢弃 = {}；挂起 = {}；\
         槽 0 淡出剩余 = {}；槽 0 在场音高 = {}",
        pool.stolen(),
        pool.dropped(),
        pool.pending_count(),
        pool.fade_remaining_at(0),
        pool.voices()[0].note(),
    );
    assert_eq!(created, 0, "池满 ⇒ 没有空槽可占（窃取占的是别人的槽）");
    assert_eq!(pool.stolen(), 1);
    assert_eq!(pool.dropped(), 0, "⭐ 窃取⛔ 不是丢弃");
    assert_eq!(pool.pending_count(), 1, "新声部挂在槽 0 等接管");
    assert_eq!(pool.fade_remaining_at(0), 144, "⭐ 3 ms ＝ 144 帧 @ 48 kHz");
    assert_eq!(
        pool.voices()[0].note(),
        60,
        "淡出窗口里槽位必须仍宣称**被窃取者**（口径与 PolySynth 同款）"
    );
    assert_eq!(pool.active_count(), SFZ_VOICES_PER_TRACK, "16 个槽一个不空");

    // ④ 输出读数：从 position = 64 起只有槽 0 出声，144 帧正好走完淡出。
    let mut out = vec![0.0f32; 144];
    pool.render_into(&one, EARLY, &mut out);
    // ⚠ 期望值写成**字面量** `1e-3`（−60 dBFS）而不是去读实现里的常量：
    //    判据用实现自己的常量做期望值是自我确认（实现改错了也一起改"对"）。
    let decay = 1.0e-3f64.powf(1.0 / 144.0) as f32;
    let mut expected = 1.0f32;
    for _ in 0..143 {
        expected *= decay;
    }
    println!(
        "[engine-sfz/S19] 淡出：out[0] = {:.9}；out[143] = {:.9}（期望 FLOOR^(143/144)·out[0] = {:.9}）；\
         比值 = {:.9}",
        out[0],
        out[143],
        out[0] * expected,
        out[143] / out[0],
    );
    assert!(out[0] > 0.0, "淡出首帧必须出声（否则比值是 0/0）");
    assert_eq!(
        out[143].to_bits(),
        (out[0] * expected).to_bits(),
        "⭐ 第 143 帧必须逐位等于 `out[0] × FLOOR^(143/144)`（StealFade 的指数口径）"
    );
    assert!(
        out[143] / out[0] < 0.002,
        "⭐ 淡出末尾必须落到 −60 dBFS 一带（实得 {}）",
        out[143] / out[0]
    );

    // ⑤ 走完 144 帧 ⇒ 挂起者**就地接管**（同一个槽），仍是活声部。
    assert_eq!(
        pool.voices()[0].note(),
        64,
        "⭐ 淡出走完 ⇒ 最旧的声部被换掉（槽 0 变成新声部）"
    );
    assert_eq!(pool.pending_count(), 0, "挂起者已经接管");
    assert_eq!(pool.fade_remaining_at(0), 0);
    assert!(pool.voices()[0].is_active(), "接管者必须开始发声");
    let mut after = vec![0.0f32; 64];
    pool.render_into(&one, EARLY + 144, &mut after);
    assert!(
        after.iter().any(|s| *s != 0.0),
        "⭐ 接管者必须真的出声（⛔ 不是把槽弄哑）"
    );

    // ⑥ 硬窃取对照臂：同样的触发序列，淡出帧数 = 0 ⇒ 立刻换人、输出无衰减。
    let mut hard = SfzVoicePool::empty();
    hard.set_steal_fade_frames(0);
    hard.trigger_note(&one, 60, 100, LATE, 1.0, None);
    hard.trigger_note(&fifteen, 60, 100, EARLY, 1.0, None);
    let hard_created = hard.trigger_note(&stealer, 64, 100, LATE, 1.0, None);
    let mut hard_out = vec![0.0f32; 144];
    hard.render_into(&one, EARLY, &mut hard_out);
    println!(
        "[engine-sfz/S19] 硬窃取对照：新建 = {hard_created}；槽 0 音高 = {}；淡出剩余 = {}；\
         指纹 软 = 0x{:016x} / 硬 = 0x{:016x}",
        hard.voices()[0].note(),
        hard.fade_remaining_at(0),
        fnv1a_64(&out),
        fnv1a_64(&hard_out),
    );
    assert_eq!(hard.stolen(), 1, "硬窃取同样计一次窃取");
    assert_eq!(hard.dropped(), 0);
    assert_eq!(
        hard.voices()[0].note(),
        64,
        "⭐ 硬窃取（帧数 0）⇒ **立刻**接管，没有淡出窗口"
    );
    assert_eq!(hard.fade_remaining_at(0), 0);
    assert_eq!(
        hard_out[143].to_bits(),
        hard_out[0].to_bits(),
        "硬窃取没有衰减（逐位相同）"
    );
    assert_ne!(
        fnv1a_64(&out),
        fnv1a_64(&hard_out),
        "⭐ 软/硬两条臂的指纹必须不同（否则'淡出生效'可能是空转）"
    );
}

/// ⭐ S20（本单新增；`sfz-needs-3`）：⭐ **三件同轨的可读信号**（⛔ 不改分派次序）。
///
/// # 裁决（本单）
///
/// 次序**维持** `鼓机 ＞ SFZ ＞ 复音`（与 `crates/yeban-engine/src/drums.rs` §4.1
/// "一条轨至多一件音源"的既有裁决一致）⇒ ⛔ **不改成叠加**。真正缺的是
/// "用户看得出被忽略了" ⇒ 新增**投影读数** [`SynthEngine::armed_sources`]
/// ／ [`SynthEngine::ignored_sources`]（`render_track` 每量子写一个 `u8`）。
///
/// # 判定量
///
/// * 三件同轨（鼓机设备 ＋ 注入 SFZ ＋ **恒在场**的复音）⇒ `armed_sources == 3`
///   ＋ `ignored_sources == 2`（⭐ 本单要求的"被忽略的音源计数 ＝ 2"）；
/// * 输出仍对"只有鼓机"**逐位相同**（S7 的复核腿 ⇒ 信号⛔ 不改变输出）；
/// * 反向对照：鼓机＋复音 ⇒ `2 / 1`；只有复音 ⇒ `1 / 0`；**没渲染过**的轨 ⇒ `None`。
#[test]
fn s20_three_sources_on_one_track_report_two_ignored() {
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let track = EntityId::new();
    let params = DrumsParams::from_devices(&[drum_kit_device()]).expect("鼓机设备必须命中");
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);

    let mut three = SynthEngine::new(48_000);
    let mut drums_only = SynthEngine::new(48_000);
    let mut poly_only = SynthEngine::new(48_000);
    let mut never_rendered = SynthEngine::new(48_000);
    three.begin_snapshot(48_000, &[track], [], [(&track, &params)]);
    drums_only.begin_snapshot(48_000, &[track], [], [(&track, &params)]);
    poly_only.begin_snapshot(48_000, &[track], [], []);
    never_rendered.begin_snapshot(48_000, &[track], [], []);

    let mut a = vec![0.0f32; 128];
    let mut b = vec![0.0f32; 128];
    let mut c = vec![0.0f32; 128];
    three.render_track(track, Some(&schedule), Some(&prepared), &mut a);
    drums_only.render_track(track, Some(&schedule), None, &mut b);
    poly_only.render_track(track, Some(&schedule), None, &mut c);

    println!(
        "[engine-sfz/S20] 三件同轨：武装 = {:?}；被忽略 = {:?}（鼓机＋SFZ 非零 = {}）；\
         鼓机＋复音：武装 = {:?}／被忽略 = {:?}；只有复音：武装 = {:?}／被忽略 = {:?}；\
         没渲染过：武装 = {:?}",
        three.armed_sources(track),
        three.ignored_sources(track),
        a.iter().filter(|s| **s != 0.0).count(),
        drums_only.armed_sources(track),
        drums_only.ignored_sources(track),
        poly_only.armed_sources(track),
        poly_only.ignored_sources(track),
        never_rendered.armed_sources(track),
    );
    assert_eq!(
        three.armed_sources(track),
        Some(3),
        "⭐ 鼓机 ＋ SFZ ＋ 复音 ⇒ 武装 3 件"
    );
    assert_eq!(
        three.ignored_sources(track),
        Some(2),
        "⭐ 三件同轨 ⇒ **被忽略的音源计数 ＝ 2**（本单的可读信号）"
    );
    assert!(
        b.iter().any(|s| *s != 0.0),
        "反向对照：鼓机臂必须真的出声（否则下面的等号可能只是两边都哑）"
    );
    assert_eq!(
        bits(&a),
        bits(&b),
        "⭐ 信号⛔ 不改变输出：三件同轨仍对'只有鼓机'**逐位相同**（S7 的复核腿）"
    );
    assert_eq!(
        drums_only.armed_sources(track),
        Some(2),
        "反向对照：鼓机 ＋ 复音 ⇒ 武装 2 件"
    );
    assert_eq!(drums_only.ignored_sources(track), Some(1));
    assert_eq!(
        poly_only.armed_sources(track),
        Some(1),
        "反向对照：只有复音 ⇒ 武装 1 件、没有取舍"
    );
    assert_eq!(poly_only.ignored_sources(track), Some(0));
    assert_eq!(
        never_rendered.armed_sources(track),
        None,
        "⛔ 没渲染过的槽必须读 `None`（不是'0 件'）"
    );
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#78`：引擎侧**消费** `TrackV3.sampler`（⭐ 只接线、⛔ 不读盘）
// ---------------------------------------------------------------------------

/// S21／S22／S23 的路径夹具：`instruments/lead.sfz`。
///
/// ⚠ 它**刻意在磁盘上不存在**（判据不碰文件系统）：引擎侧⛔ 不读盘 ⇒ 这个路径无论
/// 真假都⛔ 不该改变任何东西（⛔ 不报错、⛔ 不建声部、⛔ 不改渲染）—— 那正是
/// "接线 ⛔ 不是读盘"的机械见证。
const SAMPLER_PATH: &str = "instruments/lead.sfz";

/// S24 的块长：**小于**样本帧数（`SAMPLE_FRAMES = 480`）⇒ 有样本的声部在这一次
/// 渲染里**不会播完退休** ⇒ `sfz_active_voices` 才有区分度（`BLOCK = 512` 会让
/// 声部在同一块里播完，两条腿都会读成 `0` —— 那会让"不建声部"这条腿失去牙齿）。
const S24_BLOCK: usize = 128;

/// 把夹具工程里那条 MIDI 轨的 `sampler` 设成给定值（`None` ⇒ 清空），其余一字不动。
///
/// ⭐ "只差这一个字段"是 S21／S23 反向对照成立的**前提**：两条臂的工程除 `sampler`
/// 之外完全相同（同一份夹具、同一批音符、同一条路由）。
fn project_with_sampler(fixture: &support::Fixture, sampler: Option<&str>) -> YebanProjectV1 {
    let mut project = fixture.project.clone();
    project
        .tracks
        .get_mut(&fixture.track)
        .expect("夹具里必须有那条 MIDI 轨")
        .sampler = sampler.map(|path| SamplerBinding {
        path: path.to_owned(),
    });
    project
}

/// ⭐ S21（任务单 `#78`；⭐ 本单核心的**反向对照**）：`sampler` 缺席 ⇒ 快照与渲染与
/// **接线前**逐位相同。
///
/// # 判定量
///
/// 两条臂（无设备链 / 带音色）的端到端 **FNV-1a 指纹**必须等于 [`BASELINE_PLAIN`]／
/// [`BASELINE_TUNED`] —— 那两个字面值是**接线前**（HEAD `720db9f1`，即本单的第一条
/// 命令之后）在同一夹具、同一量子数、同一条产品路径上实测的（同 S5 的口径）。
/// 另加一条**结构腿**：`sampler = None` ⇒ `sfz_pending()` 必须**空**。
///
/// # 怎么变红
///
/// 在 `from_project_with_latencies` 里把 `track.sampler` 也塞进**摊平表**（或让
/// 实时侧读 `sfz_pending`）⇒ 第二条腿（`sfz_pending()` 空）与第一条腿（指纹）当场红。
#[test]
fn s21_an_absent_sampler_is_bit_identical_to_before_the_wiring() {
    let plain = note_project(&SFZ_NOTES);
    let plain_snapshot = EngineSnapshot::from_project(&plain.project, 1).expect("快照");
    assert!(
        plain_snapshot.sfz_pending().is_empty(),
        "⛔ `sampler = None` ⇒ 待摊平表必须为空（实得 {} 条）",
        plain_snapshot.sfz_pending().len()
    );
    assert!(plain_snapshot.pending_sfz(&plain.track).is_none());

    let rendered = render(&plain.project, SFZ_QUANTA);
    assert!(rendered.nonzero() > 0, "夹具必须真的出声（否则等号是空转）");
    println!(
        "[engine-sfz/S21] `sampler = None` 无设备链: 帧={} 非零={} 峰值={} 指纹={} (0x{:016x})",
        rendered.frames(),
        rendered.nonzero(),
        rendered.peak(),
        rendered.fingerprint(),
        rendered.fingerprint(),
    );
    let plain_checked = check_fingerprint(
        "`sampler = None` 无设备链",
        rendered.fingerprint(),
        BASELINE_PLAIN,
    );

    let tuned = tuned_project(&SFZ_NOTES, MixSpec::tone(800.0, 0.3));
    let tuned_snapshot = EngineSnapshot::from_project(&tuned.project, 1).expect("快照");
    assert!(tuned_snapshot.sfz_pending().is_empty());
    let rendered_tuned = render(&tuned.project, SFZ_QUANTA);
    println!(
        "[engine-sfz/S21] `sampler = None` 音色(800, 0.3): 帧={} 非零={} 峰值={} 指纹={} (0x{:016x})",
        rendered_tuned.frames(),
        rendered_tuned.nonzero(),
        rendered_tuned.peak(),
        rendered_tuned.fingerprint(),
        rendered_tuned.fingerprint(),
    );
    let tuned_checked = check_fingerprint(
        "`sampler = None` 音色(800, 0.3)",
        rendered_tuned.fingerprint(),
        BASELINE_TUNED,
    );

    assert_eq!(
        plain_checked, tuned_checked,
        "两条臂必须在**同一平台判定**下（否则本判据的读数不可比）"
    );
}

/// ⭐ S22（任务单 `#78`；**正向**）：`sampler = Some(路径)` ⇒ 快照里出现**该轨**的
/// 待摊平项，路径**逐字**相同。
///
/// # 判定量
///
/// * `sfz_pending()` **恰好 1 条**、键就是那条 MIDI 轨（母线⛔ 不在表里）；
/// * `pending_sfz(track).path()` **逐字**等于模型里那个路径（⛔ 不规范化、⛔ 不改写）；
/// * ⛔ **摊平表 `sfz()` 仍空** —— 引擎没有凭空摊平（那需要读盘）；
/// * 反向对照：同一夹具把 `sampler` 清回 `None` ⇒ 待摊平表**空**。
#[test]
fn s22_a_sampler_path_lands_in_the_snapshot_as_a_pending_item() {
    let fixture = note_project(&SFZ_NOTES);
    let project = project_with_sampler(&fixture, Some(SAMPLER_PATH));
    let snapshot = EngineSnapshot::from_project(&project, 1).expect("快照");

    let paths: Vec<&str> = snapshot
        .sfz_pending()
        .values()
        .map(PendingSfz::path)
        .collect();
    println!(
        "[engine-sfz/S22] 待摊平条数 = {}；路径 = {paths:?}；摊平表条数 = {}；\
         母线在待摊平表里 = {}",
        snapshot.sfz_pending().len(),
        snapshot.sfz().len(),
        snapshot.sfz_pending().contains_key(&fixture.master),
    );

    assert_eq!(
        snapshot.sfz_pending().len(),
        1,
        "⭐ `sampler = Some(…)` ⇒ 恰好一条待摊平项"
    );
    let pending = snapshot
        .pending_sfz(&fixture.track)
        .expect("⭐ 正向：那条 MIDI 轨必须出现在待摊平表里");
    assert_eq!(
        pending.path(),
        SAMPLER_PATH,
        "⭐ 路径必须**逐字**来自模型（⛔ 不规范化、⛔ 不查存在性）"
    );
    assert!(
        !snapshot.sfz_pending().contains_key(&fixture.master),
        "没绑定 `sampler` 的轨（母线）⛔ 不得出现在待摊平表里"
    );
    assert!(
        snapshot.sfz().is_empty(),
        "⛔ 引擎不读盘 ⇒ 摊平表必须仍为空（只有控制侧解码后 `with_sfz` 才填它）"
    );

    // 反向对照：同一夹具、只把 `sampler` 清回 `None` ⇒ 待摊平表空。
    let cleared = project_with_sampler(&fixture, None);
    let cleared_snapshot = EngineSnapshot::from_project(&cleared, 1).expect("快照");
    assert!(
        cleared_snapshot.sfz_pending().is_empty(),
        "反向对照：`sampler = None` ⇒ 待摊平表必须为空"
    );
}

/// ⭐ S23（任务单 `#78`）：**待摊平项是纯事实** —— 它⛔ 不改渲染、⛔ 不报错；
/// 而 `with_sfz` 注入摊平表时**取代**它。
///
/// # 判定量
///
/// 1. 同夹具 `None`／`Some(不存在的路径)` 两条臂的端到端 FNV-1a 指纹**逐位相同**
///    （且都真的出声）⇒ ⭐ 引擎⛔ 没有第二份音源事实源；
/// 2. 那个路径**磁盘上不存在**，但 `from_project` 仍 `Ok` ⇒ ⭐ 引擎⛔ 不读盘
///    （真读盘会 `Err` 或至少要碰文件系统）；
/// 3. 控制侧注入摊平表（`with_sfz`）⇒ 待摊平项被**取代**（表清空、`sfz()` 一条），
///    且指纹**变**（⇒ 摊平表真的接上了实时侧）。
///
/// # 怎么变红
///
/// 把 `with_sfz` 里那句 `self.sfz_pending.remove(&track)` 删掉 ⇒ 腿 ③ 的"表清空"红；
/// 让 `from_project` 去读那个路径 ⇒ 腿 ② 红（不存在的文件必然 `Err`）。
#[test]
fn s23_a_pending_path_changes_nothing_audible_and_is_superseded_by_with_sfz() {
    let fixture = note_project(&SFZ_NOTES);
    let bare_project = project_with_sampler(&fixture, None);
    let pending_project = project_with_sampler(&fixture, Some(SAMPLER_PATH));

    let bare = render(&bare_project, SFZ_QUANTA);
    let with_pending = render(&pending_project, SFZ_QUANTA);
    println!(
        "[engine-sfz/S23] `sampler = None`: 非零={} 指纹={} (0x{:016x})；\
         `sampler = Some({SAMPLER_PATH})`（文件不存在）: 非零={} 指纹={} (0x{:016x})",
        bare.nonzero(),
        bare.fingerprint(),
        bare.fingerprint(),
        with_pending.nonzero(),
        with_pending.fingerprint(),
        with_pending.fingerprint(),
    );
    assert!(
        bare.nonzero() > 0 && with_pending.nonzero() > 0,
        "两条臂都必须真的出声（否则'逐位相同'可能只是两边都哑）"
    );
    assert_eq!(
        with_pending.fingerprint(),
        bare.fingerprint(),
        "⭐ 待摊平项⛔ 不改渲染：`None` 与 `Some(…)` 的输出必须**逐位相同**"
    );
    assert_eq!(
        bits(&with_pending.left),
        bits(&bare.left),
        "⭐ 左声道逐位相同（指纹之外的独立见证）"
    );

    // ② 不存在的路径仍能编译成快照 ⇒ ⭐ 引擎⛔ 不读盘。
    let snapshot = EngineSnapshot::from_project(&pending_project, 1)
        .expect("⭐ 引擎不读盘 ⇒ 磁盘上不存在的 SFZ 路径也必须能编译成快照");
    assert!(snapshot.sfz().is_empty(), "⛔ 没有摊平表（引擎没读盘）");

    // ③ 控制侧（允许 I/O）解码后注入 ⇒ 摊平表**取代**待摊平项。
    let sfz = SfzInstrument::load(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n".to_owned(),
        &Default::default(),
    )
    .expect("SFZ 必须解析成功");
    let sample = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    let plan = SfzPlan::prepare_with_samples(&sfz, &[("a.wav".to_owned(), sample)], 48_000.0)
        .expect("多采样摊平必须成功");
    let armed = snapshot.with_sfz(fixture.track, plan);
    println!(
        "[engine-sfz/S23] 注入摊平表之后：待摊平条数 = {}；摊平表条数 = {}",
        armed.sfz_pending().len(),
        armed.sfz().len()
    );
    assert!(
        armed.sfz_pending().is_empty(),
        "⭐ 摊平表**取代**待摊平项（否则控制侧会重复解码同一条轨）"
    );
    assert_eq!(armed.sfz().len(), 1, "注入一次 ⇒ 摊平表一条");
    let armed_audio = render_snapshot(armed, SFZ_QUANTA);
    assert_ne!(
        armed_audio.fingerprint(),
        bare.fingerprint(),
        "⭐ 摊平表必须真的接上实时侧（否则'取代'只是账面动作）"
    );
}

/// ⭐ S24（任务单 `#78`）：**缺样本口径不变**，且它能**经新接线**走到。
///
/// 前三条判据只证明"路径进快照"；本条证明⭐ **新接线与控制侧既有分工衔接得上**：
/// 由 `sfz_pending()` 里的路径 →（控制侧"读盘"／解析）→ 只解码 `a.wav` →
/// `prepare_with_samples` → `render_track`：缺 `missing.wav` 的那条区域
/// **`NO_SAMPLE` ⇒ 不建声部 ＋ 计数**（既有口径，`R711`／`needs-7`）。
///
/// # 判定量
///
/// * `silent_region_count() == 1`、`missing_sample_paths() == ["missing.wav"]`、
///   该区域 `sample_index == PreparedRegion::NO_SAMPLE`；
/// * 引擎侧：key=64（缺样本）那次 `render_track` ⇒ `sfz_active_voices == Some(0)`
///   ＋ 输出**逐位 0**（⛔ 不建声部、⛔ 不回退播别人的采样）；
/// * 反向对照：同一份 plan 上 key=60（有样本）**真的出声** ⇒ 上一条不是"两边都哑"。
#[test]
fn s24_a_missing_sample_is_still_silent_and_counted_through_the_new_wiring() {
    const ONE_MISSING: &str = "<region> sample=a.wav key=60 pitch_keycenter=60\n\
                               <region> sample=missing.wav key=64 pitch_keycenter=60\n";
    let fixture = note_project(&SFZ_NOTES);
    let project = project_with_sampler(&fixture, Some(SAMPLER_PATH));
    let snapshot = EngineSnapshot::from_project(&project, 1).expect("快照");

    // 控制侧（模拟"读盘"）：路径必须**先**从待摊平项取到。
    let pending = snapshot
        .pending_sfz(&fixture.track)
        .expect("⭐ 待摊平项是控制侧的唯一入口");
    assert_eq!(pending.path(), SAMPLER_PATH);
    let sfz = SfzInstrument::load(ONE_MISSING.to_owned(), &Default::default()).expect("解析");
    assert_eq!(
        sfz.referenced_sample_paths().expect("路径全集"),
        ["a.wav".to_owned(), "missing.wav".to_owned()],
        "控制侧据此知道该解码哪两份（`missing.wav` 读不到 ⇒ ⛔ 不放进提供表）"
    );
    let a = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    let plan = SfzPlan::prepare_with_samples(&sfz, &[("a.wav".to_owned(), a)], 48_000.0)
        .expect("多采样摊平必须成功");
    let prepared = plan.prepared();
    println!(
        "[engine-sfz/S24] silent = {}、missing = {:?}、sample_content = {}、\
         key=64 的 sample_index = {}",
        prepared.silent_region_count(),
        prepared.missing_sample_paths(),
        prepared.sample_content_label(),
        prepared.regions()[1].sample_index(),
    );
    assert_eq!(prepared.silent_region_count(), 1, "⭐ 缺样本的区域计数");
    assert_eq!(
        prepared.missing_sample_paths().to_vec(),
        vec!["missing.wav".to_owned()],
        "⭐ 缺失路径必须**具名**登记（⛔ 不静默）"
    );
    assert_eq!(
        prepared.regions()[1].sample_index(),
        PreparedRegion::NO_SAMPLE,
        "⭐ 缺样本 ⇒ `NO_SAMPLE`（⛔ 不是回退到 `samples[0]`）"
    );

    // 引擎侧：缺样本那个键**不建声部**（`sfz_active_voices == Some(0)` ＋ 逐位 0）。
    let engine_track = EntityId::new();
    let mut engine = engine_with_track(engine_track);
    let missing_note = NoteSchedule::from_sorted(vec![ScheduledNote::new(
        0,
        12_000,
        64,
        127,
        support::yeban_dsp_note_to_hz(64),
        1.0,
        48_000.0,
    )]);
    let mut missing_out = vec![0.0f32; S24_BLOCK];
    engine.render_track(
        engine_track,
        Some(&missing_note),
        Some(prepared),
        &mut missing_out,
    );
    assert_eq!(
        engine.sfz_active_voices(engine_track),
        Some(0),
        "⭐ 缺样本 ⇒ **不建声部**（池里 0 个活声部）"
    );
    assert!(
        missing_out.iter().all(|s| *s == 0.0),
        "⭐ 缺样本的区域必须**逐位静音**"
    );

    // 反向对照：同一份 plan，key=60（有样本）必须真的出声。
    // ⚠ 用一条**新的**引擎：`SynthEngine` 的每槽 `cursor` 单调前进（同 S18 每条腿
    // 各建一台的理由）⇒ 在同一个引擎上换一份调度表不会重新触发。
    let sibling_note = NoteSchedule::from_sorted(vec![ScheduledNote::new(
        0,
        12_000,
        60,
        127,
        support::yeban_dsp_note_to_hz(60),
        1.0,
        48_000.0,
    )]);
    let mut sibling_engine = engine_with_track(engine_track);
    let mut sibling_out = vec![0.0f32; S24_BLOCK];
    sibling_engine.render_track(
        engine_track,
        Some(&sibling_note),
        Some(prepared),
        &mut sibling_out,
    );
    println!(
        "[engine-sfz/S24] 反向对照 key=60：活声部 = {:?}、非零 = {}",
        sibling_engine.sfz_active_voices(engine_track),
        sibling_out.iter().filter(|s| **s != 0.0).count(),
    );
    assert!(
        sibling_engine.sfz_active_voices(engine_track).unwrap_or(0) > 0
            && sibling_out.iter().any(|s| *s != 0.0),
        "反向对照：缺的**只有** `missing.wav` ⇒ key=60 那条区域必须照常出声"
    );
}

// ---------------------------------------------------------------------------
// ⭐ S25／S26／S27：摊平表的**字节预算**（任务单 `#84`；`sfz-needs-8` 的"可判"那一半）
//
// 背景（`sfz-needs-8` 逐字）："摊平表无字节预算／无流式（样本 PCM 整段 clone）"。
// ⭐ 本片要的**不是**流式，而是"让它可判"：一条**读数**（拆成区域表／PCM／路径文本）
// ＋ 一条**判据**（`bytes ≤ N`，`N` 的来源可复算）＋ 一条**超预算口径**
// （引擎只报数、控制侧决定 —— 理由见 `PreparedSfz::budget_overrun`）。
// ---------------------------------------------------------------------------

/// ⭐ 字节预算夹具的**声明形状**（这三个常量就是"这份音色库有多大"的声明）。
///
/// * `BUDGET_FIXTURE_REGIONS = 3` 条区域；
/// * 去重后 **2** 份样本：`a.wav` 480 帧、`b.wav` 1920 帧 ⇒ PCM ＝ `(480 + 1920) × 4`；
/// * 路径文本 ＝ `"a.wav" + "b.wav"`。
const BUDGET_FIXTURE_REGIONS: usize = 3;
const BUDGET_FIXTURE_A_FRAMES: usize = 480;
const BUDGET_FIXTURE_B_FRAMES: usize = 1920;
const BUDGET_FIXTURE_PCM_FRAMES: usize = BUDGET_FIXTURE_A_FRAMES + BUDGET_FIXTURE_B_FRAMES;
const BUDGET_FIXTURE_PATH_BYTES: usize = "a.wav".len() + "b.wav".len();

/// ⭐ 字节预算夹具的 SFZ 文本：两条区域引 `a.wav`（不同键）、一条引 `b.wav`
/// ⇒ **去重后 2 份样本**（去重口径本身由 S12 钉住，这里只借它造出"样本 < 区域"的形状）。
const BUDGET_FIXTURE_SFZ: &str = "<region> sample=a.wav key=60 pitch_keycenter=60\n\
                                  <region> sample=a.wav key=62 pitch_keycenter=62\n\
                                  <region> sample=b.wav key=64 pitch_keycenter=64\n";

/// ⭐ 建一份**声明形状已知**的摊平表（S25／S26／S27 共用）。
fn budget_fixture_plan() -> PreparedSfz {
    let instrument = SfzInstrument::load(BUDGET_FIXTURE_SFZ.to_owned(), &Default::default())
        .expect("字节预算夹具的 SFZ 必须解析成功");
    PreparedSfz::prepare_with_samples(
        &instrument,
        &[
            (
                "a.wav".to_owned(),
                InMemorySample::sine(440.0, 48_000.0, BUDGET_FIXTURE_A_FRAMES),
            ),
            (
                "b.wav".to_owned(),
                InMemorySample::sine(660.0, 48_000.0, BUDGET_FIXTURE_B_FRAMES),
            ),
        ],
        48_000.0,
    )
    .expect("字节预算夹具的摊平必须成功")
}

/// ⭐ S25（本单新增；`sfz-needs-8`）：摊平表的字节占用**拆成三项** ＋ 一条**可判的预算口径**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 一份 [`PreparedSfz`]（[`budget_fixture_plan`]：3 条区域、2 份样本、2400 帧 PCM）；
/// 单位 ＝ **字节**。三项拆开：
///
/// | 项 | 换算 | 夹具读数（字节） |
/// | :--- | :--- | ---: |
/// | 区域表 | `size_of::<PreparedRegion>() × 3` | 由 `size_of` 现读（⛔ 不手抄） |
/// | PCM | `4 × 2400` | **9 600** |
/// | 路径文本 | `"a.wav" + "b.wav"` | **10** |
///
/// # `N` 的来源（⭐ 为什么是这个数）
///
/// `N = SfzByteBudget::for_layout(3, 2400, 10)`：由夹具**自己声明的形状**按
/// [`PreparedSfz::region_bytes`] ／ [`PreparedSfz::pcm_bytes`] ／ [`PreparedSfz::path_bytes`]
/// 那**同一份**换算反推 ⇒ 上界**恰好**是该形状的精确字节数。于是判据 "`bytes ≤ N`"
/// 钉住的是"**读数里没有隐藏的第四份开销**"（例如 `Vec` 的容量余量、或有人往
/// `PreparedRegion` 里加了大字段却没进读数），⛔ **不是**"某个数比某个拍出来的阈值小"。
/// 口径与 `yeban-decode` 的 `PcmBudget::for_layout` 同一形状（那边由 `pcm_bytes_for`
/// 一条换算给出，可被判据复算）。
///
/// # 判定量
///
/// * 三项**各自的精确读数**（⛔ 不是 `> 0` 那种地板断言）＋ 合计 ＝ 既有 `memory_bytes()`；
/// * `budget_overrun(&N).is_within() == true`（三项超出读数全 0）；
/// * ⭐ **内置反向腿（⛔ 让"绿"不能是空的）**：三个维度**各自** −1 字节 ⇒
///   该维度恰好报 **1** 字节超出、`is_within() == false`、且**只有**一个维度非 0。
#[test]
fn s25_the_flat_table_byte_reading_is_split_and_has_a_judgeable_budget() {
    let plan = budget_fixture_plan();
    let region_struct = core::mem::size_of::<PreparedRegion>();
    assert_eq!(
        plan.region_count(),
        BUDGET_FIXTURE_REGIONS,
        "⭐ 声明与夹具必须一致（否则下面的 N 就不是这份夹具的形状）"
    );

    // ① 现状读数（拆开）：区域表 ／ PCM ／ 路径文本 ／ 合计。
    let usage = plan.byte_usage();
    println!(
        "[engine-sfz/S25] 摊平表字节读数（拆开）：区域表 = size_of::<PreparedRegion>() {region_struct} B × \
         {BUDGET_FIXTURE_REGIONS} = {}；PCM = 4 B × {BUDGET_FIXTURE_PCM_FRAMES} = {}；\
         路径文本 = {}；合计 = {}（＝ memory_bytes() = {}）",
        usage.region_bytes(),
        usage.pcm_bytes(),
        usage.path_bytes(),
        usage.total_bytes(),
        plan.memory_bytes(),
    );

    // ② 三项各自的**精确**读数（⛔ 不是地板断言）。
    assert_eq!(
        usage.region_bytes(),
        region_struct * BUDGET_FIXTURE_REGIONS,
        "区域表 ＝ 结构体字节数 × 区域数"
    );
    assert_eq!(
        usage.pcm_bytes(),
        4 * BUDGET_FIXTURE_PCM_FRAMES,
        "PCM ＝ 4 B × 2400 帧（去重后 2 份样本）"
    );
    assert_eq!(
        usage.pcm_bytes(),
        plan.pcm_bytes(),
        "⭐ 与既有 `pcm_bytes()` **同一份求和**（⛔ 不是第二套口径）"
    );
    assert_eq!(
        usage.path_bytes(),
        BUDGET_FIXTURE_PATH_BYTES,
        "路径文本 ＝ `\"a.wav\" + \"b.wav\"`（⛔ 不含 `String` 容量余量）"
    );
    // ③ 合计 ＝ 既有 `memory_bytes()`（⛔ 不是第二套口径）。
    assert_eq!(
        usage.total_bytes(),
        plan.memory_bytes(),
        "⭐ 三项之和必须**逐字节等于**既有的 memory_bytes()"
    );
    assert_eq!(
        usage.total_bytes(),
        usage.region_bytes() + usage.pcm_bytes() + usage.path_bytes(),
        "合计 ＝ 三项之和"
    );

    // ④ 预算判据：bytes ≤ N（N 由夹具声明的形状反推；闭区间 ⇒ 恰好等于上界通过）。
    let declared = SfzByteBudget::for_layout(
        BUDGET_FIXTURE_REGIONS,
        BUDGET_FIXTURE_PCM_FRAMES,
        BUDGET_FIXTURE_PATH_BYTES,
    );
    println!(
        "[engine-sfz/S25] 预算 N = for_layout({BUDGET_FIXTURE_REGIONS}, {BUDGET_FIXTURE_PCM_FRAMES}, \
         {BUDGET_FIXTURE_PATH_BYTES}) = {{区域表 ≤ {}，PCM ≤ {}，路径 ≤ {}}}；\
         实际 = {{区域表 {}，PCM {}，路径 {}}} ⇒ 超出 = {{区域表 {}，PCM {}，路径 {}}}（is_within = {}）",
        declared.max_region_bytes(),
        declared.max_pcm_bytes(),
        declared.max_path_bytes(),
        usage.region_bytes(),
        usage.pcm_bytes(),
        usage.path_bytes(),
        plan.budget_overrun(&declared).region_bytes(),
        plan.budget_overrun(&declared).pcm_bytes(),
        plan.budget_overrun(&declared).path_bytes(),
        plan.budget_overrun(&declared).is_within(),
    );
    assert_eq!(
        declared.max_region_bytes(),
        usage.region_bytes(),
        "N 的区域表那一维必须恰好等于夹具的实际区域表字节数（同一份换算）"
    );
    assert_eq!(
        declared.max_pcm_bytes(),
        usage.pcm_bytes(),
        "N 的 PCM 那一维必须恰好等于夹具的实际 PCM 字节数"
    );
    assert_eq!(
        declared.max_path_bytes(),
        usage.path_bytes(),
        "N 的路径那一维必须恰好等于夹具的实际路径文本字节数"
    );
    let within = plan.budget_overrun(&declared);
    assert!(
        within.is_within(),
        "⭐ 夹具的实际占用必须 ≤ 声明形状反推的 N（超出读数 = {within:?}）"
    );
    assert_eq!(within.total_bytes(), 0, "在预算内 ⇒ 三项超出量全 0");

    // ⑤ ⭐ 内置反向腿：每个维度各 −1 字节 ⇒ 该维度恰好报 1 字节超出（⛔ 绿不是空的）。
    let tight = [
        (
            "区域表",
            SfzByteBudget::new(
                declared.max_region_bytes() - 1,
                declared.max_pcm_bytes(),
                declared.max_path_bytes(),
            ),
        ),
        (
            "PCM",
            SfzByteBudget::new(
                declared.max_region_bytes(),
                declared.max_pcm_bytes() - 1,
                declared.max_path_bytes(),
            ),
        ),
        (
            "路径文本",
            SfzByteBudget::new(
                declared.max_region_bytes(),
                declared.max_pcm_bytes(),
                declared.max_path_bytes() - 1,
            ),
        ),
    ];
    for (name, budget) in tight {
        let over = plan.budget_overrun(&budget);
        let nonzero = [over.region_bytes(), over.pcm_bytes(), over.path_bytes()]
            .iter()
            .filter(|bytes| **bytes != 0)
            .count();
        println!(
            "[engine-sfz/S25] 反向腿（{name} −1 B）⇒ 超出 = {{区域表 {}，PCM {}，路径 {}}}、\
             is_within = {}",
            over.region_bytes(),
            over.pcm_bytes(),
            over.path_bytes(),
            over.is_within(),
        );
        assert!(
            !over.is_within(),
            "⭐ {name} 预算 −1 字节 ⇒ 判据必须红（实得 {over:?}）"
        );
        assert_eq!(over.total_bytes(), 1, "⭐ {name}：恰好超出 1 字节");
        assert_eq!(
            nonzero, 1,
            "⭐ {name}：**只有**该维度非 0（其余两项在预算内）"
        );
    }
}

/// ⭐ S26（本单新增；`sfz-needs-8`）：**超预算会怎样** —— 引擎**只报数**。
///
/// 构造一份**真的超预算**的表：同一份夹具（PCM 9 600 字节），但预算按"只给 `a.wav`
/// 那一份"声明 ＝ `for_layout(3, 480, 10)` ⇒ PCM 超出 `9600 − 1920` ＝ **7 680** 字节。
///
/// # 三条腿（对应"超预算怎么办"的候选 ①②③）
///
/// 1. **⛔ 不报错**：`prepare_with_samples` 仍然返回 `Ok`（本测试能走到断言就是证据）；
/// 2. **⛔ 不截断 / 不改摊平结果**：`budget_overrun` 前后 —— `byte_usage` ／ `sample_count`
///    ／ `pcm_bytes` ／ `region_count` ／ **渲染输出**全部**相同**；
///    ⭐ 零预算（`new(0, 0, 0)`）也**只**报数（三项全报超），表一个字不变；
/// 3. **只报数**：读数**逐项**给出超出量（区域表 0 ／ PCM 7 680 ／ 路径 0）——
///    于是"超了多少、超在哪一项"是机械可读的（归属裁决与三条理由见
///    `PreparedSfz::budget_overrun`）。
#[test]
fn s26_over_budget_is_reported_not_refused() {
    let plan = budget_fixture_plan();
    let before = plan.byte_usage();
    let before_samples = plan.sample_count();
    let before_pcm = plan.pcm_bytes();
    let before_regions = plan.region_count();

    // 渲染参照：`budget_overrun` 不得改变任何渲染读数。
    let render = |plan: &PreparedSfz| {
        let mut out = vec![0.0f32; 512];
        let written = plan.render_block_into(64, 100, &mut out);
        (written, out)
    };
    let reference = render(&plan);

    // ① 真的超预算：预算按"只给 `a.wav` 那一份"声明。
    let only_a = SfzByteBudget::for_layout(
        BUDGET_FIXTURE_REGIONS,
        BUDGET_FIXTURE_A_FRAMES,
        BUDGET_FIXTURE_PATH_BYTES,
    );
    let over = plan.budget_overrun(&only_a);
    println!(
        "[engine-sfz/S26] 超预算读数：N = for_layout({BUDGET_FIXTURE_REGIONS}, {BUDGET_FIXTURE_A_FRAMES}, \
         {BUDGET_FIXTURE_PATH_BYTES}) ⇒ 超出 = {{区域表 {}，PCM {}，路径 {}}}、合计 {} 字节、is_within = {}；\
         ⭐ prepare_with_samples 仍 Ok（⛔ 不报错），样本数 = {}、PCM = {} 字节、区域数 = {}",
        over.region_bytes(),
        over.pcm_bytes(),
        over.path_bytes(),
        over.total_bytes(),
        over.is_within(),
        plan.sample_count(),
        plan.pcm_bytes(),
        plan.region_count(),
    );
    assert!(
        !over.is_within(),
        "⭐ 这份夹具对「只给 `a.wav`」的预算必须**超**（否则本判据无话可说）"
    );
    assert_eq!(over.region_bytes(), 0, "区域表那一维仍在预算内");
    assert_eq!(
        over.pcm_bytes(),
        4 * BUDGET_FIXTURE_B_FRAMES,
        "⭐ PCM 恰好超出 `b.wav` 那一份（1920 帧 × 4 = 7680 字节）"
    );
    assert_eq!(over.path_bytes(), 0, "路径文本那一维仍在预算内");
    assert_eq!(over.total_bytes(), 7_680, "合计超出 = 7680 字节");

    // ② ⭐ 零预算：三项全报超 ⇒ 仍然**只报数**。
    let zero = plan.budget_overrun(&SfzByteBudget::new(0, 0, 0));
    println!(
        "[engine-sfz/S26] 零预算读数：超出 = {{区域表 {}，PCM {}，路径 {}}}、合计 {} 字节（⭐ 仍不改表）",
        zero.region_bytes(),
        zero.pcm_bytes(),
        zero.path_bytes(),
        zero.total_bytes(),
    );
    assert!(!zero.is_within(), "零预算 ⇒ 必然超");
    assert_eq!(
        zero.region_bytes(),
        before.region_bytes(),
        "零预算 ⇒ 区域表超出量 ＝ 它的全部占用（⛔ 不是被截断后的值）"
    );

    // ③ ⛔ 摊平结果**逐位不变**（"只报数"的机械证据）。
    let after = plan.byte_usage();
    let rendered = render(&plan);
    println!(
        "[engine-sfz/S26] 摊平结果逐位不变：byte_usage {before:?} → {after:?}；\
         sample_count {before_samples} → {}；pcm_bytes {before_pcm} → {}；region_count {before_regions} → {}；\
         渲染 (写入 {}, 非零 {}) → (写入 {}, 非零 {})",
        plan.sample_count(),
        plan.pcm_bytes(),
        plan.region_count(),
        reference.0,
        reference.1.iter().filter(|s| **s != 0.0).count(),
        rendered.0,
        rendered.1.iter().filter(|s| **s != 0.0).count(),
    );
    assert_eq!(after, before, "⭐ 预算判定不得改变字节读数");
    assert_eq!(plan.sample_count(), before_samples, "⛔ 不丢样本");
    assert_eq!(plan.pcm_bytes(), before_pcm, "⛔ 不裁 PCM");
    assert_eq!(plan.region_count(), before_regions, "⛔ 不丢区域");
    assert_eq!(rendered.0, reference.0, "⛔ 不改变写入帧数");
    assert_eq!(
        rendered.1, reference.1,
        "⭐ 超预算判定之后，渲染输出必须**逐位相同**（只报数 ⇒ 表没被改）"
    );
    assert!(
        rendered.1.iter().any(|sample| *sample != 0.0),
        "⭐ 见证：这条渲染路径**真的出声**（⛔ 挡住「什么都没渲染」的假绿）"
    );
}

/// ⭐ S27（本单新增；`sfz-needs-8` 的**动机**）："巨大音色库"这件事今天**可判**。
///
/// # 为什么要这条（逐字背景）
///
/// `sfz-needs-8` ＝ "摊平表无字节预算／无流式（样本 PCM 整段 clone）" ⇒ 1 GB PCM 的
/// 音色库会被**整段读进内存并 clone 进摊平表**。本判据给出的是**那个库会不会被看出来**。
///
/// # 量什么（对象 ＋ 单位）
///
/// 对象 ＝ 一份**参数化**的 [`SfzByteUsage`]（128 条区域 ＋ **1 GiB** PCM ＋ 128 × 12 字节
/// 路径文本）；单位 ＝ **字节**。⭐ 判定是**纯算术**（[`SfzByteUsage::overrun`]）⇒
/// **⛔ 不需要真的分配 1 GiB**（那正是"可判"与"实现流式"的区别）。
///
/// # 判定量
///
/// * 对 **512 MiB** 的 PCM 上界：`pcm` 超出 **恰好** `1 GiB − 512 MiB` ＝ **536 870 912** 字节、
///   `is_within() == false`、区域表与路径两维**为 0**；
/// * ⭐ **反向腿**（闭区间）：上界给**恰好 1 GiB** ⇒ **通过**（⛔ 判据不是"永远红"）。
#[test]
fn s27_a_gib_scale_library_is_visible_to_the_budget() {
    const GIB: usize = 1 << 30;
    const HALF_GIB: usize = 1 << 29;
    let region_bytes = core::mem::size_of::<PreparedRegion>() * 128;
    let path_bytes = 128 * 12;
    let usage = SfzByteUsage::new(region_bytes, GIB, path_bytes);
    let budget = SfzByteBudget::new(region_bytes, HALF_GIB, path_bytes);
    let over = usage.overrun(&budget);
    println!(
        "[engine-sfz/S27] 1 GiB 级 PCM（128 条区域）：读数 = {{区域表 {region_bytes}，PCM {GIB}，路径 {path_bytes}}}、\
         预算 = {{区域表 {region_bytes}，PCM {HALF_GIB}，路径 {path_bytes}}} ⇒ \
         超出 = {{区域表 {}，PCM {}，路径 {}}}、合计 {} 字节、is_within = {}",
        over.region_bytes(),
        over.pcm_bytes(),
        over.path_bytes(),
        over.total_bytes(),
        over.is_within(),
    );
    assert_eq!(
        usage.total_bytes(),
        region_bytes + GIB + path_bytes,
        "读数合计"
    );
    assert!(
        !over.is_within(),
        "⭐ 1 GiB PCM 对 512 MiB 的预算必须超（否则「巨大音色库不可判」）"
    );
    assert_eq!(
        over.pcm_bytes(),
        GIB - HALF_GIB,
        "⭐ 恰好超出 512 MiB ＝ 536 870 912 字节"
    );
    assert_eq!(
        over.total_bytes(),
        536_870_912,
        "合计超出 ＝ 536 870 912 字节"
    );
    assert_eq!(
        (over.region_bytes(), over.path_bytes()),
        (0, 0),
        "区域表与路径两维在预算内（⇒ 超预算**指向** PCM 这一项）"
    );
    // 反向腿：闭区间 ⇒ 上界恰好等于占用时**通过**（⛔ 判据不是"永远红"）。
    let exact = SfzByteBudget::new(region_bytes, GIB, path_bytes);
    assert!(
        usage.overrun(&exact).is_within(),
        "⭐ 上界恰好等于占用时必须**通过**（闭区间，与 `PcmBudget` 同口径）"
    );
}

// ---------------------------------------------------------------------------
// ⭐ S28～S33：**SFZ 循环点接进实时播放**（任务单 `#91` 的"循环那一半"）
//
// ⚠ **本单是接线，⛔ 不是新实现**：`loop_start` / `loop_end` / `loop_mode` 的解析
// 与"哪些模式才循环 / 退化窗口不循环"的裁决**早就存在**于 `yeban-sfz`
// （`instrument.rs` 的 `Region` 三字段与 `LoopMode` 白名单、`playback.rs` 的
// `Region::loop_window`）。缺的只是**播放层装不下** —— 摊平表此前不携带这三个字段。
// 本片把它们搬进 `PreparedRegion`、在唯一的逐样本循环 `mix_span_into` 里回绕，
// 并按 `region_index` 从逐块路径读回。
//
// 判据的分工：
//   * S28 —— 周期**逐样本精确**（下标序列，⛔ 不是"波形看起来在重复"）；
//   * S29 —— `no_loop` / `one_shot` **不循环** ＋ `one_shot` 忽略 note-off；
//   * S30 —— 字段**真的**被播放层读到（两份只差一个数的夹具）；
//   * S31 —— 输入政策不变（非法取值仍响亮 `Err`）；
//   * S32 —— `loop_sustain ≡ loop_continuous` 的登记**可判**；
//   * S33 —— 不带 `loop_*` 的既有夹具**逐位不变**（改动前实测指纹）。
// ---------------------------------------------------------------------------

/// ⭐ 循环夹具的 PCM 长度（帧；`rate` 恒 1.0 ⇒ 源下标与输出帧一一对应）。
const LOOP_PCM_FRAMES: usize = 400;

/// ⭐ 循环窗口（源采样点；半开 `[LOOP_START, LOOP_END)`）。
const LOOP_START: usize = 100;
const LOOP_END: usize = 164;

/// ⭐ 循环周期 ＝ `loop_end − loop_start`（帧）。
const LOOP_PERIOD: usize = LOOP_END - LOOP_START;

/// ⭐ 渲染帧数：跨过 **3 整圈**（⇒ "周期"不是从一段里猜的）。
const LOOP_RENDER_FRAMES: usize = LOOP_END + 3 * LOOP_PERIOD;

/// ⭐ **可解码的斜坡样本**：`pcm[i] = (i + 1) / 1024`。
///
/// 分母是 2 的幂 ⇒ 在 binary32 下**逐位精确**（`i < 2²⁴`）。
/// ⚠ 从 `i + 1` 起（⛔ 不是 `i`）：`pcm[0]` **必须非零**，否则"非零帧数"会把第 0 帧
/// 误记成静音（本单实测过一次 off-by-one）。
/// `gain == 1.0` 时输出**恰好**等于源采样值 ⇒ 判据可以把每个输出帧**反解成源采样
/// 下标**，从而把"循环周期"量成**下标的精确序列**，⛔ 不是"波形看起来像在重复"。
fn ramp_sample(frames: usize) -> InMemorySample {
    InMemorySample {
        pcm: (0..frames)
            .map(|frame| (frame + 1) as f32 / 1024.0)
            .collect(),
        sample_hz: 48_000.0,
    }
}

/// ⭐ 摊平一份**自己给样本**的 SFZ（循环夹具用）。
fn prepare_with(text: &str, sample: &InMemorySample) -> PreparedSfz {
    let instrument = SfzInstrument::load(text.to_owned(), &Default::default())
        .expect("循环夹具的 SFZ 必须解析成功");
    PreparedSfz::prepare(&instrument, sample, 48_000.0).expect("摊平必须成功")
}

/// ⭐ 单区域循环夹具的 SFZ 文本（`key=60`、零移调 ⇒ `rate == 1.0`）。
fn loop_sfz(mode: &str, loop_start: usize, loop_end: usize) -> String {
    format!(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode={mode} \
         loop_start={loop_start} loop_end={loop_end}\n"
    )
}

/// ⭐ 从输出帧**反解源采样下标**（斜坡夹具专用；见 [`ramp_sample`]）。
fn source_index_at(out: &[f32], frame: usize) -> usize {
    (out[frame] * 1024.0) as usize - 1
}

/// ⭐ 触发**一个**声部并渲染 `frames` 帧（实时池路径；⭐ 本单的目标路径）。
fn render_pool(plan: &PreparedSfz, end_sample: u64, frames: usize) -> Vec<f32> {
    let mut pool = SfzVoicePool::new(48_000.0);
    let created = pool.trigger_note(plan, 60, 127, end_sample, 1.0, None);
    assert_eq!(created, 1, "单区域夹具 ⇒ 恰好建 1 个声部");
    let mut out = vec![0.0f32; frames];
    pool.render_into(plan, 0, &mut out);
    out
}

/// ⭐ **实测最小周期**：窗口段 `out[start..start+8)` 第一次**逐位重复**的位置减去 `start`。
///
/// ⛔ 不是"数非零点"：斜坡夹具下任何小于真周期的平移都会**逐位不同** ⇒ 首个重复位置
/// 就是真周期。
fn detect_period(out: &[f32], start: usize, search_to: usize) -> usize {
    const WINDOW: usize = 8;
    let head = &out[start..start + WINDOW];
    for candidate in (start + 1)..=search_to {
        if out[candidate..candidate + WINDOW] == *head {
            return candidate - start;
        }
    }
    panic!(
        "⭐ 在 [{}..{}] 内找不到周期（说明逐样本路径根本没回绕）",
        start + 1,
        search_to
    );
}

/// ⭐ **循环段下标序列的逐帧对账**：`t < start` ⇒ `t`；否则 `start + (t−start) mod period`。
fn loop_index_mismatches(out: &[f32], start: usize, period: usize) -> usize {
    out.iter()
        .enumerate()
        .filter(|(frame, _)| {
            let expected = if *frame < start {
                *frame
            } else {
                start + (*frame - start) % period
            };
            source_index_at(out, *frame) != expected
        })
        .count()
}

/// ⭐ S28（任务单 `#91`；`sfz-needs-6` 的"循环"那一半）：**循环周期逐样本精确**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 一个实时 SFZ 声部（[`SfzVoicePool`]）渲染出的一段输出；单位 ＝ **源采样下标**
/// （由斜坡夹具**逐帧反解**，见 [`ramp_sample`]）。
///
/// # 判定量
///
/// * 摊平表**真的**带出了三个循环字段（`loop_start` / `loop_end` / `loop_mode`）——
///   ⛔ 否则这条判据量到的只是 `PlaybackSpec` 里的读数；
/// * 下标序列**逐帧**等于 `t < 100 ? t : 100 + (t−100) mod 64`（**0 处不符**）；
/// * ⭐ **实测最小周期**（首个窗口段逐位重复的位置）**恰好** `64 ＝ loop_end − loop_start`；
/// * ⭐ 反向腿（⛔ 防空转）：窗口段 `[100,164)` 必须 ≥ 2 个**不同位模式**。
#[test]
fn s28_the_loop_cycle_is_exactly_loop_end_minus_loop_start() {
    let plan = prepare_with(
        &loop_sfz("loop_continuous", LOOP_START, LOOP_END),
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let region = &plan.regions()[0];
    assert_eq!(
        (region.loop_start(), region.loop_end()),
        (LOOP_START as u32, LOOP_END as u32),
        "⭐ 摊平表必须**真的**带出 `loop_start` / `loop_end`（⛔ 不是只落在 `PlaybackSpec` 里）"
    );
    assert_eq!(
        region.loop_mode(),
        LoopMode::LoopContinuous,
        "⭐ 生效循环模式必须进摊平表"
    );
    let window = region
        .loop_window(LOOP_PCM_FRAMES)
        .expect("loop_continuous ＋ 合法窗口 ⇒ 必须有窗口");
    assert_eq!(
        (window.start as usize, window.end as usize),
        (LOOP_START, LOOP_END),
        "归约后的窗口必须逐字等于文件里的两个数"
    );

    let out = render_pool(&plan, u64::MAX, LOOP_RENDER_FRAMES);
    let nonzero = out.iter().filter(|sample| **sample != 0.0).count();
    let mismatches = loop_index_mismatches(&out, LOOP_START, LOOP_PERIOD);
    let measured = detect_period(&out, LOOP_START, LOOP_END);
    let distinct = out[LOOP_START..LOOP_END]
        .iter()
        .map(|sample| sample.to_bits())
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    println!(
        "[engine-sfz/S28] 窗口 = [{LOOP_START},{LOOP_END}) ⇒ 声明周期 = {LOOP_PERIOD}；\
         {LOOP_RENDER_FRAMES} 帧里非零 = {nonzero}；⭐ **实测最小周期** = {measured}；\
         下标序列不符 = {mismatches}；窗口段不同位模式 = {distinct}；\
         前 8 帧下标 = {:?}、回绕点前后（163,164,165）= {:?}",
        (0..8)
            .map(|frame| source_index_at(&out, frame))
            .collect::<Vec<_>>(),
        (163..166)
            .map(|frame| source_index_at(&out, frame))
            .collect::<Vec<_>>(),
    );
    assert_eq!(
        nonzero, LOOP_RENDER_FRAMES,
        "循环声部必须写满整段（⛔ 不因'样本播完'退休）"
    );
    assert_eq!(
        mismatches, 0,
        "⭐ 下标序列必须**逐帧精确**（⛔ 这不是'波形看起来在重复'）"
    );
    assert_eq!(
        measured, LOOP_PERIOD,
        "⭐ **实测周期必须恰好等于 `loop_end − loop_start`**（实得 {measured}）"
    );
    assert!(
        distinct >= 2,
        "⭐ 反向腿：窗口段必须 ≥ 2 个不同位模式（否则'周期'可能是常数段的假象）"
    );
}

/// ⭐ S29（任务单 `#91`）：**`no_loop` / `one_shot` 都不循环**，且 **`one_shot` 忽略 note-off**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 实时池的输出（斜坡夹具 400 帧 ⇒ 源下标可反解）；单位 ＝ **非零帧数**
/// （⛔ 不是"有没有声音"：`no_loop` 与 `one_shot` 都**必须**出声，只是**不重复**）。
///
/// # 为什么四条腿都要
///
/// * 两份夹具都**写了** `loop_start=100 loop_end=164` ⇒ 若播放层不看 `loop_mode`
///   就会循环（非零会远超 399）⇒ 这两条腿把"模式被读到"钉住；
/// * `one_shot` ＋ `end_sample=100` ⇒ 非零仍 **399** ＝ **忽略 note-off**；
/// * ⭐ **反向腿**：`no_loop` ＋ `end_sample=100` ⇒ 恰好 **100**
///   （证明 `end_sample` **真的在切**，否则"忽略 note-off"那一条是空绿）。
#[test]
fn s29_no_loop_and_one_shot_do_not_loop_and_one_shot_ignores_note_off() {
    // 样本 400 帧、从源 0 起播：会写下的**最大**帧数（线性插值要读 `index+1`）。
    const MAX_WRITTEN: usize = LOOP_PCM_FRAMES - 1;
    let frames = 512usize;

    let no_loop = prepare_with(
        &loop_sfz("no_loop", LOOP_START, LOOP_END),
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let one_shot = prepare_with(
        &loop_sfz("one_shot", LOOP_START, LOOP_END),
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    assert!(
        no_loop.regions()[0].loop_window(LOOP_PCM_FRAMES).is_none(),
        "`no_loop` 即使写了 `loop_start`/`loop_end` 也⛔ 不产生窗口"
    );
    assert!(
        one_shot.regions()[0].loop_window(LOOP_PCM_FRAMES).is_none(),
        "`one_shot` 同样⛔ 不产生窗口"
    );

    let no_loop_out = render_pool(&no_loop, u64::MAX, frames);
    let one_shot_out = render_pool(&one_shot, u64::MAX, frames);
    let one_shot_held = render_pool(&one_shot, 100, frames);
    let no_loop_cut = render_pool(&no_loop, 100, frames);

    let count = |out: &[f32]| out.iter().filter(|sample| **sample != 0.0).count();
    println!(
        "[engine-sfz/S29] no_loop ⇒ 非零 = {}；one_shot ⇒ 非零 = {}；\
         one_shot ＋ end_sample=100 ⇒ 非零 = {}；⭐ no_loop ＋ end_sample=100（反向腿）⇒ 非零 = {}；\
         （样本 {LOOP_PCM_FRAMES} 帧 ⇒ 不循环时上限 {MAX_WRITTEN}）",
        count(&no_loop_out),
        count(&one_shot_out),
        count(&one_shot_held),
        count(&no_loop_cut),
    );
    for (label, out) in [("no_loop", &no_loop_out), ("one_shot", &one_shot_out)] {
        assert_eq!(
            count(out),
            MAX_WRITTEN,
            "⭐ `{label}` **不循环**：播到样本尾就停（⛔ 不是从 `loop_start` 重播）"
        );
        assert!(
            out[MAX_WRITTEN..].iter().all(|sample| *sample == 0.0),
            "⭐ `{label}`：样本尾之后必须是**逐位静音**（⛔ 不是重复）"
        );
    }
    assert_eq!(
        count(&one_shot_held),
        MAX_WRITTEN,
        "⭐ `one_shot` **忽略 note-off**：`end_sample=100` 到点⛔ 不切它"
    );
    assert_eq!(
        count(&no_loop_cut),
        100,
        "⭐ 反向腿：`no_loop` 在 `end_sample=100` 处**恰好**停 100 帧\
         （证明 `end_sample` 真的在切，⛔ 否则上一条是空绿）"
    );
}

/// ⭐ S30（任务单 `#91`；§4.3 的**常驻腿**）：字段**真的**被逐样本路径读到。
///
/// # 为什么需要它（把"接线"与"只是搬了个字段"分开）
///
/// 一份"搬了字段但没接线"的实现，让 `PreparedRegion` 带上 `loop_start` / `loop_end`
/// 也能通过类型检查、也能让 S9 的尺寸读数变化 —— 但⛔ **不会**让周期跟着字段走。
/// 本判据用两份**只差 `loop_end` 一个数**的夹具（`164` / `200`），要求：
///
/// * 回读的字段与归约窗口**逐字**等于文件里的数；
/// * **实测最小周期**分别为 `64` / `100`，且下标序列各自**逐帧精确**。
///
/// ⇒ 字段错一位（或没接线）**必红**。
#[test]
fn s30_the_loop_window_really_feeds_the_per_sample_path() {
    for (loop_end, period) in [(164usize, 64usize), (200usize, 100usize)] {
        let plan = prepare_with(
            &loop_sfz("loop_continuous", LOOP_START, loop_end),
            &ramp_sample(LOOP_PCM_FRAMES),
        );
        let region = &plan.regions()[0];
        assert_eq!(
            (region.loop_start(), region.loop_end()),
            (LOOP_START as u32, loop_end as u32),
            "回读的循环字段必须逐字等于文件"
        );
        let window = region.loop_window(LOOP_PCM_FRAMES).expect("有效窗口");
        assert_eq!(
            (
                window.start as usize,
                window.end as usize,
                window.len() as usize
            ),
            (LOOP_START, loop_end, period),
            "归约窗口与长度"
        );

        let frames = loop_end + 3 * period;
        let out = render_pool(&plan, u64::MAX, frames);
        let measured = detect_period(&out, LOOP_START, loop_end);
        let mismatches = loop_index_mismatches(&out, LOOP_START, period);
        println!(
            "[engine-sfz/S30] loop_end = {loop_end} ⇒ 声明周期 = {period}；\
             实测周期 = {measured}；下标序列不符 = {mismatches}（帧数 {frames}）"
        );
        assert_eq!(
            measured, period,
            "⭐ 实测周期必须跟着 `loop_end` 走（⛔ 只搬字段不接线会在这里红）"
        );
        assert_eq!(mismatches, 0, "⭐ 下标序列逐帧精确");
    }
}

/// ⭐ S31（任务单 `#91`；第 259 条）：**非法循环输入仍响亮 `Err`**，⛔ 不静默降级。
///
/// # 判定量（逐条）
///
/// * 集合外 `loop_mode` ⇒ `SfzError::InvalidOption`（`yeban-sfz` 的 `as_option` 白名单）；
/// * 越界 `loop_start` ⇒ `SfzError::IntegerOutOfRange`（`read_u32`）；
/// * ⭐ **唯一保留的一档**：`loop_end <= loop_start`（两个值**各自合法**、只有**组合**
///   退化）⇒ `load` **`Ok`**、`loop_window() == None` ＝ **按不循环渲染**
///   ——既有语义，本片⛔ 不加新机制、⛔ 不报错。
#[test]
fn s31_illegal_loop_input_still_fails_loudly_on_the_engine_path() {
    let load = |text: &str| SfzInstrument::load(text.to_owned(), &Default::default());

    let bad_mode = load("<region> sample=a.wav loop_mode=bogus\n")
        .expect_err("⭐ 集合外的 `loop_mode` 必须**响亮报错**（⛔ 不许降级 ＋ 记录）");
    assert!(
        matches!(bad_mode, SfzError::InvalidOption { .. }),
        "⭐ 必须是 `InvalidOption`（白名单拒绝），实得 {bad_mode:?}"
    );

    let bad_start = load(
        "<region> sample=a.wav loop_mode=loop_continuous loop_start=99999999999999 loop_end=20\n",
    )
    .expect_err("⭐ 越界的 `loop_start` 必须**响亮报错**（⛔ 不许降级）");
    assert!(
        matches!(bad_start, SfzError::IntegerOutOfRange { .. }),
        "⭐ 必须是 `IntegerOutOfRange`，实得 {bad_start:?}"
    );

    // ⭐ 唯一保留的一档：组合退化 ⇒ `Ok` ＋ 不循环（既有语义）。
    let degenerate = load(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous loop_start=100 loop_end=100\n",
    )
    .expect("⭐ 两个值各自合法 ⇒ `load` 必须 `Ok`（⛔ 不新增降级机制）");
    let plan = PreparedSfz::prepare(&degenerate, &ramp_sample(LOOP_PCM_FRAMES), 48_000.0)
        .expect("摊平必须成功");
    let window = plan.regions()[0].loop_window(LOOP_PCM_FRAMES);
    println!(
        "[engine-sfz/S31] `loop_mode=bogus` ⇒ {bad_mode:?}；越界 `loop_start` ⇒ {bad_start:?}；\
         退化窗口（`loop_end == loop_start`）⇒ `load` Ok、`loop_window` = {window:?}"
    );
    assert!(
        window.is_none(),
        "⭐ `loop_end <= loop_start` ⇒ 既有语义是**按不循环渲染**（⛔ 不是死循环窗口）"
    );
}

/// ⭐ S32（任务单 `#91`）：**`loop_sustain ≡ loop_continuous` 的登记可判**。
///
/// # 判定量
///
/// `include_str!("../src/sfz_instrument.rs")`（模块头**源码**）必须含那条**逐字**登记；
/// ⭐ 反向腿：文档里**没有**的那一句 ⇒ `contains` 必须 `false`（⛔ 判据不是恒真）。
///
/// ⚠ 形态照本仓"文本即判据"的既有做法（如 `yeban-engine/src/level.rs` /
/// `yeban-app/tests/engine_device_leg.rs` 的 `include_str!` 断言）。
#[test]
fn s32_the_loop_sustain_equivalence_is_registered_in_the_module_doc() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const NEEDLE: &str =
        "note-off 后两者的差别（走完当前循环再进释放）属 ADSR 片、本片不声称已实现";
    println!(
        "[engine-sfz/S32] 模块头含登记 = {}；反向腿（文档里没有的句子）= {}",
        MODULE_SOURCE.contains(NEEDLE),
        MODULE_SOURCE.contains("note-off 后两者的差别属本片已实现"),
    );
    assert!(
        MODULE_SOURCE.contains(NEEDLE),
        "⭐ 模块头必须逐字登记：{NEEDLE}"
    );
    assert!(
        !MODULE_SOURCE.contains("note-off 后两者的差别属本片已实现"),
        "⭐ 反向腿：文档里**没有**的句子必须 `contains == false`（否则判据恒真）"
    );
}

/// ⭐ S33（任务单 `#91`；§4.4）：**不带任何 `loop_*` 的既有夹具逐位不变**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 既有夹具 [`TWO_MATCH_ONE_MISS`]（**一个 `loop_*` 都没有**）经
/// `SynthEngine::render_track` 实时路径渲染的 512 帧；单位 ＝ **FNV-1a 64 指纹**（逐位）。
///
/// # 字面值的来源（⭐ 改动前实测）
///
/// `0xa933ddab286bdf5e` 是**基线探针**（`git checkout` 回 HEAD `5ac570eb`、工作树干净时
/// 运行、测后删除）在本机 `aarch64/macos` 上量到的**同一个夹具、同一段 512 帧**的读数：
/// 摊平路径与**引擎实时路径**两条路**同值**、`max|engine − flat| = 0`。
/// ⭐ 它同时等于既有 [`BROADCAST_STEP2_FINGERPRINT`]（步 2 实测）——两条独立来路的
/// 交叉印证。
///
/// # 反向腿（⛔ 让"绿"不能是空的）
///
/// 把同一段输出**乘 `1.0000001`** ⇒ 指纹**必须变**（证明它是**逐位**判据，
/// ⛔ 不是"有输出就算过"）。
#[test]
fn s33_a_fixture_without_any_loop_fields_renders_bit_identically() {
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);
    let mut out = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut out);
    let actual = fnv1a_64(&out);
    // ⭐ 反向腿：逐位判据的敏感性见证。
    let scaled: Vec<f32> = out.iter().map(|sample| sample * 1.000_000_1).collect();
    let scaled_hash = fnv1a_64(&scaled);
    println!(
        "[engine-sfz/S33] 无 `loop_*` 夹具（512 帧 @60,127）：非零 = {}、指纹 = 0x{actual:016x}\
         （改动前实测 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）；\
         反向腿（× 1.0000001）指纹 = 0x{scaled_hash:016x}（必须不同）",
        out.iter().filter(|sample| **sample != 0.0).count(),
    );
    assert!(
        out.iter().any(|sample| *sample != 0.0),
        "夹具必须真的出声（否则指纹比对是空转）"
    );
    let _checked = check_fingerprint(
        "S33 无 loop 夹具逐位不变",
        actual,
        NO_LOOP_FIXTURE_FINGERPRINT,
    );
    assert_ne!(
        scaled_hash, actual,
        "⭐ 反向腿：输出乘 1.0000001 ⇒ 指纹**必须**不同（否则判据不是逐位的）"
    );
}

// ---------------------------------------------------------------------------
// ⭐ S34～S38：**SFZ `ampeg` ADSR 接进实时播放**（任务单 `#92` 的 ADSR 那一半）
//
// 判据的分工：
//   * S34 —— 解析层五条腿（含单位后缀）＋ `Err` 政策 ＋ 缺失 ⇒ 缺省 ＋ 帧换算；
//   * S35 —— ⭐ **包络形状逐样本可判**（到峰帧数 / sustain 电平 / 释放归零 ＋ 段位真的推进）；
//   * S36 —— ⭐ **`loop_sustain` 与 `loop_continuous` 在 note-off 之后输出不同**
//             （各配一条"它自己该怎样"的断言）；
//   * S37 —— ⭐ **无 `ampeg_*` 的既有夹具逐位不变**（改动前实测指纹 ＋ 乘 `1.0000001` 的反向腿）；
//   * S38 —— ⭐ 模块文档里"取线性段 / 指数对数不在本片范围"那条登记**可判**（＋ 反向腿）。
// ---------------------------------------------------------------------------

/// ⭐ S35 夹具的形状（**秒**；48 kHz ⇒ 帧数都是整数，四舍五入与截断**不可区分**的
/// 边界之外还刻意留了一条 `.01` 的腿）。
const AMPEG_ATTACK_SECONDS: f32 = 0.010; // 480 帧
const AMPEG_HOLD_SECONDS: f32 = 0.005; // 240 帧
const AMPEG_DECAY_SECONDS: f32 = 0.005; // 240 帧
const AMPEG_SUSTAIN_PERCENT: f32 = 50.0;
const AMPEG_RELEASE_SECONDS: f32 = 0.020; // 960 帧

/// 与上面四段对应的**引擎帧**（48 kHz；判据里⛔ 不手抄进断言，全部由这两条常量推）。
const AMPEG_ATTACK_FRAMES: usize = 480;
const AMPEG_HOLD_FRAMES: usize = 240;
const AMPEG_DECAY_FRAMES: usize = 240;
const AMPEG_RELEASE_FRAMES: usize = 960;
/// 进入 sustain 的帧（＝ 前 3 段之和）。
const AMPEG_SUSTAIN_START: usize = AMPEG_ATTACK_FRAMES + AMPEG_HOLD_FRAMES + AMPEG_DECAY_FRAMES;
/// note-off 落在 sustain 里、且**离段边界有余量**（这样"释放段"]的起点电平是 `sustain`）。
const AMPEG_NOTE_OFF: usize = AMPEG_SUSTAIN_START + 240;

/// ⭐ **包络判据的夹具样本**：恒定 `1.0`。
///
/// 为什么必须是常量：`gain == 1.0`（`volume=0`、`velocity=127` ⇒ 两条恒等）时
/// 输出**恰好**等于包络电平 ⇒ 判据可以把每个输出帧**直接当成包络读数**对账
/// （⛔ 不是"波形看起来像包络"）。
/// ⚠ 速率必须是 `1.0`（`pitch_keycenter == note`、`sample_hz == engine_hz`）：
/// 否则 `frac ≠ 0` 会让 `1.0 * (1 − frac) + 1.0 * frac` 出现 1 ulp 的偏差
/// （本片实测：`frac = 0.1` 时该式**不等于** 1.0）。
fn flat_sample(frames: usize) -> InMemorySample {
    InMemorySample {
        pcm: vec![1.0f32; frames],
        sample_hz: 48_000.0,
    }
}

/// ⭐ S35/S36 的 SFZ 文本（单区域、`key=60`、零移调 ⇒ `rate == 1.0`）。
fn ampeg_sfz(mode: &str) -> String {
    format!(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode={mode} \
         ampeg_attack={AMPEG_ATTACK_SECONDS} ampeg_hold={AMPEG_HOLD_SECONDS} \
         ampeg_decay={AMPEG_DECAY_SECONDS} ampeg_sustain={AMPEG_SUSTAIN_PERCENT} \
         ampeg_release={AMPEG_RELEASE_SECONDS}\n"
    )
}

/// ⭐ S34（任务单 `#92`）：**解析层五条腿 ＋ `Err` 政策 ＋ 缺失 ⇒ 缺省 ＋ 帧换算**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 摊平表 [`PreparedRegion`] 的五个只读读数（**秒 / 百分比**）与
/// [`AmpegRun`] 的**帧数**；单位 ＝ 秒、百分比、引擎帧（48 kHz）。
///
/// # 判定量（逐条）
///
/// * 五个 opcode **各自**一条腿，且**混用单位后缀**（`1.5s` / `250ms` / 裸值 / `50%` / `2s`）
///   ⇒ 回读值**逐字**等于文件里的数（⛔ 不是"能解析就算过"）；
/// * `PreparedSfz::engine_hz()` ＝ 摊平期的 48 kHz（帧换算的唯一事实源）；
/// * 帧换算：`0.010 s × 48 kHz` ⇒ **480 帧**（⭐ 四舍五入：截断在 `.01` 上会得到 479）；
/// * ⭐ **非法 ⇒ 响亮 `Err`**（三类各一条：认不出 / 负 / 越界）＋ ⭐
///   **同一批数据里的合法样例必须被接受**（⛔ 防"输入永远被拒"的假绿）；
/// * ⭐ **缺失 ⇒ 缺省**（与"非法"**分开**断言）：五个读数全在透明缺省上、
///   `ampeg_is_transparent()` 为真、`ampeg_run()` 为 `None`（＝ ⛔ 不进包络路径）。
#[test]
fn s34_the_five_ampeg_opcodes_parse_and_the_illegal_ones_still_fail_loudly() {
    let load = |text: &str| SfzInstrument::load(text.to_owned(), &Default::default());

    // ---- ① 五个 opcode 各自一条腿（混用单位后缀写法）----
    const FIVE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 ampeg_attack=1.5s \
                        ampeg_hold=250ms ampeg_decay=0.25 ampeg_sustain=50% ampeg_release=2s\n";
    let instrument = load(FIVE).expect("⭐ 合法样例必须被接受");
    let plan = PreparedSfz::prepare(&instrument, &flat_sample(64), 48_000.0).expect("摊平");
    let region = &plan.regions()[0];
    println!(
        "[engine-sfz/S34] 五个 opcode（`1.5s` / `250ms` / `0.25` / `50%` / `2s`）⇒ \
         attack={} hold={} decay={} sustain={} release={}；engine_hz={}",
        region.ampeg_attack_seconds(),
        region.ampeg_hold_seconds(),
        region.ampeg_decay_seconds(),
        region.ampeg_sustain_percent(),
        region.ampeg_release_seconds(),
        plan.engine_hz(),
    );
    assert_eq!(region.ampeg_attack_seconds(), 1.5, "`1.5s` ⇒ 1.5 秒");
    assert_eq!(region.ampeg_hold_seconds(), 0.25, "`250ms` ⇒ 0.25 秒");
    assert_eq!(region.ampeg_decay_seconds(), 0.25, "裸值按秒读");
    assert_eq!(region.ampeg_sustain_percent(), 50.0, "`50%` ⇒ 50 个百分点");
    assert_eq!(region.ampeg_release_seconds(), 2.0, "`2s` ⇒ 2 秒");
    assert_eq!(plan.engine_hz(), 48_000.0, "帧换算的事实源＝摊平期采样率");

    // ---- ② 帧换算：四舍五入（⛔ 不是截断）----
    let rounded = PreparedSfz::prepare(
        &load("<region> sample=a.wav key=60 pitch_keycenter=60 ampeg_attack=0.01\n").expect("load"),
        &flat_sample(64),
        48_000.0,
    )
    .expect("摊平");
    let run = rounded.regions()[0]
        .ampeg_run(rounded.engine_hz())
        .expect("0.01 s ≠ 缺省 ⇒ 必须进包络路径");
    println!(
        "[engine-sfz/S34] `0.01 s @ 48 kHz` ⇒ attack_frames = {}（四舍五入；截断会给 479）",
        run.attack_frames()
    );
    assert_eq!(
        run.attack_frames(),
        480,
        "⭐ 0.01 s × 48 kHz 必须**四舍五入**到 480 帧（截断 479 ⇒ 到峰帧数差一）"
    );
    assert_eq!(run.hold_frames(), 0, "未给出的段 ⇒ 0 帧（零长段）");
    assert_eq!(run.decay_frames(), 0);
    assert_eq!(run.release_frames(), 0);
    assert_eq!(run.sustain_level(), 1.0, "未给出的 sustain ⇒ 100 % ⇒ 1.0");

    // ---- ③ 非法 ⇒ 响亮 `Err`（三类各一条）----
    let bad_float = load("<region> sample=a.wav ampeg_attack=abc\n")
        .expect_err("⭐ 认不出的数值必须**响亮报错**");
    let bad_duration =
        load("<region> sample=a.wav ampeg_release=-1s\n").expect_err("⭐ 负时长必须**响亮报错**");
    let bad_range = load("<region> sample=a.wav ampeg_sustain=150\n")
        .expect_err("⭐ 越界的 sustain 必须**响亮报错**");
    println!("[engine-sfz/S34] 非法输入 ⇒ {bad_float:?} / {bad_duration:?} / {bad_range:?}");
    assert!(
        matches!(bad_float, SfzError::InvalidFloat { .. }),
        "⛔ `ampeg_attack=abc` 不许静默降级，实得 {bad_float:?}"
    );
    assert!(
        matches!(bad_duration, SfzError::InvalidDuration { .. }),
        "⛔ `ampeg_release=-1s` 不许静默钳位，实得 {bad_duration:?}"
    );
    assert!(
        matches!(bad_range, SfzError::FloatOutOfRange { .. }),
        "⛔ `ampeg_sustain=150` 不许静默钳位，实得 {bad_range:?}"
    );
    // ⭐ 同一批数据里必须有一条**合法**样例被正确接受（⛔ 否则上面三条可能是"永远拒绝"的假绿）。
    let mixed = "<region> sample=a.wav ampeg_attack=abc\n\
                 <region> sample=b.wav ampeg_attack=0.5s\n";
    assert!(load(mixed).is_err(), "同一批里有一条非法 ⇒ 整份 `Err`");
    let legal = load("<region> sample=b.wav ampeg_attack=0.5s\n").expect("⭐ 合法样例必须被接受");
    let legal_value = legal
        .with_instrument(|parsed| parsed.regions()[0].ampeg_attack)
        .expect("查询");
    assert_eq!(legal_value, 0.5, "同批数据里的合法值照读");

    // ---- ④ 缺失 ⇒ 缺省（**与非法分开**断言）----
    let absent = PreparedSfz::prepare(
        &load("<region> sample=a.wav key=60 pitch_keycenter=60\n").expect("load"),
        &flat_sample(64),
        48_000.0,
    )
    .expect("摊平");
    let absent_region = &absent.regions()[0];
    println!(
        "[engine-sfz/S34] 缺失读数：attack={} hold={} decay={} sustain={} release={}、\
         transparent={}、ampeg_run={:?}",
        absent_region.ampeg_attack_seconds(),
        absent_region.ampeg_hold_seconds(),
        absent_region.ampeg_decay_seconds(),
        absent_region.ampeg_sustain_percent(),
        absent_region.ampeg_release_seconds(),
        absent_region.ampeg_is_transparent(),
        absent_region.ampeg_run(absent.engine_hz()).is_some(),
    );
    assert_eq!(absent_region.ampeg_attack_seconds(), 0.0);
    assert_eq!(absent_region.ampeg_hold_seconds(), 0.0);
    assert_eq!(absent_region.ampeg_decay_seconds(), 0.0);
    assert_eq!(absent_region.ampeg_sustain_percent(), 100.0);
    assert_eq!(
        absent_region.ampeg_release_seconds(),
        0.0,
        "⭐ 本仓 `ampeg_release` 缺省是 0（⛔ 不是规范的 0.001）—— 见 yeban-sfz 的常量文档"
    );
    assert!(
        absent_region.ampeg_is_transparent(),
        "五个值都在透明缺省上 ⇒ 快速通道"
    );
    assert!(
        absent_region.ampeg_run(absent.engine_hz()).is_none(),
        "⭐ 透明 ⇒ `None` ⇒ 逐样本路径一个浮点运算都不加"
    );
}

/// ⭐ S35（任务单 `#92`）：**包络形状逐样本可判**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 实时池（[`SfzVoicePool`]）在**恒定 1.0 样本**上的输出；单位 ＝ **包络电平**
/// （`gain == 1.0` ⇒ 输出**恰好**是包络值，见 [`flat_sample`]）。
///
/// # ⭐ 容差口径（写死，⛔ 不用"大约"）
///
/// **线性段上每一点都在 `|实测 − 理论| ≤ 1e-6` 内**。理论上界（逐段）：
/// `t/A`、`1`、`1 − (1−S)(t−A−H)/D`、`S`、`L_off·(R−k)/R`。
/// ⚠ 实现只做「一次整数→浮点转换 ＋ 一两次乘加」（倒数在逐块时算好）⇒ 实测偏差
/// 应在 `1e-7` 量级（本判据会把实测最大偏差**打印出来**）。
///
/// # 判定量（逐条）
///
/// * `|out[t] − t/A| ≤ 1e-6`（`t ∈ 0..A`）＋ `out[A] == 1.0`（⭐ **恰好第 A 帧到峰**）；
/// * `out[t] == 1.0`（保持段）＋ `out[t] == 0.5`（衰减后的 sustain 电平）；
/// * ⭐ note-off 后按 `ampeg_release` **恰好 960 帧**线性归零：
///   `|out[T_off + k] − 0.5·(960 − k)/960| ≤ 1e-6`（`k ∈ 0..960`）、
///   `out[T_off + 960] == 0.0` 且**之后逐位为 0**（声部已退休）；
/// * ⭐ **段位真的在推进**（`SfzVoice::envelope_stage` 逐块读数：`Attack → Hold → Decay
///   → Sustain → Release`）—— ⛔ 这条把"电平恰好对"与"状态真的动了"分开钉住
///   （一个永远返回 `Attack` 的假读数会在这里红）。
#[test]
fn s35_the_envelope_shape_is_judgeable_sample_by_sample() {
    // 释放段需要写满 960 帧 ⇒ 总帧数留到 note-off ＋ 释放 ＋ 余量。
    const FRAMES: usize = AMPEG_NOTE_OFF + AMPEG_RELEASE_FRAMES + 64;
    let plan = prepare_with(&ampeg_sfz("no_loop"), &flat_sample(4096));
    let mut pool = SfzVoicePool::new(48_000.0);
    assert_eq!(
        pool.trigger_note(&plan, 60, 127, AMPEG_NOTE_OFF as u64, 1.0, None),
        1,
        "单区域夹具 ⇒ 恰好建 1 个声部"
    );

    // ⭐ 逐块渲染：每块之后读段位（状态真的在推进的机械见证）。
    let mut out = vec![0.0f32; FRAMES];
    let mut stages: Vec<(usize, String)> = Vec::new();
    let mut cursor = 0usize;
    for chunk in [
        1usize,
        AMPEG_ATTACK_FRAMES - 1,
        AMPEG_HOLD_FRAMES,
        AMPEG_DECAY_FRAMES,
    ] {
        pool.render_into(&plan, cursor as u64, &mut out[cursor..cursor + chunk]);
        cursor += chunk;
        stages.push((cursor, format!("{:?}", pool.voices()[0].envelope_stage())));
    }
    // 保持到 note-off 前一刻，再读一次（此时仍在 sustain）。
    let to_note_off = AMPEG_NOTE_OFF - cursor;
    pool.render_into(&plan, cursor as u64, &mut out[cursor..cursor + to_note_off]);
    cursor += to_note_off;
    stages.push((cursor, format!("{:?}", pool.voices()[0].envelope_stage())));
    // 释放段（含 note-off 那一帧）。
    let rest = FRAMES - cursor;
    pool.render_into(&plan, cursor as u64, &mut out[cursor..]);
    stages.push((
        cursor + rest,
        format!("{:?}", pool.voices()[0].envelope_stage()),
    ));

    // ---- ① 逐样本对账（线性段，容差 1e-6）----
    let mut worst = 0.0f32;
    let mut worst_at = 0usize;
    let check = |frame: usize, expected: f32, worst: &mut f32, worst_at: &mut usize| {
        let delta = (out[frame] - expected).abs();
        if delta > *worst {
            *worst = delta;
            *worst_at = frame;
        }
    };
    let sustain = AMPEG_SUSTAIN_PERCENT / 100.0;
    for t in 0..AMPEG_ATTACK_FRAMES {
        let expected = t as f32 / AMPEG_ATTACK_FRAMES as f32;
        check(t, expected, &mut worst, &mut worst_at);
    }
    // 保持段（只有 `A..A+H`；衰减段在下一个循环里单独对账）。
    for t in AMPEG_ATTACK_FRAMES..(AMPEG_ATTACK_FRAMES + AMPEG_HOLD_FRAMES) {
        check(t, 1.0, &mut worst, &mut worst_at);
    }
    // 衰减段：从 1.0 线性到 sustain。
    for t in (AMPEG_ATTACK_FRAMES + AMPEG_HOLD_FRAMES)..AMPEG_SUSTAIN_START {
        let k = t - AMPEG_ATTACK_FRAMES - AMPEG_HOLD_FRAMES;
        let expected = 1.0 - (1.0 - sustain) * (k as f32 / AMPEG_DECAY_FRAMES as f32);
        check(t, expected, &mut worst, &mut worst_at);
    }
    // sustain 段。
    for t in AMPEG_SUSTAIN_START..=AMPEG_NOTE_OFF {
        check(t, sustain, &mut worst, &mut worst_at);
    }
    // 释放段。
    for k in 0..AMPEG_RELEASE_FRAMES {
        let expected = sustain * (AMPEG_RELEASE_FRAMES - k) as f32 / AMPEG_RELEASE_FRAMES as f32;
        check(AMPEG_NOTE_OFF + k, expected, &mut worst, &mut worst_at);
    }
    println!(
        "[engine-sfz/S35] 恒定 1.0 样本、{FRAMES} 帧：⭐ 线性段最大偏差 = {worst:e}（在第 \
         {worst_at} 帧）；到峰帧 = {}（out[{}] = {}）；sustain = {}；\
         释放起点（第 {} 帧）= {}、释放末帧（第 {} 帧）= {}；第 {} 帧起 = {}；\
         段位读数 = {stages:?}",
        AMPEG_ATTACK_FRAMES,
        AMPEG_ATTACK_FRAMES,
        out[AMPEG_ATTACK_FRAMES],
        out[AMPEG_SUSTAIN_START],
        AMPEG_NOTE_OFF,
        out[AMPEG_NOTE_OFF],
        AMPEG_NOTE_OFF + AMPEG_RELEASE_FRAMES - 1,
        out[AMPEG_NOTE_OFF + AMPEG_RELEASE_FRAMES - 1],
        AMPEG_NOTE_OFF + AMPEG_RELEASE_FRAMES,
        out[AMPEG_NOTE_OFF + AMPEG_RELEASE_FRAMES],
    );
    assert!(
        worst <= 1.0e-6,
        "⭐ 容差口径：线性段每一点 |实测 − 理论| ≤ 1e-6（实测最大 {worst:e}，第 {worst_at} 帧）"
    );

    // ---- ② 到峰 / sustain / 归零三条**精确**腿 ----
    assert_eq!(
        out[AMPEG_ATTACK_FRAMES], 1.0,
        "⭐ 起音**恰好**在 A ＝ {AMPEG_ATTACK_FRAMES} 帧到峰（⛔ 不是 A±1）"
    );
    assert_eq!(
        out[AMPEG_SUSTAIN_START], sustain,
        "衰减段终点恰好是 sustain"
    );
    assert_eq!(
        out[AMPEG_NOTE_OFF + AMPEG_RELEASE_FRAMES],
        0.0,
        "⭐ 释放段**恰好** R ＝ {AMPEG_RELEASE_FRAMES} 帧归零"
    );
    assert!(
        out[AMPEG_NOTE_OFF + AMPEG_RELEASE_FRAMES..]
            .iter()
            .all(|sample| *sample == 0.0),
        "⭐ 归零之后必须**逐位**静音（声部已退休，⛔ 不是「接近 0」）"
    );
    assert_eq!(
        pool.active_count(),
        0,
        "⭐ 释放走完 ⇒ 声部退休（池内状态翻转）"
    );

    // ---- ③ 段位读数（状态真的在推进）----
    let labels: Vec<&str> = stages.iter().map(|(_, label)| label.as_str()).collect();
    // ⚠ 读数的语义：`envelope_stage()` 是**最后一帧所落的段**（状态是"处理完"的机器状态，
    // 不是"下一帧将要进"的段）⇒ 在第 480 帧处读到的仍是 Attack（最后一帧 = 第 479 帧）。
    // 这条**逐块**的序列本身就是"状态真的在按 A/H/D 推进"的机械见证。
    assert_eq!(
        labels,
        vec![
            "Some(Attack)",  // 第 1 帧之后（最后一帧 = 第 0 帧）
            "Some(Attack)",  // 480 帧之后（最后一帧 = 第 479 帧，仍在起音段）
            "Some(Hold)",    // 720 帧之后（最后一帧 = 第 719 帧，落在保持段）
            "Some(Decay)",   // 960 帧之后（最后一帧 = 第 959 帧，落在衰减段）
            "Some(Sustain)", // 1200 帧之后（最后一帧 = 第 1199 帧，落在 sustain）
            "None",          // 释放走完 ⇒ 声部退休
        ],
        "⭐ 段位必须逐块按 A/H/D 的边界推进，并在释放走完后回到 `None`（退休）"
    );
}

/// ⭐ S36（任务单 `#92` 新增；⭐ **任务单 `#94` 按规范改写期望**）：**`loop_sustain` 与
/// `loop_continuous` 在 note-off 之后的输出必须不同**，且**各配一条"它自己在 note-off
/// 之后该怎样"的断言**（⛔ 不是只断言"两者不同"）。
///
/// # ⚠ 本判据为什么被改写（沿革，⛔ 不改写历史）
///
/// `#92` 曾按"`loop_sustain` ⇒ **走完当前循环**再进释放；`loop_continuous` ⇒ note-off
/// **根本不进释放**（`end_sample` 硬停）"实现。任务单 `#94` 查了 `sfzformat` 的两份页面后
/// **撤掉了这两条口径**（逐字引文见下）⇒ 本判据的**期望**随之改写（**编号与判据名不变**）。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 实时池在**斜坡样本**（⇒ 输出可**逐帧反解源下标**）上的输出；单位 ＝
/// **非零帧数**（存在性）＋ **源采样下标序列**（形状）＋ **释放段逐帧对账**
/// （`|实测 − 理论| ≤ 1e-6`）。
///
/// # 规范逐字（全部来自 `sfzformat`，⭐ 三条）
///
/// 1. <https://sfzformat.com/opcodes/loop_mode/>：「loop_sustain: the player will play the
///    loop while the note is held … **During the release phase, there's no looping.**」；
/// 2. 同页：「Whether no_loop, **loop_continuous** or **loop_sustain** is set, **the duration
///    of the release phase is set using `ampeg_release`**. However, in loop_sustain or
///    no_loop mode, **the sound can be cut off before the release phase ends, if the end of
///    sample is reached**. In loop_continuous mode, **the loop will repeat if the loop end
///    is reached during the release phase**, including repeating multiple times if the
///    release time is longer than the loop length.」；
/// 3. <https://sfzformat.com/legacy/>：「loop_sustain: … **The rest of the sample will play
///    after note release.**」
///
/// # 判定量（两条腿**各自**成立）
///
/// * ⭐ **`loop_continuous`**：note-off（第 200 帧）**就地进释放**，且**释放期照旧回绕**
///   ⇒ 非零**恰好** `200 + 480 = 680`（释放走完才结束）；⭐ **整段**与**独立**理论轨迹
///   （源下标按 `[100,164)` 循环 × 释放斜坡）逐点相符 ⇒ 那一条同时钉住"释放期仍在循环"；
/// * ⭐ **`loop_sustain`**：note-off **就地进释放**、释放期**⛔ 不循环**（沿源位置往后播）
///   ⇒ 第 200 帧起源下标**逐帧 +1、永不回绕**，直到**样本播完**
///   （`source_end = 400` ⇒ 最后一个可写下标 `398`）⇒ 非零**恰好** `200 + 263 = 463`
///   （⚠ "释放走完（680）"与"到样本尾（463）"**谁先到谁结束** ⇒ 这里样本尾先到）。
/// * ⭐ 反向腿（⛔ 防空绿）：两条腿的**非零帧数必须不同**（680 ≠ 463）；
///   `loop_sustain` 的输出**确实越过** `end_sample`（第 200 帧必须非零）；
///   释放段的理论值由 `pcm` ＋ 斜坡**独立算出**（⛔ 不拿实测反解自己比自己）；
///   ⭐ 前置见证：两份夹具在 note-off **之前**都实测周期 ＝ `loop_end − loop_start`。
#[test]
fn s36_loop_sustain_and_loop_continuous_differ_after_note_off() {
    const END_SAMPLE: usize = 200;
    const RELEASE_FRAMES: usize = 480; // 0.01 s @ 48 kHz
    /// ⭐ note-off 那一帧的源位置：窗口 `[100,164)`、周期 64 ⇒ `100 + (200 − 164) mod 64`。
    const SUSTAIN_POSITION_AT_NOTE_OFF: usize = LOOP_START + (END_SAMPLE - LOOP_END) % LOOP_PERIOD;
    /// ⭐ `loop_sustain` 在释放期还能写的帧数：源下标从 136 一路 +1 到最后一个可写下标 398。
    const SUSTAIN_TAIL: usize = (LOOP_PCM_FRAMES - 1) - SUSTAIN_POSITION_AT_NOTE_OFF;
    const FRAMES: usize = END_SAMPLE + RELEASE_FRAMES + 8;

    let text = |mode: &str| {
        format!(
            "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode={mode} \
             loop_start={LOOP_START} loop_end={LOOP_END} ampeg_release=0.01\n"
        )
    };
    let pcm = ramp_sample(LOOP_PCM_FRAMES);
    let continuous = prepare_with(&text("loop_continuous"), &pcm);
    let sustain = prepare_with(&text("loop_sustain"), &pcm);

    let continuous_out = render_pool(&continuous, END_SAMPLE as u64, FRAMES);
    let sustain_out = render_pool(&sustain, END_SAMPLE as u64, FRAMES);
    let count = |out: &[f32]| out.iter().filter(|sample| **sample != 0.0).count();

    // ⭐ `loop_continuous` 的**独立**理论轨迹：源下标永远按 `[100,164)` 循环，
    // 第 200 帧起乘 `(R − k)/R`（k ≥ R ⇒ 0 ⇒ 声部已退休）。
    let continuous_index = |t: usize| {
        if t < LOOP_END {
            t
        } else {
            LOOP_START + (t - LOOP_START) % LOOP_PERIOD
        }
    };
    let continuous_mismatches = (0..=END_SAMPLE + RELEASE_FRAMES)
        .filter(|t| {
            let ramp = if *t < END_SAMPLE {
                1.0
            } else {
                (RELEASE_FRAMES - (*t - END_SAMPLE)) as f32 / RELEASE_FRAMES as f32
            };
            (continuous_out[*t] - pcm.pcm[continuous_index(*t)] * ramp).abs() > 1.0e-6
        })
        .count();
    // ⭐ `loop_sustain` 的**独立**理论轨迹：第 200 帧起源下标**逐帧 +1**（⛔ 不回绕），
    // 直到样本播完（最后一个可写下标 = `LOOP_PCM_FRAMES − 2`）。
    let sustain_mismatches = (0..SUSTAIN_TAIL)
        .filter(|k| {
            let ramp = (RELEASE_FRAMES - k) as f32 / RELEASE_FRAMES as f32;
            (sustain_out[END_SAMPLE + k] - pcm.pcm[SUSTAIN_POSITION_AT_NOTE_OFF + k] * ramp).abs()
                > 1.0e-6
        })
        .count();
    // ⭐ "释放期⛔ 不循环"的**形状**读数：除掉释放斜坡后反解的源下标必须**严格递增**。
    let recover = |k: usize| {
        sustain_out[END_SAMPLE + k] * RELEASE_FRAMES as f32 / (RELEASE_FRAMES - k) as f32
    };
    let sustain_indices_increase = (1..SUSTAIN_TAIL).all(|k| recover(k) > recover(k - 1));
    // ⭐ 前置见证：note-off **之前**两份夹具都真的按窗口循环（⛔ 防"根本没出声"的假绿）。
    let continuous_period = detect_period(&continuous_out, LOOP_START, LOOP_END + 3 * LOOP_PERIOD);
    let sustain_period = detect_period(&sustain_out, LOOP_START, LOOP_END + 3 * LOOP_PERIOD);
    println!(
        "[engine-sfz/S36] ⭐ `loop_continuous`（end_sample={END_SAMPLE}）⇒ 非零 = {}（＝ note-off \
         ＋ 释放 {RELEASE_FRAMES} 帧）；全程与「循环 × 斜坡」不符 = {continuous_mismatches}；\
         ⭐ `loop_sustain` ⇒ 非零 = {}（＝ note-off ＋ 往后播到样本尾 {SUSTAIN_TAIL} 帧）；\
         释放段与「源下标恒 +1 × 斜坡」不符 = {sustain_mismatches}；反解源下标严格递增 = \
         {sustain_indices_increase}；前置周期 = {continuous_period} / {sustain_period}",
        count(&continuous_out),
        count(&sustain_out),
    );

    // ---- 腿 ①：`loop_continuous` —— note-off 进释放、释放期照旧循环 ----
    assert_eq!(
        continuous_period, LOOP_PERIOD,
        "⭐ 前置见证：`loop_continuous` 在 note-off 之前必须按 `loop_end − loop_start` 循环"
    );
    assert_eq!(
        count(&continuous_out),
        END_SAMPLE + RELEASE_FRAMES,
        "⭐ `loop_continuous`：note-off **就地进释放**且**释放期照旧回绕** ⇒ 声部活到释放走完"
    );
    assert_eq!(
        continuous_mismatches, 0,
        "⭐ `loop_continuous`：整段必须逐点等于「源下标按 [100,164) 循环 × 释放斜坡」\
         （|实测 − 理论| ≤ 1e-6）"
    );
    assert!(
        continuous_out[END_SAMPLE + RELEASE_FRAMES..]
            .iter()
            .all(|sample| *sample == 0.0),
        "⭐ `loop_continuous`：释放走完 ⇒ 逐位静音"
    );

    // ---- 腿 ②：`loop_sustain` —— 释放期⛔ 不循环，沿源位置往后播到样本尾 ----
    assert_eq!(
        sustain_period, LOOP_PERIOD,
        "⭐ 前置见证：`loop_sustain` 在 note-off 之前照旧「按住才循环」"
    );
    assert_eq!(
        count(&sustain_out),
        END_SAMPLE + SUSTAIN_TAIL,
        "⭐ `loop_sustain`：非零 = note-off（{END_SAMPLE}）＋ 往后播到样本尾（{SUSTAIN_TAIL}）\
         —— 释放（{RELEASE_FRAMES}）比样本尾巴长 ⇒ **样本尾先到**"
    );
    assert_eq!(
        sustain_mismatches, 0,
        "⭐ `loop_sustain`：释放段必须逐点等于「源下标 **恒 +1**（⛔ 不回绕）× 释放斜坡」\
         （|实测 − 理论| ≤ 1e-6）"
    );
    assert!(
        sustain_indices_increase,
        "⭐ `loop_sustain`：释放期的源下标必须**严格递增**（⛔ 不回绕）\
         —— 这就是「During the release phase, there's no looping」的机械读数"
    );
    assert!(
        sustain_out[END_SAMPLE] != 0.0,
        "⭐ 反向腿：`loop_sustain` 的输出必须**越过** `end_sample`（否则这条腿是空绿）"
    );
    assert!(
        sustain_out[END_SAMPLE + SUSTAIN_TAIL..]
            .iter()
            .all(|sample| *sample == 0.0),
        "⭐ `loop_sustain`：样本播完 ⇒ 逐位静音"
    );
    // ⭐ 两条腿必须**不同**（本节的核心判据；680 ≠ 463）。
    assert_ne!(
        count(&continuous_out),
        count(&sustain_out),
        "⭐ 核心：note-off 之后两者输出必须不同（前一片搬家过来的判据）"
    );

    // ---- 腿 ③：`one_shot` ＋ 有包络 ⇒ **连释放段也不进**（"忽略 note-off"是完整裁决）----
    let one_shot = prepare_with(&text("one_shot"), &pcm);
    let one_shot_out = render_pool(&one_shot, END_SAMPLE as u64, FRAMES);
    // 参照臂：同一个 `one_shot` 夹具但**没有** note-off（`end_sample = u64::MAX`）
    // ⇒ 逐帧对照才能证明"note-off 那一帧没有被释放段改写"。
    let one_shot_free = render_pool(&one_shot, u64::MAX, FRAMES);
    println!(
        "[engine-sfz/S36] ⭐ `one_shot` ＋ `ampeg_release`（end_sample={END_SAMPLE}）⇒ 非零 = {}；\
         第 {END_SAMPLE} 帧 = {}（⛔ 不许就地进释放）",
        count(&one_shot_out),
        one_shot_out[END_SAMPLE],
    );
    assert!(
        one_shot.regions()[0].ignores_note_off(),
        "`one_shot` 的既有裁决：忽略 note-off"
    );
    assert_eq!(
        count(&one_shot_out),
        LOOP_PCM_FRAMES - 1,
        "⭐ `one_shot` ＋ 有包络：note-off（＝ {END_SAMPLE}）既不退休、**也不起释放** ⇒ \
         声部照旧播到样本尾（{LOOP_PCM_FRAMES} 帧样本 ⇒ 最多 {} 帧）",
        LOOP_PCM_FRAMES - 1
    );
    assert_eq!(
        one_shot_out[END_SAMPLE], one_shot_free[END_SAMPLE],
        "⭐ `one_shot`：note-off 那一帧的电平必须等于「无 note-off」（⛔ 不是释放段的第 0 帧）"
    );
    assert_eq!(
        fnv1a_64(&one_shot_out),
        fnv1a_64(&one_shot_free),
        "⭐ `one_shot` ＋ 有包络：整段输出与「无 note-off」**逐位相同**"
    );
}

/// ⭐ S37（任务单 `#92`；§4.4）：**无 `ampeg_*` 的既有夹具逐位不变**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 两份**一个 `ampeg_*` 都没有**的既有形状夹具（① 循环 ＋ 有限 `end_sample`；
/// ② `no_loop` ＋ `end_sample = u64::MAX`）经**实时池**渲染的输出；单位 ＝
/// **FNV-1a 64 指纹**（逐位）＋ **非零帧数**。
///
/// # 字面值的来源（⭐ 改动前实测）
///
/// 两个 `u64` 由本线在**改动任何源码之前**于 base `1beffe2a`（`aarch64/macos`、
/// 同一份夹具、同一条产品路径、一次性探针，测后删除）测得：
///
/// | 夹具 | 帧数 | 非零 | 指纹 |
/// | :--- | :--- | :--- | :--- |
/// | `loop_continuous` ＋ `end_sample = 200` | 512 | 200 | `0xa9dec8a87f69106c` |
/// | `no_loop` ＋ `end_sample = u64::MAX` | 512 | 399 | `0xd3c2a82076bd8947` |
///
/// ⚠ 与既有 [`NO_LOOP_FIXTURE_FINGERPRINT`]（`S33`）同一条纪律：字面值是**跨提交对账**
/// 的读数，⛔ 不是"跨架构必须相等"的规范常数 ⇒ 异平台**如实跳过并点名原因**。
///
/// # 反向腿（⛔ 让"绿"不能是空的）
///
/// 把同一段输出**乘 `1.0000001`** ⇒ 指纹**必须变**（证明它是**逐位**判据）。
#[test]
fn s37_a_fixture_without_any_ampeg_fields_renders_bit_identically() {
    /// ⭐ 改动前实测（base `1beffe2a`、`aarch64/macos`）。
    const LOOP_FIXTURE_FINGERPRINT: u64 = 0xa9de_c8a8_7f69_106c;
    /// ⭐ 改动前实测（同上）。
    const PLAIN_FIXTURE_FINGERPRINT: u64 = 0xd3c2_a820_76bd_8947;

    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    assert!(
        looped.regions()[0].ampeg_is_transparent(),
        "夹具必须**一个 `ampeg_*` 都没有**（否则下面的指纹比对不是「缺省路径」的判据）"
    );
    assert!(plain.regions()[0].ampeg_is_transparent());

    for (label, plan, end_sample, frames, nonzero, expected) in [
        (
            "loop_continuous ＋ end_sample = 200",
            &looped,
            200u64,
            512usize,
            200usize,
            LOOP_FIXTURE_FINGERPRINT,
        ),
        (
            "no_loop ＋ end_sample = u64::MAX",
            &plain,
            u64::MAX,
            512usize,
            399usize,
            PLAIN_FIXTURE_FINGERPRINT,
        ),
    ] {
        let out = render_pool(plan, end_sample, frames);
        let actual = fnv1a_64(&out);
        let nonzero_actual = out.iter().filter(|sample| **sample != 0.0).count();
        // ⭐ 反向腿：逐位判据的敏感性见证。
        let scaled: Vec<f32> = out.iter().map(|sample| sample * 1.000_000_1).collect();
        let scaled_hash = fnv1a_64(&scaled);
        println!(
            "[engine-sfz/S37] {label}：非零 = {nonzero_actual}（改动前 {nonzero}）、\
             指纹 = 0x{actual:016x}（改动前实测 0x{expected:016x}）；\
             反向腿（× 1.0000001）指纹 = 0x{scaled_hash:016x}（必须不同）"
        );
        assert_eq!(nonzero_actual, nonzero, "⭐ {label}：非零帧数也必须不变");
        let _checked = check_fingerprint(&format!("S37 {label}"), actual, expected);
        assert_ne!(
            scaled_hash, actual,
            "⭐ 反向腿（{label}）：输出乘 1.0000001 ⇒ 指纹**必须**不同"
        );
    }
}

/// ⭐ S38（任务单 `#92`；§3.5）：**模块文档里那条"取线性段"的登记可判**。
///
/// # 判定量
///
/// `include_str!("../src/sfz_instrument.rs")`（模块头**源码**）必须含那条**逐字**登记
/// 「本仓取线性段；参考实现的指数／对数选项不在本片范围内」；
/// ⭐ 反向腿：文档里**没有**的那一句 ⇒ `contains` 必须 `false`（⛔ 判据不是恒真）。
///
/// ⚠ 形态照本仓"文本即判据"的既有做法（`S32` 同款）。
#[test]
fn s38_the_linear_segment_registration_is_judgeable() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    /// ⭐ 任务单 `#92` 裁决第 2 条要求逐字写明的那一句。
    const NEEDLE: &str = "本仓取线性段；参考实现的指数／对数选项不在本片范围内";
    println!(
        "[engine-sfz/S38] 模块头含「线性段 ＋ 指数/对数不在本片范围」登记 = {}；\
         反向腿（文档里没有的句子）= {}",
        MODULE_SOURCE.contains(NEEDLE),
        MODULE_SOURCE.contains("本仓取指数段；参考实现的指数选项已在本片范围内"),
    );
    assert!(
        MODULE_SOURCE.contains(NEEDLE),
        "⭐ 模块头必须逐字登记：{NEEDLE}"
    );
    assert!(
        !MODULE_SOURCE.contains("本仓取指数段；参考实现的指数选项已在本片范围内"),
        "⭐ 反向腿：文档里**没有**的句子必须 `contains == false`（否则判据恒真）"
    );
    // ⭐ 第二条登记（⭐ 任务单 `#94` **按规范改写**）：note-off 语义表必须与
    // "`loop_continuous` 释放期照旧循环"一起在案；⭐ **反向腿**：旧口径那一句必须
    // `contains == false`（⛔ 不许留一句与实现相反的文档）。
    const NOTE_OFF_NEEDLE: &str = "释放期照旧循环（可以重复多次）";
    assert!(
        MODULE_SOURCE.contains(NOTE_OFF_NEEDLE),
        "⭐ note-off 语义表必须逐字在案：{NOTE_OFF_NEEDLE}"
    );
    const OLD_NEEDLE: &str = "note-off **不影响循环**：照旧循环并在 `end_sample` 硬停";
    assert!(
        !MODULE_SOURCE.contains(OLD_NEEDLE),
        "⭐ 反向腿：被任务单 `#94` 撤掉的旧口径必须 `contains == false`"
    );
}

// ---------------------------------------------------------------------------
// ⭐ S39～S45：**`group` / `off_by` / `off_mode` 接进实时播放**（任务单 `#94`）
//
// 规范逐字（全部来自 `sfzformat`，⭐ 三条）：
// * <https://sfzformat.com/opcodes/group/>：「Exclusive group number for this region.」
//   ＋「In these cases, the `group` number will be equal to the `off_by` number.」
//   ＋ 镲片扼音例（"the crash sounds would be in one group, the choke samples in another"）；
// * <https://sfzformat.com/opcodes/off_by/>：「Region off group. When a new region with a
//   group number equal to `off_by` plays, this region will be turned off.」；
// * <https://sfzformat.com/opcodes/off_mode/>：「This opcode will determinate how a region
//   is turned off by an `off_by` opcode.」—— `fast`（缺省）＝「The voice will be turned off
//   immediately. Release settings will not have any effect.」；`normal` ＝「The region will
//   be set into release stage.」
//
// ⚠ **作用面**（任务单 `#94` 按规范字面裁）：`off_mode` **只管 `off_by` 关断**，
// ⛔ **不管** MIDI note-off —— 那条路由 `loop_mode` ＋ `ampeg_*` 决定（见 `S35`/`S36`）。
// ---------------------------------------------------------------------------

/// ⭐ S39（任务单 `#94`；§4.3）：**`off_by` 真的把"停"落到那一个声部上**，
/// 且 victim 按**它自己**的关断规则衰减（两个读数：**释放起点** ＋ **非零长度**）。
#[test]
fn s39_off_by_really_stops_the_named_group_member() {
    const NOTE_OFF_AT: usize = 200;
    const RELEASE: usize = 480; // 0.01 s @ 48 kHz
    const TAIL: usize = 64;
    const FRAMES: usize = NOTE_OFF_AT + RELEASE + TAIL;
    /// ⭐ 样本 PCM 长度（`flat_sample(PCM)` 下最多写 `PCM − 1` 帧，见 `mix_span_into`）。
    const PCM: usize = 4096;

    // A：出声、`group=1`、`off_mode=normal`（⇒ 被关断时**进释放**）。
    // B：规范登记的**静音关断区**（`end=-1`）—— 它自己⛔ 不建声部，但照常关断别人
    //    （<https://sfzformat.com/legacy/> 的 `end` 词条逐字："Marking a region end with -1
    //    can be used to use a silent region to turn off other regions by using the `group`
    //    and `off_by` opcodes."）。
    let text = |off_by: u32| {
        format!(
            "<region> sample=a.wav key=60 pitch_keycenter=60 group=1 off_mode=normal \
             ampeg_release=0.01\n\
             <region> sample=s.wav key=62 pitch_keycenter=62 end=-1 off_by={off_by}\n"
        )
    };
    let sample = flat_sample(PCM);
    let plan = prepare_with(&text(1), &sample);
    let control = prepare_with(&text(0), &sample);
    let mut pool = SfzVoicePool::new(48_000.0);
    let mut control_pool = SfzVoicePool::new(48_000.0);
    assert_eq!(
        pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None),
        1,
        "A 必须建 1 个声部"
    );
    assert_eq!(
        control_pool.trigger_note(&control, 60, 127, u64::MAX, 1.0, None),
        1
    );
    let mut out = vec![0.0f32; FRAMES];
    let mut control_out = vec![0.0f32; FRAMES];
    pool.render_into(&plan, 0, &mut out[..NOTE_OFF_AT]);
    control_pool.render_into(&control, 0, &mut control_out[..NOTE_OFF_AT]);
    assert!(
        out[..NOTE_OFF_AT].iter().all(|sample| *sample == 1.0),
        "⭐ 前置见证：关断之前 A 恒 1.0（`ampeg_attack` 缺省 0、sustain 缺省 100 %）"
    );
    assert_eq!(
        pool.voices()[0].end_sample(),
        u64::MAX,
        "关断之前 A 的引擎终点仍是「永不」（夹具给的就是 u64::MAX）"
    );
    // ⭐ 触发 B（静音关断区）：它自己⛔ 不建声部，但 `off_by=1` 必须关掉 group=1 的 A。
    assert_eq!(
        pool.trigger_note(&plan, 62, 127, u64::MAX, 1.0, None),
        0,
        "⭐ 静音关断区（`end=-1`）⛔ 不建声部（既有 `span == None` 口径）"
    );
    assert_eq!(
        control_pool.trigger_note(&control, 62, 127, u64::MAX, 1.0, None),
        0
    );
    assert_eq!(
        pool.voices()[0].end_sample(),
        0,
        "⭐ `normal` 关断 ＝ 把 victim 的 note-off 挪到「现在」（既有 note-off 机接手）"
    );
    assert_eq!(
        control_pool.voices()[0].end_sample(),
        u64::MAX,
        "⭐ 负对照：`off_by=0` ⇒ 一个都不关（同一份夹具、只差那一个数）"
    );
    pool.render_into(&plan, NOTE_OFF_AT as u64, &mut out[NOTE_OFF_AT..]);
    control_pool.render_into(
        &control,
        NOTE_OFF_AT as u64,
        &mut control_out[NOTE_OFF_AT..],
    );
    let count = |samples: &[f32]| samples.iter().filter(|sample| **sample != 0.0).count();
    let ramp_mismatches = (0..RELEASE)
        .filter(|k| {
            let expected = (RELEASE - k) as f32 / RELEASE as f32;
            (out[NOTE_OFF_AT + k] - expected).abs() > 1.0e-6
        })
        .count();
    println!(
        "[engine-sfz/S39] ⭐ `normal` 关断（第 {NOTE_OFF_AT} 帧触发）⇒ 释放起点电平 = {}；\
         非零 = {}（＝ 关断前 {NOTE_OFF_AT} ＋ 释放 {RELEASE}）；释放段与 (R−k)/R 不符 = \
         {ramp_mismatches}；⭐ 负对照（`off_by=0`）在窗内非零 = {}",
        out[NOTE_OFF_AT],
        count(&out),
        count(&control_out),
    );
    assert_eq!(
        out[NOTE_OFF_AT], 1.0,
        "⭐ 释放起点：关断那一帧的电平必须＝关断前那一刻（就地进释放，⛔ 不跳变、⛔ 不硬切）"
    );
    assert_eq!(
        count(&out),
        NOTE_OFF_AT + RELEASE,
        "⭐ 非零长度：关断前 {NOTE_OFF_AT} 帧 ＋ 恰好 {RELEASE} 帧释放"
    );
    assert_eq!(
        ramp_mismatches, 0,
        "⭐ 释放段逐点 ＝ (R − k)/R（|Δ| ≤ 1e-6）"
    );
    assert!(
        out[NOTE_OFF_AT + RELEASE..]
            .iter()
            .all(|sample| *sample == 0.0),
        "⭐ 释放走完 ⇒ 逐位 0（声部已退休）"
    );
    assert_eq!(
        count(&control_out),
        FRAMES,
        "⭐ 负对照：`off_by=0` ⇒ A 一路有声（窗内 {FRAMES} 帧全非零）"
    );
    assert!(
        count(&out) < count(&control_out),
        "⭐ 正/负对照（第 42 条）：关断腿必须比不关断那条**更短**"
    );
}

/// ⭐ S40（任务单 `#94`；§4.4）：**组号不匹配的区域必须完全不受影响**（⛔ 不误伤）。
///
/// ⭐ **负判据的正对照**（第 42 条）：同一批数据里同时有"该被停的"（A，`group=1`）与
/// "不该被停的"（C，`group=4`）；`off_by` 取 `1`（关 A）／`0`（不关任何）／`5`（⛔ 没有
/// 区域属于组 5）三跑 ⇒ 后两跑**整段逐位相同**，而第一跑必须不同；C 的**声部状态**
/// 在"关 A"与"不关"两跑之间也必须**逐字段相同**。
#[test]
fn s40_off_by_never_touches_a_region_outside_the_named_group() {
    const HALF: usize = 200;
    let text = |off_by: u32| {
        format!(
            "<region> sample=a.wav key=60 pitch_keycenter=60 group=1 off_mode=normal ampeg_release=0.01\n\
             <region> sample=s.wav key=62 pitch_keycenter=62 end=-1 off_by={off_by}\n\
             <region> sample=c.wav key=62 pitch_keycenter=62 group=4\n"
        )
    };
    let sample = flat_sample(4096);
    let run = |off_by: u32| {
        let plan = prepare_with(&text(off_by), &sample);
        let mut pool = SfzVoicePool::new(48_000.0);
        assert_eq!(pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None), 1);
        let mut out = vec![0.0f32; HALF * 2];
        pool.render_into(&plan, 0, &mut out[..HALF]);
        // ⭐ 关断区是**静音**的 ⇒ 本次触发只可能改变 A 的状态。
        assert_eq!(
            pool.trigger_note(&plan, 62, 127, u64::MAX, 1.0, None),
            1,
            "只有 C 建声部"
        );
        pool.render_into(&plan, HALF as u64, &mut out[HALF..]);
        (pool, out)
    };
    let (pool_stop, out_stop) = run(1);
    let (pool_none, out_none) = run(0);
    let (pool_other, out_other) = run(5);
    println!(
        "[engine-sfz/S40] 指纹：off_by=1 ⇒ {:#018x}；off_by=0 ⇒ {:#018x}；off_by=5 ⇒ {:#018x}",
        fnv1a_64(&out_stop),
        fnv1a_64(&out_none),
        fnv1a_64(&out_other),
    );
    assert_eq!(
        fnv1a_64(&out_none),
        fnv1a_64(&out_other),
        "⭐ 组号不匹配（off_by=5，⛔ 没有区域属于组 5）⇒ 与「不关任何」逐位相同"
    );
    assert_eq!(out_none, out_other, "⭐ 逐位相同（比整段，⛔ 不止比指纹）");
    assert_eq!(
        pool_other.voices()[1],
        pool_none.voices()[1],
        "⭐ 声部状态读数：`off_by=5`（无人属于组 5）与 `off_by=0` 下 C 逐字段相同"
    );
    assert_ne!(
        fnv1a_64(&out_stop),
        fnv1a_64(&out_none),
        "⭐ 正对照：`off_by=1` 真的关掉了 A ⇒ 输出必须不同"
    );
    // ⭐ C 的声部**状态**（位置／增益／包络计数器／终点…）在关 A 与不关 A 两跑之间相同。
    assert_eq!(
        pool_stop.voices()[1],
        pool_none.voices()[1],
        "⭐ C 必须逐字段不受影响（它不在被点名的组里）"
    );
    assert_eq!(
        pool_stop.active_count(),
        2,
        "关断腿：A 进释放（仍 active）＋ C 在响 ⇒ 活声部 2"
    );
    assert!(
        pool_stop.voices()[0].is_active(),
        "⭐ `normal` 关断⛔ 不是硬停：A 在释放段里仍然是活声部"
    );
}

/// ⭐ S41（任务单 `#94`；原 §4.1 的"fast vs normal 可判"**改在 `off_by` 关断路径上考**
/// —— 那是规范唯一赋予 `off_mode` 意义的路径）：两条腿**都必须不同**，
/// 且**各配一条"它自己该怎样"的断言**（⛔ 只断言"不同"不够）。
///
/// 规范逐字（<https://sfzformat.com/opcodes/off_mode/>）：
/// * `fast`（缺省）：「The voice will be turned off immediately. Release settings will not
///   have any effect.」⇒ 关断帧起**逐位 0**（`ampeg_release` 不生效）；
/// * `normal`：「The region will be set into release stage.」⇒ 就地进释放段
///   （`ampeg_release × engine_hz` 帧线性归零）。
#[test]
fn s41_off_by_fast_cuts_immediately_and_normal_enters_release() {
    const NOTE_OFF_AT: usize = 200;
    const RELEASE: usize = 480;
    const TAIL: usize = 64;
    const FRAMES: usize = NOTE_OFF_AT + RELEASE + TAIL;
    let text = |mode: &str| {
        format!(
            "<region> sample=a.wav key=60 pitch_keycenter=60 group=1 off_mode={mode} \
             ampeg_release=0.01\n\
             <region> sample=s.wav key=62 pitch_keycenter=62 end=-1 off_by=1\n"
        )
    };
    let sample = flat_sample(4096);
    let run = |mode: &str| {
        let plan = prepare_with(&text(mode), &sample);
        let mut pool = SfzVoicePool::new(48_000.0);
        assert_eq!(pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None), 1);
        let mut out = vec![0.0f32; FRAMES];
        pool.render_into(&plan, 0, &mut out[..NOTE_OFF_AT]);
        pool.trigger_note(&plan, 62, 127, u64::MAX, 1.0, None);
        pool.render_into(&plan, NOTE_OFF_AT as u64, &mut out[NOTE_OFF_AT..]);
        (pool, out)
    };
    let (fast_pool, fast_out) = run("fast");
    let (normal_pool, normal_out) = run("normal");
    let count = |samples: &[f32]| samples.iter().filter(|sample| **sample != 0.0).count();
    let ramp_mismatches = (0..RELEASE)
        .filter(|k| {
            let expected = (RELEASE - k) as f32 / RELEASE as f32;
            (normal_out[NOTE_OFF_AT + k] - expected).abs() > 1.0e-6
        })
        .count();
    println!(
        "[engine-sfz/S41] ⭐ `fast` ⇒ 非零 = {}（关断帧起逐位 0）；⭐ `normal` ⇒ 非零 = {}；\
         释放起点电平 = {}；释放段与 (R−k)/R 不符 = {ramp_mismatches}",
        count(&fast_out),
        count(&normal_out),
        normal_out[NOTE_OFF_AT],
    );
    // ---- 腿 ①：`fast` ⇒ 立刻关断（release 设置无效）----
    assert_eq!(
        count(&fast_out),
        NOTE_OFF_AT,
        "⭐ `fast`：关断帧起逐位 0 ⇒ 非零恰好 {NOTE_OFF_AT}"
    );
    assert!(
        fast_out[NOTE_OFF_AT..].iter().all(|sample| *sample == 0.0),
        "⭐ `fast`：`ampeg_release` 设置**无效**"
    );
    assert!(
        !fast_pool.voices()[0].is_active(),
        "⭐ `fast` ＝ 声部**当场退休**（池内状态翻转）"
    );
    // ---- 腿 ②：`normal` ⇒ 进释放段 ----
    assert_eq!(
        normal_out[NOTE_OFF_AT], 1.0,
        "⭐ `normal`：关断那一帧 ＝ 释放起点电平（就地进释放，⛔ 不跳变）"
    );
    assert_eq!(
        count(&normal_out),
        NOTE_OFF_AT + RELEASE,
        "⭐ `normal`：非零 ＝ 关断前 {NOTE_OFF_AT} ＋ 恰好 {RELEASE} 帧释放"
    );
    assert_eq!(ramp_mismatches, 0, "⭐ `normal`：释放段逐点 ＝ (R − k)/R");
    assert!(
        normal_out[NOTE_OFF_AT + RELEASE - 1] > 0.0,
        "⭐ `normal`：释放的**最后一帧**仍非零（释放段真的走满 {RELEASE} 帧 ⇒ ⛔ 不是硬停）"
    );
    assert!(
        !normal_pool.voices()[0].is_active(),
        "⭐ `normal`：**释放走完才退休**（与 `fast` 的「立刻退休」分开钉）"
    );
    // ---- 反向腿：两者必须不同 ----
    assert_ne!(
        count(&fast_out),
        count(&normal_out),
        "⭐ 核心：`fast` ≠ `normal`（{NOTE_OFF_AT} ≠ {}）",
        NOTE_OFF_AT + RELEASE
    );
}

/// ⭐ S42（任务单 `#94` 裁决 4）：**`one_shot` 的 victim 也忽略 `off_by`**
/// （"忽略 note-off"是一条**完整**裁决 ⇒ `off_by` 这种停止请求同样被忽略），
/// ⭐ **并配正对照**：同一批数据里把 victim 换成 `no_loop` ⇒ 关断**必须**发生
/// （⛔ 否则上面那条"逐位相同"可能是"夹具根本没触发"的假绿）。
#[test]
fn s42_a_one_shot_victim_ignores_off_by() {
    const HALF: usize = 200;
    let text = |mode: &str, off_by: u32| {
        format!(
            "<region> sample=a.wav key=60 pitch_keycenter=60 group=1 off_mode=normal \
             loop_mode={mode} ampeg_release=0.01\n\
             <region> sample=s.wav key=62 pitch_keycenter=62 end=-1 off_by={off_by}\n"
        )
    };
    let sample = flat_sample(4096);
    let run = |mode: &str, off_by: u32| {
        let plan = prepare_with(&text(mode, off_by), &sample);
        assert!(
            plan.regions()[0].ignores_note_off() == (mode == "one_shot"),
            "夹具自检：`ignores_note_off` 必须与 loop_mode 一致"
        );
        let mut pool = SfzVoicePool::new(48_000.0);
        assert_eq!(pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None), 1);
        let mut out = vec![0.0f32; HALF * 2];
        pool.render_into(&plan, 0, &mut out[..HALF]);
        pool.trigger_note(&plan, 62, 127, u64::MAX, 1.0, None);
        pool.render_into(&plan, HALF as u64, &mut out[HALF..]);
        out
    };
    let one_shot_stopped = run("one_shot", 1);
    let one_shot_free = run("one_shot", 0);
    let no_loop_stopped = run("no_loop", 1);
    let no_loop_free = run("no_loop", 0);
    println!(
        "[engine-sfz/S42] ⭐ `one_shot`：off_by=1 与 off_by=0 的指纹 = {:#018x} / {:#018x}；\
         ⭐ 正对照 `no_loop`：{:#018x} / {:#018x}",
        fnv1a_64(&one_shot_stopped),
        fnv1a_64(&one_shot_free),
        fnv1a_64(&no_loop_stopped),
        fnv1a_64(&no_loop_free),
    );
    assert_eq!(
        one_shot_stopped, one_shot_free,
        "⭐ `one_shot` ＋ `off_by=1` 必须与 `off_by=0` **逐位相同**（它忽略 `off_by`）"
    );
    assert_eq!(
        fnv1a_64(&one_shot_stopped),
        fnv1a_64(&one_shot_free),
        "⭐ 同一条的指纹读数"
    );
    assert_ne!(
        no_loop_stopped, no_loop_free,
        "⭐ 正对照：同批数据里 `no_loop` 的 victim **必须**被关掉（否则上面那条是空绿）"
    );
}

/// ⭐ S43（任务单 `#94` 裁决 5）：**触发者不自掐**。
///
/// 夹具就是登记语料 `assets/samples/karoryfer-272-merry-orks/ork_dialogue.sfz` 的写法
/// （`group=1` ＋ `off_by=1` ＝ 同组独占）：第二次触发**必须关掉第一个声部**，
/// 而**第二个声部自己**必须照常发声 —— ⭐ 按 ARIA 的自掐解释，新声部会被自己立刻掐掉，
/// 那 20 处会**发不出声** ⇒ 本仓取 rgc／sfizz 一侧（不自掐）。
#[test]
fn s43_the_triggering_region_does_not_choke_itself() {
    const FIRST: usize = 100;
    let sample = flat_sample(4096);
    let plan = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 group=1 off_by=1\n",
        &sample,
    );
    let mut pool = SfzVoicePool::new(48_000.0);
    assert_eq!(
        pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None),
        1,
        "第一次触发建 1 个声部"
    );
    let mut out = vec![0.0f32; FIRST * 2];
    pool.render_into(&plan, 0, &mut out[..FIRST]);
    assert_eq!(pool.active_count(), 1);
    assert_eq!(pool.voices()[0].source_position(), FIRST as f32);
    // ⭐ 第二次触发**同一条区域**：它自己就是自己的 `off_by` 目标。
    assert_eq!(
        pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None),
        1,
        "第二次触发建 1 个声部"
    );
    assert_eq!(
        pool.active_count(),
        1,
        "⭐ 恰好 1 个活声部：旧声部被关掉、**新声部没有被自己掐掉**\
         （自掐 ⇒ 0；完全不关 ⇒ 2 ⇒ 两种都被这条抓住）"
    );
    assert_eq!(
        pool.voices()[0].source_position(),
        0.0,
        "⭐ 活下来的是**新**声部（源位置从 0 起）"
    );
    pool.render_into(&plan, FIRST as u64, &mut out[FIRST..]);
    assert!(
        out[FIRST..].iter().all(|sample| *sample == 1.0),
        "⭐ 新声部必须照常发声（整段恒 1.0）—— 自掐会让它一个样本都发不出来"
    );
}

/// ⭐ S44（任务单 `#94`；第 259 条）：**非法的 `group` / `off_by` 响亮 `Err`**，
/// ⛔ 不静默降级；⭐ 同批数据里的合法样例**必须被接受**；⭐ 缺省与别名逐字回读。
///
/// ⚠ 域是 `yeban-sfz` 的**既有**口径（`read_u32` ⇒ `0..=u32::MAX`，与
/// `tests/malformed_inputs.rs` 的登记一致）—— 本片⛔ 不改解析、⛔ 不发明边界。
#[test]
fn s44_illegal_group_and_off_by_are_errors_not_defaults() {
    let load = |text: &str| SfzInstrument::load(text.to_owned(), &Default::default());
    // ---- ① 合法 ⇒ 原样读出 ----
    let legal = load("<region> sample=a.wav group=7 off_by=9\n").expect("⭐ 合法样例必须被接受");
    let plan = PreparedSfz::prepare(&legal, &flat_sample(64), 48_000.0).expect("摊平");
    let region = &plan.regions()[0];
    assert_eq!(region.group(), 7, "`group` 原样");
    assert_eq!(region.off_by(), 9, "`off_by` 原样");
    assert_eq!(
        region.off_mode(),
        OffMode::Fast,
        "`off_mode` 缺省是 `fast`（规范缺省）"
    );
    // ---- ② 缺省：`group=0` ＋ `off_by=0`（⛔ 不关任何人）----
    let default = load("<region> sample=a.wav\n").expect("parses");
    let default_plan = PreparedSfz::prepare(&default, &flat_sample(64), 48_000.0).expect("摊平");
    let default_region = &default_plan.regions()[0];
    assert_eq!(
        (default_region.group(), default_region.off_by()),
        (0, 0),
        "⭐ 缺省：组 0、⛔ 不关任何区域"
    );
    // ---- ③ 非法 ⇒ `Err`（⛔ 不是"降级 ＋ 记录"）----
    for text in [
        "<region> sample=a.wav off_by=-1\n",
        "<region> sample=a.wav group=-1\n",
    ] {
        assert!(
            matches!(load(text), Err(SfzError::IntegerOutOfRange { .. })),
            "⛔ {text:?} 必须**越界报错**（⛔ 不许静默钳到 0）"
        );
    }
    for text in [
        "<region> sample=a.wav off_by=abc\n",
        "<region> sample=a.wav group=abc\n",
    ] {
        assert!(
            matches!(load(text), Err(SfzError::InvalidInteger { .. })),
            "⛔ {text:?} 必须**认不出就报错**（⛔ 不许落缺省）"
        );
    }
    // ---- ④ 两个别名与四级作用域链同径 ----
    let alias = load("<group>polyphony_group=3 offby=4\n<region> sample=a.wav\n").expect("parses");
    let alias_plan = PreparedSfz::prepare(&alias, &flat_sample(64), 48_000.0).expect("摊平");
    assert_eq!(
        (
            alias_plan.regions()[0].group(),
            alias_plan.regions()[0].off_by()
        ),
        (3, 4),
        "⭐ `polyphony_group` / `offby` 两个别名经 `<group>` 段继承下来"
    );
}

/// ⭐ S45（任务单 `#94` §3.2 的第二条）：**`off_by` 的硬停只动 `active` 那一个声部，
/// ⛔ 不丢掉同槽的挂起者（`pending`）**。
///
/// 场景：池被 `SFZ_VOICES_PER_TRACK` 条区域灌满 ⇒ 第 17 条区域走**窃取**，那个槽里
/// `active` ＝ 正在淡出的 victim、`pending` ＝ 等着接管的新声部；此时再触发一条 `off_by`
/// 静音关断区 ⇒ victim 被**硬停**，而 `pending` 必须**照常接管**
/// （读数：`pending_count()` ＋ 接管后那个声部的 `sample_index` ＋ 输出非零）。
#[test]
fn s45_an_off_by_hard_stop_keeps_the_pending_voice_in_the_same_slot() {
    let mut text = String::new();
    for _ in 0..SFZ_VOICES_PER_TRACK {
        text.push_str("<region> sample=a.wav key=60 pitch_keycenter=60 group=7\n");
    }
    // 第 17 条：走窃取 ⇒ 挂起（用另一份 PCM ⇒ 接管后能靠 `sample_index` 认出来）。
    text.push_str("<region> sample=b.wav key=60 pitch_keycenter=60 group=7\n");
    // 关断区（另一个音符 ⇒ ⛔ 不占池的槽）：静音、`off_by=7`。
    text.push_str("<region> sample=s.wav key=62 pitch_keycenter=62 end=-1 off_by=7\n");
    let instrument = SfzInstrument::load(text, &Default::default()).expect("夹具必须解析成功");
    let plan = PreparedSfz::prepare_with_samples(
        &instrument,
        &[
            ("a.wav".to_string(), flat_sample(4096)),
            ("b.wav".to_string(), flat_sample(4096)),
        ],
        48_000.0,
    )
    .expect("摊平必须成功");
    assert_eq!(plan.samples()[0].path(), "a.wav");
    assert_eq!(plan.samples()[1].path(), "b.wav");
    let mut pool = SfzVoicePool::new(48_000.0);
    let created = pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None);
    assert_eq!(created, SFZ_VOICES_PER_TRACK, "⭐ 前 16 条占满池");
    assert_eq!(pool.stolen(), 1, "⭐ 第 17 条走窃取");
    assert_eq!(pool.pending_count(), 1, "⭐ 窃取 ⇒ 恰好 1 个挂起者");
    assert_eq!(
        pool.voices()[0].sample_index(),
        0,
        "victim 仍占着槽 0（它还在淡出）"
    );
    // ⭐ 触发关断区：槽 0 的 active victim 被**硬停**（缺省 `off_mode=fast`）。
    assert_eq!(
        pool.trigger_note(&plan, 62, 127, u64::MAX, 1.0, None),
        0,
        "静音关断区⛔ 不建声部"
    );
    assert_eq!(
        pool.active_count(),
        0,
        "⭐ 组 7 的 16 个 active 声部全被关掉"
    );
    assert_eq!(
        pool.pending_count(),
        1,
        "⭐ 挂起者**必须还在**（⛔ 不许被 `off_by` 的硬停连带丢掉）"
    );
    let mut out = vec![0.0f32; 512];
    pool.render_into(&plan, 0, &mut out);
    assert_eq!(
        pool.pending_count(),
        0,
        "⭐ 同一块内挂起者就地接管（`render_slot` 第 2 步）"
    );
    assert_eq!(pool.active_count(), 1, "⭐ 接管之后恰好 1 个活声部");
    assert_eq!(
        pool.voices()[0].sample_index(),
        1,
        "⭐ 接管的是**挂起者**（`b.wav`），⛔ 不是被硬停的 victim"
    );
    assert!(
        out.iter().any(|sample| *sample != 0.0),
        "⭐ 接管者必须真的发声（⛔ 不是「槽还在但永远不出声」）"
    );
}

// ---------------------------------------------------------------------------
// ⭐ S46～S48：**`loop_end == pcm_len` 也循环（插值钳位）**（任务单 `#97`）
//
// 缺口（`#91` 主动登记、集成者确认是真的）：`reduce_loop_window` 的旧口径要求
// `loop_end` **严格小于** `pcm_len`（理由是线性插值要读 `index + 1`）⇒
// `loop_end = 文件总帧数`（"循环到结尾"）的窗口被**判成不循环** ⇒ 真实 SFZ 会
// **静默变成不循环**。裁决：**在循环边界处把插值钳位**，⛔ 不是把窗口判成不循环。
//
// 判据分工：
//   * S46 —— 两条腿（`pcm_len − 1` / `pcm_len`）**都周期化**，各自实测周期精确；
//   * S47 —— 钳位**不越界、不爆音**，且 `pcm_len − 1` 那条腿**未被钳位**（行为不变）；
//   * S48 —— 既有判据（`S28`／`S30`／`S37`／`S33`）的读数**原样复跑并断言**。
// ---------------------------------------------------------------------------

/// ⭐ S46（任务单 `#97`；§3.1）：**`loop_end == pcm_len` 也循环**，且两条腿的
/// **实测最小周期**各自恰好等于 `loop_end − loop_start`。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 实时池（[`SfzVoicePool`]）渲染出的一段输出；单位 ＝ **源采样下标**
/// （斜坡夹具**逐帧反解**，见 [`ramp_sample`]；`rate == 1.0` ⇒ 源下标与输出帧一一对应）。
///
/// # 两条腿（⭐ 都必须循环）
///
/// | 腿 | `loop_end` | 声明周期 | 为什么必须量 |
/// | :--- | :--- | :--- | :--- |
/// | **A（既有）** | `pcm_len − 1 = 399` | `299` | ⭐ 硬边界：它的行为⛔ 不许变 |
/// | **B（本单）** | `pcm_len = 400` | `300` | ⭐ 旧口径把它**判成不循环** ⇒ 本单必须让它周期化 |
///
/// 两条腿各断言：窗口逐字回读／整段写满／**实测最小周期 == 声明周期**／下标序列
/// **逐帧精确**（0 处不符）。⭐ **反向腿**：窗口段必须 ≥ 2 个不同位模式（⛔ 防空转）。
#[test]
fn s46_a_window_ending_exactly_at_the_sample_end_still_loops() {
    for (label, loop_end, period) in [
        (
            "既有腿 loop_end = pcm_len − 1",
            LOOP_PCM_FRAMES - 1,
            LOOP_PCM_FRAMES - 1 - LOOP_START,
        ),
        (
            "本单腿 loop_end = pcm_len",
            LOOP_PCM_FRAMES,
            LOOP_PCM_FRAMES - LOOP_START,
        ),
    ] {
        let plan = prepare_with(
            &loop_sfz("loop_continuous", LOOP_START, loop_end),
            &ramp_sample(LOOP_PCM_FRAMES),
        );
        let region = &plan.regions()[0];
        assert_eq!(
            (region.loop_start(), region.loop_end()),
            (LOOP_START as u32, loop_end as u32),
            "⭐ {label}：摊平表必须逐字带出两个循环点"
        );
        let window = region.loop_window(LOOP_PCM_FRAMES).unwrap_or_else(|| {
            panic!("⭐ {label}：`loop_end <= pcm_len` ⇒ 必须有**有效窗口**（⛔ 不是按不循环渲染）")
        });
        assert_eq!(
            (
                window.start as usize,
                window.end as usize,
                window.len() as usize
            ),
            (LOOP_START, loop_end, period),
            "⭐ {label}：归约窗口与长度"
        );

        let frames = loop_end + 3 * period;
        let out = render_pool(&plan, u64::MAX, frames);
        let nonzero = out.iter().filter(|sample| **sample != 0.0).count();
        let measured = detect_period(&out, LOOP_START, loop_end);
        let mismatches = loop_index_mismatches(&out, LOOP_START, period);
        let distinct = out[LOOP_START..loop_end]
            .iter()
            .map(|sample| sample.to_bits())
            .collect::<std::collections::BTreeSet<_>>()
            .len();
        println!(
            "[engine-sfz/S46] {label}：窗口 = [{LOOP_START},{loop_end}) ⇒ 声明周期 = {period}；\
             {frames} 帧里非零 = {nonzero}；⭐ **实测最小周期** = {measured}；\
             下标序列不符 = {mismatches}；窗口段不同位模式 = {distinct}"
        );
        assert_eq!(
            nonzero, frames,
            "⭐ {label}：循环声部必须**写满整段**（⛔ 不因「样本播完」退休）"
        );
        assert_eq!(
            measured, period,
            "⭐ {label}：**实测周期必须恰好等于 `loop_end − loop_start`**（实得 {measured}）"
        );
        assert_eq!(
            mismatches, 0,
            "⭐ {label}：下标序列必须**逐帧精确**（⛔ 不是「波形看起来在重复」）"
        );
        assert!(
            distinct >= 2,
            "⭐ {label} 反向腿：窗口段必须 ≥ 2 个不同位模式（否则「周期」可能是常数段的假象）"
        );
    }
}

/// ⭐ S47（任务单 `#97`；§3.2）：**钳位不越界、不爆音**，且**未钳位腿行为不变**。
///
/// # 夹具（为什么必须长这样）
///
/// * `pcm_len = 400`、窗口 `[100, loop_end)`；
/// * `pcm[0] = −1.0`（窗口**外**的负离群点 —— 它是"钳到 0"那种错法的**证人**）；
/// * `pcm[399] = +1.0`（窗口**末格**；对 `loop_end = 400` 腿它在窗口内，对 `399` 腿它在窗口外）；
/// * 其余是斜坡 `pcm[i] = (i + 1) / 1024`（2 的幂 ⇒ binary32 逐位精确）；
/// * ⭐ `key=60 pitch_keycenter=72` ⇒ `rate = 2^-1 = 0.5`（**2 的幂 ⇒ 逐位精确**）
///   ⇒ `frac ≡ 0.5` ⇒ **插值的那一格真的被读到**。
///   ⚠ `rate == 1.0`（`S28`／`S30`／`S46`）时 `frac ≡ 0` ⇒ **钳位与不钳位读不出差别**
///   —— 在这条判据上那会是**空转**，故本条必须换夹具。
///
/// # 判定量（逐条）
///
/// * ⭐ **钳位腿**（`loop_end = pcm_len`）：回绕点那一帧**逐位** ＝
///   `pcm[399]*(1−0.5) + pcm[399]*0.5`（**两格都是最后一格**）＋ 进入循环后**每一帧**
///   都落在窗口 `[window_min, window_max]` 内 ⇒ "钳到 0"（把 `pcm[0] = −1.0` 卷进来）
///   **必红**；
/// * ⭐ **未钳位腿**（`loop_end = pcm_len − 1`）：回绕点那一帧**仍**读窗口**外**紧邻的
///   `pcm[loop_end] = +1.0` ⇒ **逐位**等于 `pcm[398]*(1−0.5) + pcm[399]*0.5` 且
///   **大于**窗口最大值 ⇒ 正面见证"本单只对 `== pcm_len` 那一档钳位"；
/// * **有界**（不爆音）：每个输出帧 `|out| ≤ 样本峰值`；
/// * **周期化**：`rate = 0.5` ⇒ 输出帧周期 ＝ `2 × (loop_end − loop_start)`（`598` / `600`）
///   —— ⭐ 与 S46 的 `rate = 1.0` 口径互为独立见证；
/// * **不 panic**：钳位腿上若不钳，`pcm[index + 1]` 就是 `pcm[400]`（⭐ 这条判据会当场炸）
///   ⇒ 跑完即证。
#[test]
fn s47_the_clamp_stays_inside_the_window_and_bounds_every_sample() {
    /// ⭐ 夹具的两格"物证"（窗口外负离群点 ＋ 窗口末格正离群点）。
    const OUTLIER: f32 = 1.0;
    /// ⭐ 半速率（`pitch_keycenter=72`）：`frac` 恒为 `1 − 0.5`／`0.5`。
    const HALF: f32 = 0.5;

    let mut pcm: Vec<f32> = (0..LOOP_PCM_FRAMES)
        .map(|frame| (frame + 1) as f32 / 1024.0)
        .collect();
    pcm[0] = -OUTLIER;
    pcm[LOOP_PCM_FRAMES - 1] = OUTLIER;
    let sample = InMemorySample {
        pcm: pcm.clone(),
        sample_hz: 48_000.0,
    };
    let peak = pcm.iter().fold(0.0f32, |acc, value| acc.max(value.abs()));

    for (label, loop_end, clamped) in [
        (
            "未钳位腿 loop_end = pcm_len − 1",
            LOOP_PCM_FRAMES - 1,
            false,
        ),
        ("钳位腿 loop_end = pcm_len", LOOP_PCM_FRAMES, true),
    ] {
        let period = loop_end - LOOP_START;
        let text = format!(
            "<region> sample=a.wav key=60 pitch_keycenter=72 loop_mode=loop_continuous \
             loop_start={LOOP_START} loop_end={loop_end}\n"
        );
        let plan = prepare_with(&text, &sample);
        // ⚠ `rate = 0.5` ⇒ `position = 0.5 t`：到 `loop_start` 要 `2 × loop_start` 帧。
        let entered = 2 * LOOP_START;
        // ⚠ 回绕点**前**那一帧：`position = loop_end − 1 + 0.5` ⇒ `t = 2 (loop_end − 1) + 1`。
        let boundary = 2 * (loop_end - 1) + 1;
        let frames = boundary + 2 * (2 * period) + 8;
        let out = render_pool(&plan, u64::MAX, frames);
        let window_min = pcm[LOOP_START..loop_end]
            .iter()
            .copied()
            .fold(f32::INFINITY, f32::min);
        let window_max = pcm[LOOP_START..loop_end]
            .iter()
            .copied()
            .fold(f32::NEG_INFINITY, f32::max);
        let over_peak = out.iter().filter(|value| value.abs() > peak).count();
        let outside_window = out[entered..]
            .iter()
            .filter(|value| **value < window_min || **value > window_max)
            .count();
        let measured = detect_period(&out, entered, entered + 2 * period);
        println!(
            "[engine-sfz/S47] {label}：窗口 = [{LOOP_START},{loop_end}) ⇒ 声明周期 = {period}；\
             帧周期实测 = {measured}（期望 {}）；边界帧 t = {boundary} ⇒ out = {}（窗口 [{window_min},\
             {window_max}]）；越峰帧 = {over_peak}；进入循环后越窗帧 = {outside_window}；\
             pcm[0] = {}、pcm[loop_end] = {:?}",
            2 * period,
            out[boundary],
            pcm[0],
            pcm.get(loop_end).copied(),
        );

        // ① **不爆音**：每个输出帧都在样本峰值之内。
        assert_eq!(
            over_peak, 0,
            "⭐ {label}：每个输出帧都必须 `|out| ≤ 样本峰值`（实得越峰 {over_peak} 帧）"
        );
        // ② **周期化**：源周期 `period` 帧 ⇒ 输出帧周期 `2 × period`（`rate = 0.5`）。
        assert_eq!(
            measured,
            2 * period,
            "⭐ {label}：输出帧周期必须是 `2 × (loop_end − loop_start)`（实得 {measured}）"
        );
        // ③ 回绕点那一帧的**读法**（钳位腿 vs 未钳位腿）。
        if clamped {
            let expected = pcm[loop_end - 1] * (1.0 - HALF) + pcm[loop_end - 1] * HALF;
            assert_eq!(
                out[boundary], expected,
                "⭐ {label}：回绕点那一帧**两格都是最后一格**（钳位到最后一个样本）；\
                 「钳到 0」会把 `pcm[0] = {OUTLIER}` 的相反数卷进来 ⇒ 这里红"
            );
            assert_eq!(
                outside_window, 0,
                "⭐ {label}：进入循环后**每一帧**都必须落在窗口 `[{window_min}, {window_max}]` 内\
                 （⛔ 窗口外的 `pcm[0]` 一次都不许被读到）"
            );
        } else {
            let expected = pcm[loop_end - 1] * (1.0 - HALF) + pcm[loop_end] * HALF;
            assert_eq!(
                out[boundary], expected,
                "⭐ {label}：回绕点那一帧读的仍是窗口**外**紧邻的 `pcm[{loop_end}]`（⛔ 行为不许变）"
            );
            assert!(
                out[boundary] > window_max,
                "⭐ {label}：这一帧**故意**越出窗口最大值（＝ 它没有被钳位的正面见证）"
            );
        }
    }
}

/// ⭐ S48（任务单 `#97`；§3.3）：**既有判据的读数原样**（复跑并断言）。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// ① 对象 ＝ `S28`／`S30` 的两份斜坡夹具在**实时池**上的输出；单位 ＝ **实测最小周期**
/// （帧）＋ **逐帧下标不符数**（处）；
/// ② 对象 ＝ `S37` 的两份无 `ampeg_*` 夹具 512 帧输出；单位 ＝ **FNV-1a 64 指纹**（逐位）
/// ＋ **非零帧数**（帧）；
/// ③ 对象 ＝ `S33` 的无 `loop_*` 夹具（[`TWO_MATCH_ONE_MISS`]）经 `render_track` 的
/// 512 帧输出；单位 ＝ **FNV-1a 64 指纹**（逐位）。
///
/// # 字面值的来源
///
/// 全部是**既有判据自己**钉住的常数（`S28`／`S30`／`S37`／`S33` 的文档里各有点名），
/// ⛔ 本判据不新造任何字面值 —— 它只是把那些读数**再量一次**，让"既有判据 0 条变状态"
/// 这件事有一条**当期**的、能因**夹具被扰动**而变红的见证。
///
/// # 反向腿（⛔ 让"绿"不能是空的）
///
/// ⭐ 把**无 `loop_*` 的既有夹具样本**乘 `1.0000001` ⇒ 本判据的 ③（以及 `S33`、`S37`
/// 的 `plain` 腿）**必须红**（任务单 `#97` 的注入 3）。
#[test]
fn s48_the_existing_loop_readings_and_fingerprints_are_unchanged() {
    /// ⭐ `S37` 的两条既有指纹（改动前实测；来源见 `S37` 的文档）。
    const S37_LOOPED: u64 = 0xa9de_c8a8_7f69_106c;
    const S37_PLAIN: u64 = 0xd3c2_a820_76bd_8947;

    // ① `S28`／`S30`：周期 ＋ 逐帧下标（`rate = 1.0`，窗口 `[100, loop_end)`）。
    for (label, loop_end, period) in [
        ("S28／S30 loop_end = 164", 164usize, 64usize),
        ("S30 loop_end = 200", 200usize, 100usize),
    ] {
        let plan = prepare_with(
            &loop_sfz("loop_continuous", LOOP_START, loop_end),
            &ramp_sample(LOOP_PCM_FRAMES),
        );
        let frames = loop_end + 3 * period;
        let out = render_pool(&plan, u64::MAX, frames);
        let measured = detect_period(&out, LOOP_START, loop_end);
        let mismatches = loop_index_mismatches(&out, LOOP_START, period);
        println!(
            "[engine-sfz/S48] ① {label}：声明周期 = {period}；实测周期 = {measured}；\
             下标序列不符 = {mismatches}（帧数 {frames}）"
        );
        assert_eq!(measured, period, "⭐ {label}：既有周期读数必须原样");
        assert_eq!(mismatches, 0, "⭐ {label}：既有逐帧下标读数必须原样");
    }

    // ② `S37`：两个无 `ampeg_*` 夹具的 FNV 指纹 ＋ 非零帧数。
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, nonzero, expected) in [
        (
            "S37 loop_continuous ＋ end_sample = 200",
            &looped,
            200u64,
            200usize,
            S37_LOOPED,
        ),
        (
            "S37 no_loop ＋ end_sample = u64::MAX",
            &plain,
            u64::MAX,
            399usize,
            S37_PLAIN,
        ),
    ] {
        let out = render_pool(plan, end_sample, 512);
        let actual = fnv1a_64(&out);
        let nonzero_actual = out.iter().filter(|sample| **sample != 0.0).count();
        println!(
            "[engine-sfz/S48] ② {label}：非零 = {nonzero_actual}（既有 {nonzero}）、\
             指纹 = 0x{actual:016x}（既有 0x{expected:016x}）"
        );
        assert_eq!(nonzero_actual, nonzero, "⭐ {label}：既有非零帧数必须原样");
        let _checked = check_fingerprint(&format!("S48 {label}"), actual, expected);
    }

    // ③ `S33`：无 `loop_*` 的既有夹具经**引擎实时路径**（同一个夹具、同一段 512 帧）。
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);
    let mut out = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut out);
    let actual = fnv1a_64(&out);
    let nonzero_actual = out.iter().filter(|sample| **sample != 0.0).count();
    println!(
        "[engine-sfz/S48] ③ S33 无 `loop_*` 夹具（512 帧 @60,127）：非零 = {nonzero_actual}、\
         指纹 = 0x{actual:016x}（既有 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）"
    );
    assert!(nonzero_actual > 0, "夹具必须真的出声（否则指纹比对是空转）");
    let _checked = check_fingerprint(
        "S48 ③ S33 无 loop 夹具逐位不变",
        actual,
        NO_LOOP_FIXTURE_FINGERPRINT,
    );
}

// ---------------------------------------------------------------------------
// ⭐ S49～S53：`note_polyphony` ＋ `note_selfmask` 的**播放层接线**（任务单 `#100`）
//
// 缺口（`docs/ledger/sfz-core-notes.md` 的 `sfz-needs-6` 行「② 仍未落」点名
// `note_polyphony`）：两个 opcode **早就解析了**——
// `crates/yeban-sfz/src/instrument.rs:1987` 的 `read_note_polyphony`（域、缺省、
// `note_selfmask` 白名单与错误政策全在，判据在 `instrument.rs:3618-3760` 与
// `tests/malformed_inputs.rs:1335-1440`），`yeban-sfz` 的 `VoicePool` 甚至早有一份完整策略
// `VoicePool::apply_note_polyphony`（`voice_pool.rs:418`）。**缺的只是播放层**：那个池
// **不被引擎使用**（见 `SFZ_VOICES_PER_TRACK` 的文档），而引擎的 `SfzVoicePool` 与
// `PreparedRegion` 从来不消费这份读数 ⇒ 本片是**接线**，⛔ 不是新实现、⛔ 不是新解析。
//
// 判据分工：
//   * S49 —— 上限**真的生效**（同音连发 `N = 5`、上限 `M = 2` ⇒ 在场数恒 ≤ 2）＋ 内置正对照；
//   * S50 —— 键是 **polyphony group × 音高**：另一个音高照常发声（§4.2 的负判据正对照）；
//   * S51 —— `note_selfmask` 的力度规则（缺省 `on` 是 hint、显式 `off` 才严格）；
//   * S52 —— 不带 `note_polyphony` 的既有夹具**指纹逐位不变**（§4.4）；
//   * S53 —— ⛔ **不是窃取**：`stolen`／`dropped`／`pending`／淡出 全 0（§3.3）。
// ---------------------------------------------------------------------------

/// ⭐ S49（任务单 `#100`；§4.1）：**`note_polyphony` 真的生效** —— 同音连发 `N = 5` 次、
/// 上限 `M = 2 < N` ⇒ **在场声部数恒 ≤ M**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 实时池 [`SfzVoicePool`] 的**在场声部数**（[`SfzVoicePool::active_count`]；
/// 单位 ＝ 声部）＋ 一段输出的**非零帧数**（单位 ＝ 帧）。两次触发之间**不渲染**
/// （⛔ 不让"样本自然播完"混进读数）。
///
/// # ⭐ 为什么这个夹具**有牙**（§4.3：先证明差异能体现在读数上）
///
/// 同一条 SFZ 文本**去掉 `note_polyphony`** 就是**内置正对照**：同样 5 次触发 ⇒ 在场数
/// **5**（⛔ 不是 2）。实测读数：带 opcode 的臂逐次 `1,2,2,2,2`；两条对照臂 `1,2,3,4,5`。
/// 判据因此量的是**上限**，⛔ 不是"能建声部"。
/// `note_polyphony=0`（＝不限制；登记语料里出现 **26** 处，用法是复位）也走对照臂那一档。
#[test]
fn s49_note_polyphony_really_caps_the_voices_of_one_pitch() {
    const N: usize = 5;
    const M: usize = 2;

    /// 同一条区域的三种写法（⚠ 只有 opcode 一处不同 ⇒ 对照是干净的）。
    fn text(opcode: &str) -> String {
        format!("<region> sample=a.wav key=60 pitch_keycenter=60 {opcode}\n")
    }

    let sample = flat_sample(4096);
    let limited = prepare_with(&text("note_polyphony=2"), &sample);
    let zero = prepare_with(&text("note_polyphony=0"), &sample);
    let absent = prepare_with(&text(""), &sample);

    // ⭐ 摊平表**真的**带上了这份读数（⛔ 不是"只解析了、没搬过来"）。
    assert_eq!(
        limited.regions()[0].note_polyphony().limit,
        M as u32,
        "摊平表必须原样带上 `note_polyphony`"
    );
    assert!(!limited.regions()[0].note_polyphony().is_unlimited());
    assert!(
        limited.regions()[0].note_polyphony().self_mask,
        "`note_selfmask` 的规范缺省是 `on`"
    );
    for (label, plan) in [("note_polyphony=0", &zero), ("无 opcode", &absent)] {
        assert!(
            plan.regions()[0].note_polyphony().is_unlimited(),
            "⭐ {label} ⇒ 与「未给出」同义（`yeban-sfz` 的既有裁决：`limit == 0` 即不限制）"
        );
    }

    // ⭐ 主臂：同音连发 5 次，逐次读在场数。
    let mut pool = SfzVoicePool::new(48_000.0);
    let mut readings = Vec::new();
    for _ in 0..N {
        pool.trigger_note(&limited, 60, 100, u64::MAX, 1.0, None);
        readings.push(pool.active_count());
    }
    println!("[engine-sfz/S49] 带 `note_polyphony=2` 的逐次在场数 = {readings:?}（上限 {M}）");
    assert_eq!(readings, vec![1, 2, 2, 2, 2], "⭐ 在场声部数恒 ≤ M ＝ {M}");
    assert!(pool.active_count() <= M);

    // ⭐ 剩下的声部必须**真的出声**（⛔ 不是"槽还在但永远不出声"）。
    let mut out = vec![0.0f32; 256];
    pool.render_into(&limited, 0, &mut out);
    let nonzero = out.iter().filter(|sample| **sample != 0.0).count();
    println!(
        "[engine-sfz/S49] 渲染 256 帧：非零 = {nonzero}、在场 = {}",
        pool.active_count()
    );
    assert!(
        nonzero > 0,
        "⭐ 主臂必须真的出声（⛔ 证明不是「全被掐成静音」的假绿）"
    );
    assert!(pool.active_count() <= M, "渲染之后仍在场 ≤ M");

    // ⭐ 内置正对照（§4.3 的"有牙"见证）：同夹具去掉该 opcode ⇒ 5 个在场声部。
    for (label, plan) in [("note_polyphony=0", &zero), ("无 opcode", &absent)] {
        let mut control = SfzVoicePool::new(48_000.0);
        for _ in 0..N {
            control.trigger_note(plan, 60, 100, u64::MAX, 1.0, None);
        }
        println!(
            "[engine-sfz/S49] 正对照（{label}）：在场 = {}",
            control.active_count()
        );
        assert_eq!(
            control.active_count(),
            N,
            "⭐ 正对照（{label}）必须 {N} 个在场 ⇒ 夹具真的有牙（差异真的体现在读数上）"
        );
    }
}

/// ⭐ S50（任务单 `#100`；§4.2）：**键 ＝ polyphony group × 音高** —— 另一个音高照常发声。
///
/// # 量什么（对象 ＋ 单位）
///
/// 对象 ＝ 同一个池的**在场声部数**（单位 ＝ 声部）＋ 在场声部的**音高分布**（单位 ＝ 个）。
///
/// # ⭐ 负判据的**正对照**（第 42 条）
///
/// ① 同一条区域覆盖 `60..=64` ＋ `note_polyphony=2`：音高 60 连发 5 次 ⇒ **2**；
///    随后音高 64 连发 5 次 ⇒ **4**（2 ＋ 2）—— 若上限**不**按音高分键（变成全局上限），
///    第二条腿会停在 **2** ⇒ 必红。
/// ② 同音高、**不同 `group`**（规范："checked within a polyphony group"）⇒ 两组各自的上限
///    ⇒ 5 次触发（每次两条区域各建 1 个声部）之后在场 **4**；若上限跨 group 合并 ⇒ 会停在 2。
/// ③ 收尾：在场声部里必须**真的有**音高 64 的（⛔ 不是"计数对上了但那条腿根本没触发"）。
#[test]
fn s50_the_note_polyphony_key_is_the_group_plus_the_pitch() {
    const N: usize = 5;
    let sample = flat_sample(4096);

    // ① 一个音高一份上限。
    let one_key_range = prepare_with(
        "<region> sample=a.wav lokey=60 hikey=64 pitch_keycenter=60 note_polyphony=2\n",
        &sample,
    );
    let mut pool = SfzVoicePool::new(48_000.0);
    for _ in 0..N {
        pool.trigger_note(&one_key_range, 60, 100, u64::MAX, 1.0, None);
    }
    let after_sixty = pool.active_count();
    for _ in 0..N {
        pool.trigger_note(&one_key_range, 64, 100, u64::MAX, 1.0, None);
    }
    let after_sixty_four = pool.active_count();
    let sixty_four_voices = pool
        .voices()
        .iter()
        .filter(|voice| voice.is_active() && voice.note() == 64)
        .count();
    println!(
        "[engine-sfz/S50] ① 音高 60 连发 {N} 次后在场 = {after_sixty}；\
         再连发音高 64 {N} 次后在场 = {after_sixty_four}（其中音高 64 = {sixty_four_voices}）"
    );
    assert_eq!(after_sixty, 2, "音高 60 被自己的上限限到 2");
    assert_eq!(
        after_sixty_four, 4,
        "⭐ 另一个音高**照常发声**（2 ＋ 2）—— ⛔ 不是全局上限（那会停在 2）"
    );
    assert_eq!(
        sixty_four_voices, 2,
        "⭐ 音高 64 的声部必须真的在场（⛔ 不是空计数）"
    );

    // ⭐ 另一音高的声部必须**真的出声**：只触发 64（新池）⇒ 输出非零。
    let mut only_sixty_four = SfzVoicePool::new(48_000.0);
    only_sixty_four.trigger_note(&one_key_range, 64, 100, u64::MAX, 1.0, None);
    let mut out = vec![0.0f32; 256];
    only_sixty_four.render_into(&one_key_range, 0, &mut out);
    assert!(
        out.iter().any(|sample| *sample != 0.0),
        "⭐ 音高 64 必须真的出声（§4.2 的「逐位或计数对照」那一半）"
    );

    // ② 同音高、不同 `group` ⇒ 两份互不干涉的上限。
    let two_groups = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 group=1 note_polyphony=2\n\
         <region> sample=b.wav key=60 pitch_keycenter=60 group=2 note_polyphony=2\n",
        &sample,
    );
    let mut grouped = SfzVoicePool::new(48_000.0);
    for _ in 0..N {
        grouped.trigger_note(&two_groups, 60, 100, u64::MAX, 1.0, None);
    }
    println!(
        "[engine-sfz/S50] ② 两个 group（各 `note_polyphony=2`）连发 {N} 次后在场 = {}",
        grouped.active_count()
    );
    assert_eq!(
        grouped.active_count(),
        4,
        "⭐ 每个 polyphony group 各自的上限 2 ⇒ 4（2 ＋ 2）；跨 group 合并会停在 2"
    );
}

/// ⭐ S51（任务单 `#100`；§4.1 的 `note_selfmask` 那一半）：**力度规则**。
///
/// # 量什么（对象 ＋ 单位）
///
/// 对象 ＝ 池的**在场声部数**与在场声部的**力度读数**（[`SfzVoice::velocity`]；单位 ＝ 个 / 力度值）。
///
/// # 腿（规范逐字，<https://sfzformat.com/opcodes/note_selfmask/>）
///
/// * **缺省 `on`**："higher-or-equal-velocity notes turn off lower-velocity notes, but
///   lower-velocity notes do not turn off higher-velocity notes." ⇒ 力度 100 在场时，
///   来一个力度 40 ⇒ ⛔ **不掐**、新音符照常发声（在场 **2** > `limit = 1`：规范原句
///   "The `note_polyphony` opcode is thus not a strict polyphony limit but more of a hint"）；
///   再来一个力度 100 ⇒ 两个不高于它的都在资格内 ⇒ 掐到只剩**新音符**（在场 **1**）。
/// * **显式 `off`**："notes turn off notes with the same pitch regardless of velocity, which
///   … does ensure that note polyphony is always preserved within the set limit" ⇒ 力度 100
///   在场时来力度 40 ⇒ 掐掉 100、留下 **40**（在场 **1**）——
///   ⭐ 留在场上的必须是**新音符**（规范："A new note will always play."），⛔ 不是反过来。
#[test]
fn s51_note_selfmask_decides_which_voices_may_be_turned_off() {
    let sample = flat_sample(4096);
    let default_on = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 note_polyphony=1\n",
        &sample,
    );
    let explicit_off = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 note_polyphony=1 note_selfmask=off\n",
        &sample,
    );
    // ⭐ 摊平表读数：缺省 `on` / 显式 `off` 必须分得开（⛔ 不是"都读成缺省"）。
    assert!(
        default_on.regions()[0].note_polyphony().self_mask,
        "规范 Default = `on`"
    );
    assert!(
        !explicit_off.regions()[0].note_polyphony().self_mask,
        "显式 `note_selfmask=off` 必须带出 `self_mask == false`"
    );

    // --- 腿 A：缺省 `on` —— 低力度新音符**照常发声**且⛔ 不掐高力度者（hint ⛔ 不是硬上限）。
    let mut soft = SfzVoicePool::new(48_000.0);
    soft.trigger_note(&default_on, 60, 100, u64::MAX, 1.0, None);
    soft.trigger_note(&default_on, 60, 40, u64::MAX, 1.0, None);
    let mut velocities: Vec<u8> = soft
        .voices()
        .iter()
        .filter(|voice| voice.is_active())
        .map(SfzVoice::velocity)
        .collect();
    velocities.sort_unstable();
    println!(
        "[engine-sfz/S51] A（缺省 on）力度 100 → 40：在场 = {}、力度 = {velocities:?}",
        soft.active_count()
    );
    assert_eq!(
        soft.active_count(),
        2,
        "⭐ 低力度新音符⛔ 不掐高力度者 ⇒ 在场 2 > limit 1（规范：hint，⛔ 不是硬上限）"
    );
    assert_eq!(
        velocities,
        vec![40, 100],
        "⭐ 两个声部都在场（新的那个也真的在）"
    );

    // --- 腿 A2：再来一个**高**力度 ⇒ 两个不高于它的都在资格内 ⇒ 掐到只剩新音符。
    soft.trigger_note(&default_on, 60, 100, u64::MAX, 1.0, None);
    let survivors: Vec<u8> = soft
        .voices()
        .iter()
        .filter(|voice| voice.is_active())
        .map(SfzVoice::velocity)
        .collect();
    println!(
        "[engine-sfz/S51] A2（缺省 on）再 +100：在场 = {}、力度 = {survivors:?}",
        soft.active_count()
    );
    assert_eq!(soft.active_count(), 1, "⭐ 高力度新音符掐掉两个不高于它的");
    assert_eq!(
        survivors,
        vec![100],
        "⭐ 留下的是**新音符**（最晚触发的那个 100）"
    );

    // --- 腿 B：显式 `off` —— 严格上限（不分力度都掐），且留下来的是**新音符**。
    let mut strict = SfzVoicePool::new(48_000.0);
    strict.trigger_note(&explicit_off, 60, 100, u64::MAX, 1.0, None);
    strict.trigger_note(&explicit_off, 60, 40, u64::MAX, 1.0, None);
    let survivor: Vec<u8> = strict
        .voices()
        .iter()
        .filter(|voice| voice.is_active())
        .map(SfzVoice::velocity)
        .collect();
    println!(
        "[engine-sfz/S51] B（显式 off）力度 100 → 40：在场 = {}、力度 = {survivor:?}",
        strict.active_count()
    );
    assert_eq!(
        strict.active_count(),
        1,
        "⭐ `note_selfmask=off` ⇒ 严格上限（规范：'does ensure that note polyphony is always \
         preserved within the set limit'）"
    );
    assert_eq!(
        survivor,
        vec![40],
        "⭐ 留在场上的必须是**新音符**（规范：'A new note will always play.'），⛔ 不是被掐的那个"
    );
}

/// ⭐ S52（任务单 `#100`；§4.4）：**不带 `note_polyphony` 的既有夹具逐位不变**。
///
/// # 量什么（对象 ＋ 单位）
///
/// 对象 ＝ 既有夹具经**同一条产品路径**渲染出的一段输出；单位 ＝ **FNV-1a 64 指纹**
/// （逐位；把每个 `f32` 的 4 个字节按小端卷进哈希）。
///
/// # 三个**承重指纹**（⭐ 改动前实测值，本片一字未动）
///
/// | 夹具 | 帧数 | 非零 | 指纹 |
/// | :--- | :--- | :--- | :--- |
/// | `S37` `loop_continuous` ＋ `end_sample = 200` | 512 | 200 | `0xa9dec8a87f69106c` |
/// | `S37` `no_loop` ＋ `end_sample = u64::MAX` | 512 | 399 | `0xd3c2a82076bd8947` |
/// | `S33` [`TWO_MATCH_ONE_MISS`]（引擎实时路径） | 512 | 478 | `0xa933ddab286bdf5e` |
///
/// ⚠ 三条夹具**一个 `note_polyphony` 都没有**（本片新增的路径在缺省下必须是**空操作**）。
/// 字面值的来源与"同平台硬红、异平台如实跳过"的纪律见 [`check_fingerprint`]。
///
/// # ⭐ 第二条腿（本片新增的"缺省 ⇒ 逐位不动"）
///
/// 一条**带 `group`** 的夹具（`note_polyphony` 缺省）与**同文本再加 `note_polyphony=0`**
/// 必须**逐位相同**（`limit == 0` 与"未给出"同义）；
/// ⭐ **反向腿**：把 `note_polyphony` 改成 `1` 并**连发两次同音**⇒ 指纹**必须变**
/// （证明这条新路径真的活着，且差异确实落在这段读数上，⛔ 不是判据空转）。
#[test]
fn s52_a_fixture_without_note_polyphony_renders_bit_identically() {
    /// ⭐ `S37` 两条既有指纹（改动前实测；来源见 `S37` 的文档）。
    const S37_LOOPED: u64 = 0xa9de_c8a8_7f69_106c;
    const S37_PLAIN: u64 = 0xd3c2_a820_76bd_8947;

    // --- ① 三个承重指纹：原样复跑并断言。
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, nonzero, expected) in [
        (
            "S37 loop_continuous ＋ end_sample = 200",
            &looped,
            200u64,
            200usize,
            S37_LOOPED,
        ),
        (
            "S37 no_loop ＋ end_sample = u64::MAX",
            &plain,
            u64::MAX,
            399usize,
            S37_PLAIN,
        ),
    ] {
        assert!(
            plan.regions()[0].note_polyphony().is_unlimited(),
            "⭐ {label}：夹具必须**一个 `note_polyphony` 都没有**（否则指纹比对不是「缺省路径」的判据）"
        );
        let out = render_pool(plan, end_sample, 512);
        let actual = fnv1a_64(&out);
        let nonzero_actual = out.iter().filter(|sample| **sample != 0.0).count();
        println!(
            "[engine-sfz/S52] ① {label}：非零 = {nonzero_actual}（既有 {nonzero}）、\
             指纹 = 0x{actual:016x}（既有 0x{expected:016x}）"
        );
        assert_eq!(nonzero_actual, nonzero, "⭐ {label}：既有非零帧数必须原样");
        let _checked = check_fingerprint(&format!("S52 ① {label}"), actual, expected);
    }
    // `S33`：`TWO_MATCH_ONE_MISS` 经**引擎实时路径**（同一个夹具、同一段 512 帧）。
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);
    let mut out = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut out);
    let actual = fnv1a_64(&out);
    let nonzero_actual = out.iter().filter(|sample| **sample != 0.0).count();
    println!(
        "[engine-sfz/S52] ① S33 无 `loop_*`／无 `note_polyphony` 夹具：非零 = {nonzero_actual}、\
         指纹 = 0x{actual:016x}（既有 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）"
    );
    assert_eq!(nonzero_actual, 478, "⭐ S33 的既有非零帧数必须原样");
    let _checked = check_fingerprint("S52 ① S33", actual, NO_LOOP_FIXTURE_FINGERPRINT);

    // --- ② 缺省 ⇒ 空操作：`group` 在、`note_polyphony` 缺省 vs 显式 `0` ⇒ 逐位相同。
    let sample = flat_sample(4096);
    let absent = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 group=7\n",
        &sample,
    );
    let explicit_zero = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 group=7 note_polyphony=0\n",
        &sample,
    );
    let mut absent_pool = SfzVoicePool::new(48_000.0);
    let mut zero_pool = SfzVoicePool::new(48_000.0);
    for _ in 0..2 {
        absent_pool.trigger_note(&absent, 60, 100, u64::MAX, 1.0, None);
        zero_pool.trigger_note(&explicit_zero, 60, 100, u64::MAX, 1.0, None);
    }
    let mut absent_out = vec![0.0f32; 256];
    let mut zero_out = vec![0.0f32; 256];
    absent_pool.render_into(&absent, 0, &mut absent_out);
    zero_pool.render_into(&explicit_zero, 0, &mut zero_out);
    println!(
        "[engine-sfz/S52] ② 缺省 vs `note_polyphony=0`：在场 = {}/{}、逐位相同 = {}",
        absent_pool.active_count(),
        zero_pool.active_count(),
        bits(&absent_out) == bits(&zero_out)
    );
    assert_eq!(
        bits(&absent_out),
        bits(&zero_out),
        "⭐ `note_polyphony=0` 与「未给出」必须逐位相同（`yeban-sfz` 的既有裁决）"
    );
    assert_eq!(
        absent_pool.active_count(),
        2,
        "缺省 ⇒ ⛔ 不掐（两个都在场）"
    );

    // --- ③ 反向腿：把它改成 `1` 并连发两次同音 ⇒ 指纹**必须变**。
    let limited = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 group=7 note_polyphony=1\n",
        &sample,
    );
    let mut limited_pool = SfzVoicePool::new(48_000.0);
    for _ in 0..2 {
        limited_pool.trigger_note(&limited, 60, 100, u64::MAX, 1.0, None);
    }
    let mut limited_out = vec![0.0f32; 256];
    limited_pool.render_into(&limited, 0, &mut limited_out);
    println!(
        "[engine-sfz/S52] ③ 反向腿（`note_polyphony=1`，连发两次）：在场 = {}、\
         指纹 = 0x{:016x}（缺省 0x{:016x}，必须不同）",
        limited_pool.active_count(),
        fnv1a_64(&limited_out),
        fnv1a_64(&absent_out)
    );
    assert_eq!(
        limited_pool.active_count(),
        1,
        "⭐ 反向腿的前置见证：真的掐到 1"
    );
    assert_ne!(
        fnv1a_64(&limited_out),
        fnv1a_64(&absent_out),
        "⭐ 反向腿：带上限 ⇒ 指纹必须变（⛔ 判据不是恒绿的空转）"
    );
}

/// ⭐ S53（任务单 `#100`；§3.3）：**`note_polyphony` 的让位 ⛔ 不是 [`SfzVoicePool::steal`]**。
///
/// # 量什么（对象 ＋ 单位）
///
/// 对象 ＝ 池的四个**既有**计数读数（单位 ＝ 个）：`stolen`（池满窃取，累计）、
/// `dropped`（真丢弃，累计）、`pending_count`（挂起者）、`fade_remaining_at`（每槽淡出帧数）。
///
/// # 两条腿（⭐ 正对照证明这些读数**分得开**两件事）
///
/// * **A（本片）**：`note_polyphony=2` ＋ 同音连发 5 次 ⇒ 掐掉 3 个，但四个读数**全 0**
///   —— 掐是**立即**的硬停（⛔ 不淡出、⛔ 不挂起、⛔ 不计窃取/丢弃）。
/// * **B（对照，池满）**：17 条同键区域 ⇒ 走既有**窃取**路径 ⇒ `stolen > 0`、
///   `pending_count > 0`、`fade_remaining_at > 0` ⇒ 证明 A 的"全 0"不是"读数根本没接"。
#[test]
fn s53_note_polyphony_is_not_the_pool_full_steal() {
    const N: usize = 5;
    let sample = flat_sample(4096);
    let limited = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 note_polyphony=2\n",
        &sample,
    );
    let mut pool = SfzVoicePool::new(48_000.0);
    for _ in 0..N {
        pool.trigger_note(&limited, 60, 100, u64::MAX, 1.0, None);
    }
    let fades: Vec<u32> = (0..SFZ_VOICES_PER_TRACK)
        .map(|index| pool.fade_remaining_at(index))
        .collect();
    println!(
        "[engine-sfz/S53] A（`note_polyphony=2`，连发 {N} 次）：在场 = {}、窃取 = {}、\
         丢弃 = {}、挂起 = {}、逐槽淡出 = {fades:?}",
        pool.active_count(),
        pool.stolen(),
        pool.dropped(),
        pool.pending_count()
    );
    assert_eq!(pool.active_count(), 2, "前置见证：真的掐到上限 2");
    assert_eq!(
        pool.stolen(),
        0,
        "⭐ 每音符上限⛔ 不是池满窃取 ⇒ `stolen` 必须 0"
    );
    assert_eq!(pool.dropped(), 0, "⭐ ⛔ 不丢弃任何声部");
    assert_eq!(
        pool.pending_count(),
        0,
        "⭐ ⛔ 不动挂起者（那不是窃取路径）"
    );
    assert!(
        fades.iter().all(|remaining| *remaining == 0),
        "⭐ 掐是**立即**的硬停 ⇒ ⛔ 不留任何 3 ms 窃取淡出：{fades:?}"
    );

    // --- B：正对照（既有窃取路径必须能被这四个读数**抓住**）。
    let mut text = String::new();
    for _ in 0..SFZ_VOICES_PER_TRACK {
        text.push_str("<region> sample=a.wav key=60 pitch_keycenter=60\n");
    }
    text.push_str("<region> sample=b.wav key=60 pitch_keycenter=60\n");
    let full = prepare_with(&text, &sample);
    let mut control = SfzVoicePool::new(48_000.0);
    control.trigger_note(&full, 60, 100, u64::MAX, 1.0, None);
    let control_fades: Vec<u32> = (0..SFZ_VOICES_PER_TRACK)
        .map(|index| control.fade_remaining_at(index))
        .collect();
    println!(
        "[engine-sfz/S53] B（池满对照）：在场 = {}、窃取 = {}、挂起 = {}、逐槽淡出 = {control_fades:?}",
        control.active_count(),
        control.stolen(),
        control.pending_count()
    );
    assert!(
        control.stolen() > 0
            && control.pending_count() > 0
            && control_fades.iter().any(|remaining| *remaining > 0),
        "⭐ 正对照：池满路径必须让这三个读数**动起来**（否则 A 的「全 0」没有信息量）"
    );
}

// ---------------------------------------------------------------------------
// ⭐ S54～S58：`ampeg_*` 的 CC 调制（任务单 `#104`）
// ---------------------------------------------------------------------------
//
// 本片的落点是**解析 ＋ 归约 ＋ 离线求值**：`yeban-sfz` 读得进
// `ampeg_attackcc100` / `ampeg_attack_oncc100` / `ampeg_attack_curvecc100`，
// 归约结果经 `PreparedRegion` 承载，并由**既有**的 `RegionQuery::with_cc` 探针在
// 离线两条路（`render_note_into_with_cc` / `render_block_into_with_cc`）求值。
// ⛔ 实时通路（`SfzVoicePool`）**本片一个字都不动** ⇒ 那里仍走基准值（登记见 S58）。

/// ⭐ 四形态夹具（一条 `<curve>` ＋ 五条区域）：
///
/// | region | 形态 | 期望读数 `(param, cc, delta, curve)` |
/// | :--- | :--- | :--- |
/// | `key=60` | legacy `ccN` | `(Attack, 100, 1.5, 0)` |
/// | `key=61` | v2 `_onccN` | `(Decay, 71, -0.4, 0)` |
/// | `key=62` | v2 ＋ `_curveccN`（**自定义**曲线 7） | `(Sustain, 74, 25.0, 7)` |
/// | `key=63` | v2 ＋ `_curveccN`（**内建双极**曲线 1） | `(Release, 93, 1.0, 1)` |
/// | `key=64` | **缺省**（一个调制 opcode 都没有） | `[]` |
const AMPEG_FOUR_FORMS: &str = "<curve>curve_index=7\n\
                                v000=0\n\
                                v063=1\n\
                                v127=0\n\
                                <region> sample=a.wav key=60 pitch_keycenter=60 ampeg_attack=0.5 ampeg_attackcc100=1.5\n\
                                <region> sample=a.wav key=61 pitch_keycenter=60 ampeg_decay=0.2 ampeg_decay_oncc71=-0.4\n\
                                <region> sample=a.wav key=62 pitch_keycenter=60 ampeg_sustain=50 ampeg_sustain_oncc74=25 ampeg_sustain_curvecc74=7\n\
                                <region> sample=a.wav key=63 pitch_keycenter=60 ampeg_release=0.3 ampeg_release_oncc93=1.0 ampeg_release_curvecc93=1\n\
                                <region> sample=a.wav key=64 pitch_keycenter=60 ampeg_hold=0.1\n";

/// S54 负判据要认的几种 `Err` 形状。
#[derive(Debug, Clone, Copy)]
enum ModErrorShape {
    IntRange255,
    FloatRange100,
    InvalidInteger,
    InvalidFloat,
    NonFinite,
}

fn matches_mod_error(error: &SfzError, shape: ModErrorShape) -> bool {
    match shape {
        ModErrorShape::IntRange255 => {
            matches!(
                error,
                SfzError::IntegerOutOfRange {
                    min: 0,
                    max: 255,
                    ..
                }
            )
        }
        ModErrorShape::FloatRange100 => matches!(
            error,
            SfzError::FloatOutOfRange { min, max, .. } if *min == -100.0 && *max == 100.0
        ),
        ModErrorShape::InvalidInteger => matches!(error, SfzError::InvalidInteger { .. }),
        ModErrorShape::InvalidFloat => matches!(error, SfzError::InvalidFloat { .. }),
        ModErrorShape::NonFinite => matches!(error, SfzError::NonFiniteFloat { .. }),
    }
}

/// ⭐ S54（任务单 `#104`；§4.1）：**四形态各至少一条 ＋ 缺省 ＋ 非法 ⇒ `Err`**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 一份含 `<curve>` 与五条区域的 SFZ；单位 ＝ 每条区域归约出的
/// `(AmpegParam, cc, delta, curve)` 读数（元组）＋ 非法输入的 `SfzError` 变体。
///
/// ⭐ 负判据每条都与**同一批数据里的一个合法样例**同现（`ampeg_attackcc100=1.5`），
/// 并且该合法样例**单独**出现时必须被接受 ⇒ ⛔ 证明那些 `Err` 不是"整族一律拒"。
#[test]
fn s54_the_four_ampeg_cc_forms_are_parsed_with_their_domains() {
    let instrument = SfzInstrument::load(AMPEG_FOUR_FORMS.to_owned(), &Default::default())
        .expect("四形态夹具必须解析成功");
    let expected: [&[(AmpegParam, u8, f32, u8)]; 5] = [
        &[(AmpegParam::Attack, 100, 1.5, 0)],
        &[(AmpegParam::Decay, 71, -0.4, 0)],
        &[(AmpegParam::Sustain, 74, 25.0, 7)],
        &[(AmpegParam::Release, 93, 1.0, 1)],
        &[],
    ];
    let actual: Vec<Vec<(AmpegParam, u8, f32, u8)>> = instrument
        .with_instrument(|parsed| {
            parsed
                .regions()
                .iter()
                .map(|region| {
                    region
                        .ampeg_modulations()
                        .iter()
                        .map(|item| {
                            (
                                item.target.ampeg().expect("本夹具全是 ampeg 目标"),
                                item.cc,
                                item.delta,
                                item.curve,
                            )
                        })
                        .collect()
                })
                .collect()
        })
        .expect("重解析");
    assert_eq!(actual.len(), 5, "五条区域都在");
    for (index, (got, want)) in actual.iter().zip(expected).enumerate() {
        assert_eq!(
            got.as_slice(),
            want,
            "⭐ region {index} 的 `(param, cc, delta, curve)` 读数"
        );
    }
    println!("[engine-sfz/S54] 四形态读数（逐条）：{actual:?}（第 5 条 = 缺省 ⇒ 空）");

    // ---- 负判据：非法 ⇒ 响亮 `Err`（第 259 条；⛔ 不静默降级、⛔ 不钳位）----
    let legal = "ampeg_attackcc100=1.5";
    let bad: [(&str, ModErrorShape); 8] = [
        ("ampeg_attackcc256=1.0", ModErrorShape::IntRange255),
        ("ampeg_attack_oncc99999=1.0", ModErrorShape::IntRange255),
        ("ampeg_attackcc100=200", ModErrorShape::FloatRange100),
        ("ampeg_attackcc100=-250", ModErrorShape::FloatRange100),
        ("ampeg_attack_curvecc100=300", ModErrorShape::IntRange255),
        ("ampeg_attack_curvecc100=1.5", ModErrorShape::InvalidInteger),
        ("ampeg_attackcc100=abc", ModErrorShape::InvalidFloat),
        ("ampeg_attackcc100=inf", ModErrorShape::NonFinite),
    ];
    for (illegal, shape) in bad {
        // ⭐ 同一批数据里带一个**合法样例**（`legal`）：它能被接受（见下一条断言），
        // 因此这里的 `Err` 必然是 `illegal` 那一行造成的。
        let text = format!(
            "<region> sample=a.wav key=60 pitch_keycenter=60 {legal} {illegal}\n\
             <region> sample=a.wav key=61 pitch_keycenter=60 ampeg_hold=0.1\n"
        );
        let error = SfzInstrument::load(text, &Default::default())
            .expect_err(&format!("{illegal} 必须响亮 Err"));
        assert!(
            matches_mod_error(&error, shape),
            "⭐ {illegal} ⇒ {error:?}（不是期望的 {shape:?}）"
        );
        println!("[engine-sfz/S54] {illegal} ⇒ {error}");
    }
    // ⭐ 同一条合法样例**单独**出现 ⇒ 必须被接受（负判据的正对照）。
    let accepted = SfzInstrument::load(
        format!("<region> sample=a.wav key=60 pitch_keycenter=60 {legal}\n"),
        &Default::default(),
    );
    assert!(
        accepted.is_ok(),
        "⭐ 同批数据里的合法样例必须被接受：{accepted:?}"
    );
    // ⛔ 缺失 ≠ 非法：一个 `ampeg_*ccN` 都没有 ⇒ `Ok` ＋ 空表（见上面第 5 条区域）。
    assert!(
        SfzInstrument::load(
            "<region> sample=a.wav key=60 pitch_keycenter=60 ampeg_attack=0.5\n".to_owned(),
            &Default::default()
        )
        .is_ok(),
        "缺省（没有该族 opcode）必须合法"
    );
}

/// ⭐ 起音段**实测帧数**：输出从 0 线性升到平台（＝ `1.0`）所用的帧数。
///
/// 夹具是**恒定 `1.0`** 的样本 ＋ 力度 `127`（`velocity_gain(127) == 1.0`，见 S18）
/// ⇒ 输出**恰好**是包络电平本身，于是"到峰帧"可逐样本读出来。
fn measured_attack_frames(out: &[f32]) -> usize {
    out.iter().take_while(|sample| **sample < 1.0).count()
}

/// ⭐ S55（任务单 `#104`；§4.2）：**端到端离线（既有 `with_cc` 探针）**——
/// 同一份 SFZ ＋ 两个不同的 CC 值 ⇒ 包络按规范公式不同，且**两条离线路逐位相同**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ `ampeg_attack=0.5` ＋ `ampeg_attack_oncc100=0.5` 的区域在
/// `cc = 0` 与 `cc = 127` 两个探针值下的输出；单位 ＝ **起音段实测帧数**（帧）；
/// 容差口径 ＝ 线性段**每一点** `|实测 − t/A| ≤ 1e-6`（与 S35 同口径）。
///
/// # 公式（逐字出处见 `yeban_sfz::modulation` 的模块文档）
///
/// `A = round((0.5 + 0.5 × cc/127) × 48000)` ⇒ `cc = 0` ⇒ **24000**、
/// `cc = 127` ⇒ **48000**（⭐ 各自配一条"它自己该怎样"的断言，⛔ 不是只断言"两者不同"）。
#[test]
fn s55_two_cc_values_change_the_envelope_by_the_specification_formula() {
    const HZ: f32 = 48_000.0;
    const FRAMES: usize = 72_000;
    const SFZ: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                       ampeg_attack=0.5 ampeg_attack_oncc100=0.5\n";
    let instrument = SfzInstrument::load(SFZ.to_owned(), &Default::default()).expect("解析");
    // ⚠ 样本**比输出缓冲更长**：否则逐样本路径会在最后一帧前停住（实测写入 71999）。
    let sample = InMemorySample {
        pcm: vec![1.0; FRAMES + 1_024],
        sample_hz: HZ,
    };
    let plan = prepare_with(SFZ, &sample);
    assert_eq!(
        plan.regions()[0].ampeg_modulations().len(),
        1,
        "摊平表必须真的承载那一条调制项"
    );

    let expected = |cc: u8| -> usize {
        let seconds = 0.5f32 + 0.5 * (f32::from(cc) / 127.0);
        (f64::from(seconds) * f64::from(HZ)).round() as usize
    };

    let mut measured = [0usize; 2];
    for (index, cc) in [0u8, 127].into_iter().enumerate() {
        let probe = move |_: u8| cc;
        let mut offline = vec![0.0f32; FRAMES];
        let written_offline = instrument
            .render_note_into_with_cc(&sample, 60, 127, Some(&probe), &mut offline, HZ)
            .expect("离线渲染");
        let mut flat = vec![0.0f32; FRAMES];
        let written_flat = plan.render_block_into_with_cc(60, 127, Some(&probe), &mut flat);
        assert_eq!(written_offline, FRAMES, "离线整段写满");
        assert_eq!(written_flat, FRAMES, "摊平整段写满");
        // ⭐ 两条离线路走**同一份**求值（`ampeg_value_with_baked`）⇒ 必须逐位相同。
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ cc = {cc}：离线 → 摊平两条路必须逐位相同"
        );

        let attack = measured_attack_frames(&offline);
        measured[index] = attack;
        // ⭐ 线性段逐点对账（容差 1e-6）。
        let mut worst = 0.0f32;
        for (t, value) in offline.iter().enumerate().take(attack) {
            worst = worst.max((value - t as f32 / attack as f32).abs());
        }
        println!(
            "[engine-sfz/S55] cc = {cc}：⭐ 起音实测帧数 = {attack}（规范公式 = {}）；\
             线性段最大偏差 = {worst:e}；out[0] = {}、out[{attack}] = {}、out[last] = {}",
            expected(cc),
            offline[0],
            offline[attack],
            offline[FRAMES - 1]
        );
        assert_eq!(
            attack,
            expected(cc),
            "⭐ cc = {cc} 的起音帧数必须**逐帧**等于规范公式 `round((0.5 + 0.5 × cc/127) × 48000)`"
        );
        assert!(
            worst <= 1e-6,
            "⭐ cc = {cc}：线性段最大偏差 {worst:e} > 1e-6"
        );
        assert_eq!(
            offline[attack], 1.0,
            "⭐ cc = {cc}：第 A 帧必须**恰好**到峰"
        );
    }
    assert_eq!(measured, [24_000, 48_000], "⭐ 两个 CC 值的实测帧数");
    assert_ne!(
        measured[0], measured[1],
        "⭐ 两个 CC 值必须给出**不同**的包络（⛔ 不是『两者相同也算过』）"
    );
}

/// ⭐ S56（任务单 `#104`；§4.3）：**无探针 ⇒ 逐位不变** ＋ ⭐ **复跑承重指纹**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ ① 既有夹具的三个 **FNV-1a 64 指纹**（逐位）；② 新入口传 `None` 与旧入口
/// 的**位模式序列**（逐帧比较）。单位 ＝ `u64` 指纹 ＋ 位模式相等的布尔。
///
/// 三个承重指纹就是 §4.3 逐字点名的：`0xa9dec8a87f69106c`（S37 臂 1）、
/// `0xd3c2a82076bd8947`（S37 臂 2）、`0xa933ddab286bdf5e`（S33／S14 的广播路径）。
#[test]
fn s56_without_a_probe_the_readings_are_bit_identical_and_the_fingerprints_hold() {
    // ---- ① 三个承重指纹 ----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    assert!(looped.regions()[0].ampeg_is_transparent());
    assert!(plain.regions()[0].ampeg_is_transparent());
    for (label, plan, end_sample, expected) in [
        (
            "S37 loop_continuous ＋ end_sample = 200",
            &looped,
            200u64,
            0xa9de_c8a8_7f69_106cu64,
        ),
        (
            "S37 no_loop ＋ end_sample = u64::MAX",
            &plain,
            u64::MAX,
            0xd3c2_a820_76bd_8947u64,
        ),
    ] {
        let out = render_pool(plan, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!("[engine-sfz/S56] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）");
        let _checked = check_fingerprint(&format!("S56 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let legacy = fnv1a_64(&legacy_block);
    println!(
        "[engine-sfz/S56] S33／S14 广播路径 512 帧 @ (60,127)：指纹 = 0x{legacy:016x}\
         （承重 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）；写入 = {legacy_frames}"
    );
    let _checked = check_fingerprint("S56 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    // ⭐ 应绿反向腿（§6.3）：同一段输出 × `1.0000001` ⇒ 指纹**必须**变
    // （证明上面那三条是**逐位**判据，⛔ 不是"有输出就算过"）。
    let scaled: Vec<f32> = legacy_block
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    let scaled_hash = fnv1a_64(&scaled);
    println!(
        "[engine-sfz/S56] 反向腿（× 1.0000001）：指纹 = 0x{scaled_hash:016x}         （原指纹 0x{legacy:016x}，必须不同）"
    );
    assert_ne!(scaled_hash, legacy, "⭐ 反向腿：乘 1.0000001 后指纹必须变");

    // ---- ② 无探针 ⇒ 逐位不变（新入口 vs 旧入口）----
    let mut probe_none = vec![0.0f32; BLOCK];
    let none_frames = broadcast.render_block_into_with_cc(60, 127, None, &mut probe_none);
    assert_eq!(none_frames, legacy_frames);
    assert_eq!(
        bits(&legacy_block),
        bits(&probe_none),
        "⭐ `render_block_into_with_cc(cc = None)` 必须逐位等于 `render_block_into`"
    );

    let instrument =
        SfzInstrument::load(TWO_MATCH_ONE_MISS.to_owned(), &Default::default()).expect("解析");
    let sample = InMemorySample::sine(440.0, 48_000.0, SAMPLE_FRAMES);
    let mut offline_legacy = vec![0.0f32; BLOCK];
    let mut offline_none = vec![0.0f32; BLOCK];
    instrument
        .render_note_into(&sample, 60, 127, &mut offline_legacy, 48_000.0)
        .expect("离线旧入口");
    instrument
        .render_note_into_with_cc(&sample, 60, 127, None, &mut offline_none, 48_000.0)
        .expect("离线新入口");
    assert_eq!(
        bits(&offline_legacy),
        bits(&offline_none),
        "⭐ `render_note_into_with_cc(cc = None)` 必须逐位等于 `render_note_into`"
    );
    println!(
        "[engine-sfz/S56] 无探针逐位对账：摊平 512 帧逐位相同 = {}、离线 512 帧逐位相同 = {}",
        bits(&legacy_block) == bits(&probe_none),
        bits(&offline_legacy) == bits(&offline_none)
    );
}

/// ⭐ S57（任务单 `#104`；§4.4）：**判据有牙**——夹具能让被测差异真的体现在读数上。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 同一份 `ampeg_attack` 夹具**去掉** `ampeg_attack_oncc100` 那一行前后的
/// 起音实测帧数（帧）。单位 ＝ 帧。
///
/// ⭐ 内置**正对照**：去掉那一行 ⇒ 两个 CC 值给出**同一个**帧数（＝ 基准 24000）
/// ⇒ 证明 S55 的差异完全来自"解析 ＋ 归约 ＋ 求值"这条新链，⛔ 不是探针管道自身
/// 制造的假差异（若把本片的解析短接掉，这一条正对照与 S55 必然分道扬镳）。
#[test]
fn s57_the_fixture_can_actually_show_the_difference() {
    const HZ: f32 = 48_000.0;
    const FRAMES: usize = 72_000;
    const WITH_MOD: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                            ampeg_attack=0.5 ampeg_attack_oncc100=0.5\n";
    const WITHOUT_MOD: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 ampeg_attack=0.5\n";
    let sample = InMemorySample {
        pcm: vec![1.0; FRAMES + 1_024],
        sample_hz: HZ,
    };
    let measure = |text: &str, cc: u8| -> usize {
        let instrument = SfzInstrument::load(text.to_owned(), &Default::default()).expect("解析");
        let probe = move |_: u8| cc;
        let mut out = vec![0.0f32; FRAMES];
        instrument
            .render_note_into_with_cc(&sample, 60, 127, Some(&probe), &mut out, HZ)
            .expect("渲染");
        measured_attack_frames(&out)
    };
    let with = [measure(WITH_MOD, 0), measure(WITH_MOD, 127)];
    let without = [measure(WITHOUT_MOD, 0), measure(WITHOUT_MOD, 127)];
    println!(
        "[engine-sfz/S57] 带 `ampeg_attack_oncc100` ⇒ cc0/cc127 起音帧数 = {with:?}；\
         去掉那一行 ⇒ {without:?}"
    );
    assert_eq!(
        with,
        [24_000, 48_000],
        "⭐ 有调制：两个 CC 值必须落在规范公式的两个端点上"
    );
    assert_eq!(
        without,
        [24_000, 24_000],
        "⭐ 正对照：去掉调制 opcode ⇒ 两个 CC 值给出**同一个**基准帧数"
    );
    assert_ne!(
        with[0], with[1],
        "⭐ 有牙：夹具必须让被测差异真的体现在读数上"
    );
    assert_ne!(
        with[1], without[1],
        "⭐ 有牙：唯一变化的那一行必须真的改变读数"
    );
}

/// ⭐ S58（任务单 `#104`；§3.4 / §9）：**「双口径登记」可判**。
///
/// # 判定量
///
/// `include_str!("../src/sfz_instrument.rs")`（模块头**源码**）必须逐字含两条登记：
/// ① 双口径（离线按 CC 调制 ／ 实时恒为基准值）；② 摊平表不随探针改变区域选择。
/// ⭐ 反向腿：文档里**没有**的那两句 ⇒ `contains` 必须 `false`（⛔ 判据不是恒真）。
///
/// ⚠ 形态照本仓"文本即判据"的既有做法（S32／S38 同款）。
#[test]
fn s58_the_two_caliber_registration_is_judgeable() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const CALIBER: &str = "⭐ 双口径登记（任务单 `#104`）";
    const GATE: &str = "⭐ 摊平期门控登记（任务单 `#104`）";
    // ⭐ 反向腿：文档里**不存在**的两句（旧口径 ／ 从未写过的承诺）。
    const ABSENT_CALIBER: &str = "实时通路也已经按 CC 调制包络";
    const ABSENT_GATE: &str = "摊平表会随探针重新选择区域";
    println!(
        "[engine-sfz/S58] 模块头含双口径登记 = {}、摊平期门控登记 = {}；\
         反向腿 = {} / {}",
        MODULE_SOURCE.contains(CALIBER),
        MODULE_SOURCE.contains(GATE),
        MODULE_SOURCE.contains(ABSENT_CALIBER),
        MODULE_SOURCE.contains(ABSENT_GATE),
    );
    assert!(
        MODULE_SOURCE.contains(CALIBER),
        "⭐ 模块头必须逐字登记：{CALIBER}"
    );
    assert!(
        MODULE_SOURCE.contains(GATE),
        "⭐ 模块头必须逐字登记：{GATE}"
    );
    assert!(
        !MODULE_SOURCE.contains(ABSENT_CALIBER),
        "⭐ 反向腿：文档里**没有**的句子必须 `contains == false`"
    );
    assert!(
        !MODULE_SOURCE.contains(ABSENT_GATE),
        "⭐ 反向腿：文档里**没有**的句子必须 `contains == false`"
    );
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#106`：`ampeg_vel2*`（力度调制的五个包络参数）
//
// 规范逐字（`yeban_sfz::modulation` 的模块文档 §4 —— 本文件 ⛔ 不复制那份事实源）：
// 表行 `ampeg_vel2{attack,hold,decay,release}` = float / 默认 0 / Range `-100 to 100` /
// Unit `seconds`，`ampeg_vel2sustain` 同域、Unit `%`；
// 公式 `(param) = base + ( vel2(param) * velocity / 127 )`。
//
// ⭐ 三条路**全部接线**（⛔ 不是只接离线）：离线 `render_note_into_with_cc`、
// 摊平表 `render_block_into_with_cc`、实时 `SfzVoicePool` 的每块现算路径
// （输入 ＝ 逐声部力度 `SfzVoice::velocity`，⛔ 无新字段 ⇒ 声部仍 40 B）。
// ⛔ 与 `ccN` 是**两支独立输入**（一个来自音符力度、一个来自 CC 状态）。
// ---------------------------------------------------------------------------

/// ⭐ S59 夹具：五个 `vel2` opcode 各一条区域（**分形态**）＋ 一条缺省区域。
///
/// | region | opcode | 期望读数 |
/// | :--- | :--- | :--- |
/// | `key=60` | `ampeg_vel2attack=-0.4` | `Attack ⇒ Some(-0.4)` |
/// | `key=61` | `ampeg_vel2hold=250ms` | `Hold ⇒ Some(0.25)`（单位后缀） |
/// | `key=62` | `ampeg_vel2decay=1` | `Decay ⇒ Some(1.0)` |
/// | `key=63` | `ampeg_vel2sustain=-25%` | `Sustain ⇒ Some(-25.0)`（百分比、负值合法） |
/// | `key=64` | `ampeg_vel2release=0.5s` | `Release ⇒ Some(0.5)` |
/// | `key=65` | 缺省 | 五个全 `None` |
const AMPEG_VEL2_FIVE_FORMS: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 ampeg_vel2attack=-0.4\n\
                                     <region> sample=a.wav key=61 pitch_keycenter=60 ampeg_vel2hold=250ms\n\
                                     <region> sample=a.wav key=62 pitch_keycenter=60 ampeg_vel2decay=1\n\
                                     <region> sample=a.wav key=63 pitch_keycenter=60 ampeg_vel2sustain=-25%\n\
                                     <region> sample=a.wav key=64 pitch_keycenter=60 ampeg_vel2release=0.5s\n\
                                     <region> sample=a.wav key=65 pitch_keycenter=60 ampeg_hold=0.1\n";

/// ⭐ S59（任务单 `#106`；§5.1）：**五个 opcode 的解析与域**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 一份含六条区域的 SFZ（五形态 ＋ 缺省）；单位 ＝ 每条区域五参数上的
/// `Option<f32>` 读数（**力度调制量**，与目标同单位）＋ 非法输入的 `SfzError` 变体。
///
/// ⭐ 每条负判据都与**同一批数据里的一个合法样例**同现，并且该合法样例**单独**出现时
/// 必须被接受 ⇒ ⛔ 证明那些 `Err` 不是"整族一律拒"。
#[test]
fn s59_the_five_vel2_forms_are_parsed_with_their_domains() {
    let instrument = SfzInstrument::load(AMPEG_VEL2_FIVE_FORMS.to_owned(), &Default::default())
        .expect("五形态夹具必须解析成功");
    let readings: Vec<[Option<f32>; 5]> = instrument
        .with_instrument(|parsed| {
            parsed
                .regions()
                .iter()
                .map(|region| {
                    let mut row = [None; 5];
                    for param in AmpegParam::ALL {
                        row[param.index()] = region.ampeg_vel2(param);
                    }
                    row
                })
                .collect()
        })
        .expect("重解析");
    let expected: [[Option<f32>; 5]; 6] = [
        [Some(-0.4), None, None, None, None],
        [None, Some(0.25), None, None, None],
        [None, None, Some(1.0), None, None],
        [None, None, None, Some(-25.0), None],
        [None, None, None, None, Some(0.5)],
        [None, None, None, None, None],
    ];
    assert_eq!(readings.len(), 6, "六条区域都在");
    for (index, (got, want)) in readings.iter().zip(expected).enumerate() {
        assert_eq!(got, &want, "⭐ region {index} 的五参数力度读数");
    }
    println!("[engine-sfz/S59] 五形态读数（逐条）：{readings:?}（第 6 条 = 缺省 ⇒ 全 None）");

    // ---- 负判据：越界／畸形 ⇒ 响亮 `Err`（第 259 条；⛔ 不静默降级、⛔ 不钳位）----
    let legal = "ampeg_vel2attack=-0.4";
    let bad: [(&str, ModErrorShape); 8] = [
        ("ampeg_vel2attack=200", ModErrorShape::FloatRange100),
        ("ampeg_vel2attack=-250", ModErrorShape::FloatRange100),
        ("ampeg_vel2sustain=150", ModErrorShape::FloatRange100),
        ("ampeg_vel2sustain=-101", ModErrorShape::FloatRange100),
        ("ampeg_vel2attack=abc", ModErrorShape::InvalidFloat),
        ("ampeg_vel2attack=1.5x", ModErrorShape::InvalidFloat),
        ("ampeg_vel2hold=50%", ModErrorShape::InvalidFloat),
        ("ampeg_vel2attack=inf", ModErrorShape::NonFinite),
    ];
    for (illegal, shape) in bad {
        // ⭐ 同一批数据里带一个**合法样例**（`legal`）：它能被接受（见下一条断言），
        // 因此这里的 `Err` 必然是 `illegal` 那一行造成的。
        let text = format!(
            "<region> sample=a.wav key=60 pitch_keycenter=60 {legal} {illegal}\n\
             <region> sample=a.wav key=61 pitch_keycenter=60 ampeg_hold=0.1\n"
        );
        let error = SfzInstrument::load(text, &Default::default())
            .expect_err(&format!("{illegal} 必须响亮 Err"));
        assert!(
            matches_mod_error(&error, shape),
            "⭐ {illegal} ⇒ {error:?}（不是期望的 {shape:?}）"
        );
        println!("[engine-sfz/S59] {illegal} ⇒ {error}");
    }
    // ⭐ 同一条合法样例**单独**出现 ⇒ 必须被接受（负判据的正对照）。
    let accepted = SfzInstrument::load(
        format!("<region> sample=a.wav key=60 pitch_keycenter=60 {legal}\n"),
        &Default::default(),
    );
    assert!(
        accepted.is_ok(),
        "⭐ 同批数据里的合法样例必须被接受：{accepted:?}"
    );
    // ⭐ **负值合法**（Range 的下界就是 `-100`）：五个 opcode 各自 −100 都要读得进。
    for name in [
        "ampeg_vel2attack",
        "ampeg_vel2hold",
        "ampeg_vel2decay",
        "ampeg_vel2sustain",
        "ampeg_vel2release",
    ] {
        let text = format!("<region> sample=a.wav key=60 pitch_keycenter=60 {name}=-100\n");
        assert!(
            SfzInstrument::load(text, &Default::default()).is_ok(),
            "⭐ {name} = -100 必须合法（Range 下界）"
        );
    }
    // ⛔ **缺省 ≠ 非法**：一个 `vel2` opcode 都没有 ⇒ `Ok` ＋ 全 `None`（见上面第 6 条区域）。
    assert_eq!(
        readings[5], [None; 5],
        "缺省 ⇒ 无调制（⛔ 不是 `Some(0.0)`）"
    );
    // ⭐ **写了 0** ⇒ `Some(0.0)` —— 与"缺省"**可区分**（求值期见 S62 的第二条腿）。
    let zero = SfzInstrument::load(
        "<region> sample=a.wav key=60 pitch_keycenter=60 ampeg_vel2attack=0\n".to_owned(),
        &Default::default(),
    )
    .expect("写 0 必须合法");
    let zero_readings: [Option<f32>; 5] = zero
        .with_instrument(|parsed| {
            let region = &parsed.regions()[0];
            let mut row = [None; 5];
            for param in AmpegParam::ALL {
                row[param.index()] = region.ampeg_vel2(param);
            }
            row
        })
        .expect("重解析");
    assert_eq!(zero_readings[0], Some(0.0), "显式 0 ⇒ Some(0.0)");
    assert_ne!(zero_readings[0], readings[5][0], "⛔ 与缺省必须可区分");

    // ⛔ **不属本族的名字**按未知 opcode 忽略（既有的忽略口径）：解析成功 ＋ 无调制。
    for ignored in [
        "ampeg_vel2foo=1",
        "ampeg_vel2=1",
        "ampeg_vel2attackcc1=1",
        "ampeg_vel2attack_curvecc1=1",
        "fileg_vel2attack=1",
        "pitcheg_vel2attack=1",
    ] {
        let text = format!(
            "<region> sample=a.wav key=60 pitch_keycenter=60 ampeg_vel2attack=-0.4 {ignored}\n"
        );
        let parsed =
            SfzInstrument::load(text, &Default::default()).expect("未知/不属本族的名字不构成错误");
        let row: [Option<f32>; 5] = parsed
            .with_instrument(|instrument| {
                let region = &instrument.regions()[0];
                let mut row = [None; 5];
                for param in AmpegParam::ALL {
                    row[param.index()] = region.ampeg_vel2(param);
                }
                row
            })
            .expect("重解析");
        assert_eq!(
            row[0],
            Some(-0.4),
            "⭐ {ignored} 必须被忽略（只剩下同批的合法样例）"
        );
    }
}

/// ⭐ S60（任务单 `#106`；§5.2）：**端到端 —— 两个力度 ⇒ 起音帧数不同且等于公式**，
/// 并且 **离线 → 摊平** 两条路**逐位相同**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ `ampeg_attack=0.5` ＋ `ampeg_vel2attack=-0.4` 的区域在**两个力度**下的输出；
/// 单位 ＝ **起音段实测帧数**（帧）＋ 两条路的位模式序列（逐帧 `u32`）。
///
/// # 公式与实测（⛔ 不写"约等于"）
///
/// `A(v) = round((0.5 + (−0.4) × v/127) × 48000)` ⇒ `v = 1` ⇒ **23849**、
/// `v = 127` ⇒ **4800**。⭐ 两个力度**各自**配一条"它自己该怎样"的断言。
///
/// ⚠ **为什么不用力度 0**：`amp_veltrack` 的既有归约把 `velocity == 0` 特判成
/// `0.0` 增益（`yeban-sfz` 的 `veltrack_gain`）⇒ 力度 0 的输出恒零，起音帧数**读不出来**。
/// 夹具取 `amp_veltrack=0`（`velocity >= 1` 时增益恰为 `1.0`）⇒ 输出**恰好**是包络电平本身。
#[test]
fn s60_two_velocities_change_the_envelope_by_the_specification_formula() {
    const HZ: f32 = 48_000.0;
    const FRAMES: usize = 72_000;
    const SFZ_WITH: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
                            ampeg_attack=0.5 ampeg_vel2attack=-0.4\n";
    let instrument = SfzInstrument::load(SFZ_WITH.to_owned(), &Default::default()).expect("解析");
    // ⚠ 样本**比输出缓冲更长**：否则逐样本路径会在最后一帧前停住（与 S55 同款）。
    let sample = InMemorySample {
        pcm: vec![1.0; FRAMES + 1_024],
        sample_hz: HZ,
    };
    let plan = prepare_with(SFZ_WITH, &sample);
    assert_eq!(
        plan.regions()[0].ampeg_vel2(AmpegParam::Attack),
        Some(-0.4),
        "摊平表必须真的承载那一条力度调制量"
    );

    let expected = |velocity: u8| -> usize {
        let seconds = 0.5f32 + (-0.4f32) * (f32::from(velocity) / 127.0);
        (f64::from(seconds) * f64::from(HZ)).round() as usize
    };

    let mut measured = [0usize; 2];
    for (index, velocity) in [1u8, 127].into_iter().enumerate() {
        let mut offline = vec![0.0f32; FRAMES];
        let written_offline = instrument
            .render_note_into_with_cc(&sample, 60, velocity, None, &mut offline, HZ)
            .expect("离线渲染");
        let mut flat = vec![0.0f32; FRAMES];
        let written_flat = plan.render_block_into_with_cc(60, velocity, None, &mut flat);
        assert_eq!(written_offline, FRAMES, "离线整段写满");
        assert_eq!(written_flat, FRAMES, "摊平整段写满");
        // ⭐ 两条离线路走**同一份**求值（`ampeg_value_with_baked_and_vel2`）⇒ 必须逐位相同。
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ 力度 = {velocity}：离线 → 摊平两条路必须逐位相同"
        );

        let attack = measured_attack_frames(&offline);
        measured[index] = attack;
        // ⭐ 线性段逐点对账（容差 1e-6，与 S35／S55 同口径）。
        let mut worst = 0.0f32;
        for (t, value) in offline.iter().enumerate().take(attack) {
            worst = worst.max((value - t as f32 / attack as f32).abs());
        }
        println!(
            "[engine-sfz/S60] 力度 = {velocity}：⭐ 起音实测帧数 = {attack}\
             （规范公式 = {}）；线性段最大偏差 = {worst:e}；out[0] = {}、out[{attack}] = {}",
            expected(velocity),
            offline[0],
            offline[attack]
        );
        assert_eq!(
            attack,
            expected(velocity),
            "⭐ 力度 = {velocity} 的起音帧数必须**逐帧**等于规范公式 \
             `round((0.5 + (−0.4) × v/127) × 48000)`"
        );
        assert!(
            worst <= 1e-6,
            "⭐ 力度 = {velocity}：线性段最大偏差 {worst:e} > 1e-6"
        );
        assert_eq!(
            offline[attack], 1.0,
            "⭐ 力度 = {velocity}：第 A 帧必须**恰好**到峰"
        );
    }
    assert_eq!(measured, [23_849, 4_800], "⭐ 两个力度的实测起音帧数");
    assert_ne!(
        measured[0], measured[1],
        "⭐ 两个力度必须给出**不同**的包络（⛔ 不是『两者相同也算过』）"
    );
    // ⭐ 力度越大 ⇒ 负的 `vel2` 调制把起音压得越短（单调方向，⛔ 不是"碰巧两个数不同"）。
    assert!(measured[1] < measured[0], "负 delta ⇒ 力度 127 的起音更短");
}

/// ⭐ S61（任务单 `#106`；§5.2 的核心新增）：**实时那条路**与**摊平**那条路在
/// **同一力度**下**逐位相同**，并且**三条路**（离线／摊平／实时）同值。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 同一份 `ampeg_attack=0.005` ＋ `ampeg_vel2attack=-0.004` 的 SFZ 在力度
/// `1` 与 `127` 下、由**三条路**各渲染 512 帧的输出；单位 ＝ 位模式序列（逐帧 `u32`）
/// ＋ 起音段实测帧数（帧）。
///
/// # 公式与实测
///
/// `A(v) = round((0.005 + (−0.004) × v/127) × 48000)` ⇒ `v = 1` ⇒ **238**、`v = 127` ⇒ **48**
/// （两者都 < 512 ⇒ 在本块内就能读到峰值）。
///
/// ⭐ 实时那条路的力度取自 [`SfzVoice::velocity`]（触发期抄下）—— `SfzVoice` 因此
/// **＋0 字节**（判据 `S9` 把 40 B 钉住）。
#[test]
fn s61_the_realtime_path_matches_the_flat_path_bit_for_bit_at_the_same_velocity() {
    const HZ: f32 = 48_000.0;
    const FRAMES: usize = 512;
    const SFZ: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
                       ampeg_attack=0.005 ampeg_vel2attack=-0.004\n";
    let instrument = SfzInstrument::load(SFZ.to_owned(), &Default::default()).expect("解析");
    let sample = InMemorySample {
        pcm: vec![1.0; 4_096],
        sample_hz: HZ,
    };
    let plan = prepare_with(SFZ, &sample);
    let expected = |velocity: u8| -> usize {
        let seconds = 0.005f32 + (-0.004f32) * (f32::from(velocity) / 127.0);
        (f64::from(seconds) * f64::from(HZ)).round() as usize
    };

    let mut realtime_frames = [0usize; 2];
    for (index, velocity) in [1u8, 127].into_iter().enumerate() {
        // ① 离线
        let mut offline = vec![0.0f32; FRAMES];
        let written_offline = instrument
            .render_note_into_with_cc(&sample, 60, velocity, None, &mut offline, HZ)
            .expect("离线渲染");
        // ② 摊平表
        let mut flat = vec![0.0f32; FRAMES];
        let written_flat = plan.render_block_into_with_cc(60, velocity, None, &mut flat);
        // ③ ⭐ 实时池（逐声部力度就是本函数的 `velocity` 参数）
        let mut pool = SfzVoicePool::new(HZ);
        let created = pool.trigger_note(&plan, 60, velocity, u64::MAX, 1.0, None);
        assert_eq!(created, 1, "单区域夹具 ⇒ 恰好建 1 个声部");
        assert_eq!(
            pool.voices()[0].velocity(),
            velocity,
            "⭐ 逐声部力度必须**真的**是本次触发的力度（实时那条路的输入）"
        );
        let mut realtime = vec![0.0f32; FRAMES];
        pool.render_into(&plan, 0, &mut realtime);

        assert_eq!(written_offline, FRAMES);
        assert_eq!(written_flat, FRAMES);
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ 力度 = {velocity}：离线 → 摊平"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ 力度 = {velocity}：**摊平 → 实时**必须逐位相同（本单的核心新增）"
        );
        assert_eq!(bits(&offline), bits(&realtime), "⭐ 三条路同值");

        let attack = measured_attack_frames(&realtime);
        realtime_frames[index] = attack;
        println!(
            "[engine-sfz/S61] 力度 = {velocity}：⭐ 实时起音实测帧数 = {attack}\
             （规范公式 = {}）；三条路位模式相同 = {}",
            expected(velocity),
            bits(&offline) == bits(&realtime)
        );
        assert_eq!(
            attack,
            expected(velocity),
            "⭐ 力度 = {velocity}：实时那条路的起音帧数也必须**逐帧**等于规范公式"
        );
    }
    assert_eq!(
        realtime_frames,
        [238, 48],
        "⭐ 实时那条路两个力度的实测帧数"
    );
    assert_ne!(
        realtime_frames[0], realtime_frames[1],
        "⭐ 实时那条路必须真的按力度变（⛔ 不是把 vel2 短接掉）"
    );
}

/// ⭐ S62（任务单 `#106`；§5.3）：**应绿的反向腿 ＋ 三个承重指纹**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// ① 去掉 `ampeg_vel2attack` 那一行前后的**起音帧数**（帧，两力度各一档）；
/// ② 三个既有夹具的 **FNV-1a 64 指纹**（逐位）；
/// ③ 「× 1.0000001 ⇒ 指纹必须变」这条**反空判**腿（`u64` 比较）。
///
/// 三个承重指纹就是 §5.3 逐字点名的：`0xa9dec8a87f69106c`（S37 臂 1）、
/// `0xd3c2a82076bd8947`（S37 臂 2）、`0xa933ddab286bdf5e`（S33／S14 的广播路径）。
#[test]
fn s62_the_reverse_legs_and_the_three_load_bearing_fingerprints() {
    const HZ: f32 = 48_000.0;
    const FRAMES: usize = 512;
    const WITH_MOD: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
                            ampeg_attack=0.005 ampeg_vel2attack=-0.004\n";
    const WITHOUT_MOD: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
                               ampeg_attack=0.005\n";
    const ZERO_MOD: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
                            ampeg_attack=0.005 ampeg_vel2attack=0\n";
    let sample = InMemorySample {
        pcm: vec![1.0; 4_096],
        sample_hz: HZ,
    };
    let measure = |text: &str, velocity: u8| -> (usize, Vec<f32>) {
        let plan = prepare_with(text, &sample);
        let mut out = vec![0.0f32; FRAMES];
        plan.render_block_into_with_cc(60, velocity, None, &mut out);
        (measured_attack_frames(&out), out)
    };
    let with = [measure(WITH_MOD, 1), measure(WITH_MOD, 127)];
    let without = [measure(WITHOUT_MOD, 1), measure(WITHOUT_MOD, 127)];
    let zero = [measure(ZERO_MOD, 1), measure(ZERO_MOD, 127)];
    let with_frames = [with[0].0, with[1].0];
    let without_frames = [without[0].0, without[1].0];
    let zero_frames = [zero[0].0, zero[1].0];
    println!(
        "[engine-sfz/S62] 带 `ampeg_vel2attack=-0.004` ⇒ 力度 1／127 起音帧数 = {with_frames:?}；\
         去掉那一行 ⇒ {without_frames:?}；写成 0 ⇒ {zero_frames:?}"
    );
    assert_eq!(
        with_frames,
        [238, 48],
        "⭐ 有调制：两个力度落在规范公式的两个点上"
    );
    assert_eq!(
        without_frames,
        [240, 240],
        "⭐ 反向腿 ①：去掉那一行 ⇒ 两个力度给出**同一个**基准帧数（round(0.005×48000) = 240）"
    );
    assert_eq!(
        zero_frames,
        [240, 240],
        "⭐ 反向腿 ①′：写成 `ampeg_vel2attack=0` ⇒ 值上**也是**无调制（`+ 0 × v/127`）"
    );
    assert_ne!(
        with_frames[1], without_frames[1],
        "⭐ 有牙：唯一变化的那个 opcode 必须真的改变读数"
    );

    // ---- ②③ 三个承重指纹（无 `vel2` 的既有夹具必须**逐字不变**）----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, expected) in [
        (
            "S37 loop_continuous ＋ end_sample = 200",
            &looped,
            200u64,
            0xa9de_c8a8_7f69_106cu64,
        ),
        (
            "S37 no_loop ＋ end_sample = u64::MAX",
            &plain,
            u64::MAX,
            0xd3c2_a820_76bd_8947u64,
        ),
    ] {
        let out = render_pool(plan, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!("[engine-sfz/S62] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）");
        let _checked = check_fingerprint(&format!("S62 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let legacy = fnv1a_64(&legacy_block);
    println!(
        "[engine-sfz/S62] S33／S14 广播路径 512 帧 @ (60,127)：指纹 = 0x{legacy:016x}\
         （承重 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）；写入 = {legacy_frames}"
    );
    let _checked = check_fingerprint("S62 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    // ⭐ 应绿反向腿：同一段输出 × `1.0000001` ⇒ 指纹**必须**变
    // （证明上面那三条是**逐位**判据，⛔ 不是"有输出就算过"）。
    let scaled: Vec<f32> = legacy_block
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    let scaled_hash = fnv1a_64(&scaled);
    println!(
        "[engine-sfz/S62] 反向腿（× 1.0000001）：指纹 = 0x{scaled_hash:016x}\
         （原指纹 0x{legacy:016x}，必须不同）"
    );
    assert_ne!(scaled_hash, legacy, "⭐ 反向腿：乘 1.0000001 后指纹必须变");

    // ---- ④ 无 `vel2` 的**新入口**与旧入口逐位相同（缺省 ⇒ 与接线前逐位相同）----
    let mut probe_none = vec![0.0f32; BLOCK];
    let none_frames = broadcast.render_block_into_with_cc(60, 127, None, &mut probe_none);
    assert_eq!(none_frames, legacy_frames);
    assert_eq!(
        bits(&legacy_block),
        bits(&probe_none),
        "⭐ 无 `ampeg_vel2*` 的既有夹具：`render_block_into_with_cc(cc = None)` 逐位不变"
    );
    // ⭐ 有 `ampeg_vel2attack` 的区域在**力度 127** 与**力度 1** 下必须**不同**
    // （上面 `with` 两条臂的位模式直接比）。
    assert_ne!(
        bits(&with[0].1),
        bits(&with[1].1),
        "⭐ 有牙：同一份 SFZ 在两个力度下的输出必须**逐位不同**"
    );
    assert_eq!(
        bits(&without[0].1),
        bits(&without[1].1),
        "⭐ 反向腿 ①″：没有 `vel2` ⇒ 两个力度的输出**逐位相同**"
    );
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#107`：把 MIDI CC 状态接进引擎的**实时通路**
// ---------------------------------------------------------------------------
//
// ⛔ 本片**不动**解析/归约（`#104` 已完成），也**不动**求值本体
// （`yeban_sfz::modulation::ampeg_value_with_baked*` 是唯一一份实现）：
// 本片补的是"**喂值**"那一半 —— 把会话运行态的 CC 表当探针
// （`Fn(u8) -> u8`）交给**实时**那条逐块现算的路。
//
// 三条路（离线 `render_note_into_with_cc` ／ 摊平 `render_block_into_with_cc` ／
// 实时 `render_into_with_cc`）在**同一 CC ＋ 同一力度**下必须**逐位相同**。
// ⛔ 区域选择仍由摊平期的掩码决定（`loccN`/`hiccN` 的显式选路 ③，登记见 `src/sfz_instrument.rs`）。
// ⭐ ⭐ **追加修订段（任务单 `#109`）—— 被修订的是上面这一行**（⛔ 原文一字未删）：
// `loccN`/`hiccN` **不再**在摊平期判定 —— 掩码只留静态门控（通道 / `trigger` /
// keyswitch），CC 门控在**触发期**（`SfzVoicePool::trigger_note`）按探针裁决。
// ⚠ `ampeg_*` 的 CC 调制（本段夹具的题材）**仍然**是逐块求值 ⇒ 本段各判据的
// 语义与读数不受影响（`trigger_note` 多收一个 `cc = None` 的参数）。

/// ⭐ S63 夹具：`ampeg_attack=0.005` ＋ `ampeg_attackcc100=0.004`（legacy `ccN` 形态）。
///
/// 公式：`A(cc) = round((0.005 + 0.004 × cc/127) × 48 000)` ⇒ `cc = 0` ⇒ **240 帧**、
/// `cc = 127` ⇒ **432 帧**（两者都 < 512 ⇒ 在本块内就能读到峰值）。
///
/// ⚠ `amp_veltrack=0`（与 S60／S61 同款）：`velocity >= 1` 时力度增益恰 `1.0`
/// ⇒ 输出**恰好**是包络电平本身（S64 的"起音帧数"那条打印因此也可读）。
const CC_ATTACK_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
                                 ampeg_attack=0.005 ampeg_attackcc100=0.004\n";

/// ⭐ S63（任务单 `#107`；判据 §7.2）：**实时那条路读得到 CC** —— 两个 CC 值
/// ⇒ 实时起音帧数**不同**且**等于规范公式**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 同一份 [`CC_ATTACK_FIXTURE`] 经**实时声部池**
/// （[`SfzVoicePool::render_into_with_cc`]）渲染 512 帧的输出；
/// 单位 ＝ **起音段实测帧数**（帧）＋ 位模式序列（逐帧 `u32`）。
///
/// ⭐ 反空判腿：**同一份夹具**在 `cc = None` 下必须给基准帧数 **240**，且
/// `cc = Some(0)` 与 `cc = None` 在这里**恰好同值**（`0.005 × 48000 = 240`）——
/// 因此"两个 CC 值不同"这条判据的**有牙**来自 `cc = 127` 那一臂，
/// ⛔ 不是"探针管道自己造出来的假差异"（正对照见下一条断言里的 `cc = 37`）。
#[test]
fn s63_the_realtime_path_reads_cc_and_follows_the_specification_formula() {
    const HZ: f32 = 48_000.0;
    const FRAMES: usize = 512;
    let sample = InMemorySample {
        pcm: vec![1.0; 4_096],
        sample_hz: HZ,
    };
    let plan = prepare_with(CC_ATTACK_FIXTURE, &sample);
    assert_eq!(
        plan.regions()[0].ampeg_modulations().len(),
        1,
        "摊平表必须真的承载那一条 CC 调制项"
    );
    let expected = |cc: u8| -> usize {
        let seconds = 0.005f32 + 0.004f32 * (f32::from(cc) / 127.0);
        (f64::from(seconds) * f64::from(HZ)).round() as usize
    };

    // ⭐ 探针：`cc == 100` 读传入值，其余控制器读 `0`
    // （与 `ControlChangeState::value` 的"未设置读 0"同一口径）。
    let render_at = |cc: Option<u8>| -> (Vec<f32>, usize) {
        let mut pool = SfzVoicePool::new(HZ);
        assert_eq!(
            pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None),
            1,
            "单区域夹具 ⇒ 恰好建 1 个声部"
        );
        let probe = |controller: u8| -> u8 {
            if controller == 100 {
                cc.unwrap_or(0)
            } else {
                0
            }
        };
        let cc_arg: Option<&dyn Fn(u8) -> u8> = match cc {
            Some(_) => Some(&probe),
            None => None,
        };
        let mut out = vec![0.0f32; FRAMES];
        pool.render_into_with_cc(&plan, 0, &mut out, cc_arg);
        let attack = measured_attack_frames(&out);
        (out, attack)
    };

    let (out_none, attack_none) = render_at(None);
    let (out_zero, attack_zero) = render_at(Some(0));
    let (out_mid, attack_mid) = render_at(Some(37));
    let (out_full, attack_full) = render_at(Some(127));

    println!(
        "[engine-sfz/S63] 实时路起音帧数：cc=None ⇒ {attack_none}、cc=0 ⇒ {attack_zero}、\
         cc=37 ⇒ {attack_mid}、cc=127 ⇒ {attack_full}；公式 = [{}..{}]",
        expected(0),
        expected(127)
    );
    assert_eq!(
        attack_none, 240,
        "`cc = None` ⇒ 基准（与接线前逐位相同的那条路）"
    );
    assert_eq!(attack_zero, expected(0));
    assert_eq!(attack_mid, expected(37));
    assert_eq!(attack_full, expected(127));
    assert_ne!(
        attack_full, attack_none,
        "⭐ 有牙：CC 127 必须真的改变实时那条路的包络（⛔ 不是探针被短接）"
    );
    assert_ne!(
        attack_mid, attack_zero,
        "⭐ 中间值也必须落在公式上（⛔ 不是两档查表）"
    );
    assert_ne!(
        bits(&out_mid),
        bits(&out_zero),
        "⭐ 中间 CC 值的输出必须与基准**逐位不同**"
    );
    assert_eq!(
        bits(&out_zero),
        bits(&out_none),
        "⭐ `cc = Some(0)` 与 `cc = None` 在本夹具下**同值**（公式 ⇒ 240）——\
         这是『探针本身不引入差异』的反空判腿"
    );
    assert_ne!(bits(&out_full), bits(&out_none), "⭐ 输出必须**逐位**不同");
}

/// ⭐ S64（任务单 `#107`；判据 §7.3）：**三条路一致** —— 同一 CC ＋ 同一力度下
/// 离线 ／ 摊平 ／ 实时**位模式逐位相同**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_ATTACK_FIXTURE`] 在 `cc ∈ {0, 37, 127}` 三个值下的三条路输出；
/// 单位 ＝ 位模式序列（逐帧 `u32`）＋ 起音段实测帧数（帧）。
///
/// ⚠ 实时那条路的 CC 只进 [`SfzVoicePool::render_into_with_cc`]（渲染），
/// ⛔ 不进 `trigger_note`（区域选择在摊平期）⇒ 三条路的选择口径一致。
///
/// ⭐ ⭐ **追加修订段（任务单 `#109`）—— 被修订的是上面这一行的后半**（⛔ 原文一字未删）：
/// `trigger_note` 现在**也**收 `cc`（`#109`：`loccN`/`hiccN` 在触发期裁决）。本判据的
/// 夹具**没有** CC 门控 ⇒ 两条入口（`cc = None` 与本段的探针）给出**同一个**声部集合，
/// 因此下面三条路的**位模式**读数不变（本段判据复跑全绿即可见）。
#[test]
fn s64_the_three_paths_agree_bit_for_bit_at_the_same_cc() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 100;
    const FRAMES: usize = 512;
    let instrument = SfzInstrument::load(CC_ATTACK_FIXTURE.to_owned(), &Default::default())
        .expect("夹具必须解析成功");
    let sample = InMemorySample {
        pcm: vec![1.0; 4_096],
        sample_hz: HZ,
    };
    let plan = prepare_with(CC_ATTACK_FIXTURE, &sample);

    for cc_value in [0u8, 37, 127] {
        let probe = |controller: u8| -> u8 { if controller == 100 { cc_value } else { 0 } };
        let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);

        // ① 离线（`SfzInstrument` 的一次性渲染）
        let mut offline = vec![0.0f32; FRAMES];
        let written_offline = instrument
            .render_note_into_with_cc(&sample, 60, VELOCITY, cc_arg, &mut offline, HZ)
            .expect("离线渲染");
        // ② 摊平表（`PreparedSfz` 的一次性渲染）
        let mut flat = vec![0.0f32; FRAMES];
        let written_flat = plan.render_block_into_with_cc(60, VELOCITY, cc_arg, &mut flat);
        // ③ ⭐ 实时声部池（本单接线的那条路）
        let mut pool = SfzVoicePool::new(HZ);
        assert_eq!(
            pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, None),
            1,
            "单区域夹具 ⇒ 恰好建 1 个声部"
        );
        let mut realtime = vec![0.0f32; FRAMES];
        pool.render_into_with_cc(&plan, 0, &mut realtime, cc_arg);

        assert_eq!(written_offline, FRAMES);
        assert_eq!(written_flat, FRAMES);
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ cc = {cc_value}：离线 → 摊平必须逐位相同"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ cc = {cc_value}：**摊平 → 实时**必须逐位相同（本单的核心新增）"
        );
        assert_eq!(
            bits(&offline),
            bits(&realtime),
            "⭐ cc = {cc_value}：三条路同值"
        );
        println!(
            "[engine-sfz/S64] cc = {cc_value}：三条路位模式相同 = {}；起音帧数 = {}",
            bits(&offline) == bits(&realtime),
            measured_attack_frames(&realtime)
        );
    }

    // ⭐ 反向腿（应绿）：同一份夹具在**两个不同 CC** 下的实时输出必须**逐位不同**
    // ⇒ "三条路相同"⛔ 不能靠"整份夹具根本没接线"来满足。
    let mut arms = Vec::new();
    for cc_value in [0u8, 127] {
        let probe = |controller: u8| -> u8 { if controller == 100 { cc_value } else { 0 } };
        let mut pool = SfzVoicePool::new(HZ);
        pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, None);
        let mut out = vec![0.0f32; FRAMES];
        pool.render_into_with_cc(&plan, 0, &mut out, Some(&probe));
        arms.push(bits(&out));
    }
    assert_ne!(
        arms[0], arms[1],
        "⭐ 应绿反向腿：两个 CC 值的实时输出必须逐位不同"
    );
}

/// ⭐ S65（任务单 `#107`；判据 §7.4）：**没有 CC ⇒ 逐位不变**（三个承重指纹）
/// ＋ 新入口在 `cc = None` 下与旧入口**逐位相同**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 三个**既有**夹具（与 S33／S37／S62 逐字相同）经**新入口**
/// （`render_into_with_cc(..., None)` ／ `render_block_into_with_cc(..., None)`）
/// 的输出；单位 ＝ **FNV-1a 64 指纹**（逐位）＋ 非零帧数（帧）。
///
/// ⭐ 三个承重指纹（§5.3 逐字点名）：`0xa9dec8a87f69106c`（S37 臂 1）／
/// `0xd3c2a82076bd8947`（S37 臂 2）／`0xa933ddab286bdf5e`（S33／S14 广播路径）。
#[test]
fn s65_the_new_entry_points_leave_the_three_load_bearing_fingerprints_untouched() {
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, expected) in [
        (
            "S65 loop_continuous ＋ end_sample = 200",
            &looped,
            200u64,
            0xa9de_c8a8_7f69_106cu64,
        ),
        (
            "S65 no_loop ＋ end_sample = u64::MAX",
            &plain,
            u64::MAX,
            0xd3c2_a820_76bd_8947u64,
        ),
    ] {
        // 旧入口
        let old = render_pool(plan, end_sample, BLOCK);
        // ⭐ 新入口（`cc = None`）：必须与旧入口**逐位相同**。
        let mut pool = SfzVoicePool::new(48_000.0);
        assert_eq!(pool.trigger_note(plan, 60, 127, end_sample, 1.0, None), 1);
        let mut new = vec![0.0f32; BLOCK];
        pool.render_into_with_cc(plan, 0, &mut new, None);
        assert_eq!(
            bits(&old),
            bits(&new),
            "⭐ {label}：`render_into_with_cc(cc = None)` 必须与旧入口逐位相同"
        );
        let actual = fnv1a_64(&new);
        println!(
            "[engine-sfz/S65] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）；\
             非零帧数 = {}",
            new.iter().filter(|sample| **sample != 0.0).count()
        );
        let _checked = check_fingerprint(&format!("S65 {label}"), actual, expected);
    }

    // ③ 广播路径（S33／S14）：`render_block_into_with_cc(cc = None)` 与旧入口逐位相同。
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let mut probe_none = vec![0.0f32; BLOCK];
    let none_frames = broadcast.render_block_into_with_cc(60, 127, None, &mut probe_none);
    assert_eq!(none_frames, legacy_frames);
    assert_eq!(
        bits(&legacy_block),
        bits(&probe_none),
        "⭐ `render_block_into_with_cc(cc = None)` 必须与旧入口逐位相同"
    );
    let legacy = fnv1a_64(&probe_none);
    println!(
        "[engine-sfz/S65] S33／S14 广播路径：指纹 = 0x{legacy:016x}\
         （承重 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）"
    );
    let _checked = check_fingerprint("S65 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    // ⭐ 应绿反向腿：× `1.0000001` ⇒ 指纹必须变（证明上面三条是**逐位**判据）。
    let scaled: Vec<f32> = probe_none
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    assert_ne!(
        fnv1a_64(&scaled),
        legacy,
        "⭐ 反向腿：乘 1.0000001 后指纹必须变"
    );
}

/// ⭐ S66（任务单 `#107`；§2.3 的"⛔ 不许静默"）：**追加修订段 ＋ 显式选路 ③ 可判**。
///
/// # 判定量
///
/// `include_str!("../src/sfz_instrument.rs")`（模块头**源码**）必须逐字含：
/// ① 追加修订段的标题（`#107`）；② 门控那条的**显式选路 ③**；
/// ③ `#104` 的两条**原文**登记仍在（S58 的判据不许被本单的修订段冲掉）；
/// ④ `#107` 未接线的两族（`pan_oncc*` / `set_ccN` 的播种）。
/// ⭐ 反向腿：文档里**没有**的两句 ⇒ `contains` 必须 `false`（⛔ 判据不是恒真）。
#[test]
fn s66_the_107_revision_is_appended_and_the_gate_choice_is_explicit() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const REVISION: &str = "⭐ ⭐ **追加修订段（任务单 `#107`）";
    const GATE_CHOICE: &str = "摊平期门控登记维持不变（显式选路 ③）";
    const ORIGINAL_CALIBER: &str = "⭐ 双口径登记（任务单 `#104`）";
    const ORIGINAL_GATE: &str = "⭐ 摊平期门控登记（任务单 `#104`）";
    const UNWIRED: &str = "本单未接线（登记，⛔ 不静默）";
    const ABSENT_REVISION: &str = "本单把门控也搬进了实时逐块判定";
    const ABSENT_UNWIRED: &str = "pan_oncc* 与 set_ccN 已经全部接线";
    println!(
        "[engine-sfz/S66] 追加修订段 = {}、显式选路 ③ = {}、`#104` 原文两条 = {} / {}、\
         未接线登记 = {}",
        MODULE_SOURCE.contains(REVISION),
        MODULE_SOURCE.contains(GATE_CHOICE),
        MODULE_SOURCE.contains(ORIGINAL_CALIBER),
        MODULE_SOURCE.contains(ORIGINAL_GATE),
        MODULE_SOURCE.contains(UNWIRED),
    );
    assert!(
        MODULE_SOURCE.contains(REVISION),
        "⭐ 必须有 `#107` 的追加修订段"
    );
    assert!(
        MODULE_SOURCE.contains(GATE_CHOICE),
        "⭐ 必须显式登记门控的选路"
    );
    assert!(
        MODULE_SOURCE.contains(ORIGINAL_CALIBER) && MODULE_SOURCE.contains(ORIGINAL_GATE),
        "⭐ `#104` 的两条原文登记必须**保留**（第 278 条：保留原文 ＋ 追加修订段）"
    );
    assert!(MODULE_SOURCE.contains(UNWIRED), "⭐ 未接线的两族必须登记");
    assert!(!MODULE_SOURCE.contains(ABSENT_REVISION), "⭐ 反向腿");
    assert!(!MODULE_SOURCE.contains(ABSENT_UNWIRED), "⭐ 反向腿");
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#108`：把交叉淡化的 **CC 轴**（`xfin_loccN` ／ `xfin_hiccN` ／
//    `xfout_loccN` ／ `xfout_hiccN`）接进引擎的**三条路**
// ---------------------------------------------------------------------------
//
// ⛔ 本片**不动** `yeban-sfz` 的语义：`Region::crossfade_gain` 早就读得到
// `RegionQuery::cc`（公式在 `crossfade.rs` 的 `fade_in` ／ `fade_out` 里），
// 本片补的是"**把几何烘进摊平表** ＋ **把探针喂进逐块路径**"那一半。
//
// 三条路（离线 `render_note_into_with_cc` ／ 摊平 `render_block_into_with_cc` ／
// 实时 `render_into_with_cc`）在**同一 CC ＋ 同一力度**下必须**逐位相同**。

/// ⭐ S67 夹具：`xfin_locc1=0` ＋ `xfin_hicc1=100`（规范页示例的形态），曲线缺省 `power`。
///
/// `amp_veltrack=0` ⇒ 力度 ≥ 1 时 `velocity_gain == 1.0`；样本恒 `1.0`、`rate == 1.0`
/// ⇒ 输出的**每一帧逐位等于**该 CC 处的交叉淡化增益（于是可以把输出**反解成公式值**，
/// ⛔ 不是"看起来在变"）。
const CC_FADE_IN_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                  amp_veltrack=0 xfin_locc1=0 xfin_hicc1=100\n";

/// ⭐ S67 的第二条腿：同一条淡入、显式取 `xf_cccurve=gain`（线性增益曲线）。
const CC_FADE_IN_LINEAR_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                        amp_veltrack=0 xf_cccurve=gain \
                                        xfin_locc1=0 xfin_hicc1=100\n";

/// ⭐ S69 的反向腿夹具（**单行**形态）：`xfout_locc1=64` 单独出现 ⇒ 上界取
/// `xfout` 族的规范缺省 **127** ⇒ 区间 `[64, 127]`（真的淡出）；
/// ⭐ **去掉这一行** ⇒ 该区域一段交叉淡化都没有 ⇒ 增益恒 `1.0` ⇒ CC 不再影响输出。
const CC_FADE_OUT_ONE_LINE_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                           amp_veltrack=0 xfout_locc1=64\n";

/// ⭐ S69 的对照夹具：与 [`CC_FADE_OUT_ONE_LINE_FIXTURE`] **同文本、去掉那一行**。
const CC_FADE_OUT_ONE_LINE_REMOVED: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                            amp_veltrack=0\n";

/// ⭐ S69 的第三条腿夹具：`xfin_hicc1=100` 单独出现 ⇒ 下界取 `xfin` 族的规范缺省 **0**
/// ⇒ 区间 `[0, 100]`。⚠ **去掉 `xfin_locc1=0` 那一行不改变这条区间的生效性** ——
/// 这正是下面那条"去行"反向腿**分形态**的原因（测出来的事实，⛔ 不是假设）。
const CC_FADE_IN_NO_LOCC_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                          amp_veltrack=0 xfin_hicc1=100\n";

/// ⭐ 规范公式（逐字照 `yeban-sfz` 的 `crossfade::fade_in`）：
/// `t = 0`（`v <= low`）／`t = 1`（`v >= high`）／其间 `(v − low) / (high − low)`；
/// `power`（缺省）⇒ `sqrt(t)`、`gain` ⇒ `t`。本夹具 `low = 0`。
fn expected_cc_fade_in(v: u8, high: u8, power: bool) -> f32 {
    let t = if v >= high {
        1.0
    } else {
        f32::from(v) / f32::from(high)
    };
    if power { t.sqrt() } else { t }
}

/// ⭐ 恒 `1.0` 的样本（S67／S68 用）：`rate == 1.0`、`frac == 0` ⇒ 插值逐位精确。
fn constant_sample(frames: usize) -> InMemorySample {
    InMemorySample {
        pcm: vec![1.0; frames],
        sample_hz: 48_000.0,
    }
}

/// ⭐ S67（任务单 `#108`；判据 §6.1）：**端到端 —— 两个 CC 值给出不同增益，且逐位等于公式**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_FADE_IN_FIXTURE`] ／ [`CC_FADE_IN_LINEAR_FIXTURE`] 经**离线**
/// `render_note_into_with_cc` 渲染的 512 帧输出；单位 ＝ 增益（无量纲，`1.0` ＝ 满幅）
/// ＋ 位模式（逐帧 `u32`）。
///
/// 规范逐字（<https://sfzformat.com/opcodes/xfin_loccN/>）："The volume of the region will
/// be zero for values of the MIDI continuous controller N lower than or equal to
/// `xfin_loccN`, and maximum … for values greater than or equal to `xfin_hiccN`."
/// ⇒ `[0, 100]` 上 `gain = sqrt(v/100)`（`power`）／`v/100`（`gain`）。
#[test]
fn s67_the_cc_axis_fade_follows_the_specification_formula_on_the_offline_path() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 100;
    const FRAMES: usize = 512;
    const HIGH: u8 = 100;
    let sample = constant_sample(4_096);

    for (label, text, power) in [
        ("power（缺省）", CC_FADE_IN_FIXTURE, true),
        ("gain（线性）", CC_FADE_IN_LINEAR_FIXTURE, false),
    ] {
        let instrument =
            SfzInstrument::load(text.to_owned(), &Default::default()).expect("夹具必须解析成功");
        for value in [0u8, 25, 50, 75, 100, 127] {
            let probe = |controller: u8| -> u8 { if controller == 1 { value } else { 0 } };
            let mut out = vec![0.0f32; FRAMES];
            let written = instrument
                .render_note_into_with_cc(&sample, 60, VELOCITY, Some(&probe), &mut out, HZ)
                .expect("离线渲染");
            assert_eq!(written, FRAMES);
            let want = expected_cc_fade_in(value, HIGH, power);
            assert_eq!(
                out[0].to_bits(),
                want.to_bits(),
                "⭐ {label} cc = {value}：第 0 帧必须**逐位**等于规范公式值 \
                 （实测 {:.9} / {:#010x}，公式 {:.9} / {:#010x}）",
                out[0],
                out[0].to_bits(),
                want,
                want.to_bits()
            );
            assert!(
                out.iter().all(|s| s.to_bits() == want.to_bits()),
                "⭐ 恒 `1.0` 样本 ⇒ 512 帧**每一帧**都等于该 CC 处的增益"
            );
            println!(
                "[engine-sfz/S67] {label} cc = {value}：实测增益 = {:.9}（{:#010x}）；\
                 公式 = {:.9}（{:#010x}）",
                out[0],
                out[0].to_bits(),
                want,
                want.to_bits()
            );
        }
    }

    // ⭐ 反空判腿：`power` 腿的 `cc = 25`（恰好 `0.5`）与 `cc = 100`（恰好 `1.0`）必须不同。
    let power = SfzInstrument::load(CC_FADE_IN_FIXTURE.to_owned(), &Default::default())
        .expect("夹具必须解析成功");
    let render = |value: u8| -> f32 {
        let probe = |controller: u8| -> u8 { if controller == 1 { value } else { 0 } };
        let mut out = vec![0.0f32; FRAMES];
        power
            .render_note_into_with_cc(&sample, 60, VELOCITY, Some(&probe), &mut out, HZ)
            .expect("离线渲染");
        out[0]
    };
    assert_eq!(
        render(25),
        0.5,
        "⭐ `v = 25`、`high = 100` ⇒ `sqrt(0.25)` **恰好** 0.5"
    );
    assert_eq!(render(100), 1.0, "⭐ `v >= high` ⇒ 满幅 1.0");
    assert_eq!(
        render(100),
        render(127),
        "⭐ 上界以上**钳到**满幅（同一段，⛔ 不是外推）"
    );
    assert_ne!(
        render(25),
        render(50),
        "⭐ 两个 CC 值必须给出**不同**的增益"
    );
}

/// ⭐ S68（任务单 `#108`；判据 §6.2）：**三条路一致** —— 同一 CC ＋ 同一力度下，
/// 离线 ／ 摊平 ／ 实时**位模式逐位相同**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_FADE_IN_FIXTURE`] 在 `cc ∈ {0, 25, 50, 75, 100, 127}`（力度 100）下
/// 三条路的 512 帧输出；单位 ＝ 位模式序列（逐帧 `u32`）＋ 逐声部 `track_gain`（无量纲）。
#[test]
fn s68_the_three_paths_agree_bit_for_bit_at_the_same_cc_on_the_crossfade_axis() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 100;
    const FRAMES: usize = 512;
    let instrument = SfzInstrument::load(CC_FADE_IN_FIXTURE.to_owned(), &Default::default())
        .expect("夹具必须解析成功");
    let sample = constant_sample(4_096);
    let plan = prepare_with(CC_FADE_IN_FIXTURE, &sample);
    assert_eq!(
        plan.regions()[0].cc_crossfade_count(),
        1,
        "摊平表必须真的承载那一条 CC 段"
    );
    // ⭐ 烘的几何必须与**解析层**逐字一致（同一条区间、同一个方向、同一条曲线）。
    let parsed = instrument
        .with_instrument(|parsed| parsed.regions()[0].crossfades.clone())
        .expect("闭包式访问");
    assert_eq!(
        plan.regions()[0].cc_crossfades(),
        parsed.as_slice(),
        "⭐ 摊平表里的 CC 段必须与 `Region::crossfades` **逐字**相同（⛔ 不是另造一份几何）"
    );

    let mut fingerprints: Vec<(u8, u64)> = Vec::new();
    for cc_value in [0u8, 25, 50, 75, 100, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc_value } else { 0 } };
        let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);

        // ① 离线
        let mut offline = vec![0.0f32; FRAMES];
        let written_offline = instrument
            .render_note_into_with_cc(&sample, 60, VELOCITY, cc_arg, &mut offline, HZ)
            .expect("离线渲染");
        // ② 摊平表
        let mut flat = vec![0.0f32; FRAMES];
        let written_flat = plan.render_block_into_with_cc(60, VELOCITY, cc_arg, &mut flat);
        // ③ 实时声部池
        // ⭐ `#109`：`trigger_note` 现在**也**收 `cc`；本夹具**没有** CC 门控
        // ⇒ 门控一项都不查，声部数与 `cc = None` 时**同一个**（下面三条路逐位相同
        // 就是这条的机械见证）。
        let mut pool = SfzVoicePool::new(HZ);
        assert_eq!(
            pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, cc_arg),
            1,
            "单区域夹具 ⇒ 恰好建 1 个声部"
        );
        let mut realtime = vec![0.0f32; FRAMES];
        pool.render_into_with_cc(&plan, 0, &mut realtime, cc_arg);

        assert_eq!(written_offline, FRAMES);
        assert_eq!(written_flat, FRAMES);
        // ⭐ 声部里存的是**引擎层**那一份（⛔ 不是"乐器层 × 引擎层"的乘积）。
        assert_eq!(
            pool.voices()[0].track_gain(),
            1.0,
            "⭐ 单位轨增益 ⇒ `track_gain` 恰 `1.0`（它**只**承载引擎层那一份）"
        );
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ cc = {cc_value}：离线 → 摊平必须逐位相同"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ cc = {cc_value}：**摊平 → 实时**必须逐位相同"
        );
        assert_eq!(
            bits(&offline),
            bits(&realtime),
            "⭐ cc = {cc_value}：三条路同值"
        );
        let fingerprint = fnv1a_64(&realtime);
        fingerprints.push((cc_value, fingerprint));
        println!(
            "[engine-sfz/S68] cc = {cc_value}：三条路位模式相同 = {}；增益 = {:.9}；\
             指纹 = 0x{fingerprint:016x}",
            bits(&offline) == bits(&realtime),
            realtime[0]
        );
    }
    // ⭐ 反空判腿：六个 CC 值里至少要出现**两个不同**的指纹
    // （⛔ 否则"三条路相同"可以靠"整条轴根本没接线"满足）。
    assert!(
        fingerprints.iter().any(|(_, f)| *f != fingerprints[0].1),
        "⭐ 有牙：不同 CC 值必须给出**不同**的输出指纹"
    );
    assert_eq!(
        fingerprints[4].1, fingerprints[5].1,
        "⭐ `cc = 100`（＝ `xfin_hicc1`）与 `cc = 127`（上界以上）落在**同一段**\
         ⇒ 同值（⛔ 不是外推：`position` 在 `v >= high` 处恒 `1.0`）"
    );
    assert_ne!(
        fingerprints[0].1, fingerprints[1].1,
        "⭐ `cc = 0`（下界 ⇒ 静音）与 `cc = 25` 必须不同"
    );

    // ⭐ 第四条腿：非单位 `track_gain`（0.5）下声部存的确实是**它**，
    // 而输出 = 乐器层 × 0.5（⛔ 不是"把乘积当成 track_gain"）。
    let mut pool = SfzVoicePool::new(HZ);
    assert_eq!(
        pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 0.5, None),
        1
    );
    assert_eq!(
        pool.voices()[0].track_gain(),
        0.5,
        "⭐ `track_gain = 0.5` ⇒ 声部里存的正是 0.5"
    );
    let probe = |controller: u8| -> u8 { if controller == 1 { 100 } else { 0 } };
    let mut scaled = vec![0.0f32; FRAMES];
    pool.render_into_with_cc(&plan, 0, &mut scaled, Some(&probe));
    assert_eq!(
        scaled[0].to_bits(),
        (1.0f32 * 0.5).to_bits(),
        "⭐ 满幅（cc = 100）× 轨增益 0.5 ⇒ 每帧恰 0.5"
    );
}

/// ⭐ S69（任务单 `#108`；判据 §6.3）：**反向腿 ＋ 三个承重指纹**。
///
/// # 反向腿（⭐ 分形态 —— 测出来的事实，⛔ 不是假设）
///
/// * ① **两条都去掉**（同文本去掉 `xfin_locc1=0` 与 `xfin_hicc1=100`）⇒ 两个 CC 值的
///   输出**逐位相同**，且与 `cc = None` 逐位相同；
/// * ② **`xfout` 单行形态**：`xfout_locc1=64` 单独出现 ⇒ 区间 `[64, 127]` 真的淡出
///   （`cc = 64` ⇒ 1.0、`cc = 127` ⇒ 0.0 ⇒ 输出不同）；**去掉那一行** ⇒ 两个 CC 值的
///   输出**逐位相同**（⛔ 这一条才是任务单说的"去掉那一行 ⇒ 逐位相同"的成立形态）；
/// * ③ **`xfin` 单行形态的反面读数**：`xfin_locc1=0` 单独去掉之后**仍然不同** ——
///   因为 `xfin` 族的下界规范缺省是 **0**，`[0, 100]` 照样生效。本片把这条**如实测出来
///   并登记**（⛔ 不假装"去行必然等价"）。
///
/// # 三个承重指纹（⛔ 必须逐字不变）
///
/// `0xa9dec8a87f69106c`（S37 臂 1）／`0xd3c2a82076bd8947`（S37 臂 2）／
/// `0xa933ddab286bdf5e`（S33／S14 广播路径）；⭐ 应绿反向腿：同一输出 × `1.0000001`
/// ⇒ 指纹**必须**变。
#[test]
fn s69_the_reverse_legs_and_the_three_load_bearing_fingerprints() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 100;
    const FRAMES: usize = 512;
    let sample = constant_sample(4_096);

    // ---- 反向腿 ①：两条都去掉 ⇒ 两个 CC 值逐位相同，且与 `cc = None` 相同 ----
    let bare = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n",
        &sample,
    );
    let render_bare = |value: Option<u8>| -> Vec<f32> {
        let probe = |controller: u8| -> u8 {
            if controller == 1 {
                value.unwrap_or(0)
            } else {
                0
            }
        };
        let cc_arg: Option<&dyn Fn(u8) -> u8> = match value {
            Some(_) => Some(&probe),
            None => None,
        };
        let mut out = vec![0.0f32; FRAMES];
        bare.render_block_into_with_cc(60, VELOCITY, cc_arg, &mut out);
        out
    };
    let (bare_none, bare_a, bare_b) = (
        render_bare(None),
        render_bare(Some(25)),
        render_bare(Some(100)),
    );
    assert_eq!(
        bits(&bare_a),
        bits(&bare_b),
        "⭐ 反向腿 ①：没有 CC 轴交叉淡化 ⇒ 两个 CC 值的输出必须**逐位相同**"
    );
    assert_eq!(
        bits(&bare_none),
        bits(&bare_a),
        "⭐ 反向腿 ①：也必须与 `cc = None` 相同"
    );
    assert!(
        bare_a.iter().all(|s| *s == 1.0),
        "⭐ 反向腿 ①：没有交叉淡化 ⇒ 增益恒 `1.0`（恒 `1.0` 样本 ⇒ 每帧 1.0）"
    );

    // ---- 反向腿 ②：`xfout` 单行 ⇒ 真的淡出；去掉那一行 ⇒ 逐位相同 ----
    let one_line = prepare_with(CC_FADE_OUT_ONE_LINE_FIXTURE, &sample);
    let render_one_line = |value: u8| -> Vec<f32> {
        let probe = |controller: u8| -> u8 { if controller == 1 { value } else { 0 } };
        let mut out = vec![0.0f32; FRAMES];
        one_line.render_block_into_with_cc(60, VELOCITY, Some(&probe), &mut out);
        out
    };
    let (out_low, out_high) = (render_one_line(64), render_one_line(127));
    assert_eq!(out_low[0], 1.0, "⭐ `cc = low = 64` ⇒ 淡出起点 ⇒ 满幅 1.0");
    assert_eq!(
        out_high[0], 0.0,
        "⭐ `cc = high = 127` ⇒ 淡出终点 ⇒ 静音 0.0"
    );
    assert_ne!(
        bits(&out_low),
        bits(&out_high),
        "⭐ 标定：这一行确实在起作用"
    );
    let removed = prepare_with(CC_FADE_OUT_ONE_LINE_REMOVED, &sample);
    let render_removed = |value: u8| -> Vec<f32> {
        let probe = |controller: u8| -> u8 { if controller == 1 { value } else { 0 } };
        let mut out = vec![0.0f32; FRAMES];
        removed.render_block_into_with_cc(60, VELOCITY, Some(&probe), &mut out);
        out
    };
    assert_eq!(
        bits(&render_removed(64)),
        bits(&render_removed(127)),
        "⭐ 反向腿 ②：去掉 `xfout_locc1=64` 那一行 ⇒ 两个 CC 值的输出**逐位相同**"
    );

    // ---- 反向腿 ③：`xfin` 单行 ⇒ 去掉 `xfin_locc1=0` 之后**仍然不同**（如实登记） ----
    let no_locc = prepare_with(CC_FADE_IN_NO_LOCC_FIXTURE, &sample);
    let render_no_locc = |value: u8| -> Vec<f32> {
        let probe = |controller: u8| -> u8 { if controller == 1 { value } else { 0 } };
        let mut out = vec![0.0f32; FRAMES];
        no_locc.render_block_into_with_cc(60, VELOCITY, Some(&probe), &mut out);
        out
    };
    let (only_hicc_a, only_hicc_b) = (render_no_locc(25), render_no_locc(100));
    assert_ne!(
        bits(&only_hicc_a),
        bits(&only_hicc_b),
        "⭐ 反向腿 ③（如实登记）：`xfin_hicc1=100` 单独出现时下界取规范缺省 **0** \
         ⇒ 区间 `[0, 100]` 仍然生效 ⇒ 去掉 `xfin_locc1=0` **不**等于「没有 CC 轴」"
    );
    assert_eq!(
        only_hicc_a[0], 0.5,
        "⭐ 而且与「两条都在」的读数**逐位相同**（`[0, 100]` 就是那条区间）"
    );

    // ---- 三个承重指纹（⛔ 与 S33／S37／S52／S56／S62／S65 逐字同一份） ----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, expected) in [
        (
            "S69 loop_continuous ＋ end_sample = 200",
            &looped,
            200u64,
            0xa9de_c8a8_7f69_106cu64,
        ),
        (
            "S69 no_loop ＋ end_sample = u64::MAX",
            &plain,
            u64::MAX,
            0xd3c2_a820_76bd_8947u64,
        ),
    ] {
        let mut pool = SfzVoicePool::new(HZ);
        assert_eq!(pool.trigger_note(plan, 60, 127, end_sample, 1.0, None), 1);
        let mut out = vec![0.0f32; BLOCK];
        pool.render_into_with_cc(plan, 0, &mut out, None);
        let actual = fnv1a_64(&out);
        println!(
            "[engine-sfz/S69] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）；\
             非零帧数 = {}",
            out.iter().filter(|sample| **sample != 0.0).count()
        );
        let _checked = check_fingerprint(&format!("S69 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut block = vec![0.0f32; BLOCK];
    broadcast.render_block_into_with_cc(60, 127, None, &mut block);
    let legacy = fnv1a_64(&block);
    println!(
        "[engine-sfz/S69] S33／S14 广播路径：指纹 = 0x{legacy:016x}\
         （承重 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）"
    );
    let _checked = check_fingerprint("S69 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    // ⭐ 应绿反向腿：× `1.0000001` ⇒ 指纹必须变（证明上面三条是**逐位**判据）。
    let scaled: Vec<f32> = block.iter().map(|sample| sample * 1.000_000_1).collect();
    assert_ne!(
        fnv1a_64(&scaled),
        legacy,
        "⭐ 反向腿：乘 1.0000001 后指纹必须变"
    );
}

/// ⭐ S70（任务单 `#108`；判据 §6.4）：**Key／Velocity 两轴未被扰动**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 两条**只差 CC 两行**的区域（键轴 ＋ 力度淡入／淡出 ＋ `volume` 全同）的
/// [`PreparedRegion::gain_at`]；单位 ＝ 增益（无量纲）里的位模式，覆盖**全 128×128
/// 网格**（16384 点）。
///
/// ⭐ 判定：**逐点位模式相同** ⇒ "往区域表里加 CC 几何"⛔ 一个字都没动键／力度两轴的读数。
/// ⭐ 另一条腿：同一条带 CC 的区域在 `cc = None` 时与**不带 CC 的那条**输出逐位相同
/// （渲染层面的同一件事）。
#[test]
fn s76_the_key_and_velocity_axes_are_undisturbed_by_the_cc_geometry() {
    const BASE: &str = "sample=a.wav key=60 pitch_keycenter=60 volume=-3 \
                        xfin_lokey=48 xfin_hikey=72 xfout_lokey=48 xfout_hikey=72 \
                        xfin_lovel=40 xfin_hivel=90 xfout_lovel=60 xfout_hivel=110";
    let without_cc = format!("<region> {BASE}\n");
    let with_cc =
        format!("<region> {BASE} xfin_locc1=0 xfin_hicc1=100 xfout_locc2=20 xfout_hicc2=90\n");
    let sample = constant_sample(SAMPLE_FRAMES);
    let plain = prepare_with(&without_cc, &sample);
    let faded = prepare_with(&with_cc, &sample);

    assert_eq!(plain.regions()[0].cc_crossfade_count(), 0);
    assert_eq!(faded.regions()[0].cc_crossfade_count(), 2);

    let mut mismatches = 0usize;
    let mut first: Option<(u8, u8, u32, u32)> = None;
    for n in 0u16..128 {
        for v in 0u16..128 {
            let a = plain.regions()[0].gain_at(n as u8, v as u8);
            let b = faded.regions()[0].gain_at(n as u8, v as u8);
            if a.to_bits() != b.to_bits() {
                mismatches += 1;
                if first.is_none() {
                    first = Some((n as u8, v as u8, a.to_bits(), b.to_bits()));
                }
            }
        }
    }
    // 两轴读数对照（键轴 ⇒ 逐点不同的那几行；力度轴 ⇒ 逐点不同的那几列）。
    let key_reading = [
        plain.regions()[0].gain_at(60, 100),
        plain.regions()[0].gain_at(72, 100),
    ];
    let vel_reading = [
        plain.regions()[0].gain_at(60, 40),
        plain.regions()[0].gain_at(60, 100),
    ];
    assert_ne!(key_reading[0], key_reading[1], "⭐ 键轴必须仍在生效");
    assert_ne!(vel_reading[0], vel_reading[1], "⭐ 力度轴必须仍在生效");
    println!(
        "[engine-sfz/S76] `gain_at` 全 128×128 网格（16384 点）位型不同 = {mismatches}\
         （首个 = {first:?}）；键轴读数 [cc 无关] = {key_reading:?}；力度轴读数 = {vel_reading:?}"
    );
    assert_eq!(
        mismatches, 0,
        "⭐ 加 CC 几何⛔ 不得扰动键／力度两轴的读数（首个不同点 = {first:?}）"
    );

    // ⭐ 渲染层面的同一件事：带 CC 的区域在 `cc = None` 时与不带 CC 的**逐位相同**。
    let render_flat = |plan: &PreparedSfz| -> Vec<f32> {
        let mut out = vec![0.0f32; BLOCK];
        plan.render_block_into_with_cc(60, 100, None, &mut out);
        out
    };
    assert_eq!(
        bits(&render_flat(&plain)),
        bits(&render_flat(&faded)),
        "⭐ `cc = None` ⇒ 带 CC 几何的区域与不带它的区域输出**逐位相同**"
    );
}

/// ⭐ S71（任务单 `#108`；判据 §6.5 ＋ §11 的"登记可判"）：**条数上界的来历 ＋ 修订段 ＋ 尺寸**。
///
/// # 判定量
///
/// * `include_str!("../src/sfz_instrument.rs")` 必须逐字含 `#108` 的追加修订段、
///   新的 CC 轴一节、以及**结构性上界**那句；`#107`／`#104` 的原文登记仍在；
/// * [`CC_CROSSFADE_CAP`] ＝ **256**，且 `size_of::<Crossfade>()` ＝ **6**
///   ⇒ 每区域的代价恰 `256 × 6 = 1536` 字节；
/// * 尺寸读数：`SfzVoice` **40**（＋0）／`SfzVoicePool` **1712**（＋0）／
///   `EngineRuntime` < 192 KiB（＋0）；`PreparedRegion` **由 `size_of` 现读**（⛔ 不手抄）。
#[test]
fn s71_the_cap_provenance_and_the_sizes_are_judgeable() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const REVISION: &str = "⭐ ⭐ **追加修订段（任务单 `#108`）";
    const SECTION: &str = "# ⭐ CC 轴交叉淡化（任务单 `#108`）";
    const STRUCTURAL: &str = "结构性上界";
    const OLD_ROW: &str = "未做（回调侧没有 CC 状态 ⇒ 与离线 `playback_spec` 一致地**跳过**该轴）";
    const PREV_REVISION: &str = "⭐ ⭐ **追加修订段（任务单 `#107`）";
    const CALIBER: &str = "⭐ 双口径登记（任务单 `#104`）";
    const ABSENT: &str = "CC 轴交叉淡化仍然一行都不接线";
    println!(
        "[engine-sfz/S71] 模块头：`#108` 修订段 = {}、新一节 = {}、结构性上界 = {}、\
         ⑦ 原文保留 = {}、`#107` 原文 = {}、`#104` 原文 = {}",
        MODULE_SOURCE.contains(REVISION),
        MODULE_SOURCE.contains(SECTION),
        MODULE_SOURCE.contains(STRUCTURAL),
        MODULE_SOURCE.contains(OLD_ROW),
        MODULE_SOURCE.contains(PREV_REVISION),
        MODULE_SOURCE.contains(CALIBER),
    );
    for (label, needle) in [
        ("`#108` 追加修订段", REVISION),
        ("CC 轴交叉淡化一节", SECTION),
        ("结构性上界（条数上界的来历）", STRUCTURAL),
        ("局限表第 ⑦ 行的**原文**（第 278 条：⛔ 不许删）", OLD_ROW),
        ("`#107` 的修订段", PREV_REVISION),
        ("`#104` 的双口径登记", CALIBER),
    ] {
        assert!(MODULE_SOURCE.contains(needle), "⭐ 必须逐字含：{label}");
    }
    assert!(
        !MODULE_SOURCE.contains(ABSENT),
        "⭐ 反向腿：文档里没有的句子必须 `false`"
    );

    // ⭐ 语料普查的原始读数（分母 ＋ 已知非零对照 ＋ 单区域最大条数）必须登记在源码里。
    for needle in [
        "**1398**",
        "**1205**",
        "**64894**",
        "{0: 62436, 1: 1816, 2: 642}",
        "{0: 62281, 1: 1920, 2: 693}",
        "{1, 85, 121}",
    ] {
        assert!(
            MODULE_SOURCE.contains(needle),
            "⭐ 条数上界的来历必须可判：模块头缺少普查读数 `{needle}`"
        );
    }

    // ⭐ 容量与每区域代价。
    let crossfade_bytes = core::mem::size_of::<Crossfade>();
    let region_bytes = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S71] size_of: Crossfade={crossfade_bytes} PreparedRegion={region_bytes} \
         SfzVoice={voice} SfzVoicePool={pool} EngineRuntime={runtime}\
         （CC_CROSSFADE_CAP={CC_CROSSFADE_CAP} ⇒ ＋{} B／区域；\
         门槛 192 KiB = {}；余量 = {}）",
        CC_CROSSFADE_CAP * crossfade_bytes,
        192 * 1024,
        192 * 1024 - runtime,
    );
    assert_eq!(
        CC_CROSSFADE_CAP, 256,
        "⭐ 结构性上界：128（淡入）× 2 张映射"
    );
    assert_eq!(
        crossfade_bytes, 6,
        "⭐ `Crossfade` ＝ `XfAxis`(2) ＋ `XfDirection`(1) ＋ `XfRange`(2) ＋ `XfCurve`(1)"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（仍是 40 B）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0（仍是 1712 B）");
    assert!(
        runtime < 192 * 1024,
        "⛔ `EngineRuntime` 必须 ＋0（仍是 {runtime} B < 192 KiB）"
    );
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#109`：把 **CC 区域门控**（`loccN` ／ `hiccN`）接进引擎的**三条路**
// ---------------------------------------------------------------------------
//
// ⛔ 本片**不动**解析/归约：门控几何早就在 `Region::cc_gates` 里（`yeban-sfz`）。
// 本片补的是"**按会话运行态的 CC 状态裁决**"那一半：
//
// * **离线** `render_note_into_with_cc`：**本来就在跑**（探针经 `RegionQuery::with_cc`
//   进 `region_matches`）—— 本片只把它**锁住**（判据不得改坏）；
// * **摊平表** `render_block_into_with_cc`：掩码之上再加一步 `cc_gates_ok(probe)`；
// * **实时** `SfzVoicePool::trigger_note`：**触发期**按探针裁决（⛔ 不是逐块）。
//
// 规范逐字与"为什么是触发期"的裁定见 `src/sfz_instrument.rs` 模块头的
// 「⭐ CC 区域门控（`loccN` / `hiccN`，任务单 `#109`）」一节。

/// ⭐ S81／S82／S83 的**带门控**夹具（规范页示例的形态）：
/// `locc1=64 hicc1=127` ⇒ 区域只在 `CC1 ∈ [64, 127]` 时发声。
///
/// ⚠ `amp_veltrack=0`（与 S60／S61／S67／S68 同款）：力度 ≥ 1 时力度增益恰 `1.0`
/// ⇒ 输出的**每一帧逐位等于** `1.0`（恒 `1.0` 样本 ＋ `rate == 1.0`）⇒
/// "发声 / 不发声"与"位模式"都能用手算的读数判。
const CC_GATE_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                               amp_veltrack=0 locc1=64 hicc1=127\n";

/// ⭐ S82 的**反向腿**夹具：同文本**去掉那两行** ⇒ 门控集合为空。
const CC_GATE_REMOVED_FIXTURE: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n";

/// 一个 CC1 探针（其余控制器读 `0`）。
fn cc1_probe(value: u8) -> impl Fn(u8) -> u8 {
    move |controller: u8| -> u8 { if controller == 1 { value } else { 0 } }
}

/// 非零帧数（帧）—— 三条路共用的"发不发声"读数。
fn nonzero_frames(out: &[f32]) -> usize {
    out.iter().filter(|sample| **sample != 0.0).count()
}

/// ⭐ S81（任务单 `#109`；判据 §5.2）：**门控真的活** —— 同一份带
/// `locc1=64 hicc1=127` 的 SFZ，两个 CC 值给出**相反**的发声结论。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_GATE_FIXTURE`] 经**三条路**渲染 512 帧的输出；
/// 单位 ＝ **声部数**（个）＋ **非零帧数**（帧）＋ FNV-1a 指纹（逐位）。
///
/// ⭐ 两个 CC 值：`0`（< `locc1`）⇒ **不发声**；`100`（∈ `[64, 127]`）⇒ **发声**。
/// ⭐ 附**边界读数**：`63` ⇒ 不发声、`64` ⇒ 发声（闭区间两端都含）。
#[test]
fn s81_the_cc_gate_is_live_on_all_three_paths() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 100;
    const FRAMES: usize = 512;
    let instrument = SfzInstrument::load(CC_GATE_FIXTURE.to_owned(), &Default::default())
        .expect("夹具必须解析成功");
    let sample = constant_sample(4_096);
    let plan = prepare_with(CC_GATE_FIXTURE, &sample);

    // ⭐ 摊平表必须真的承载那一条门控，且与解析层**逐字**相同。
    let parsed_gates = instrument
        .with_instrument(|parsed| parsed.regions()[0].cc_gates.clone())
        .expect("闭包式访问");
    assert_eq!(
        plan.regions()[0].cc_gates(),
        parsed_gates.as_slice(),
        "⭐ 摊平表里的门控必须与 `Region::cc_gates` **逐字**相同（⛔ 不是另造一份几何）"
    );
    assert_eq!(
        plan.regions()[0].cc_gates(),
        &[CcGate {
            cc: 1,
            lo: 64,
            hi: 127
        }],
        "⭐ `locc1=64 hicc1=127` ⇒ 恰好一条闭区间门控"
    );

    let render = |value: u8, frames: usize| -> (usize, Vec<f32>, usize) {
        let probe = cc1_probe(value);
        let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);
        let mut pool = SfzVoicePool::new(HZ);
        let voices = pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, cc_arg);
        let mut out = vec![0.0f32; frames];
        pool.render_into_with_cc(&plan, 0, &mut out, cc_arg);
        let nonzero = nonzero_frames(&out);
        (voices, out, nonzero)
    };

    // ---- 两条主臂 ----
    let (voices_closed, closed, nonzero_closed) = render(0, FRAMES);
    let (voices_open, open, nonzero_open) = render(100, FRAMES);
    println!(
        "[engine-sfz/S81] cc = 0：声部数 = {voices_closed}、非零帧数 = {nonzero_closed}、\
         指纹 = 0x{:016x}",
        fnv1a_64(&closed)
    );
    println!(
        "[engine-sfz/S81] cc = 100：声部数 = {voices_open}、非零帧数 = {nonzero_open}、\
         指纹 = 0x{:016x}",
        fnv1a_64(&open)
    );
    assert_eq!(voices_closed, 0, "⭐ cc = 0 < locc1 = 64 ⇒ **不建声部**");
    assert_eq!(nonzero_closed, 0, "⭐ cc = 0 ⇒ 输出恒 0（不发声）");
    assert_eq!(voices_open, 1, "⭐ cc = 100 ∈ [64, 127] ⇒ 恰好 1 个声部");
    assert_eq!(nonzero_open, FRAMES, "⭐ cc = 100 ⇒ 512 帧全非零（发声）");
    assert_ne!(
        fnv1a_64(&closed),
        fnv1a_64(&open),
        "⭐ 有牙：两个 CC 值的输出必须**逐位不同**"
    );

    // ---- 闭区间两端的边界读数 ----
    let (voices_below, _, nonzero_below) = render(63, FRAMES);
    let (voices_at, _, nonzero_at) = render(64, FRAMES);
    assert_eq!(
        (voices_below, nonzero_below),
        (0, 0),
        "⭐ 边界：cc = 63 < locc1 ⇒ 不发声"
    );
    assert_eq!(
        (voices_at, nonzero_at),
        (1, FRAMES),
        "⭐ 边界：cc = 64 ＝ locc1 ⇒ **发声**（下界**含**）"
    );

    // ---- 三条路在四个 CC 值上必须一致（判据 §5.3）----
    for value in [0u8, 63, 64, 100] {
        let probe = cc1_probe(value);
        let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);
        // ① 离线
        let mut offline = vec![0.0f32; FRAMES];
        let written_offline = instrument
            .render_note_into_with_cc(&sample, 60, VELOCITY, cc_arg, &mut offline, HZ)
            .expect("离线渲染");
        // ② 摊平表
        let mut flat = vec![0.0f32; FRAMES];
        let written_flat = plan.render_block_into_with_cc(60, VELOCITY, cc_arg, &mut flat);
        // ③ 实时
        let (voices, realtime, _) = render(value, FRAMES);
        assert_eq!(
            written_offline, written_flat,
            "⭐ cc = {value}：离线与摊平的 `written` 必须同值"
        );
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ cc = {value}：**离线 ＝ 摊平** 必须逐位相同"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ cc = {value}：**摊平 ＝ 实时** 必须逐位相同"
        );
        println!(
            "[engine-sfz/S81] cc = {value}：三条路位模式相同 = {}；声部数 = {voices}；\
             非零帧数 = {}",
            bits(&offline) == bits(&realtime),
            nonzero_frames(&offline)
        );
    }
}

/// ⭐ S82（任务单 `#109`；判据 §5.4 反向腿 ＋ 三个承重指纹）：
/// **去掉 `locc1`／`hicc1` 那两行** ⇒ 两个 CC 值**逐位相同**，且三个既有承重指纹
/// **逐字不变**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_GATE_REMOVED_FIXTURE`]（无门控）在 `cc ∈ {0, 100}` 下的三条路输出；
/// 单位 ＝ 声部数（个）＋ 非零帧数（帧）＋ FNV-1a 指纹（逐位）。
#[test]
fn s82_removing_the_gate_lines_makes_the_two_cc_values_bit_identical() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 100;
    const FRAMES: usize = 512;
    let plan = prepare_with(CC_GATE_REMOVED_FIXTURE, &constant_sample(4_096));
    assert!(
        plan.regions()[0].cc_gates().is_empty(),
        "⭐ 反向腿夹具**一条门控都没有**"
    );

    let render = |value: u8| -> (usize, u64, usize) {
        let probe = cc1_probe(value);
        let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);
        let mut pool = SfzVoicePool::new(HZ);
        let voices = pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, cc_arg);
        let mut out = vec![0.0f32; FRAMES];
        pool.render_into_with_cc(&plan, 0, &mut out, cc_arg);
        (voices, fnv1a_64(&out), nonzero_frames(&out))
    };
    let (voices_0, fingerprint_0, nonzero_0) = render(0);
    let (voices_100, fingerprint_100, nonzero_100) = render(100);
    println!(
        "[engine-sfz/S82] 无门控：cc = 0 ⇒ 声部 {voices_0}／非零 {nonzero_0}／\
         指纹 0x{fingerprint_0:016x}；cc = 100 ⇒ 声部 {voices_100}／非零 {nonzero_100}／\
         指纹 0x{fingerprint_100:016x}"
    );
    assert_eq!(
        (voices_0, nonzero_0),
        (1, FRAMES),
        "⭐ 无门控 ⇒ 两个 CC 值都发声（对照读数必须非空）"
    );
    assert_eq!(
        fingerprint_0, fingerprint_100,
        "⭐ 反向腿：去掉那两行 ⇒ 两个 CC 值**逐位相同**（输出指纹相等）"
    );

    // ⭐ 三个承重指纹：无门控的既有夹具 ⇒ ⛔ 必须不变（复跑 S37／S33 的两条臂）。
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, fixture, end_sample, expected) in [
        ("S82 → S37 臂 1", &looped, 200u64, 0xa9de_c8a8_7f69_106cu64),
        ("S82 → S37 臂 2", &plain, u64::MAX, 0xd3c2_a820_76bd_8947u64),
    ] {
        let out = render_pool(fixture, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!(
            "[engine-sfz/S82] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）；\
             非零帧数 = {}",
            nonzero_frames(&out)
        );
        let _checked = check_fingerprint(&format!("S82 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy = vec![0.0f32; BLOCK];
    broadcast.render_block_into_with_cc(60, 127, None, &mut legacy);
    println!(
        "[engine-sfz/S82] S82 → S33／S14 广播路径：指纹 = 0x{:016x}（承重 = 0x{:016x}）",
        fnv1a_64(&legacy),
        NO_LOOP_FIXTURE_FINGERPRINT
    );
    let _checked = check_fingerprint(
        "S82 S33/S14 广播路径",
        fnv1a_64(&legacy),
        NO_LOOP_FIXTURE_FINGERPRINT,
    );
}

/// ⭐ S83（任务单 `#109`；判据 §2 的"语义裁决"）：**判定时机 ＝ 触发期**
/// —— 声部一旦建立，**中途**把 CC 挪出区间**不会**截断它。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_GATE_FIXTURE`] 先以 `cc = 100` 触发、再以**逐步变化**的 CC 分两块
/// 渲染（`cc = 100` 一块 ＋ `cc = 0` 一块）；单位 ＝ 非零帧数（帧）。
///
/// ⭐ 如果门控是**逐块**判定，第二块（`cc = 0`）会**静音**；触发期判定 ⇒ 第二块
/// **照旧发声**（规范逐字是 "hard switch"／"required for the region to play"，
/// 见模块头那一节）。
#[test]
fn s83_the_gate_is_decided_at_trigger_time_not_per_block() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 100;
    const FRAMES: usize = 512;
    let plan = prepare_with(CC_GATE_FIXTURE, &constant_sample(4_096));

    let open = cc1_probe(100);
    let closed = cc1_probe(0);
    let open_arg: Option<&dyn Fn(u8) -> u8> = Some(&open);
    let closed_arg: Option<&dyn Fn(u8) -> u8> = Some(&closed);

    let mut pool = SfzVoicePool::new(HZ);
    assert_eq!(
        pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, open_arg),
        1,
        "⭐ 触发期：cc = 100 ⇒ 建 1 个声部"
    );
    let mut first = vec![0.0f32; FRAMES];
    pool.render_into_with_cc(&plan, 0, &mut first, open_arg);
    let mut second = vec![0.0f32; FRAMES];
    pool.render_into_with_cc(&plan, FRAMES as u64, &mut second, closed_arg);
    println!(
        "[engine-sfz/S83] 第一块（cc = 100）非零帧数 = {}；第二块（cc = 0）非零帧数 = {}",
        nonzero_frames(&first),
        nonzero_frames(&second)
    );
    assert_eq!(
        nonzero_frames(&second),
        FRAMES,
        "⭐ 触发期判定：声部已建 ⇒ 中途把 CC 挪出区间**不截断**它（⛔ 不是逐块判定）"
    );

    // ⭐ 反空判腿：**触发时** CC 已经在区间外 ⇒ 一个声部都不建（与上一条同源）。
    let mut closed_pool = SfzVoicePool::new(HZ);
    assert_eq!(
        closed_pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, closed_arg),
        0,
        "⭐ 触发期：cc = 0 ⇒ 0 个声部（同上一条判定时机）"
    );
}

/// ⭐ S84（任务单 `#109`；判据 §5.5）：**既有掩码行为未扰动** ——
/// keyswitch ／ `trigger` ／ 力度／键轴那几张掩码的读数一个字节没变，
/// 且"有 CC 门控"的区域**进得了**掩码（非空对照）。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 四条夹具的摊平表 `key_mask` / `vel_mask`（各 128 位）；
/// 单位 ＝ 位模式 `[u64; 2]`（逐位）。
#[test]
fn s84_the_existing_masks_are_undisturbed_and_a_gated_region_enters_them() {
    // ① keyswitch 门控：`sw_last=36` ＋ `sw_default=36` ⇒ 缺省成立（既有口径）。
    let keyswitch_default = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 sw_last=36 sw_default=36\n",
        &constant_sample(SAMPLE_FRAMES),
    );
    let mask = keyswitch_default.regions()[0].key_mask();
    let bit = |mask: [u64; 2], note: u8| mask[usize::from(note) / 64] & (1u64 << (note % 64)) != 0;
    assert!(bit(mask, 60), "⭐ `sw_default` 满足 `sw_last` ⇒ 掩码含 60");
    assert!(!bit(mask, 61), "⭐ 键域之外不含 61");
    assert_eq!(
        plan_match_count(&keyswitch_default, 60),
        1,
        "⭐ 非空对照：键 60 上恰 1 条区域过掩码"
    );

    // ② keyswitch 门控**没有** `sw_default` ⇒ 严格策略：掩码清 0（既有行为）。
    let keyswitch_strict = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 sw_last=36\n",
        &constant_sample(SAMPLE_FRAMES),
    );
    assert_eq!(
        keyswitch_strict.regions()[0].key_mask(),
        [0, 0],
        "⭐ 没有 `sw_default` 的 `sw_last` ⇒ 掩码清 0（既有行为，⛔ 未被本单改动）"
    );
    assert_eq!(plan_match_count(&keyswitch_strict, 60), 0);

    // ③ `trigger=release` ⇒ 不进 note-on 掩码（既有行为）。
    let release = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 trigger=release\n",
        &constant_sample(SAMPLE_FRAMES),
    );
    assert_eq!(
        release.regions()[0].key_mask(),
        [0, 0],
        "⭐ `trigger=release` ⇒ note-on 掩码清 0（既有行为）"
    );

    // ④ ⭐ 有 CC 门控的区域**如今进得了**掩码（本单的机械差异；门控仍不通过 ⇒ 不发声）。
    let gated = prepare_with(CC_GATE_FIXTURE, &constant_sample(SAMPLE_FRAMES));
    assert_eq!(
        plan_match_count(&gated, 60),
        1,
        "⭐ 有 `locc1=64` 的区域在掩码里**在**（#109 之前它被清 0 ⇒ 永远不发声）"
    );
    // ⚠ 但探针为 `None`（会话表一条 CC 都没收到过）⇒ 门控**不成立** ⇒ 仍不发声。
    let mut pool = SfzVoicePool::new(48_000.0);
    assert_eq!(
        pool.trigger_note(&gated, 60, 100, u64::MAX, 1.0, None),
        0,
        "⭐ `cc = None` ⇒ 有门控的区域仍然不建声部（`yeban-sfz` 的严格策略，三条路一致）"
    );
    // ⭐ 有牙的对照：同一个池、同一个区域，`cc = 100` ⇒ 建 1 个声部。
    let probe = cc1_probe(100);
    let mut open_pool = SfzVoicePool::new(48_000.0);
    assert_eq!(
        open_pool.trigger_note(&gated, 60, 100, u64::MAX, 1.0, Some(&probe)),
        1,
        "⭐ 非空对照：`cc = 100` ⇒ 同一条区域建 1 个声部"
    );
}

/// 摊平表里"键 60 上过掩码的区域条数"（判据用的只读读数）。
fn plan_match_count(plan: &PreparedSfz, note: u8) -> usize {
    plan.regions()
        .iter()
        .filter(|region| region.accepts(note, 100))
        .count()
}

/// ⭐ S85（任务单 `#109`；判据 §5.6）：**条数上界 ＋ 尺寸**。
///
/// # 判定量
///
/// * [`CC_GATE_CAP`] ＝ **128**（结构性上界：`yeban-sfz` 的 `BTreeMap<u8, _>` 键域
///   ＝ `0..=127`）；`size_of::<CcGate>()` ＝ **3**；
/// * `PreparedRegion` **由 `size_of` 现读**（⛔ 不手抄）；
/// * ⛔ `SfzVoice` **40**、⛔ `SfzVoicePool` **1712**、⛔ `EngineRuntime` < 192 KiB；
/// * 模块头必须逐字含 `#109` 的追加修订段、新一节、结构性上界与语料普查读数。
#[test]
fn s85_the_gate_cap_provenance_and_the_sizes_are_judgeable() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const REVISION: &str = "⭐ ⭐ **追加修订段（任务单 `#109`）";
    const SECTION: &str = "# ⭐ CC 区域门控（`loccN` / `hiccN`，任务单 `#109`）";
    const STRUCTURAL: &str = "结构性上界";
    const PREV_REVISION_108: &str = "⭐ ⭐ **追加修订段（任务单 `#108`）";
    const PREV_REVISION_107: &str = "⭐ ⭐ **追加修订段（任务单 `#107`）";
    const ORIGINAL_CALIBER: &str = "⭐ 双口径登记（任务单 `#104`）";
    const ORIGINAL_GATE: &str = "⭐ 摊平期门控登记（任务单 `#104`）";
    const GATE_CHOICE_107: &str = "摊平期门控登记维持不变（显式选路 ③）";
    const ABSENT: &str = "CC 区域门控仍然一行都不接线";
    println!(
        "[engine-sfz/S85] 模块头：`#109` 修订段 = {}、新一节 = {}、结构性上界 = {}、\
         `#108` 原文 = {}、`#107` 原文 = {}、`#104` 原文两条 = {} / {}、选路 ③ 原文 = {}",
        MODULE_SOURCE.contains(REVISION),
        MODULE_SOURCE.contains(SECTION),
        MODULE_SOURCE.contains(STRUCTURAL),
        MODULE_SOURCE.contains(PREV_REVISION_108),
        MODULE_SOURCE.contains(PREV_REVISION_107),
        MODULE_SOURCE.contains(ORIGINAL_CALIBER),
        MODULE_SOURCE.contains(ORIGINAL_GATE),
        MODULE_SOURCE.contains(GATE_CHOICE_107),
    );
    for (label, needle) in [
        ("`#109` 追加修订段", REVISION),
        ("CC 区域门控一节", SECTION),
        ("结构性上界（条数上界的来历）", STRUCTURAL),
        ("`#108` 的修订段（第 278 条：⛔ 不许删）", PREV_REVISION_108),
        ("`#107` 的修订段（⛔ 不许删）", PREV_REVISION_107),
        ("`#104` 的双口径登记", ORIGINAL_CALIBER),
        ("`#104` 的摊平期门控登记", ORIGINAL_GATE),
        ("`#107` 的显式选路 ③ 原文", GATE_CHOICE_107),
    ] {
        assert!(MODULE_SOURCE.contains(needle), "⭐ 必须逐字含：{label}");
    }
    assert!(
        !MODULE_SOURCE.contains(ABSENT),
        "⭐ 反向腿：文档里没有的句子必须 `false`"
    );

    // ⭐ 语料普查的原始读数（分母 ＋ 已知非零对照 ＋ 单区域最大条数）必须登记在源码里。
    for needle in [
        "**1398**",
        "**1205**",
        "**64894**",
        "{0: 43831, 1: 16872, 2: 797, 3: 3394}",
        "{0: 62281, 1: 1920, 2: 693}",
    ] {
        assert!(
            MODULE_SOURCE.contains(needle),
            "⭐ 条数上界的来历必须可判：模块头缺少普查读数 `{needle}`"
        );
    }

    let gate_bytes = core::mem::size_of::<CcGate>();
    let region_bytes = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S85] size_of: CcGate={gate_bytes} PreparedRegion={region_bytes} \
         SfzVoice={voice} SfzVoicePool={pool} EngineRuntime={runtime}\
         （CC_GATE_CAP={CC_GATE_CAP} ⇒ ＋{} B／区域；门槛 192 KiB = {}；余量 = {}）",
        CC_GATE_CAP * gate_bytes,
        192 * 1024,
        192 * 1024 - runtime,
    );
    assert_eq!(
        CC_GATE_CAP, 128,
        "⭐ 结构性上界：`BTreeMap<u8, _>` 的键域 ＝ `0..=127`"
    );
    assert_eq!(
        gate_bytes, 3,
        "⭐ `CcGate` ＝ `cc`(1) ＋ `lo`(1) ＋ `hi`(1)"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（仍是 40 B）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0（仍是 1712 B）");
    assert!(
        runtime < 192 * 1024,
        "⛔ `EngineRuntime` 必须 ＋0（仍是 {runtime} B < 192 KiB）"
    );
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#110`：把 `<control> set_ccN=` 的**加载时初值**播种进会话 CC 表
// ---------------------------------------------------------------------------
//
// 规范逐字（<https://sfzformat.com/opcodes/set_ccN/>）：
//
// > Sets a default initial value for MIDI CC number N, when the instrument is
// > initially loaded. Used under the ‹`control`› header.
//
// 播种点 ＝ **快照边界**（`rt.rs::render_block` 的 `2a-cc` 段）：按摊平表自带的
// `CcSeedTable`（`PreparedSfz::cc_seeds`）调 `ControlChangeState::seed`，
// 规则 ＝ **只填从未收到过的槽** ⇒ 真 MIDI CC 永远赢、`set_ccN` 为空表时**一次都不写**。
//
// ⚠ 三条路（离线 `render_note_into_with_cc` ／ 摊平 `render_block_into_with_cc` ／
// 实时 `SfzVoicePool`）都**只**认调用方给的探针；本单让那个探针的**初值来源**变成
// 文件声明的 `set_ccN`（S88 用"从会话表读回来的探针"把三条路钉在一起）。

/// ⭐ S86／S87／S88／S89／S90 的夹具基（**没有** `<control>` 行）：
/// `locc1=64 hicc1=127` 门控 ＋ `amp_veltrack=0`。
///
/// ⚠ `amp_veltrack=0` ⇒ 力度 ≥ 1 时乐器层增益恰 `1.0`；样本是恒 `1.0` 的常数
/// ⇒ "发声 / 不发声"与位模式都能手算（与 S81 同款夹具形态）。
const CC_SEED_GATE_PLAIN: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                  amp_veltrack=0 locc1=64 hicc1=127\n";

/// ⭐ 与 [`CC_SEED_GATE_PLAIN`] **只差一行** `<control>set_cc1=64` 的夹具。
const CC_SEED_GATE_SEEDED: &str = "<control>set_cc1=64\n\
                                   <region> sample=a.wav key=60 pitch_keycenter=60 \
                                   amp_veltrack=0 locc1=64 hicc1=127\n";

/// ⭐ S86 的**规范公式**臂（S63／S64 同款题材）：`ampeg_attack=0.005` ＋
/// `ampeg_attackcc100=0.004`，摊平表里的初值 ＝ `<control>set_cc100=64`
/// ⇒ 期望起音帧数 ＝ `round((0.005 + 0.004 × 64/127) × 48 000)` ＝ **337**
/// （`0.005 + 0.002015748 = 0.007015748`；`× 48 000 = 336.7559`）。
const CC_SEED_ATTACK_PLAIN: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                    amp_veltrack=0 ampeg_attack=0.005 ampeg_attackcc100=0.004\n";
const CC_SEED_ATTACK_SEEDED: &str = "<control>set_cc100=64\n\
                                     <region> sample=a.wav key=60 pitch_keycenter=60 \
                                     amp_veltrack=0 ampeg_attack=0.005 ampeg_attackcc100=0.004\n";

/// ⭐ S87 的"**没有** `set_ccN`"端到端夹具（可闻 ⇒ 指纹非平凡、⛔ 不是静音指纹）。
const CC_SEED_ABSENT: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n";

/// ⭐ **改动前实测**（`#110` 之前、`git status --porcelain` 为空时的一次性探针，测后删除）：
/// [`CC_SEED_ABSENT`] 经**产品路径**（`EngineRuntime`，16 量子 ＝ 2048 帧）渲染的
/// FNV-1a 指纹 ＝ `0xec4ca6ac0fe2b1e9`（非零样本 **4030**、峰值 `0.70710677`）。
///
/// ⚠ 与 S37／S33 的三条承重指纹同一条纪律：它是**本机实现读数**（`aarch64/macos`），
/// ⛔ 不是规范常数 ⇒ 同平台硬红、异平台如实跳过（[`check_fingerprint`]）。
const CC_SEED_ABSENT_RUNTIME_FINGERPRINT: u64 = 0xec4c_a6ac_0fe2_b1e9;

/// ⭐ **改动前实测**：同一装置下**带 `<control>set_cc1=64`** 的夹具（[`CC_SEED_GATE_SEEDED`]）
/// 指纹 ＝ `0x9c1bda7f8c872325`（**与不带那一行的 [`CC_SEED_GATE_PLAIN`] 逐位相同**、
/// 非零样本 **0**）—— ⭐ 那正是本单要闭合的缺口：加载时初值当时被静默忽略。
const CC_SEED_IGNORED_RUNTIME_FINGERPRINT: u64 = 0x9c1b_da7f_8c87_2325;

/// ⭐ `#110` 的端到端装置：**产品路径**（`EngineRuntime::process_quantum`）＋ 可在量子
/// 之间注入 `EngineEvent`（S89 要"先播种、再喂真 CC"）＋ 可重新发布快照（幂等腿）。
///
/// ⚠ 与 `support::render_snapshot` **同一份形态**（`SnapshotSlot` ＋ `retire_channel` ＋
/// `event_channel` ＋ `meter_channel` ⇒ `EngineRuntime::new`）；唯一的区别是本装置
/// **留着**事件发送端（那边把它丢掉）。
struct CcSeedRig {
    slot: std::sync::Arc<yeban_engine::snapshot::SnapshotSlot>,
    sender: yeban_engine::ring::EventSender,
    runtime: yeban_engine::rt::EngineRuntime,
    _collector: yeban_engine::meter::MeterCollector,
    _queue: yeban_engine::snapshot::RetireQueue,
    project: YebanProjectV1,
    track: EntityId,
    plan: SfzPlan,
    revision: u64,
    out: Vec<f32>,
    left: Vec<f32>,
    right: Vec<f32>,
}

impl CcSeedRig {
    fn new(fixture: &support::Fixture, plan: SfzPlan) -> Self {
        let track = fixture.track;
        let snapshot = EngineSnapshot::from_project(&fixture.project, 1)
            .expect("夹具工程必须能编译成快照")
            .with_sfz(track, plan.clone());
        let slot = yeban_engine::snapshot::SnapshotSlot::new(snapshot);
        let (retire, queue) = yeban_engine::snapshot::retire_channel(64);
        let (sender, receiver) = yeban_engine::ring::event_channel(64);
        let (publisher, collector) = yeban_engine::meter::meter_channel(4096);
        let runtime = yeban_engine::rt::EngineRuntime::new(&slot, retire, receiver, publisher);
        Self {
            slot,
            sender,
            runtime,
            _collector: collector,
            _queue: queue,
            project: fixture.project.clone(),
            track,
            plan,
            revision: 1,
            out: vec![0.0; 2 * 128],
            left: Vec::new(),
            right: Vec::new(),
        }
    }

    /// 走 `quanta` 个量子（每个量子 128 帧 × 2 声道），输出追加进两声道。
    fn run(&mut self, quanta: usize) {
        for _ in 0..quanta {
            self.out.fill(0.0);
            self.runtime.process_quantum(&mut self.out, 2);
            for frame in 0..128 {
                self.left.push(self.out[frame * 2]);
                self.right.push(self.out[frame * 2 + 1]);
            }
        }
    }

    /// 发布事件（SPSC 生产端 ＝ `#107` 的事件面）。
    fn publish(&mut self, events: &[yeban_engine::ring::EngineEvent]) -> usize {
        self.sender.publish(events)
    }

    /// 换一份**等价的新快照**（同一条轨、同一份摊平表，只改修订号）⇒ 触发重新武装。
    fn rearm(&mut self) {
        self.revision += 1;
        let snapshot = EngineSnapshot::from_project(&self.project, self.revision)
            .expect("等价快照")
            .with_sfz(self.track, self.plan.clone());
        self.slot.publish(snapshot);
    }

    /// FNV-1a 64（与 `support::Render::fingerprint` **同一份口径**：左声道后右声道）。
    fn fingerprint(&self) -> u64 {
        let mut hash = 0xcbf2_9ce4_8422_2325u64;
        for sample in self.left.iter().chain(self.right.iter()) {
            for byte in sample.to_bits().to_le_bytes() {
                hash ^= u64::from(byte);
                hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
            }
        }
        hash
    }

    /// 两声道里的非零样本数。
    fn nonzero(&self) -> usize {
        self.left
            .iter()
            .chain(self.right.iter())
            .filter(|sample| **sample != 0.0)
            .count()
    }

    /// ⭐ 把会话 CC 表读成一个 `Fn(u8) -> u8`（与 `ControlChangeState::value` **同口径**：
    /// 未收到过 ⇒ `0`）—— 这就是 S88 三条路共用的那个探针。
    fn probe_value(&self, controller: u8) -> u8 {
        self.runtime.control_change(controller).unwrap_or(0)
    }
}

/// ⭐ S86（任务单 `#110`；§5.2）：**播种真的生效** —— 同一份区域，只差一行
/// `<control>set_cc1=64`：会话表从"一条 CC 都没有"变成 `Some(64)`，且区域真的发声；
/// 规范公式臂上实时起音帧数**等于** `round((0.005 + 0.004 × 64/127) × 48 000)`。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_SEED_GATE_SEEDED`] ／ [`CC_SEED_GATE_PLAIN`] ／ [`CC_SEED_ATTACK_SEEDED`]
/// 经**产品路径**（`EngineRuntime`，16 量子）与**实时声部池**（512 帧）的输出；
/// 单位 ＝ `armed`（布尔）＋ `control_change(N)`（`Option<u8>`）＋ 收到过的控制器个数（个）
/// ＋ 非零样本数（个）＋ 起音段帧数（帧）＋ FNV-1a 指纹（逐位）。
#[test]
fn s86_the_seeded_initial_value_reaches_the_session_state_and_the_probe() {
    const HZ: f32 = 48_000.0;
    const QUANTA: usize = 16;
    let fixture = note_project(&[NoteSpec::at(0, 480, 60, 100)]);
    let sample = constant_sample(4_096);

    // ---- ① 门控臂：同一份区域，只差一行 `<control>set_cc1=64` ----
    let plain_plan = prepare_with(CC_SEED_GATE_PLAIN, &sample);
    let seeded_plan = prepare_with(CC_SEED_GATE_SEEDED, &sample);
    assert!(
        plain_plan.cc_seeds().is_empty(),
        "无 `<control>` ⇒ 空表（保命不变量的机械开关）"
    );
    assert_eq!(
        seeded_plan.cc_seeds().len(),
        1,
        "`set_cc1=64` ⇒ 恰好一条初值"
    );
    assert_eq!(seeded_plan.cc_seeds().value(1), Some(64));
    assert_eq!(seeded_plan.cc_seeds().out_of_domain(), 0);

    let mut plain = CcSeedRig::new(&fixture, SfzPlan::from_prepared(plain_plan));
    plain.run(QUANTA);
    let mut seeded = CcSeedRig::new(&fixture, SfzPlan::from_prepared(seeded_plan));
    seeded.run(QUANTA);
    println!(
        "[engine-sfz/S86] 门控臂：plain ⇒ armed={} control_change(1)={:?} \
         received_count={} 非零={} 指纹=0x{:016x}",
        plain.runtime.control_change_armed(),
        plain.runtime.control_change(1),
        plain.runtime.control_change_received_count(),
        plain.nonzero(),
        plain.fingerprint()
    );
    println!(
        "[engine-sfz/S86] 门控臂：seeded ⇒ armed={} control_change(1)={:?} \
         received_count={} 非零={} 指纹=0x{:016x}",
        seeded.runtime.control_change_armed(),
        seeded.runtime.control_change(1),
        seeded.runtime.control_change_received_count(),
        seeded.nonzero(),
        seeded.fingerprint()
    );
    assert!(
        !plain.runtime.control_change_armed(),
        "无 `set_ccN` ⇒ 播种一次都不写 ⇒ 表**不** armed"
    );
    assert_eq!(plain.runtime.control_change(1), None, "没播种 ⇒ 读 `None`");
    assert_eq!(
        plain.nonzero(),
        0,
        "探针 `None` ⇒ `locc1=64` 不成立 ⇒ 不发声"
    );
    assert!(seeded.runtime.control_change_armed(), "播种把表 armed");
    assert_eq!(
        seeded.runtime.control_change(1),
        Some(64),
        "初值 64 真的进表"
    );
    assert_eq!(seeded.runtime.control_change_received_count(), 1);
    assert_eq!(
        seeded.nonzero(),
        4030,
        "初值让 `locc1=64` 成立 ⇒ 端到端可闻；4030 ＝ 与 S87 的无门控夹具**同值**\
         （4096 帧 − 66 帧链路固定静音前缀；两臂同值 ⇒ 那个差值与本单无关）"
    );
    let _checked = check_fingerprint(
        "S86 gate-plain（改动前实测）",
        plain.fingerprint(),
        CC_SEED_IGNORED_RUNTIME_FINGERPRINT,
    );
    let _checked = check_fingerprint(
        "S86 gate-seeded（门控成立 ⇒ 与无门控夹具逐位相同）",
        seeded.fingerprint(),
        CC_SEED_ABSENT_RUNTIME_FINGERPRINT,
    );
    assert_ne!(
        plain.fingerprint(),
        seeded.fingerprint(),
        "⭐ 有牙：那一行真的改变端到端输出"
    );

    // ---- ② 规范公式臂：`set_cc100=64` ⇒ 实时起音帧数 ＝ 公式 ----
    let attack_plan = prepare_with(CC_SEED_ATTACK_SEEDED, &sample);
    let attack_plain = prepare_with(CC_SEED_ATTACK_PLAIN, &sample);
    assert!(attack_plain.cc_seeds().is_empty());
    assert_eq!(attack_plan.cc_seeds().value(100), Some(64));
    let expected = |cc: u8| -> usize {
        let seconds = 0.005f32 + 0.004f32 * (f32::from(cc) / 127.0);
        (f64::from(seconds) * f64::from(HZ)).round() as usize
    };
    // 会话表那条腿：同一份摊平表经产品路径 ⇒ `control_change(100) == Some(64)`。
    let mut attack_rig = CcSeedRig::new(&fixture, SfzPlan::from_prepared(attack_plan.clone()));
    attack_rig.run(1);
    assert_eq!(
        attack_rig.runtime.control_change(100),
        Some(64),
        "`set_cc100=64` 真的进会话表"
    );
    // 探针 ＝ **播种表本身**（与①里会话表的值同源）。
    let seed_probe = |controller: u8| attack_plan.cc_seeds().value(controller).unwrap_or(0);
    let seed_arg: Option<&dyn Fn(u8) -> u8> = Some(&seed_probe);
    let mut pool = SfzVoicePool::new(HZ);
    assert_eq!(
        pool.trigger_note(&attack_plan, 60, 127, u64::MAX, 1.0, seed_arg),
        1
    );
    let mut out = vec![0.0f32; 512];
    pool.render_into_with_cc(&attack_plan, 0, &mut out, seed_arg);
    let seeded_attack = measured_attack_frames(&out);
    // 反向对照：同一份区域**没有** `<control>` ⇒ `cc = None` ⇒ 基准 240 帧。
    let mut base_pool = SfzVoicePool::new(HZ);
    assert_eq!(
        base_pool.trigger_note(&attack_plain, 60, 127, u64::MAX, 1.0, None),
        1
    );
    let mut base_out = vec![0.0f32; 512];
    base_pool.render_into_with_cc(&attack_plain, 0, &mut base_out, None);
    let base_attack = measured_attack_frames(&base_out);
    println!(
        "[engine-sfz/S86] 公式臂：播种 cc=64 ⇒ 起音 {seeded_attack} 帧；\
         无 `set_ccN` ⇒ 基准 {base_attack} 帧；公式(64) = {}、公式(0) = {}",
        expected(64),
        expected(0)
    );
    assert_eq!(
        expected(64),
        337,
        "公式自身可复算：round((0.005 + 0.004 × 64/127) × 48000) = round(336.7559)"
    );
    assert_eq!(
        seeded_attack,
        expected(64),
        "⭐ 播种的初值 64 ⇒ 起音帧数**等于规范公式**"
    );
    assert_eq!(base_attack, 240, "无 `set_ccN` ⇒ `cc = None` ⇒ 基准 240 帧");
    assert_ne!(seeded_attack, base_attack, "⭐ 有牙：两个读数必须不同");
}

/// ⭐ S87（任务单 `#110`；§5.3 保命不变量）：**没有 `set_ccN` 的夹具 ⇒ 播种机制一个
/// 字节都不动** —— 会话表不 armed、收到过的控制器 0 个、端到端指纹等于**改动前实测**，
/// 且三个**承重指纹**逐字不变。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_SEED_ABSENT`] 经产品路径（`EngineRuntime`，16 量子）的输出
/// ＋ 三个既有夹具（S37 两臂、S33／S14 广播路径）；
/// 单位 ＝ `armed`（布尔）＋ 收到过的控制器个数（个）＋ 非零样本数（个）
/// ＋ FNV-1a 指纹（逐位）。
#[test]
fn s87_without_set_cc_the_seeding_moves_no_byte() {
    let fixture = note_project(&[NoteSpec::at(0, 480, 60, 100)]);
    let plan = prepare_with(CC_SEED_ABSENT, &constant_sample(4_096));
    assert!(plan.cc_seeds().is_empty(), "没有 `<control>` ⇒ 空表");
    assert_eq!(plan.cc_seeds().len(), 0);
    assert_eq!(plan.cc_seeds().out_of_domain(), 0);
    let mut rig = CcSeedRig::new(&fixture, SfzPlan::from_prepared(plan));
    rig.run(16);
    let actual = rig.fingerprint();
    println!(
        "[engine-sfz/S87] 无 set_ccN：armed={} received_count={} control_change(1)={:?} \
         非零={} 指纹=0x{actual:016x}（改动前 0x{CC_SEED_ABSENT_RUNTIME_FINGERPRINT:016x}）",
        rig.runtime.control_change_armed(),
        rig.runtime.control_change_received_count(),
        rig.runtime.control_change(1),
        rig.nonzero(),
    );
    assert!(
        !rig.runtime.control_change_armed(),
        "⭐ 保命不变量：空表 ⇒ 一次 `seed` 都不调 ⇒ 表**不** armed"
    );
    assert_eq!(
        rig.runtime.control_change_received_count(),
        0,
        "⭐ 收到过的控制器个数必须仍是 0"
    );
    assert_eq!(rig.runtime.control_change(1), None);
    assert!(rig.nonzero() > 0, "夹具必须**可闻**（⛔ 不是静音指纹）");
    let _checked = check_fingerprint(
        "S87 无 set_ccN 的端到端指纹",
        actual,
        CC_SEED_ABSENT_RUNTIME_FINGERPRINT,
    );

    // ⭐ 三个承重指纹：无 `set_ccN` 的既有夹具 ⇒ ⛔ 必须不变（复跑 S37／S33 的两条臂）。
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, fixture, end_sample, expected) in [
        ("S87 → S37 臂 1", &looped, 200u64, 0xa9de_c8a8_7f69_106cu64),
        ("S87 → S37 臂 2", &plain, u64::MAX, 0xd3c2_a820_76bd_8947u64),
    ] {
        let out = render_pool(fixture, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!(
            "[engine-sfz/S87] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）；\
             非零帧数 = {}",
            nonzero_frames(&out)
        );
        let _checked = check_fingerprint(&format!("S87 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy = vec![0.0f32; BLOCK];
    broadcast.render_block_into_with_cc(60, 127, None, &mut legacy);
    println!(
        "[engine-sfz/S87] S87 → S33／S14 广播路径：指纹 = 0x{:016x}（承重 = 0x{:016x}）",
        fnv1a_64(&legacy),
        NO_LOOP_FIXTURE_FINGERPRINT
    );
    let _checked = check_fingerprint(
        "S87 S33/S14 广播路径",
        fnv1a_64(&legacy),
        NO_LOOP_FIXTURE_FINGERPRINT,
    );
}

/// ⭐ S88（任务单 `#110`；§5.4 三条路一致）：探针**从被播种的会话表读回来** ⇒
/// **离线 ＝ 摊平 ＝ 实时** 位模式逐位相同，且三条路都真的发声。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_SEED_GATE_SEEDED`] 经三条路渲染 512 帧的输出；
/// 单位 ＝ 声部数（个）＋ 非零帧数（帧）＋ 写入帧数（帧）＋ 位模式序列（逐帧 `u32`）。
#[test]
fn s88_the_three_paths_agree_with_the_probe_read_back_from_the_seeded_session_table() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 100;
    const FRAMES: usize = 512;
    let fixture = note_project(&[NoteSpec::at(0, 480, 60, 100)]);
    let sample = constant_sample(4_096);
    let instrument = SfzInstrument::load(CC_SEED_GATE_SEEDED.to_owned(), &Default::default())
        .expect("夹具必须解析成功");
    let plan = prepare_with(CC_SEED_GATE_SEEDED, &sample);

    let mut rig = CcSeedRig::new(&fixture, SfzPlan::from_prepared(plan.clone()));
    rig.run(1);
    assert_eq!(
        rig.runtime.control_change(1),
        Some(64),
        "⭐ 探针的来源：会话表真的拿到了 `set_cc1=64` 的初值"
    );

    // ⭐ 探针 ＝ **从会话表读回来的那个函数**（与 `ControlChangeState::value` 同口径）。
    let probe = |controller: u8| rig.probe_value(controller);
    let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);

    // ① 离线
    let mut offline = vec![0.0f32; FRAMES];
    let written_offline = instrument
        .render_note_into_with_cc(&sample, 60, VELOCITY, cc_arg, &mut offline, HZ)
        .expect("离线渲染");
    // ② 摊平
    let mut flat = vec![0.0f32; FRAMES];
    let written_flat = plan.render_block_into_with_cc(60, VELOCITY, cc_arg, &mut flat);
    // ③ 实时（声部池）
    let mut pool = SfzVoicePool::new(HZ);
    let voices = pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, cc_arg);
    let mut realtime = vec![0.0f32; FRAMES];
    pool.render_into_with_cc(&plan, 0, &mut realtime, cc_arg);

    println!(
        "[engine-sfz/S88] 探针 = 会话表（cc1 = {:?}）：声部数 = {voices}、\
         离线写入 = {written_offline}、摊平写入 = {written_flat}、非零帧数 = {}、\
         三条路位模式相同 = {}",
        rig.runtime.control_change(1),
        nonzero_frames(&offline),
        bits(&offline) == bits(&flat) && bits(&flat) == bits(&realtime)
    );
    assert_eq!(voices, 1, "初值让门控成立 ⇒ 建 1 个声部");
    assert_eq!(nonzero_frames(&offline), FRAMES, "三条路都**真的发声**");
    assert_eq!(written_offline, written_flat, "离线与摊平的写入帧数同值");
    assert_eq!(bits(&offline), bits(&flat), "⭐ 离线 ＝ 摊平（逐位）");
    assert_eq!(bits(&flat), bits(&realtime), "⭐ 摊平 ＝ 实时（逐位）");

    // ⭐ 反空判腿：同一个夹具、初值为 0（门控不成立）⇒ 三条路都静音 ⇒ 与上面**不同**。
    let closed = |_controller: u8| 0u8;
    let closed_arg: Option<&dyn Fn(u8) -> u8> = Some(&closed);
    let mut closed_offline = vec![0.0f32; FRAMES];
    instrument
        .render_note_into_with_cc(&sample, 60, VELOCITY, closed_arg, &mut closed_offline, HZ)
        .expect("离线渲染");
    assert_eq!(nonzero_frames(&closed_offline), 0);
    assert_ne!(
        bits(&offline),
        bits(&closed_offline),
        "⭐ 有牙：初值 64 与 0 必须给出**逐位不同**的输出"
    );
}

/// ⭐ S89（任务单 `#110`；§5.5 真实 CC 覆盖初值）：**先播种、再喂一条同号
/// `ControlChange` ⇒ 后者赢** —— 同一量子、后面的量子、以及"重新武装一份等价快照"
/// 三条腿都成立（播种**幂等** ⇒ ⛔ 不覆盖真值）。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_SEED_GATE_SEEDED`] 的会话表在四条时间线上的读数；
/// 单位 ＝ `control_change(1)`（`Option<u8>`）＋ `armed`（布尔）。
#[test]
fn s89_a_real_control_change_beats_the_seeded_initial_value() {
    let fixture = note_project(&[NoteSpec::at(0, 480, 60, 100)]);
    let sample = constant_sample(4_096);
    let mut rig = CcSeedRig::new(
        &fixture,
        SfzPlan::from_prepared(prepare_with(CC_SEED_GATE_SEEDED, &sample)),
    );
    // ① 同一量子：真 CC 与快照第一次武装**同批**到达 ⇒ 事件面先跑 ⇒ 真值赢。
    assert_eq!(
        rig.publish(&[yeban_engine::ring::EngineEvent::ControlChange {
            controller: 1,
            value: 0,
        }]),
        1
    );
    rig.run(1);
    assert_eq!(
        rig.runtime.control_change(1),
        Some(0),
        "⭐ 同一量子：真 CC 覆盖初值（事件面在 2a-cc 段之前）"
    );
    assert_eq!(rig.runtime.control_change_received_count(), 1);
    // ② 后面的量子再来一条 ⇒ 仍是真值（最后一条赢）。
    assert_eq!(
        rig.publish(&[yeban_engine::ring::EngineEvent::ControlChange {
            controller: 1,
            value: 7,
        }]),
        1
    );
    rig.run(1);
    assert_eq!(rig.runtime.control_change(1), Some(7));
    // ③ 换一份**等价的新快照**（任何编辑都会发新修订 ⇒ 重新武装 ⇒ 再播一遍）
    //    ⇒ ⭐ 幂等：已经收到过 ⇒ 播种**跳过** ⇒ 真值不被覆盖。
    rig.rearm();
    rig.run(1);
    println!(
        "[engine-sfz/S89] 重新武装之后：control_change(1) = {:?}（初值 64 必须⛔ 不覆盖真值 7）",
        rig.runtime.control_change(1)
    );
    assert_eq!(
        rig.runtime.control_change(1),
        Some(7),
        "⭐ 重新武装：播种**幂等** ⇒ 真 CC 仍然是 7"
    );
    // ④ 反空判腿：**没有**真 CC 那一步 ⇒ 重新武装后恒为初值 64。
    let mut only_seed = CcSeedRig::new(
        &fixture,
        SfzPlan::from_prepared(prepare_with(CC_SEED_GATE_SEEDED, &sample)),
    );
    only_seed.run(1);
    only_seed.rearm();
    only_seed.run(1);
    assert_eq!(
        only_seed.runtime.control_change(1),
        Some(64),
        "非空对照：只有播种 ⇒ 值恒为初值"
    );
}

/// ⭐ S90（任务单 `#110`；§5.6 反向腿 ＋ 三个承重指纹）：**去掉 `set_ccN` 那一行** ⇒
/// 端到端与"没有播种机制"逐位相同、两个**初值**在**不读 CC** 的区域上给出**逐位相同**
/// 的输出；⭐ 三个承重指纹逐字不变；⭐ `×1.0000001` ⇒ 指纹必变。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`CC_SEED_GATE_PLAIN`]／[`CC_SEED_GATE_SEEDED`]／两份只差初值的
/// **CC-blind** 区域 ／ 三个既有夹具；单位 ＝ FNV-1a 指纹（逐位）＋ `armed`（布尔）
/// ＋ 非零样本数（个）。
#[test]
fn s90_the_reverse_legs_and_the_three_load_bearing_fingerprints() {
    let fixture = note_project(&[NoteSpec::at(0, 480, 60, 100)]);
    let sample = constant_sample(4_096);

    // ---- ① 反向腿（会话面）：去掉那一行 ⇒ 与"没有播种机制"逐位相同 ----
    let mut plain = CcSeedRig::new(
        &fixture,
        SfzPlan::from_prepared(prepare_with(CC_SEED_GATE_PLAIN, &sample)),
    );
    plain.run(16);
    let mut seeded = CcSeedRig::new(
        &fixture,
        SfzPlan::from_prepared(prepare_with(CC_SEED_GATE_SEEDED, &sample)),
    );
    seeded.run(16);
    println!(
        "[engine-sfz/S90] 反向腿：plain 指纹 = 0x{:016x}（armed={}）／seed 指纹 = 0x{:016x}\
         （armed={}）",
        plain.fingerprint(),
        plain.runtime.control_change_armed(),
        seeded.fingerprint(),
        seeded.runtime.control_change_armed()
    );
    assert!(!plain.runtime.control_change_armed());
    assert!(seeded.runtime.control_change_armed());
    let _checked = check_fingerprint(
        "S90 gate-plain（改动前实测）",
        plain.fingerprint(),
        CC_SEED_IGNORED_RUNTIME_FINGERPRINT,
    );
    assert_ne!(
        plain.fingerprint(),
        seeded.fingerprint(),
        "⭐ 有牙：那一行真的改变端到端输出"
    );

    // ---- ② 「两个初值逐位相同」腿：区域**不读 CC** ⇒ 播种本身⛔ 不制造差异 ----
    const SEED_64_BLIND: &str =
        "<control>set_cc1=64\n<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n";
    const SEED_0_BLIND: &str =
        "<control>set_cc1=0\n<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n";
    let blind_64 = prepare_with(SEED_64_BLIND, &sample);
    let blind_0 = prepare_with(SEED_0_BLIND, &sample);
    assert_eq!(blind_64.cc_seeds().value(1), Some(64));
    assert_eq!(blind_0.cc_seeds().value(1), Some(0));
    let blind_probe_64 = |controller: u8| blind_64.cc_seeds().value(controller).unwrap_or(0);
    let blind_probe_0 = |controller: u8| blind_0.cc_seeds().value(controller).unwrap_or(0);
    let arg_64: Option<&dyn Fn(u8) -> u8> = Some(&blind_probe_64);
    let arg_0: Option<&dyn Fn(u8) -> u8> = Some(&blind_probe_0);
    let mut out_64 = vec![0.0f32; BLOCK];
    let mut out_0 = vec![0.0f32; BLOCK];
    blind_64.render_block_into_with_cc(60, 100, arg_64, &mut out_64);
    blind_0.render_block_into_with_cc(60, 100, arg_0, &mut out_0);
    println!(
        "[engine-sfz/S90] CC-blind 区域：初值 64 ⇒ 0x{:016x}（非零 {}）／初值 0 ⇒ 0x{:016x}\
         （非零 {}）",
        fnv1a_64(&out_64),
        nonzero_frames(&out_64),
        fnv1a_64(&out_0),
        nonzero_frames(&out_0)
    );
    assert!(nonzero_frames(&out_64) > 0, "夹具必须可闻");
    assert_eq!(
        bits(&out_64),
        bits(&out_0),
        "⭐ 反向腿：区域不读 CC ⇒ 两个初值**逐位相同**（播种本身⛔ 不制造差异）"
    );
    // ⭐ 有牙对照：**读 CC** 的区域（`locc1`）在同样两个初值下**必须不同**。
    let gate_64 = prepare_with(CC_SEED_GATE_SEEDED, &sample);
    let gate_0 = prepare_with(
        "<control>set_cc1=0\n<region> sample=a.wav key=60 pitch_keycenter=60 \
         amp_veltrack=0 locc1=64 hicc1=127\n",
        &sample,
    );
    let gate_probe_64 = |controller: u8| gate_64.cc_seeds().value(controller).unwrap_or(0);
    let gate_probe_0 = |controller: u8| gate_0.cc_seeds().value(controller).unwrap_or(0);
    let gate_arg_64: Option<&dyn Fn(u8) -> u8> = Some(&gate_probe_64);
    let gate_arg_0: Option<&dyn Fn(u8) -> u8> = Some(&gate_probe_0);
    let mut gate_out_64 = vec![0.0f32; BLOCK];
    let mut gate_out_0 = vec![0.0f32; BLOCK];
    gate_64.render_block_into_with_cc(60, 100, gate_arg_64, &mut gate_out_64);
    gate_0.render_block_into_with_cc(60, 100, gate_arg_0, &mut gate_out_0);
    assert_ne!(
        bits(&gate_out_64),
        bits(&gate_out_0),
        "⭐ 有牙对照：读 CC 的区域在两个初值下必须**不同**"
    );

    // ---- ③ 三个承重指纹逐字复跑并断言 ----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain_fixture = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, fixture, end_sample, expected) in [
        ("S90 → S37 臂 1", &looped, 200u64, 0xa9de_c8a8_7f69_106cu64),
        (
            "S90 → S37 臂 2",
            &plain_fixture,
            u64::MAX,
            0xd3c2_a820_76bd_8947u64,
        ),
    ] {
        let out = render_pool(fixture, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!(
            "[engine-sfz/S90] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）；\
             非零帧数 = {}",
            nonzero_frames(&out)
        );
        let _checked = check_fingerprint(&format!("S90 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy = vec![0.0f32; BLOCK];
    broadcast.render_block_into_with_cc(60, 127, None, &mut legacy);
    let legacy_hash = fnv1a_64(&legacy);
    println!(
        "[engine-sfz/S90] S90 → S33／S14 广播路径：指纹 = 0x{legacy_hash:016x}\
         （承重 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）"
    );
    let _checked = check_fingerprint(
        "S90 S33/S14 广播路径",
        legacy_hash,
        NO_LOOP_FIXTURE_FINGERPRINT,
    );

    // ---- ④ 应绿反向腿：同一输出 × `1.0000001` ⇒ 指纹**必须变** ----
    let scaled: Vec<f32> = legacy.iter().map(|sample| sample * 1.000_000_1).collect();
    let scaled_hash = fnv1a_64(&scaled);
    println!(
        "[engine-sfz/S90] 反向腿（× 1.0000001）：指纹 = 0x{scaled_hash:016x}\
         （原指纹 0x{legacy_hash:016x}，必须不同）"
    );
    assert_ne!(
        scaled_hash, legacy_hash,
        "⭐ 反向腿：乘 1.0000001 后指纹必须变"
    );
}

/// ⭐ S92（任务单 `#110`；域口径）：**域外的 `set_ccN` 声明⛔ 不别名一个 7 位控制器**
/// —— `set_cc400=63` 的 `400 & 0x7F = 16`，⛔ **不得**写成 CC16；表保持空、会话表不 armed。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 两份只差 `N`（`400` / `16`）的 SFZ 与它们的会话读数；
/// 单位 ＝ 初值表条数（条）＋ 域外计数（条）＋ `armed`（布尔）＋ `control_change(16)`
/// （`Option<u8>`）＋ 非零样本数（个）。
#[test]
fn s92_an_out_of_domain_set_cc_never_aliases_a_seven_bit_controller() {
    let fixture = note_project(&[NoteSpec::at(0, 480, 60, 100)]);
    let sample = constant_sample(4_096);
    // ① 域外：`set_cc400=63` ＋ 一条 `locc16=63 hicc16=63` 的**诱饵**区域。
    let out_of_domain = prepare_with(
        "<control>set_cc400=63\n<region> sample=a.wav key=60 pitch_keycenter=60 \
         amp_veltrack=0 locc16=63 hicc16=63\n",
        &sample,
    );
    assert!(
        out_of_domain.cc_seeds().is_empty(),
        "域外声明 ⛔ 不进表（`400 & 0x7F = 16` 会**别名** CC16）"
    );
    assert_eq!(
        out_of_domain.cc_seeds().out_of_domain(),
        1,
        "但要**计数**（⛔ 不静默）"
    );
    let mut bad = CcSeedRig::new(&fixture, SfzPlan::from_prepared(out_of_domain));
    bad.run(16);
    println!(
        "[engine-sfz/S92] set_cc400=63：初值条数 = 0、域外计数 = 1、armed={}、\
         control_change(16)={:?}、非零={}",
        bad.runtime.control_change_armed(),
        bad.runtime.control_change(16),
        bad.nonzero()
    );
    assert!(
        !bad.runtime.control_change_armed(),
        "⭐ 域外声明⛔ 不得把表 armed（那正是别名的来路）"
    );
    assert_eq!(
        bad.runtime.control_change(16),
        None,
        "CC16 必须仍然**没收到过**"
    );
    assert_eq!(
        bad.nonzero(),
        0,
        "CC16 没被播种 ⇒ `locc16=63` 不成立 ⇒ 不发声"
    );

    // ② 非空对照：把 `N` 改成域内的 16 ⇒ 真的进表、真的发声。
    let in_domain = prepare_with(
        "<control>set_cc16=63\n<region> sample=a.wav key=60 pitch_keycenter=60 \
         amp_veltrack=0 locc16=63 hicc16=63\n",
        &sample,
    );
    assert_eq!(in_domain.cc_seeds().value(16), Some(63));
    assert_eq!(in_domain.cc_seeds().out_of_domain(), 0);
    let mut good = CcSeedRig::new(&fixture, SfzPlan::from_prepared(in_domain));
    good.run(16);
    assert!(good.runtime.control_change_armed());
    assert_eq!(good.runtime.control_change(16), Some(63));
    assert!(good.nonzero() > 0, "非空对照：域内声明真的进表 ⇒ 门控成立");
}

/// ⭐ S91（任务单 `#110`；§5.7）：**修订段 ＋ 条数上界的来历 ＋ 尺寸**可判。
///
/// # 判定量
///
/// * `include_str!("../src/sfz_instrument.rs")` 必须逐字含 `#110` 的追加修订段、
///   新一节、**结构性上界**与**域外不别名**那句；`#104`／`#107`／`#108`／`#109` 的
///   **原文**（第 278 条：⛔ 不许删）仍在；`include_str!("../src/cc_state.rs")` 必须含
///   `seed` 的口径句；
/// * 语料普查原始读数（分母 **1398** ／ **1137** ／ **105** ／ **38** ／ **62**）可判；
/// * 尺寸：`CcSeedTable` **152**、`PreparedSfz` **88 → 240**、`SfzPlan` **240**；
///   ⛔ `SfzVoice` **40**、⛔ `SfzVoicePool` **1712**、⛔ `EngineRuntime` **180144**
///   （< 192 KiB）、⛔ `PreparedRegion` **6152**、⛔ `ControlChangeState` **144**。
///
/// ⭐ ⭐ **追加修订段（任务单 `#113`）—— 被修订的是上面最后那三个"⛔"里
/// `PreparedRegion` **6152** 那一支**（⛔ 原文一字未删，口径同台账第 278 条）：
/// `#113`（`direction`）给摊平表加了**一个**每区域字段 ⇒ `PreparedRegion` 现为 **6160 B**；
/// ⛔ `SfzVoice` **40** / `SfzVoicePool` **1712** / `EngineRuntime` **180144** 三条**一条未动**
/// （它们才是本单的硬边界）。
#[test]
fn s91_the_110_registration_the_bound_and_the_sizes_are_judgeable() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const CC_STATE_SOURCE: &str = include_str!("../src/cc_state.rs");
    const REVISION: &str = "⭐ ⭐ **追加修订段（任务单 `#110`）";
    const SECTION: &str = "# ⭐ `set_ccN` 播种（任务单 `#110`）";
    const BOUND: &str = "上界是结构性的";
    const SEED_ONCE: &str = "只填从未收到过的槽";
    const NO_ALIAS: &str = "**不被掩码别名**";
    const INERT: &str = "表为空 ⇒ 播种机制一个字节都不动";
    const PREV_104_CALIBER: &str = "⭐ 双口径登记（任务单 `#104`）";
    const PREV_104_GATE: &str = "⭐ 摊平期门控登记（任务单 `#104`）";
    const PREV_107: &str = "⭐ ⭐ **追加修订段（任务单 `#107`）";
    const PREV_107_UNWIRED: &str = "本单未接线（登记，⛔ 不静默）";
    const PREV_108: &str = "⭐ ⭐ **追加修订段（任务单 `#108`）";
    const PREV_109: &str = "⭐ ⭐ **追加修订段（任务单 `#109`）";
    const PREV_109_UNWIRED: &str = "⛔ 本单仍未接线（登记，⛔ 不静默）";
    const CC_STATE_SEED: &str = "只在\"这个控制器从未收到过\"时写";
    const ABSENT: &str = "`set_ccN` 的播种仍然一行都不接线";
    const ABSENT_CC_STATE: &str = "本单 ⛔ 不播种，`set_ccN` 永远不被播种";
    println!(
        "[engine-sfz/S91] 模块头：`#110` 修订段 = {}、新一节 = {}、结构性上界 = {}、\
         不别名 = {}、空表不动 = {}、`seed` 口径 = {}",
        MODULE_SOURCE.contains(REVISION),
        MODULE_SOURCE.contains(SECTION),
        MODULE_SOURCE.contains(BOUND),
        MODULE_SOURCE.contains(NO_ALIAS),
        MODULE_SOURCE.contains(INERT),
        CC_STATE_SOURCE.contains(CC_STATE_SEED),
    );
    for (label, needle) in [
        ("`#110` 追加修订段", REVISION),
        ("`set_ccN` 播种一节", SECTION),
        ("结构性上界（条数上界的来历）", BOUND),
        ("域外声明不被掩码别名", NO_ALIAS),
        ("只填从未收到过的槽（幂等口径）", SEED_ONCE),
        ("空表 ⇒ 一个字节都不动（保命不变量）", INERT),
        ("`#104` 的双口径登记（⛔ 不许删）", PREV_104_CALIBER),
        ("`#104` 的摊平期门控登记（⛔ 不许删）", PREV_104_GATE),
        ("`#107` 的追加修订段（⛔ 不许删）", PREV_107),
        ("`#107` 的未接线登记原文（⛔ 不许删）", PREV_107_UNWIRED),
        ("`#108` 的追加修订段（⛔ 不许删）", PREV_108),
        ("`#109` 的追加修订段（⛔ 不许删）", PREV_109),
        ("`#109` 的未接线登记原文（⛔ 不许删）", PREV_109_UNWIRED),
    ] {
        assert!(MODULE_SOURCE.contains(needle), "⭐ 必须逐字含：{label}");
    }
    assert!(
        CC_STATE_SOURCE.contains(CC_STATE_SEED),
        "⭐ `ControlChangeState::seed` 的「只填从未收到过的槽」口径必须写在源码里"
    );
    assert!(
        !MODULE_SOURCE.contains(ABSENT),
        "⭐ 反向腿：文档里没有的句子必须 `false`"
    );
    assert!(
        !CC_STATE_SOURCE.contains(ABSENT_CC_STATE),
        "⭐ 反向腿：`cc_state.rs` 里没有的句子必须 `false`"
    );

    // ⭐ 语料普查的原始读数必须登记在源码里（第 271／274 条：口径 ＋ 分母 ＋ 对照）。
    for needle in [
        "**1398**",
        "**1137**",
        "**105**",
        "**38**",
        "**62**",
        "**128**",
        "`offset_cc131=5500`",
        "`{1: 18, 2: 1, 3: 6, 4: 7, 6: 9, 7: 9, 8: 1, 9: 9, 10: 11, 11: 8, 12: 3, 13: 7, 14: 1, 16: 3, 17: 2, 19: 2, 22: 2, 30: 1, 31: 2, 57: 1, 62: 2}`",
    ] {
        assert!(
            MODULE_SOURCE.contains(needle),
            "⭐ 语料/口径读数必须可判：模块头缺少 `{needle}`"
        );
    }

    // ⭐ 任务单 `#112`（§2①）：那条自相矛盾的旧数字（`SfzPlan` 仍 88 B）必须已经不在
    // 源码里，且新数字必须**逐字**在模块头 —— 这两条是**源文本腿**，`size_of` 抓不到
    // "文档写错、代码没错"这种形态。
    assert!(
        MODULE_SOURCE.contains("⭐ `SfzPlan` **88 → 240 B**"),
        "⭐ 模块头必须把 `SfzPlan` 的尺寸写成 **240 B**（它按值内联 `PreparedSfz`）"
    );
    assert!(
        !MODULE_SOURCE.contains("⭐ `SfzPlan` 仍 **88 B**"),
        "⭐ 反向腿：`SfzPlan` 仍 **88 B** 这条与 `size_of` 矛盾的旧文字必须已删"
    );

    let seed_table = core::mem::size_of::<yeban_engine::sfz_instrument::CcSeedTable>();
    let prepared_sfz = core::mem::size_of::<PreparedSfz>();
    let plan = core::mem::size_of::<SfzPlan>();
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let cc_state = core::mem::size_of::<yeban_engine::cc_state::ControlChangeState>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S91] size_of: CcSeedTable={seed_table} PreparedSfz={prepared_sfz}\
         （88 → {prepared_sfz}）SfzPlan={plan} PreparedRegion={region} SfzVoice={voice} \
         SfzVoicePool={pool} ControlChangeState={cc_state} EngineRuntime={runtime}\
         （门槛 192 KiB = {}；余量 = {}）",
        192 * 1024,
        192 * 1024 - runtime,
    );
    assert_eq!(
        seed_table, 152,
        "⭐ `CcSeedTable` ＝ 值表 `[u8; 128]` ＋ 掩码 `[u64; 2]` ＋ 域外计数 `usize`"
    );
    // ⭐ 任务单 `#112`（§2①）：**绝对值基线 ＋ 增量**两条腿都要钉。只钉增量
    // （`88 + seed_table`）在**基线自己漂了**的时候不会响（内层原有 88 若变成别的数，
    // 增量腿仍绿）⇒ 这里同时钉绝对值。
    assert_eq!(
        prepared_sfz, 240,
        "⭐ `PreparedSfz` 的**绝对值**基线（`88 + 152`；基线漂了本腿必须响）"
    );
    assert_eq!(
        plan, 240,
        "⭐ `SfzPlan` 的**绝对值**基线（它按值内联 `PreparedSfz` ⇒ 与内层同长）"
    );
    assert_eq!(
        prepared_sfz,
        88 + seed_table,
        "⭐ `PreparedSfz` 的增量 ＝ `size_of::<CcSeedTable>()`（摊平表长大，⛔ 不进实时对象）"
    );
    assert_eq!(
        plan,
        88 + seed_table,
        "⭐ `SfzPlan` 的增量 ＝ 内层的增量（它按值内联 `PreparedSfz`）"
    );
    assert_eq!(
        prepared_sfz, plan,
        "⭐ 包装与内层**同长**（`SfzPlan` 按值内联 `PreparedSfz`）"
    );
    // ⭐ ⭐ **追加修订段（任务单 `#113`）—— 被修订的是下面这条断言的**绝对值**那一支**
    // （⛔ 原文保留在此，口径同台账第 278 条：保留原文 ＋ 追加修订段 ＋ 点名被修订的支）：
    //     assert_eq!(region, 6152, "⛔ `PreparedRegion` 必须 ＋0（播种表是**每表**一份）");
    // ⭐ `#113`（`direction`）给摊平表加了**一个**每区域字段（`direction: PlayDirection`，
    // `size_of` ＝ 1；`#[repr(Rust)]` 重排后落在对齐 8 的尾巴上）⇒ `PreparedRegion`
    // `6152 → 6160`（＋**8**）。⚠ **被修订的只是这条绝对值**：`#110` 的原意
    // ——"**播种表**⛔ 不按区域收费"——**仍然成立**（播种表在 `PreparedSfz` 层、每表一份，
    // 上面两条 `88 → 240` 的腿整条有效）；⛔ `SfzVoice` / 池 / `EngineRuntime` 三条
    // **＋0 边界一条未动**（下面三条断言逐字保留）。
    assert_eq!(
        region, 6160,
        "⭐ `#113` 后的**绝对值**基线（`6152 ＋ 8`；⛔ 三条实时边界仍 ＋0）"
    );
    assert_eq!(
        region,
        6152 + 8,
        "⭐ `#113` 的**增量** ＝ `direction: PlayDirection` ＋ 尾部对齐（⛔ 不是 `per-table` 那一份）"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（仍是 40 B）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0（仍是 1712 B）");
    assert_eq!(
        cc_state, 144,
        "⛔ `ControlChangeState` 必须 ＋0（`seed` 不加字段）"
    );
    assert_eq!(
        runtime, 180_144,
        "⛔ `EngineRuntime` 必须 ＋0（仍是 180144 B）"
    );
    assert!(
        runtime < 192 * 1024,
        "⛔ `EngineRuntime` 必须 < 192 KiB（余量 {} B）",
        192 * 1024 - runtime
    );
}

/// ⭐ S93 的**双轨装置**（任务单 `#112`；§2② 的实测 ＋ §2③ 的离线腿）。
///
/// 两条 MIDI 轨各带一份摊平表（A ＝ 产物轨／播种轨、B ＝ 门控轨），同一条 60 号音符、
/// 同一条产品路径（`EngineRuntime::process_quantum`，每量子 128 帧 × 2 声道）。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 双轨快照经 `quanta` 个量子的输出与**会话表**读数；
/// 单位 ＝ `armed`（布尔）＋ `control_change(N)`（`Option<u8>`）＋ 非零样本数（个）
/// ＋ FNV-1a 指纹（逐位，左声道后右声道）。
///
/// ⚠ A 轨的区域是 `key=127` ⇒ 本夹具的 60 号音符**恒不匹配** ⇒ A 轨自身逐位静音
/// （由调用方用一条对照腿实测证明）⇒ 输出里的非零样本**全部**来自 B 轨。
fn run_two_track_cc_seed_leak(
    a_plan: &PreparedSfz,
    b_plan: &PreparedSfz,
    quanta: usize,
) -> (bool, Option<u8>, Option<u8>, usize, u64) {
    let (project, first, second) = support::two_track_project(
        &[NoteSpec::at(0, 480, 60, 100)],
        &[NoteSpec::at(0, 480, 60, 100)],
    );
    let snapshot = EngineSnapshot::from_project(&project, 1)
        .expect("双轨夹具必须能编译成快照")
        .with_sfz(first, SfzPlan::from_prepared(a_plan.clone()))
        .with_sfz(second, SfzPlan::from_prepared(b_plan.clone()));
    let slot = yeban_engine::snapshot::SnapshotSlot::new(snapshot);
    let (retire, _queue) = yeban_engine::snapshot::retire_channel(64);
    let (_sender, receiver) = yeban_engine::ring::event_channel(64);
    let (publisher, _collector) = yeban_engine::meter::meter_channel(4096);
    let mut runtime = yeban_engine::rt::EngineRuntime::new(&slot, retire, receiver, publisher);
    let mut out = vec![0.0f32; 2 * 128];
    let mut left = Vec::new();
    let mut right = Vec::new();
    for _ in 0..quanta {
        out.fill(0.0);
        runtime.process_quantum(&mut out, 2);
        for frame in 0..128 {
            left.push(out[frame * 2]);
            right.push(out[frame * 2 + 1]);
        }
    }
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for sample in left.iter().chain(right.iter()) {
        for byte in sample.to_bits().to_le_bytes() {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }
    let nonzero = left
        .iter()
        .chain(right.iter())
        .filter(|sample| **sample != 0.0)
        .count();
    (
        runtime.control_change_armed(),
        runtime.control_change(1),
        runtime.control_change(2),
        nonzero,
        hash,
    )
}

/// ⭐ A 轨的**可播种但恒不触发**的摊平表（区域 `key=127`，本夹具的音符恒为 60）。
fn silent_seed_plan(control: &str, sample: &InMemorySample) -> PreparedSfz {
    prepare_with(
        &format!("{control}<region> sample=a.wav key=127 pitch_keycenter=127 amp_veltrack=0\n"),
        sample,
    )
}

/// ⭐ S93（任务单 `#112`；§2② 的**(b) 登记为有意边界** ＋ §2③ 的**维持登记**）：
/// **一条轨的 `set_ccN` 会经会话表把另一条没有 `set_ccN` 的轨的门控带走** ——
/// 本判据把这个行为**钉死**（它是有意的、被登记的边界，⛔ 不是"读者自己猜"）。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 双轨快照（A ＝ `key=127` 的播种轨、B ＝ `locc1=64 hicc1=127` 的门控轨）
/// 经产品路径 16 量子 ＝ 2048 帧的输出，以及会话表的 `armed` / `control_change(1)`；
/// 单位 ＝ `armed`（布尔）＋ `control_change(N)`（`Option<u8>`）＋ 非零样本数（个）
/// ＋ FNV-1a 指纹（逐位）。
///
/// ⚠ **有牙**：去掉 `#110` 在 `rt.rs` 快照边界的播种段（`2a-cc`）⇒ 会话表不 armed
/// ⇒ `nz_seed1` 从 `4030` 掉回 `0` ⇒ 本判据的两条断言立刻红。
#[test]
fn s93_a_track_without_set_cc_is_carried_by_another_tracks_seed() {
    const QUANTA: usize = 16;
    let sample = constant_sample(4_096);
    let a_plain = silent_seed_plan("", &sample);
    let a_seed1 = silent_seed_plan("<control>set_cc1=64\n", &sample);
    let a_seed2 = silent_seed_plan("<control>set_cc2=64\n", &sample);
    // B 轨：门控 `locc1=64 hicc1=127`，**自己一条 `set_ccN` 都没有**。
    let b_gated = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 locc1=64 hicc1=127\n",
        &sample,
    );

    assert!(
        b_gated.cc_seeds().is_empty(),
        "⭐ B 轨自己**没有** `set_ccN`（外溢必须是**跨轨**的，⛔ 不是 B 轨自播）"
    );
    assert_eq!(
        b_gated.regions().len(),
        1,
        "⭐ B 轨摊平表里恰好一条区域（否则本判据量的是别的东西）"
    );
    assert_eq!(
        b_gated.regions()[0].cc_gates().len(),
        1,
        "⭐ B 轨真的带一条 `locc1=64 hicc1=127` 门控"
    );
    assert!(a_plain.cc_seeds().is_empty(), "A 对照轨没有 `<control>`");
    assert_eq!(a_seed1.cc_seeds().value(1), Some(64), "A 播种轨声明 CC1=64");
    assert_eq!(a_seed2.cc_seeds().value(2), Some(64), "A 判别轨声明 CC2=64");

    // ① 对照腿：A 无 `<control>` ⇒ 表不 armed ⇒ B 轨门控不成立 ⇒ **逐位静音**。
    let (armed_plain, cc1_plain, _cc2_plain, nz_plain, fp_plain) =
        run_two_track_cc_seed_leak(&a_plain, &b_gated, QUANTA);
    // ② 边界的**正腿**：A 的 `set_cc1=64` 经会话表走到 B 轨 ⇒ B 轨门控**成立** ⇒ 发声。
    let (armed_seed1, cc1_seed1, _cc2_seed1, nz_seed1, fp_seed1) =
        run_two_track_cc_seed_leak(&a_seed1, &b_gated, QUANTA);
    // ③ **判别腿**：A 只武装表、但 CC1 仍是 `None` ⇒ B 轨门控**不**成立 ⇒ 静音。
    let (armed_seed2, cc1_seed2, cc2_seed2, nz_seed2, fp_seed2) =
        run_two_track_cc_seed_leak(&a_seed2, &b_gated, QUANTA);
    // ④ A 轨自身静音的对照腿（B 也换成恒不触发的 `key=127`）⇒ 非零样本必须是 0。
    let b_silent = silent_seed_plan("", &sample);
    let (_armed_a_only, _cc1_a_only, _cc2_a_only, nz_a_only, _fp_a_only) =
        run_two_track_cc_seed_leak(&a_seed1, &b_silent, QUANTA);

    println!(
        "[engine-sfz/S93] 多轨跨轨外溢：A=无 ⇒ armed={armed_plain} cc1={cc1_plain:?} \
         nz={nz_plain} fp=0x{fp_plain:016x}；A=set_cc1=64 ⇒ armed={armed_seed1} \
         cc1={cc1_seed1:?} nz={nz_seed1} fp=0x{fp_seed1:016x}；\
         A=set_cc2=64（判别腿）⇒ armed={armed_seed2} cc1={cc1_seed2:?} cc2={cc2_seed2:?} \
         nz={nz_seed2} fp=0x{fp_seed2:016x}；A 轨自证的静音腿 nz={nz_a_only}"
    );

    assert_eq!(
        nz_a_only, 0,
        "⭐ 承重前提：A 轨的区域 `key=127` 恒不触发 ⇒ ②③ 的非零样本**全部**来自 B 轨"
    );
    assert!(!armed_plain, "A 无 `set_ccN` ⇒ 表不 armed");
    assert_eq!(cc1_plain, None);
    assert_eq!(
        nz_plain, 0,
        "表不 armed ⇒ 探针 `None` ⇒ B 轨门控不成立 ⇒ 静音"
    );
    assert!(
        armed_seed1,
        "⭐ A 的 `set_cc1=64` 把**会话表**武装起来（这正是跨轨外溢的机械来路）"
    );
    assert_eq!(cc1_seed1, Some(64), "初值进会话表");
    assert_eq!(
        nz_seed1, 4030,
        "⭐⭐ **有意边界**：B 轨自己没有 `set_ccN`，它的 `locc1=64` 却被 A 轨的初值带走 \
         ⇒ 端到端可闻（4030 ＝ 单轨无门控夹具同值：4096 帧 − 66 帧链路固定静音前缀）"
    );
    let _checked = check_fingerprint(
        "S93 A 无 set_ccN（B 轨静音）",
        fp_plain,
        CC_SEED_IGNORED_RUNTIME_FINGERPRINT,
    );
    let _checked = check_fingerprint(
        "S93 A 有 set_cc1=64（B 轨被带走 ⇒ 与单轨无门控指纹同值）",
        fp_seed1,
        CC_SEED_ABSENT_RUNTIME_FINGERPRINT,
    );
    assert_ne!(fp_plain, fp_seed1, "⭐ 有牙：那一行真的改变端到端输出");
    assert!(armed_seed2, "判别腿：A 的 `set_cc2=64` 同样武装会话表");
    assert_eq!(cc1_seed2, None, "判别腿：但 CC1 从未被任何轨播种");
    assert_eq!(cc2_seed2, Some(64), "判别腿：被武装的是 CC2");
    assert_eq!(
        nz_seed2, 0,
        "⭐ 判别腿：**仅仅**武装表不足以让 B 轨门控成立 —— 它读的是 A 轨 CC1 的**值**"
    );
    let _checked = check_fingerprint(
        "S93 A 有 set_cc2=64（B 轨仍静音）",
        fp_seed2,
        CC_SEED_IGNORED_RUNTIME_FINGERPRINT,
    );

    // ---- §2③ 离线腿：`SynthEngine::render_track` 仍传 `cc = None`（维持登记） ----
    //
    // 对象 ＝ 同一条轨、同一份带 `set_ccN` 的摊平表经**离线入口**渲染的 512 帧；
    // 单位 ＝ 非零帧数（帧）＋ 位模式（逐帧 `u32`）。
    let offline_track = EntityId::new();
    let offline_plan = prepare_with(CC_SEED_GATE_SEEDED, &sample);
    assert_eq!(
        offline_plan.cc_seeds().value(1),
        Some(64),
        "离线腿的夹具真的带 `set_cc1=64`"
    );
    // ⚠ 三条腿各建**一台**引擎：`SynthEngine` 的每槽 `cursor` 单调前进（同 S18／S24
    // "每条腿各建一台"的理由）⇒ 同一个引擎上换调度表不会重新触发。
    let offline_schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);
    let mut via_render_track = vec![0.0f32; BLOCK];
    engine_with_track(offline_track).render_track(
        offline_track,
        Some(&offline_schedule),
        Some(&offline_plan),
        &mut via_render_track,
    );
    let seed_probe = |controller: u8| offline_plan.cc_seeds().value(controller).unwrap_or(0);
    let seed_arg: Option<&dyn Fn(u8) -> u8> = Some(&seed_probe);
    let mut via_probe = vec![0.0f32; BLOCK];
    engine_with_track(offline_track).render_track_with_cc(
        offline_track,
        Some(&offline_schedule),
        Some(&offline_plan),
        &mut via_probe,
        seed_arg,
    );
    let mut via_none = vec![0.0f32; BLOCK];
    engine_with_track(offline_track).render_track_with_cc(
        offline_track,
        Some(&offline_schedule),
        Some(&offline_plan),
        &mut via_none,
        None,
    );
    println!(
        "[engine-sfz/S93] 离线腿：`render_track` 非零帧数 = {}、位模式 == `(…, None)` = {}、\
         位模式 == 探针臂 = {}（std = {}）",
        nonzero_frames(&via_render_track),
        bits(&via_render_track) == bits(&via_none),
        bits(&via_render_track) == bits(&via_probe),
        nonzero_frames(&via_probe),
    );
    assert_eq!(
        bits(&via_render_track),
        bits(&via_none),
        "⭐ 维持登记：`render_track` 仍**逐位等于** `render_track_with_cc(…, None)`"
    );
    assert_eq!(
        nonzero_frames(&via_render_track),
        0,
        "⭐ `set_cc1=64` 的 `locc1=64` 门控在离线入口下**不**成立 ⇒ 逐位静音"
    );
    assert!(
        nonzero_frames(&via_probe) > 0,
        "⭐ 有牙：把探针喂成同表的 `cc_seeds` ⇒ 同一份表**会**发声（离线路径只差这一个探针）"
    );
    assert_ne!(
        bits(&via_render_track),
        bits(&via_probe),
        "⭐ 有牙：离线入口与探针臂必须**逐位不同**（否则这条登记无意义）"
    );
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#113`：**播放方向**（`direction` ＝ `forward` / `reverse`）
// ---------------------------------------------------------------------------
//
// ⛔ 本片**不动**解析与取值域：`yeban-sfz` 早就解析了 `direction`
// （`PlayDirection`：`forward` 缺省 / `reverse`；白名单拒绝其余取值）——缺的是
// **播放层装不下**：`PreparedRegion` 不带这份读数、`mix_span_into` 只朝一个方向走。
//
// ⭐ 落地口径（逐条可判）：`reduce_travel` 是**唯一**归约，把方向折成三件**已有**读数
// —— 行进起点 / 带符号步进 / 行进边界（`forward`：`start` / `+rate` / `end`；
// `reverse`：`end − 1` / `−rate` / `start`）⇒ ⛔ **零新逐声部字段**（`SfzVoice` 仍 40 B）。
// 规范逐字（含 `alternate` 其实属于 `loop_type` 这件事）与语料普查见
// `src/sfz_instrument.rs` 模块头的「⭐ 播放方向（`direction`，任务单 `#113`）」一节。

/// ⭐ S94～S99 的夹具几何：400 帧斜坡上的半开区间 `[100, 200)`。
const DIR_PCM_FRAMES: usize = 400;
const DIR_OFFSET: usize = 100;
/// ⚠ `end` 是**含**端点的（规范逐字）⇒ 半开区间的终点是 `end + 1`。
const DIR_END_INCLUSIVE: usize = 199;
/// 半开区间长度（帧）＝ `200 − 100`。
const DIR_SPAN_FRAMES: usize = DIR_END_INCLUSIVE + 1 - DIR_OFFSET;
/// ⭐ 实写帧数 ＝ `区间长 − 1`（线性插值要读"下一格"）——`forward` 与 `reverse` **同数**。
const DIR_WRITTEN_FRAMES: usize = DIR_SPAN_FRAMES - 1;

/// ⭐ `forward` 臂（缺省方向 ⇒ 与接线前**逐字相同**的文本）。
const DIR_FIXTURE_FORWARD: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 offset=100 end=199\n";
/// ⭐ `reverse` 臂：**只多** `direction=reverse` 一个 token。
const DIR_FIXTURE_REVERSE: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 offset=100 end=199 direction=reverse\n";
/// ⭐ 反向 ＋ 循环（窗口 `[100, 164)`，周期 64）。
const DIR_FIXTURE_LOOP_REVERSE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
     loop_mode=loop_continuous loop_start=100 loop_end=164 direction=reverse\n";
/// ⭐ 反向 ＋ 更短的 `end`（`end=149` ⇒ 半开区间 `[100, 150)`）。
const DIR_FIXTURE_REVERSE_SHORT_END: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 offset=100 end=149 direction=reverse\n";
/// ⭐ 反向 ＋ `end=-1`（规范：采样不播）。
const DIR_FIXTURE_REVERSE_SILENT: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 end=-1 direction=reverse\n";
/// ⭐ 反向 ＋ `offset` 落在 PCM 之外（400 帧 ⇒ `offset=1000` ⇒ 空区间）。
const DIR_FIXTURE_REVERSE_OFFSET_PAST_END: &str = "<region> sample=a.wav key=60 \
     pitch_keycenter=60 offset=1000 direction=reverse\n";

/// ⭐ **三条路的位模式**（离线 / 摊平 / 实时）＋ 各自的实写帧数。
///
/// 关掉包络与 CC 依赖（夹具里没有 `ampeg_*`、`amp_veltrack` 也不写 ⇒ 力度 127 的
/// 力度增益恰 `1.0`）⇒ 每一条路的输出逐帧**逐位**可对账。
fn dir_three_paths(
    text: &str,
    sample: &InMemorySample,
    frames: usize,
) -> (Vec<u32>, Vec<u32>, Vec<u32>, usize, usize, usize) {
    let instrument =
        SfzInstrument::load(text.to_owned(), &Default::default()).expect("方向夹具必须解析成功");
    let plan = PreparedSfz::prepare(&instrument, sample, 48_000.0).expect("摊平必须成功");

    // ① 离线（`SfzInstrument` 的一次性渲染）
    let mut offline = vec![0.0f32; frames];
    let written_offline = instrument
        .render_note_into(sample, 60, 127, &mut offline, 48_000.0)
        .expect("离线渲染");
    // ② 摊平表（`PreparedSfz` 的一次性渲染）
    let mut flat = vec![0.0f32; frames];
    let written_flat = plan.render_block_into(60, 127, &mut flat);
    // ③ 实时声部池（块长与 ①② 不同 ⇒ 真的覆盖"跨块延续"）
    let mut pool = SfzVoicePool::new(48_000.0);
    let created = pool.trigger_note(&plan, 60, 127, u64::MAX, 1.0, None);
    assert_eq!(created, 1, "单区域夹具 ⇒ 恰好建 1 个声部");
    let mut realtime = vec![0.0f32; frames];
    let quantum = 128usize.min(frames.max(1));
    let mut rendered = 0usize;
    while rendered < frames {
        let end = (rendered + quantum).min(frames);
        pool.render_into(&plan, rendered as u64, &mut realtime[rendered..end]);
        rendered = end;
    }
    (
        bits(&offline),
        bits(&flat),
        bits(&realtime),
        written_offline,
        written_flat,
        frames,
    )
}

/// ⭐ S94（任务单 `#113`；判据 §5.1／§5.6）：**规范逐字 ＋ 实现口径 ＋ `alternate` 登记**可判。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ `src/sfz_instrument.rs` 的**源文本**；单位 ＝ `contains`（布尔，逐字）。
/// ⭐ 取值域的权威在 `yeban-sfz`：同时断言 `PlayDirection::OPTIONS` **恰好**两项。
#[test]
fn s94_the_direction_spec_disposition_and_the_alternate_registration_are_judgeable() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const REVISION: &str = "⭐ ⭐ **追加修订段（任务单 `#113`）";
    const SECTION: &str = "# ⭐ 播放方向（`direction`，任务单 `#113`）";
    const SPEC_ROW: &str = "| direction | SFZ v2 | string | forward | forward, reverse | |";
    const LOOP_TYPE_OPTIONS: &str = "forward, backward, alternate";
    const SPEC_ENTIRE: &str = "affects the entire sample, not just the";
    const NO_SPEC_TEXT: &str = "规范**没有**明文";
    const ALTERNATE_LOUD: &str = "⭐ **`direction=alternate` 今天的行为 ＝ 响亮报错**";
    const ZERO_VOICE_FIELDS: &str = "⛔ **零新逐声部字段**";
    const ABSENT: &str = "`direction` 与 `loop_type` 都已由本单接线";
    println!(
        "[engine-sfz/S94] 模块头：`#113` 修订段 = {}、新一节 = {}、规范表行 = {}、\
         `loop_type` 表行 = {}、`entire sample` 逐字 = {}、`offset/end` 无明文登记 = {}、\
         `alternate` 报错登记 = {}",
        MODULE_SOURCE.contains(REVISION),
        MODULE_SOURCE.contains(SECTION),
        MODULE_SOURCE.contains(SPEC_ROW),
        MODULE_SOURCE.contains(LOOP_TYPE_OPTIONS),
        MODULE_SOURCE.contains(SPEC_ENTIRE),
        MODULE_SOURCE.contains(NO_SPEC_TEXT),
        MODULE_SOURCE.contains(ALTERNATE_LOUD),
    );
    for (label, needle) in [
        ("`#113` 追加修订段", REVISION),
        ("播放方向一节", SECTION),
        ("`direction` 的规范表行", SPEC_ROW),
        (
            "`loop_type` 的取值集（`alternate` 的**家**）",
            LOOP_TYPE_OPTIONS,
        ),
        ("规范逐字（`entire sample`）", SPEC_ENTIRE),
        ("`offset`/`end` 无明文（工程口径登记）", NO_SPEC_TEXT),
        ("`direction=alternate` 今天响亮报错", ALTERNATE_LOUD),
        ("零新逐声部字段的口径", ZERO_VOICE_FIELDS),
    ] {
        assert!(MODULE_SOURCE.contains(needle), "⭐ 必须逐字含：{label}");
    }
    assert!(
        !MODULE_SOURCE.contains(ABSENT),
        "⭐ 反向腿：文档里**没有**的句子必须 `contains == false`（否则判据恒真）"
    );

    // ⭐ 语料普查的原始读数必须可判（第 271／274 条：口径 ＋ 分母 ＋ 对照）。
    for needle in [
        "**1398**",
        "**0** 处（三种口径一致",
        "**835** 处",
        "**844**",
        "对照 `loop_type` | ⭐ **0** 处",
        "**6160 B**",
    ] {
        assert!(
            MODULE_SOURCE.contains(needle),
            "⭐ 语料/尺寸读数必须可判：模块头缺少 `{needle}`"
        );
    }

    // ⭐ 取值域的**唯一权威**是 `yeban-sfz`：白名单恰好 `forward` / `reverse`。
    let options: Vec<(&str, PlayDirection)> = PlayDirection::OPTIONS.to_vec();
    println!(
        "[engine-sfz/S94] `PlayDirection::OPTIONS` = {:?}；`ALLOWED` = {:?}",
        options.iter().map(|(name, _)| *name).collect::<Vec<&str>>(),
        PlayDirection::ALLOWED
    );
    assert_eq!(
        options,
        vec![
            ("forward", PlayDirection::Forward),
            ("reverse", PlayDirection::Reverse),
        ],
        "⭐ `direction` 的取值域**恰好**两项（⛔ 没有 `alternate` —— 它在 `loop_type` 里）"
    );
    assert_eq!(
        PlayDirection::ALLOWED,
        "forward, reverse",
        "⭐ 错误信息里的允许值列表（与规范表行逐字一致）"
    );
}

/// ⭐ S95（任务单 `#113`；判据 §5.2）：**反向真的反了**，且**逐帧等于**
/// "把区间倒序之后按 `forward` 渲染"。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 400 帧斜坡（`pcm[i] = (i+1)/1024`，增益恒 `1.0` ⇒ 输出可**逐帧反解源下标**）
/// 上区间 `[100, 200)` 的输出；单位 ＝ **源采样下标** ＋ **位模式**。
///
/// # 判定量
///
/// * `forward` 写 **99** 帧、下标 `100…198`；`reverse` 写 **99** 帧、下标 `199…101`
///   （逐帧反解 ⇒ 两串必须逐字相等）；
/// * 两条输出**逐位不同**（⛔ 不是"有输出就算过"）；
/// * ⭐ **独立参照**：把 `pcm[100..200]` **倒序**成新样本、用**同一条不带 `direction`
///   的路**渲染 ⇒ 与前者的 `reverse` 输出**逐位相同**（这是"倒序 ＋ 正向"的等价性，
///   ⛔ 不是把实现抄一遍）。
#[test]
fn s95_reverse_is_really_reversed_and_matches_the_reversed_source_reading() {
    let sample = ramp_sample(DIR_PCM_FRAMES);
    let forward = prepare_with(DIR_FIXTURE_FORWARD, &sample);
    let reverse = prepare_with(DIR_FIXTURE_REVERSE, &sample);

    let mut fwd = vec![0.0f32; 256];
    let n_fwd = forward.render_block_into(60, 127, &mut fwd);
    let mut rev = vec![0.0f32; 256];
    let n_rev = reverse.render_block_into(60, 127, &mut rev);
    assert_eq!(n_fwd, DIR_WRITTEN_FRAMES, "`forward` 实写帧数");
    assert_eq!(
        n_rev, DIR_WRITTEN_FRAMES,
        "`reverse` 实写帧数（与 `forward` 同数）"
    );

    let fwd_idx: Vec<usize> = (0..n_fwd).map(|k| source_index_at(&fwd, k)).collect();
    let rev_idx: Vec<usize> = (0..n_rev).map(|k| source_index_at(&rev, k)).collect();
    let expected_fwd: Vec<usize> = (DIR_OFFSET..=DIR_END_INCLUSIVE - 1).collect();
    let expected_rev: Vec<usize> = (DIR_OFFSET + 1..=DIR_END_INCLUSIVE).rev().collect();
    assert_eq!(fwd_idx, expected_fwd, "⭐ `forward` 的源下标序列逐帧精确");
    assert_eq!(
        rev_idx, expected_rev,
        "⭐ `reverse` 的源下标序列逐帧精确（＝ 从 `end` 那一格倒着走到 `offset + 1`）"
    );
    assert_ne!(
        bits(&fwd[..n_fwd]),
        bits(&rev[..n_rev]),
        "⭐ 反向必须真的反了（位模式逐位不同）"
    );
    println!(
        "[engine-sfz/S95] forward 帧数 = {n_fwd}、首/末源下标 = {}/{}；\
         reverse 帧数 = {n_rev}、首/末源下标 = {}/{}；首帧值 = {} / {}",
        fwd_idx[0],
        fwd_idx[n_fwd - 1],
        rev_idx[0],
        rev_idx[n_rev - 1],
        fwd[0],
        rev[0],
    );
    assert_eq!(
        rev[0],
        (DIR_END_INCLUSIVE + 1) as f32 / 1024.0,
        "⭐ 反向首帧**逐位**等于 `pcm[end] = 200/1024`"
    );

    // ⭐ 独立参照：倒序切片 ＋ 不带 `direction` 的同一条路。
    let mut reversed_pcm = sample.pcm[DIR_OFFSET..DIR_END_INCLUSIVE + 1].to_vec();
    reversed_pcm.reverse();
    let reversed_sample = InMemorySample {
        pcm: reversed_pcm,
        sample_hz: sample.sample_hz,
    };
    let reference = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &reversed_sample,
    );
    let mut ref_out = vec![0.0f32; 256];
    let n_ref = reference.render_block_into(60, 127, &mut ref_out);
    assert_eq!(
        n_ref, n_rev,
        "⭐ 参照臂的帧数必须与反向臂相同（否则等价性无从谈起）"
    );
    println!(
        "[engine-sfz/S95] 独立参照（倒序样本 ＋ forward）帧数 = {n_ref}；\
         与反向臂逐位相同 = {}",
        bits(&ref_out[..n_ref]) == bits(&rev[..n_rev])
    );
    assert_eq!(
        bits(&ref_out[..n_ref]),
        bits(&rev[..n_rev]),
        "⭐ ⭐ 反向输出必须**逐位等于**「把区间样本倒序之后按 `forward` 渲染」"
    );
}

/// ⭐ S96（任务单 `#113`；判据 §5.5）：**反向 × `offset` / `end`**。
///
/// # 规范面（先说再判）
///
/// `direction` / `offset` / `end` 三页（2026-10-16 现读）**都没有**一句规定
/// "反向时 `offset` / `end` 的语义"⇒ 本仓**不发明**，只按登记在案的工程口径判：
/// `offset` / `end` 定义的是**同一个**半开区间 `[offset, min(end, pcm_len))`
/// （`reduce_span` 是三条路共用的唯一归约），方向只改变**走过它的方向**。
///
/// # 判定量（逐条读数）
///
/// * `offset=100 end=199 direction=reverse` ⇒ 写 **99** 帧、首帧源下标 **199 ＝ `end`**、
///   末帧 **101**（⚠ `offset = 100` 那一格**读不到** —— 与 `forward` 那一侧"读不到**
///   `end` 那一格"同源：线性插值要读"下一格"）；
/// * 三条路**逐位相同**；
/// * `end=149` ⇒ 首帧 **149**、写 **49** 帧（区间真的跟着 `end` 走）；
/// * `end=-1` ⇒ **0** 帧、实时侧**0** 声部（与 `forward` 同口径）；
/// * `offset` 落在 PCM 之外 ⇒ **0** 帧（空区间 ⇒ ⛔ 不从末尾兜一圈）。
#[test]
fn s96_reverse_times_offset_and_end_follow_the_registered_reading() {
    let sample = ramp_sample(DIR_PCM_FRAMES);

    // ---- ① 主腿：`offset=100 end=199 direction=reverse` ----
    let (off, flat, rt, _n_off, n_flat, _frames) =
        dir_three_paths(DIR_FIXTURE_REVERSE, &sample, 256);
    assert_eq!(n_flat, DIR_WRITTEN_FRAMES, "实写帧数");
    assert_eq!(off, flat, "⭐ 反向：离线 → 摊平逐位相同");
    assert_eq!(flat, rt, "⭐ 反向：摊平 → 实时逐位相同");

    let reverse = prepare_with(DIR_FIXTURE_REVERSE, &sample);
    let mut out = vec![0.0f32; 256];
    let n = reverse.render_block_into(60, 127, &mut out);
    let idx: Vec<usize> = (0..n).map(|k| source_index_at(&out, k)).collect();
    println!(
        "[engine-sfz/S96] 主腿：帧数 = {n}、首帧源下标 = {}（＝ `end`）、末帧源下标 = {}（＝ `offset + 1`）",
        idx[0],
        idx[n - 1]
    );
    assert_eq!(idx[0], DIR_END_INCLUSIVE, "⭐ 首帧 ＝ `end` 那一格");
    assert_eq!(idx[n - 1], DIR_OFFSET + 1, "⭐ 末帧 ＝ `offset + 1`");
    assert!(
        !idx.contains(&DIR_OFFSET),
        "⭐ `offset` 那一格**读不到**（与 `forward` 读不到 `end` 那一格同源）"
    );

    // ---- ② `end` 变小 ⇒ 区间真的跟着走 ----
    let short = prepare_with(DIR_FIXTURE_REVERSE_SHORT_END, &sample);
    let mut short_out = vec![0.0f32; 256];
    let n_short = short.render_block_into(60, 127, &mut short_out);
    assert_eq!(n_short, 49, "`[100, 150)` ⇒ 49 帧");
    assert_eq!(
        source_index_at(&short_out, 0),
        149,
        "⭐ 反向首帧跟着 `end` 走"
    );
    assert_eq!(source_index_at(&short_out, n_short - 1), 101);

    // ---- ③ `end=-1`（不发声）与 ④ `offset` 越界（空区间）----
    let silent = prepare_with(DIR_FIXTURE_REVERSE_SILENT, &sample);
    let mut silent_out = vec![0.0f32; 256];
    assert_eq!(silent.render_block_into(60, 127, &mut silent_out), 0);
    let mut pool = SfzVoicePool::new(48_000.0);
    assert_eq!(
        pool.trigger_note(&silent, 60, 127, u64::MAX, 1.0, None),
        0,
        "⭐ `end=-1` ⇒ 实时侧不建声部（与 `forward` 同口径）"
    );
    let past = prepare_with(DIR_FIXTURE_REVERSE_OFFSET_PAST_END, &sample);
    let mut past_out = vec![0.0f32; 256];
    assert_eq!(
        past.render_block_into(60, 127, &mut past_out),
        0,
        "⭐ 空区间 ⇒ 0 帧（⛔ 不从末尾兜一圈）"
    );
    assert_eq!(
        pool.trigger_note(&past, 60, 127, u64::MAX, 1.0, None),
        0,
        "⭐ 空区间 ⇒ 不建声部"
    );

    // ---- ⑤ 三条路在小 `end` 与循环腿上同样一致 ----
    let (off_s, flat_s, rt_s, ..) = dir_three_paths(DIR_FIXTURE_REVERSE_SHORT_END, &sample, 256);
    assert_eq!(off_s, flat_s);
    assert_eq!(flat_s, rt_s);
    let (off_l, flat_l, rt_l, ..) = dir_three_paths(DIR_FIXTURE_LOOP_REVERSE, &sample, 512);
    assert_eq!(off_l, flat_l);
    assert_eq!(flat_l, rt_l);
    println!(
        "[engine-sfz/S96] `end=149` 三路一致 = {}；反向 ＋ 循环三路一致 = {}",
        off_s == rt_s,
        off_l == rt_l
    );
}

/// ⭐ S97（任务单 `#113`；判据 §5.3）：**三条路一致** ＋ 反向 ＋ 循环的回绕见证。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 三个 `direction=reverse` 夹具在三条路（离线 / 摊平 / 实时）上的输出；
/// 单位 ＝ **位模式序列**（`f32::to_bits`）＋ **源采样下标**（斜坡夹具反解）。
///
/// # 判定量
///
/// * 三条路**两两逐位相同**（三个夹具各一遍）；
/// * ⭐ 实时声部可读：`source_position() == end` 那一格（`199`）、
///   `source_end() == offset`（`100`）—— 这就是"起点 ＋ 带符号步进 ＋ 行进边界"
///   三件读数落在**已有**字段上的机械见证（⛔ 零新字段）；
/// * ⭐ **反向 ＋ `loop_continuous`**：下标序列**逐帧**等于
///   `k < 300 ? 399 − k : 163 − ((k − 300) mod 64)`（**0 处不符**）
///   ＋ ⭐ **跨过起点回绕的见证**：第 `299` 帧下标 `100`、第 `300` 帧下标 **`163`**
///   （**向上**跳 63 格，跨过 `loop_start`）；
/// * ⭐ 反空判腿：同夹具**去掉** `direction=reverse` ⇒ 三条路的位模式**必须变**。
#[test]
fn s97_the_three_paths_agree_bit_for_bit_in_reverse_and_the_loop_wraps_mirrored() {
    let sample = ramp_sample(DIR_PCM_FRAMES);
    for (label, text, frames) in [
        ("朴素反向", DIR_FIXTURE_REVERSE, 256usize),
        ("反向 ＋ offset/end", DIR_FIXTURE_REVERSE_SHORT_END, 256),
        ("反向 ＋ 循环", DIR_FIXTURE_LOOP_REVERSE, 512),
    ] {
        let (off, flat, rt, n_off, n_flat, _frames) = dir_three_paths(text, &sample, frames);
        assert_eq!(off, flat, "⭐ {label}：离线 → 摊平逐位相同");
        assert_eq!(flat, rt, "⭐ {label}：摊平 → 实时逐位相同");
        assert_eq!(off, rt, "⭐ {label}：三条路同值");
        assert_eq!(n_off, n_flat);
        println!(
            "[engine-sfz/S97] {label}：三条路位模式相同 = {}（帧数 {n_flat}）",
            off == rt
        );
    }

    // ⭐ 实时声部里的三件读数（零新字段的机械见证）。
    let reverse = prepare_with(DIR_FIXTURE_REVERSE, &sample);
    let mut pool = SfzVoicePool::new(48_000.0);
    assert_eq!(pool.trigger_note(&reverse, 60, 127, u64::MAX, 1.0, None), 1);
    let voice = pool.voices()[0];
    println!(
        "[engine-sfz/S97] 反向声部：position = {}（区间末格）、source_end = {}（下界）、\
         方向 = {:?}",
        voice.source_position(),
        voice.source_end(),
        reverse.regions()[0].direction()
    );
    assert_eq!(
        voice.source_position(),
        DIR_END_INCLUSIVE as f32,
        "⭐ 反向声部从区间**末格**起步（`end − 1` 的读法：`end` 含端点 ⇒ 末格 ＝ `end`）"
    );
    assert_eq!(
        voice.source_end(),
        DIR_OFFSET as u64,
        "⭐ 反向声部把**下界**存进既有的 `source_end` 格子（⛔ 零新字段）"
    );
    assert_eq!(
        reverse.regions()[0].direction(),
        PlayDirection::Reverse,
        "⭐ 摊平表真的带上了 `direction`（回读）"
    );

    // ⭐ 反向 ＋ 循环：逐帧下标对账 ＋ 回绕见证。
    let loop_reverse = prepare_with(DIR_FIXTURE_LOOP_REVERSE, &sample);
    let mut out = vec![0.0f32; 500];
    let n = loop_reverse.render_block_into(60, 127, &mut out);
    assert_eq!(n, 500, "循环声部在 500 帧窗口内不退休");
    let idx: Vec<i64> = (0..n).map(|k| source_index_at(&out, k) as i64).collect();
    let mut mismatches = 0usize;
    for (k, actual) in idx.iter().enumerate() {
        let expected = if k < 300 {
            399 - k as i64
        } else {
            163 - ((k - 300) % LOOP_PERIOD) as i64
        };
        if *actual != expected {
            mismatches += 1;
        }
    }
    println!(
        "[engine-sfz/S97] 反向 ＋ 循环：帧数 = {n}、下标不符 = {mismatches}（周期 {}）；\
         回绕见证 idx[298..302] = {:?}",
        LOOP_END - LOOP_START,
        &idx[298..302]
    );
    assert_eq!(mismatches, 0, "⭐ 反向循环的下标序列逐帧精确");
    assert_eq!(
        idx[299], LOOP_START as i64,
        "⭐ 回绕前最后一格 ＝ `loop_start`"
    );
    assert_eq!(
        idx[300],
        (LOOP_END - 1) as i64,
        "⭐ ⭐ 跨过起点回绕：从 `loop_start` 直接折到 `loop_end − 1`（向上 63 格）"
    );
    assert!(
        idx[300] > idx[299],
        "⭐ 回绕见证：反向的上跳（⛔ 正向的下跳）"
    );

    // ⭐ 反空判腿：去掉 `direction=reverse` ⇒ 三条路的位模式必须变。
    let forward_loop = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &sample,
    );
    let mut fwd_out = vec![0.0f32; 500];
    forward_loop.render_block_into(60, 127, &mut fwd_out);
    assert_ne!(
        bits(&out),
        bits(&fwd_out),
        "⭐ 应绿反向腿：去掉 `direction=reverse` ⇒ 位模式必须变"
    );
}

/// ⭐ S98（任务单 `#113`；判据 §5.7）：**尺寸 ＋ 零分配口径**可判。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 四个类型的 `size_of`（字节）＋ 源码里的登记句；单位 ＝ 字节 / 布尔。
#[test]
fn s98_the_direction_sizes_and_the_zero_allocation_disposition_are_judgeable() {
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S98] size_of: PreparedRegion={region}（`#109` 后 6152 → ＋8）\
         SfzVoice={voice} SfzVoicePool={pool} EngineRuntime={runtime}\
         （门槛 192 KiB = {}；余量 = {}）",
        192 * 1024,
        192 * 1024 - runtime
    );
    assert_eq!(
        region, 6160,
        "⭐ 本单唯一的代价：`PreparedRegion` `6152 → 6160`（＋8 ＝ `direction` ＋ 对齐；摊平期）"
    );
    assert_eq!(
        region,
        6152 + 8,
        "⭐ 增量腿：`direction: PlayDirection`（`size_of` ＝ 1）＋ 尾部对齐"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（零新逐声部字段）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0");
    assert_eq!(runtime, 180_144, "⛔ `EngineRuntime` 必须 ＋0");
    assert!(
        runtime < 192 * 1024,
        "⛔ `EngineRuntime` 必须 < 192 KiB（余量 {} B）",
        192 * 1024 - runtime
    );

    // ⭐ "新代码为什么无分配"的**机械**依据（源文本腿）：三件读数全是标量，
    // ⛔ 没有集合、⛔ 没有 `Vec`、⛔ 没有锁 —— 归约与逐样本判别都只做整数/浮点比较。
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    for needle in [
        "⛔ **零新逐声部字段**",
        "零分配、零锁、零 I/O**（纯整数/浮点比较与一次取负）",
    ] {
        assert!(
            MODULE_SOURCE.contains(needle),
            "⭐ 零分配口径必须逐字可判：缺少 `{needle}`"
        );
    }
    assert!(
        !MODULE_SOURCE.contains("`direction` 的实现需要一张逐区域的方向表"),
        "⭐ 反向腿：文档里没有的句子必须 `false`"
    );
}

/// ⭐ S99（任务单 `#113`；判据 §5.6）：**反向腿 ＋ 三个承重指纹 ＋ `alternate` 腿**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// * **反向腿**：去掉 `direction=reverse` 那一行 ⇒ 与 `forward` 夹具**逐位相同**
///   （位模式序列）；改写 `offset` / `loop_*` ⇒ 指纹**必变**（FNV-1a 64）。
/// * **`alternate` 腿**：`direction=alternate` ⇒ 响亮 `InvalidOption`（⛔ 不静默降级）；
///   `loop_type=alternate` ⇒ **`Ok`**（未知 opcode 忽略 ＝ 今天的行为）。
/// * **三个承重指纹**（§5.6 逐字点名）：`0xa9dec8a87f69106c` / `0xd3c2a82076bd8947` /
///   `0xa933ddab286bdf5e`。
#[test]
fn s99_the_direction_reverse_legs_the_alternate_leg_and_the_three_fingerprints() {
    let sample = ramp_sample(DIR_PCM_FRAMES);

    // ---- ① 反向腿：去掉那一行 ⇒ 与 `forward` 逐位相同 ----
    let forward = prepare_with(DIR_FIXTURE_FORWARD, &sample);
    let revealed = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 offset=100 end=199\n",
        &sample,
    );
    let mut a = vec![0.0f32; 256];
    let mut b = vec![0.0f32; 256];
    let na = forward.render_block_into(60, 127, &mut a);
    let nb = revealed.render_block_into(60, 127, &mut b);
    assert_eq!(na, nb);
    assert_eq!(
        bits(&a[..na]),
        bits(&b[..nb]),
        "⭐ 反向腿：去掉 `direction=reverse` ⇒ 与成文的 `forward` 夹具**逐位相同**"
    );
    let reverse = prepare_with(DIR_FIXTURE_REVERSE, &sample);
    let mut c = vec![0.0f32; 256];
    let nc = reverse.render_block_into(60, 127, &mut c);
    assert_eq!(
        nc, DIR_WRITTEN_FRAMES,
        "⭐ 反向臂必须**真的写满** `区间长 − 1` 帧（⛔ 挡住「静默不发声也算改了输出」）"
    );
    assert!(
        nonzero_frames(&c[..nc]) > 0,
        "⭐ 反向臂必须真的出声（否则下面那条 `assert_ne!` 是空转）"
    );
    assert_ne!(
        fnv1a_64(&a[..na]),
        fnv1a_64(&c[..nc]),
        "⭐ 有牙：`direction=reverse` 那一行**确实**改了输出（指纹必变）"
    );
    println!(
        "[engine-sfz/S99] 反向腿：forward 指纹 = 0x{:016x}、reverse 指纹 = 0x{:016x}、\
         去掉那一行后与 forward 逐位相同 = {}",
        fnv1a_64(&a[..na]),
        fnv1a_64(&c[..nc]),
        bits(&a[..na]) == bits(&b[..nb])
    );

    // ---- ② `alternate` 腿（今天的行为：响亮报错 / 未知 opcode 忽略）----
    let alternate = SfzInstrument::load(
        "<region> sample=a.wav direction=alternate".to_owned(),
        &Default::default(),
    )
    .expect_err("⭐ `alternate` **不在** `direction` 的取值域里 ⇒ 必须响亮报错");
    let sideways = SfzInstrument::load(
        "<region> sample=a.wav direction=sideways".to_owned(),
        &Default::default(),
    )
    .expect_err("集合外取值同样响亮报错");
    println!("[engine-sfz/S99] `direction=alternate` ⇒ {alternate:?}");
    println!("[engine-sfz/S99] `direction=sideways` ⇒ {sideways:?}");
    match &alternate {
        SfzError::InvalidOption {
            opcode,
            value,
            allowed,
            ..
        } => {
            assert_eq!(*opcode, "direction");
            assert_eq!(*value, "alternate");
            assert_eq!(*allowed, "forward, reverse");
        }
        other => panic!("⭐ 必须是 `InvalidOption`，实得 {other:?}"),
    }
    assert!(
        matches!(sideways, SfzError::InvalidOption { .. }),
        "⭐ 越界取值同款"
    );
    // ⚠ `loop_type`（`alternate` 的**家**）在本仓**一个字节都没解析** ⇒ 它是未知 opcode、
    // 被**忽略**（⛔ 不是 `Err`，也⛔ 不是"被当成 `direction` 的第三个取值"）。
    let loop_type = SfzInstrument::load(
        "<region> sample=a.wav key=60 loop_type=alternate".to_owned(),
        &Default::default(),
    );
    assert!(
        loop_type.is_ok(),
        "⭐ `loop_type=alternate` 今天是被忽略的未知 opcode（本仓不解析 `loop_type`）"
    );
    let loop_type_plan = prepare_with(
        "<region> sample=a.wav key=60 loop_type=alternate\n",
        &ramp_sample(DIR_PCM_FRAMES),
    );
    assert_eq!(
        loop_type_plan.regions()[0].direction(),
        PlayDirection::Forward,
        "⭐ ⛔ `loop_type=alternate` **不得**被读成 `direction`（方向仍是缺省 `forward`）"
    );

    // ---- ③ 应绿反向腿：同一输出 ×1.0000001 ⇒ 指纹必须变 ----
    let scaled: Vec<f32> = a[..na].iter().map(|v| v * 1.000_000_1).collect();
    assert_ne!(
        fnv1a_64(&a[..na]),
        fnv1a_64(&scaled),
        "⭐ 应绿反向腿：×1.0000001 ⇒ 指纹**必须变**（证明它是逐位判据）"
    );
    println!(
        "[engine-sfz/S99] ×1.0000001 后的指纹 = 0x{:016x}（必须 ≠ 0x{:016x}）",
        fnv1a_64(&scaled),
        fnv1a_64(&a[..na])
    );

    // ---- ④ 三个承重指纹：逐字复跑（S37 两臂 ＋ S33 广播路径）----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let arm1 = render_pool(&looped, 200, 512);
    let arm2 = render_pool(&plain, u64::MAX, 512);
    assert_eq!(nonzero_frames(&arm1), 200, "S37 臂 1 的非零帧数");
    assert_eq!(nonzero_frames(&arm2), 399, "S37 臂 2 的非零帧数");
    let fp1 = fnv1a_64(&arm1);
    let fp2 = fnv1a_64(&arm2);
    println!(
        "[engine-sfz/S99] 承重指纹：臂 1 = 0x{fp1:016x}（非零 {}）、臂 2 = 0x{fp2:016x}\
         （非零 {}）",
        nonzero_frames(&arm1),
        nonzero_frames(&arm2)
    );
    check_fingerprint(
        "S37 臂 1（loop_continuous + end_sample=200）",
        fp1,
        0xa9de_c8a8_7f69_106c,
    );
    check_fingerprint(
        "S37 臂 2（no_loop + end_sample=u64::MAX）",
        fp2,
        0xd3c2_a820_76bd_8947,
    );

    // S33：既有夹具 [`TWO_MATCH_ONE_MISS`] 经**实时路径** 512 帧。
    let prepared = prepare(TWO_MATCH_ONE_MISS);
    let track = EntityId::new();
    let mut engine = engine_with_track(track);
    let schedule =
        NoteSchedule::from_sorted(vec![support::scheduled(0, 12_000, 60, 1.0, 48_000.0)]);
    let mut rendered = vec![0.0f32; BLOCK];
    engine.render_track(track, Some(&schedule), Some(&prepared), &mut rendered);
    let fp3 = fnv1a_64(&rendered);
    println!(
        "[engine-sfz/S99] 承重指纹：臂 3（S33 广播路径）= 0x{fp3:016x}（非零 {}）",
        nonzero_frames(&rendered)
    );
    assert_eq!(nonzero_frames(&rendered), 478, "S33 的非零帧数");
    check_fingerprint("S33／S14 广播路径", fp3, 0xa933_ddab_286b_df5e);
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#115`：把 `#104` 的 CC 调制机制推广到**增益族目标**（首个目标 `amplitude`）
// ---------------------------------------------------------------------------

/// ⭐ S100 夹具：**基准 ＋ 调制**都有（`amplitude=50` ＋ `amplitude_oncc1=50`）。
const AMPLITUDE_BASE_MOD_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                         amp_veltrack=0 amplitude=50 amplitude_oncc1=50\n";
/// 同上**去掉调制那一行**（反向腿用；`amplitude=50` 留着）。
const AMPLITUDE_BASE_ONLY_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                          amp_veltrack=0 amplitude=50\n";
/// **缺省** `amplitude`（＝ 100 ⇒ 因子 `1.0`）的三态对照。
const AMPLITUDE_DEFAULT_FIXTURE: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n";
/// ⭐ `amplitude_curveccN` 夹具：曲线 9 ＝ `0 → 0 → 1`（`‹curve›` 页的例子形状）。
const AMPLITUDE_CURVE_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                       amp_veltrack=0 amplitude=0 amplitude_oncc1=100 \
                                       amplitude_curvecc1=9\n\
                                       <curve>curve_index=9\nv000=0\nv063=0\nv127=1\n";
/// ⭐ 不可烘焙的曲线（内建 4 ＝ Concave，规范未给公式）⇒ 该项**不贡献**任何量。
const AMPLITUDE_UNRESOLVED_CURVE_FIXTURE: &str = "<region> sample=a.wav key=60 \
                                                  pitch_keycenter=60 amp_veltrack=0 amplitude=0 \
                                                  amplitude_oncc1=100 amplitude_curvecc1=4\n";
/// ⭐ `#115` 与 `#104` **同一夹具**（criterion 6 的对照：ampeg 调制仍生效）。
const AMPLITUDE_AND_AMPEG_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 amplitude=50 \
     amplitude_oncc1=50 ampeg_attack=0.5 ampeg_attack_oncc100=0.5\n";

/// ⭐ S100（任务单 `#115`；判据 §5.1／§5.2／§5.7）：**规范逐字 ＋ 语料普查 ＋ 尺寸**可判。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 模块头源码（`include_str!`）的**登记文本** ＋ 目标枚举的读数
/// ＋ 四个结构体的 `size_of`（字节）。单位 ＝ 布尔（文本存在性）／个数（目标数）／字节。
///
/// ⭐ 前提：`#115` 的 `amplitude: f32` **落进既有尾部对齐空隙** ⇒ `PreparedRegion`
/// **仍 6160 B（＋0）**；⛔ `SfzVoice`／池／`EngineRuntime` 三条硬边界**一条未动**。
#[test]
fn s100_the_target_enum_the_census_and_the_sizes_are_judgeable() {
    const MODULE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const REVISION: &str = "⭐ ⭐ **追加修订段（任务单 `#115`）";
    const SECTION: &str = "# ⭐ 增益族目标推广（任务单 `#115`）";
    const VOLUME_RELATION: &str = "linear amplitude adjustment by ampeg... opcodes";
    const ABSENT: &str = "amplitude 这一族仍未做（另开单）";
    println!(
        "[engine-sfz/S100] 模块头：`#115` 修订段 = {}、新一节 = {}、`volume` 页逐字 = {}",
        MODULE_SOURCE.contains(REVISION),
        MODULE_SOURCE.contains(SECTION),
        MODULE_SOURCE.contains(VOLUME_RELATION),
    );
    for (label, needle) in [
        ("`#115` 追加修订段", REVISION),
        ("增益族目标推广一节", SECTION),
        ("`volume` 页的 amplitude/volume 关系逐字", VOLUME_RELATION),
        ("`amplitude_onccN` 的 Range/Unit 表行", "**-100 to 100**"),
        ("语料分母", "**1398**"),
        ("`amplitude_onccN` 次数", "**420**"),
        ("`amplitude_onccN` 文件数", "**66**"),
        ("`amplitude_ccN` 次数", "**854**"),
        ("`amplitude_ccN` 文件数", "**83**"),
        ("`amplitude_curveccN` 次数", "**30**"),
        ("静态 `amplitude=` 次数", "**1**"),
        ("三档对照：家族子串", "**2828**"),
        ("三档对照：不剥注释 token", "**844**"),
        ("三档对照：剥注释 token", "**835**"),
        ("两族并集最大值", "**11**"),
        ("条数上界不抬高", "≤ `AMPEG_MOD_CAP`（20）"),
        ("尺寸：仍 6160", "6160 B"),
    ] {
        assert!(
            MODULE_SOURCE.contains(needle),
            "⭐ 必须逐字含：{label}（`{needle}`）"
        );
    }
    assert!(
        !MODULE_SOURCE.contains(ABSENT),
        "⭐ 反向腿：文档里没有的句子必须 `false`"
    );

    // ⭐ 目标枚举：声明序就是求和序，`Amplitude` 必须在**末尾**（⇒ 既有目标位模式不变）。
    assert_eq!(ModTarget::COUNT, ModTarget::ALL.len());
    for (position, target) in ModTarget::ALL.into_iter().enumerate() {
        assert_eq!(target.index(), position, "声明序与 index 必须一致");
    }
    assert_eq!(ModTarget::Amplitude.index(), AmpegParam::COUNT);
    assert_eq!(ModTarget::Amplitude.name(), "amplitude");
    assert_eq!(ModTarget::Amplitude.ampeg(), None);
    assert!(
        !ModTarget::Amplitude.is_time(),
        "`amplitude_onccN` 的单位是 %（⛔ 不是秒）"
    );

    // ⭐ 尺寸（`size_of` 现读，⛔ 不手抄）。
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S100] size_of: PreparedRegion={region} SfzVoice={voice} \
         SfzVoicePool={pool} EngineRuntime={runtime}（门槛 192 KiB = {}；余量 = {}）",
        192 * 1024,
        192 * 1024 - runtime,
    );
    assert_eq!(
        region, 6160,
        "⭐ `#115` 的 `amplitude: f32` 落进既有尾部对齐空隙 ⇒ `PreparedRegion` **＋0**"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（仍是 40 B）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0（仍是 1712 B）");
    assert_eq!(
        runtime, 180_144,
        "⛔ `EngineRuntime` 必须 ＋0（仍是 180144 B）"
    );
    assert!(runtime < 192 * 1024, "⛔ `EngineRuntime` 必须 < 192 KiB");
}

/// ⭐ S101（任务单 `#115`；判据 §5.2）：**解析与域** —— 合法值读得进、越界／畸形响亮 `Err`、
/// 缺省 ⇒ 无调制（与接线前逐位相同）。
#[test]
fn s101_amplitude_parses_its_domain_errs_are_loud_and_absence_is_a_no_op() {
    // ---- ① 合法值读得进（四种写法；目标必须是 `Amplitude`） ----
    let instrument = SfzInstrument::load(
        "<region> sample=a.wav key=60 amplitude=50 amplitude_oncc1=50 amplitude_cc2=25 \
         amplitude_curvecc3=9 amplitude_smoothcc4=150\n"
            .to_owned(),
        &Default::default(),
    )
    .expect("合法写法必须解析成功");
    let readings: Vec<(ModTarget, u8, f32, u8)> = instrument
        .with_instrument(|parsed| {
            parsed.regions()[0]
                .cc_modulations()
                .iter()
                .map(|item| (item.target, item.cc, item.delta, item.curve))
                .collect()
        })
        .expect("重解析");
    println!(
        "[engine-sfz/S101] `(target, cc, delta, curve)` 读数 = {readings:?}（`amplitude_smoothcc4` \
         的 Type = N/A ⇒ 必须不在表里）"
    );
    assert_eq!(
        readings,
        vec![
            (ModTarget::Amplitude, 1, 50.0, 0),
            (ModTarget::Amplitude, 2, 25.0, 0),
        ],
        "⭐ 两条调制项：`_onccN`／`_ccN` 归 Delta（曲线下标缺省 0）；\
         ⛔ `amplitude_curvecc3` 只有曲线、没有 delta ⇒ 按裁决 4 **不产生**调制项；\
         ⛔ `amplitude_smoothcc4`（Type = N/A）不识别 ⇒ 一个字节都不进表"
    );
    assert_eq!(
        instrument
            .with_instrument(|parsed| parsed.regions()[0].amplitude)
            .expect("重解析"),
        50.0,
        "⭐ 静态 `amplitude=50` 必须读进 `Region::amplitude`"
    );

    // ---- ② 越界／畸形 ⇒ 响亮 `Err`（原文错误文本） ----
    for (label, text, needle) in [
        (
            "delta = 101 越界",
            "<region> sample=a.wav amplitude_oncc1=101\n",
            "line 1: `amplitude_oncc1` value 101 out of range -100..=100",
        ),
        (
            "delta = -101 越界",
            "<region> sample=a.wav amplitude_oncc1=-101\n",
            "line 1: `amplitude_oncc1` value -101 out of range -100..=100",
        ),
        (
            "delta 非数",
            "<region> sample=a.wav amplitude_oncc1=abc\n",
            "line 1: `amplitude_oncc1` expects a number, got `abc`",
        ),
        (
            "曲线下标 256 越界",
            "<region> sample=a.wav amplitude_curvecc1=256\n",
            "line 1: `amplitude_curvecc1` value 256 out of range 0..=255",
        ),
        (
            "曲线下标非整数",
            "<region> sample=a.wav amplitude_curvecc1=x\n",
            "line 1: `amplitude_curvecc1` expects an integer, got `x`",
        ),
        (
            "CC 号 300 越界",
            "<region> sample=a.wav amplitude_oncc300=10\n",
            "line 1: `amplitude_oncc300` value 300 out of range 0..=255",
        ),
    ] {
        let error = SfzInstrument::load(text.to_owned(), &Default::default())
            .expect_err(&format!("{label} 必须响亮 Err"));
        let shown = format!("{error}");
        println!("[engine-sfz/S101] {label} ⇒ `{shown}`");
        assert!(
            shown.contains(needle),
            "⭐ {label}：错误文本必须逐字含 `{needle}`（实得 `{shown}`）"
        );
    }

    // ---- ③ 缺省 ⇒ 无调制（与接线前逐位相同） ----
    let sample = constant_sample(4_096);
    let plan = prepare_with(AMPLITUDE_DEFAULT_FIXTURE, &sample);
    assert_eq!(
        plan.regions()[0].amplitude_gain_with_cc(None),
        1.0,
        "⭐ 缺省 `amplitude` ＝ 100 ⇒ 因子恰 1.0"
    );
    let probe = |_: u8| 127u8;
    let mut without = vec![0.0f32; BLOCK];
    let mut with_cc = vec![0.0f32; BLOCK];
    let written = plan.render_block_into(60, 127, &mut without);
    let written_cc = plan.render_block_into_with_cc(60, 127, Some(&probe), &mut with_cc);
    assert_eq!(written, written_cc);
    assert_eq!(
        bits(&without),
        bits(&with_cc),
        "⭐ 没有 `amplitude*` opcode ⇒ 探针一个字节都改变不了输出"
    );
    // 同一条腿：离线入口同样逐位不变。
    let instrument = SfzInstrument::load(AMPLITUDE_DEFAULT_FIXTURE.to_owned(), &Default::default())
        .expect("解析");
    let mut offline_none = vec![0.0f32; BLOCK];
    let mut offline_cc = vec![0.0f32; BLOCK];
    instrument
        .render_note_into(&sample, 60, 127, &mut offline_none, 48_000.0)
        .expect("离线旧入口");
    instrument
        .render_note_into_with_cc(&sample, 60, 127, Some(&probe), &mut offline_cc, 48_000.0)
        .expect("离线新入口");
    assert_eq!(
        bits(&offline_none),
        bits(&offline_cc),
        "⭐ 离线：没有 `amplitude*` ⇒ cc = None 与探针逐位相同"
    );
}

/// ⭐ S102（任务单 `#115`；判据 §5.3）：**真的生效且逐位等于公式**（离线路径）。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`AMPLITUDE_BASE_MOD_FIXTURE`]（`amplitude=50` ＋ `amplitude_oncc1=50`）经
/// 离线 `render_note_into_with_cc` 渲染 512 帧的输出；单位 ＝ 增益（`1.0` ＝ 满幅）。
///
/// 公式（`yeban_sfz::modulation` §5.3）：`gain = (50 + 50 × curve0(cc)) / 100`，
/// `curve0(cc) = cc/127`（缺省线性 `0 → 1`）。
#[test]
fn s102_amplitude_really_modulates_and_matches_the_formula() {
    const HZ: f32 = 48_000.0;
    const FRAMES: usize = 512;
    let sample = constant_sample(4_096);
    let instrument =
        SfzInstrument::load(AMPLITUDE_BASE_MOD_FIXTURE.to_owned(), &Default::default())
            .expect("夹具必须解析成功");
    let plan = prepare_with(AMPLITUDE_BASE_MOD_FIXTURE, &sample);
    let want = |cc: u8| (50.0f32 + 50.0f32 * (f32::from(cc) / 127.0)) / 100.0;

    for cc in [0u8, 37, 63, 127] {
        // `cc` 按值捕获 ⇒ 探针是 `Fn`（与 S67 同形，⛔ 不用全局状态）。
        let probe = move |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        let gain = plan.regions()[0].amplitude_gain_with_cc(Some(&probe));
        let mut out = vec![0.0f32; FRAMES];
        let written = instrument
            .render_note_into_with_cc(&sample, 60, 127, Some(&probe), &mut out, HZ)
            .expect("离线渲染");
        assert_eq!(written, FRAMES);
        assert_eq!(
            gain.to_bits(),
            want(cc).to_bits(),
            "⭐ cc = {cc}：摊平表读数必须逐位等于公式（实测 {gain:.9} / {:#010x}，\
             公式 {:.9} / {:#010x}）",
            gain.to_bits(),
            want(cc),
            want(cc).to_bits()
        );
        assert_eq!(
            out[0].to_bits(),
            want(cc).to_bits(),
            "⭐ cc = {cc}：恒 1.0 样本 ⇒ 第 0 帧就是振幅因子本身"
        );
        assert!(
            out.iter().all(|s| s.to_bits() == want(cc).to_bits()),
            "⭐ 512 帧每一帧都等于该 CC 处的振幅因子"
        );
        println!(
            "[engine-sfz/S102] cc = {cc}：实测增益 = {:.9}（{:#010x}）；公式 = {:.9}（{:#010x}）",
            out[0],
            out[0].to_bits(),
            want(cc),
            want(cc).to_bits()
        );
    }
    let zero = plan.regions()[0].amplitude_gain_with_cc(Some(&|_| 0));
    let full = plan.regions()[0].amplitude_gain_with_cc(Some(&|_| 127));
    assert_eq!(zero, 0.5, "⭐ CC = 0 ⇒ `(50 + 0)/100` ＝ 0.5");
    assert_eq!(full, 1.0, "⭐ CC = 127 ⇒ `(50 + 50)/100` ＝ 1.0");
    assert_ne!(zero, full, "⭐ 两个 CC 值必须给出不同增益（有牙）");
}

/// ⭐ S103（任务单 `#115`；判据 §5.4）：**三条路一致** —— 同一 CC 下
/// 离线 ／ 摊平 ／ 实时**位模式逐位相同**（`cc ∈ {0, 37, 100, 127}`）。
#[test]
fn s103_the_three_paths_agree_bit_for_bit_for_amplitude() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 127;
    const FRAMES: usize = 512;
    let sample = constant_sample(4_096);
    let instrument =
        SfzInstrument::load(AMPLITUDE_BASE_MOD_FIXTURE.to_owned(), &Default::default())
            .expect("夹具必须解析成功");
    let plan = prepare_with(AMPLITUDE_BASE_MOD_FIXTURE, &sample);
    assert_eq!(plan.regions()[0].cc_modulations().len(), 1);
    let mut arms: Vec<Vec<u32>> = Vec::new();
    for cc_value in [0u8, 37, 100, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc_value } else { 0 } };
        let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);
        let mut offline = vec![0.0f32; FRAMES];
        let written_offline = instrument
            .render_note_into_with_cc(&sample, 60, VELOCITY, cc_arg, &mut offline, HZ)
            .expect("离线渲染");
        let mut flat = vec![0.0f32; FRAMES];
        let written_flat = plan.render_block_into_with_cc(60, VELOCITY, cc_arg, &mut flat);
        let mut pool = SfzVoicePool::new(HZ);
        assert_eq!(
            pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, None),
            1,
            "单区域夹具 ⇒ 恰好建 1 个声部"
        );
        let mut realtime = vec![0.0f32; FRAMES];
        pool.render_into_with_cc(&plan, 0, &mut realtime, cc_arg);
        assert_eq!(written_offline, FRAMES);
        assert_eq!(written_flat, FRAMES);
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ cc = {cc_value}：离线 → 摊平"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ cc = {cc_value}：摊平 → 实时"
        );
        assert_eq!(
            bits(&offline),
            bits(&realtime),
            "⭐ cc = {cc_value}：三条路同值"
        );
        println!(
            "[engine-sfz/S103] cc = {cc_value}：三条路位模式相同 = {}；第 0 帧 = {:.9}（{:#010x}）",
            bits(&offline) == bits(&realtime),
            realtime[0],
            realtime[0].to_bits()
        );
        arms.push(bits(&realtime));
    }
    assert_ne!(
        arms[0], arms[3],
        "⭐ 有牙：cc = 0 与 cc = 127 的实时输出必须逐位不同"
    );
    assert_ne!(arms[1], arms[2], "⭐ 中间两个 CC 值也必须分道");
}

/// ⭐ S104（任务单 `#115`；判据 §5.3／§5.4 的曲线腿）：`amplitude_curveccN` 真的
/// **shapes the controller input**；不可烘焙的曲线**不贡献**任何量（⛔ 不当成曲线 0）。
#[test]
fn s104_the_curve_shapes_the_controller_input_and_an_unresolved_curve_contributes_nothing() {
    const HZ: f32 = 48_000.0;
    const FRAMES: usize = 512;
    let sample = constant_sample(4_096);

    // ---- ① 曲线 9（`0 → 0 → 1`）：cc = 0 ⇒ 0.0、cc = 63 ⇒ 0.0、cc = 95 ⇒ 0.5、cc = 127 ⇒ 1.0 ----
    let plan = prepare_with(AMPLITUDE_CURVE_FIXTURE, &sample);
    for (cc, want) in [(0u8, 0.0f32), (63, 0.0), (95, 0.5), (127, 1.0)] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        let gain = plan.regions()[0].amplitude_gain_with_cc(Some(&probe));
        assert_eq!(
            gain.to_bits(),
            want.to_bits(),
            "⭐ 曲线 9 在 cc = {cc} 处 ⇒ 振幅因子 {want}（实测 {gain}）"
        );
        // 三条路同值（曲线在摊平期烘进区域表 ⇒ 离线与摊平必须一致）。
        let instrument =
            SfzInstrument::load(AMPLITUDE_CURVE_FIXTURE.to_owned(), &Default::default())
                .expect("解析");
        let mut offline = vec![0.0f32; FRAMES];
        instrument
            .render_note_into_with_cc(&sample, 60, 127, Some(&probe), &mut offline, HZ)
            .expect("离线");
        let mut flat = vec![0.0f32; FRAMES];
        plan.render_block_into_with_cc(60, 127, Some(&probe), &mut flat);
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ 曲线腿 cc = {cc}：离线 → 摊平必须逐位相同"
        );
        println!(
            "[engine-sfz/S104] 曲线 9，cc = {cc}：因子 = {gain:.9}（{:#010x}）；\
             离线＝摊平 = {}",
            gain.to_bits(),
            bits(&offline) == bits(&flat)
        );
    }

    // ---- ② 不可烘焙的曲线（内建 4 ＝ Concave）：项**不贡献** ⇒ 因子恒 0.0 ----
    let plan = prepare_with(AMPLITUDE_UNRESOLVED_CURVE_FIXTURE, &sample);
    assert!(
        !plan.regions()[0].cc_modulations()[0].curve.is_resolved(),
        "⭐ 内建 4 规范未给公式 ⇒ 曲线不可烘焙（登记在 `curve.rs`）"
    );
    assert_eq!(
        plan.regions()[0].ampeg_unresolved_mods(),
        1,
        "⭐ 不可烘焙的项必须**如实计数**（⛔ 不静默当成曲线 0）"
    );
    for cc in [0u8, 64, 127] {
        let probe = |_: u8| cc;
        assert_eq!(
            plan.regions()[0].amplitude_gain_with_cc(Some(&probe)),
            0.0,
            "⭐ 不可烘焙 ⇒ 不贡献任何量（`amplitude=0` ⇒ 恒 0）；cc = {cc}"
        );
    }
}

/// ⭐ S105（任务单 `#115`；判据 §5.5／§5.6）：**反向腿 ＋ 三个承重指纹 ＋ 既有 `ampeg_*` 未扰动**。
#[test]
fn s105_the_reverse_leg_the_three_fingerprints_and_ampeg_are_untouched() {
    // ---- ① 三个承重指纹（夹具里没有任何 `amplitude*` ⇒ 必须逐字不变） ----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    assert_eq!(
        looped.regions()[0].amplitude_gain_with_cc(None),
        1.0,
        "⭐ 既有夹具没有 `amplitude` ⇒ 因子 1.0"
    );
    for (label, plan, end_sample, expected) in [
        ("S37 臂 1", &looped, 200u64, 0xa9de_c8a8_7f69_106cu64),
        ("S37 臂 2", &plain, u64::MAX, 0xd3c2_a820_76bd_8947u64),
    ] {
        let out = render_pool(plan, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!("[engine-sfz/S105] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）");
        let _checked = check_fingerprint(&format!("S105 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let legacy = fnv1a_64(&legacy_block);
    println!(
        "[engine-sfz/S105] S33／S14 广播路径 512 帧 @ (60,127)：指纹 = 0x{legacy:016x}（承重 = \
         0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）；写入 = {legacy_frames}"
    );
    let _checked = check_fingerprint("S105 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    // ⭐ 应绿反向腿：× 1.0000001 ⇒ 指纹必须变（证明上面三条是逐位判据）。
    let scaled: Vec<f32> = legacy_block
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    let scaled_hash = fnv1a_64(&scaled);
    println!("[engine-sfz/S105] 反向腿（× 1.0000001）：0x{scaled_hash:016x} ≠ 0x{legacy:016x}");
    assert_ne!(scaled_hash, legacy, "⭐ 反向腿：乘 1.0000001 后指纹必须变");

    // ---- ② 反向腿：去掉那一行 ⇒ 两个 CC 值**逐位相同** ----
    let sample = constant_sample(4_096);
    let with_mod = prepare_with(AMPLITUDE_BASE_MOD_FIXTURE, &sample);
    let without_mod = prepare_with(AMPLITUDE_BASE_ONLY_FIXTURE, &sample);
    let render = |plan: &PreparedSfz, cc: u8| -> Vec<u32> {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        let mut out = vec![0.0f32; BLOCK];
        plan.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        bits(&out)
    };
    let mod_zero = render(&with_mod, 0);
    let mod_full = render(&with_mod, 127);
    let plain_zero = render(&without_mod, 0);
    let plain_full = render(&without_mod, 127);
    assert_ne!(mod_zero, mod_full, "⭐ 有那一行 ⇒ 两个 CC 值必须不同");
    assert_eq!(
        plain_zero, plain_full,
        "⭐ 去掉那一行 ⇒ 两个 CC 值**逐位相同**（`amplitude=50` 恒 0.5）"
    );
    assert_eq!(
        without_mod.regions()[0].amplitude_gain_with_cc(Some(&|_| 0)),
        0.5,
        "⭐ 只剩基准 `amplitude=50` ⇒ 因子恒 0.5"
    );
    assert_eq!(
        mod_zero, plain_zero,
        "⭐ 登记的读数：cc = 0 时调制项贡献恰 0 ⇒ 与「只有基准」逐位相同\
         （所以有牙腿必须用 cc = 127 那一臂）"
    );
    assert_ne!(
        mod_full, plain_full,
        "⭐ 有牙：那一行必须真的改变读数（⛔ 不是探针管道自造的差异）"
    );

    // ---- ③ 既有 `ampeg_*` 未扰动：同一夹具里 ampeg 调制仍按自己的公式走 ----
    let plan = prepare_with(AMPLITUDE_AND_AMPEG_FIXTURE, &sample);
    for cc in [0u8, 37, 127] {
        let probe = |controller: u8| -> u8 {
            if controller == 100 || controller == 1 {
                cc
            } else {
                0
            }
        };
        let (attack, unresolved) =
            plan.regions()[0].ampeg_value_with_cc(AmpegParam::Attack, Some(&probe));
        let want_attack = 0.5f32 + 0.5f32 * (f32::from(cc) / 127.0);
        assert_eq!(unresolved, 0);
        assert_eq!(
            attack.to_bits(),
            want_attack.to_bits(),
            "⭐ cc = {cc}：同一夹具里 `ampeg_attack` 仍走自己的公式"
        );
        let want_amplitude = (50.0f32 + 50.0f32 * (f32::from(cc) / 127.0)) / 100.0;
        assert_eq!(
            plan.regions()[0]
                .amplitude_gain_with_cc(Some(&probe))
                .to_bits(),
            want_amplitude.to_bits(),
            "⭐ cc = {cc}：`amplitude` 走自己的公式，⛔ 不互相顶替"
        );
        println!(
            "[engine-sfz/S105] 混合夹具 cc = {cc}：ampeg_attack = {attack:.9}、\
             amplitude 因子 = {want_amplitude:.9}"
        );
    }
}

// ---------------------------------------------------------------------------
// ⭐⭐ 任务单 `#116`：**`tune` 目标**（`tune` ／ `tune_ccN` ／ `tune_onccN` ／
// `tune_curveccN`）—— 把 `#104`／`#115` 那套 `_onccN` 机制**再推广一个目标**。
// ---------------------------------------------------------------------------
//
// ⭐ **规范事实（本单最重要的一条）**：`tune` 页的 **Modulation 表里没有
// `tune_onccN` / `tune_ccN` / `tune_curveccN` 行**，它列的是 `pitch` 族
// （`pitch_onccN`：Range **-9600 to 9600**、Unit **cents**）；`tune` 族与被别名者的
// 关系**只有一句**「In ARIA, `tune_*ccN` can also be used as an alias for `pitch_*ccN`.」
// ⇒ `tune` 的 `delta` 域随 `pitch_onccN`（±9600 音分），⛔ **不是** `tune` 基准自己的
// ±100（同页例子 `pitch_oncc27=200` 就超出了它）。完整依据链 ＋ 语料普查见
// `../../yeban-sfz/src/modulation.rs` 的模块文档 §6 与
// `../src/sfz_instrument.rs` 的「⭐⭐ `tune` 目标（任务单 `#116`）」一节。

/// ⭐ `#116` 的速率夹具：440 Hz 正弦 @ 48 kHz ⇒ 源周期恰 `48000 / 440 ≈ 109.0909` 帧
/// （半周期 `≈ 54.545` 帧 ⇒ **首次下穿**在源下标 **55**）。
const TUNE_SINE_HZ: f32 = 440.0;
const TUNE_SAMPLE_HZ: f32 = 48_000.0;
const TUNE_PCM_FRAMES: usize = 4_096;

/// ⭐ `+1200` 音分 ＝ **一个八度** ⇒ 乘子恰 `2.0`（速率翻倍 ⇒ 输出周期减半）。
const TUNE_OCTAVE_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
                                   tune_oncc1=1200\n";
/// ⭐ 反向腿：同文本**去掉** `tune_oncc1` 那一行（只剩静态 `tune`）。
const TUNE_BASE_ONLY_FIXTURE: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n";
/// ⭐ 四种合法写法 ＋ 静态基准（`tune=25`）。
const TUNE_FORMS_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 tune=25 \
     tune_oncc1=1200 tune_cc2=-2400 tune_curvecc3=9 tunecc4=600 \
     tune_smoothcc5=10 tune_stepcc6=1\n";
/// ⭐ 未扰动对照：同一夹具里 `amplitude` 与 `ampeg_attack` **各走自己的公式**。
const TUNE_MIXED_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
     amplitude=50 amplitude_oncc1=50 tune_oncc2=1200 \
     ampeg_attack=0.5 ampeg_attack_oncc3=0.5\n";

/// ⭐ `#116` 的可读量 ①：输出里**第一次为负**的帧下标（正弦自 0 起升 ⇒ 半个输出周期）。
fn tune_first_negative(out: &[f32]) -> Option<usize> {
    out.iter().position(|sample| *sample < 0.0)
}

/// ⭐ `#116` 的可读量 ②：**上升零交叉**次数（`< 0` → `>= 0`）。
fn tune_rising_crossings(out: &[f32]) -> usize {
    out.windows(2)
        .filter(|pair| pair[0] < 0.0 && pair[1] >= 0.0)
        .count()
}

/// ⭐ S106（任务单 `#116`；判据 §1／§5／§7）：**规范逐字 ＋ 语料普查 ＋ 尺寸可判**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ `../src/sfz_instrument.rs` 与 `../../yeban-sfz/src/modulation.rs` 的
/// **源文本**；单位 ＝ `contains`（布尔，逐字）＋ `size_of`（字节）＋
/// `ModTarget::ALL`（枚举序）。
#[test]
fn s106_the_tune_spec_the_census_and_the_sizes_are_judgeable() {
    const ENGINE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const MODULATION_SOURCE: &str = include_str!("../../yeban-sfz/src/modulation.rs");
    const REVISION: &str = "⭐ ⭐ **追加修订段（任务单 `#116`）";
    const SECTION: &str = "# ⭐⭐ `tune` 目标（任务单 `#116`）—— 第二个被推广的目标";
    const TUNE_ROW: &str = "| tune | SFZ v1 | integer | 0 | -100 to 100 | cents |";
    const ALIAS: &str = "In ARIA, `tune_*ccN` can also be used as an alias for `pitch_*ccN`.";
    const RANGE_9600: &str = "`-9600 to 9600`";
    const REVISED_BRANCH: &str =
        "⛔ **`pan_oncc*` ／ `volume_oncc*` ／ `tune_oncc*` ／ `cutoff_oncc*` ／ `pitch_oncc*`";
    const STILL_UNDONE: &str =
        "⛔ **`pan_oncc*` ／ `volume_oncc*` ／ `cutoff_oncc*` ／ `pitch_oncc*` 那四项";
    const ABSENT: &str = "`tune_oncc*` 那一项仍未做（另开单）";
    println!(
        "[engine-sfz/S106] 模块头：`#116` 修订段 = {}、新一节 = {}、`tune` 表行 = {}、\
         别名句 = {}、`pitch_onccN` 的 Range = {}",
        ENGINE_SOURCE.contains(REVISION),
        ENGINE_SOURCE.contains(SECTION),
        ENGINE_SOURCE.contains(TUNE_ROW),
        ENGINE_SOURCE.contains(ALIAS),
        ENGINE_SOURCE.contains(RANGE_9600),
    );
    for (label, needle) in [
        ("`#116` 追加修订段", REVISION),
        ("`tune` 目标一节", SECTION),
        ("`tune` 自己的规范表行（逐字）", TUNE_ROW),
        ("ARIA 别名句（逐字）", ALIAS),
        ("`pitch_onccN` 的 Range（逐字）", RANGE_9600),
        ("`#115` 登记的原文仍在（第 278 条）", REVISED_BRANCH),
        ("被修订的只是 `tune_oncc*` 那一项", STILL_UNDONE),
        // ---- 语料普查的原始读数（第 271／274 条：口径 ＋ 分母 ＋ 对照） ----
        ("语料分母", "**1398**"),
        ("`tune_onccN` 次数", "**9442**"),
        ("`tune_onccN` 文件数", "**83**"),
        ("`tune_ccN` 次数", "**608**"),
        ("`tune_ccN` 文件数", "**87**"),
        ("`tune_curveccN` 次数", "**218**"),
        ("`tune_curveccN` 文件数", "**45**"),
        ("静态 `tune=` 次数", "**4120**"),
        ("静态 `tune=` 文件数", "**154**"),
        ("裸 `tuneccN` 零处", "**0** 次 ／ **0** 文件"),
        ("`pitch_onccN` 对照", "**39** 次 ／ **1** 文件"),
        ("三档对照：家族子串", "**2828**"),
        ("三档对照：不剥注释 token", "**844**"),
        ("三档对照：剥注释 token", "**835**"),
        ("`|delta| > 100` 的处数", "**599**"),
        ("最大 `|delta|`", "**2400** 音分"),
        ("三族并集最大值", "**15**"),
        ("条数上界不抬高", "≤ `AMPEG_MOD_CAP`（20）"),
        ("尺寸：仍 6160", "6160 B"),
    ] {
        assert!(
            ENGINE_SOURCE.contains(needle),
            "⭐ 必须逐字含：{label}（`{needle}`）"
        );
    }
    assert!(
        !ENGINE_SOURCE.contains(ABSENT),
        "⭐ 反向腿：文档里没有的句子必须 `contains == false`（否则判据恒真）"
    );
    // ⭐ 唯一事实源（`yeban-sfz`）那一侧：§6 的标题、表行、别名句、域裁定与语料读数。
    assert!(
        MODULATION_SOURCE.contains("## 6. ⭐⭐ `tune` 目标（任务单 `#116`）"),
        "⭐ `yeban-sfz::modulation` 的模块文档必须有 §6"
    );
    for needle in [
        "| `pitch_onccN` | SFZ v2 | N/A | N/A | **-9600 to 9600** | **cents** |",
        "> In ARIA, `tune_*ccN` can also be used as an alias for `pitch_*ccN`.",
        "**599** 处、",
        "最大 **2400**",
        "`-9600..=9600` 音分",
    ] {
        assert!(
            MODULATION_SOURCE.contains(needle),
            "⭐ `yeban-sfz` 侧必须逐字含：`{needle}`"
        );
    }

    // ⭐ 目标枚举：声明序就是求和序，`Tune` 必须在**最后**（⇒ 既有目标位模式不变）。
    assert_eq!(ModTarget::COUNT, ModTarget::ALL.len());
    for (position, target) in ModTarget::ALL.into_iter().enumerate() {
        assert_eq!(target.index(), position, "声明序与 index 必须一致");
    }
    assert_eq!(
        ModTarget::ALL[5],
        ModTarget::Amplitude,
        "⭐ `#115` 登记的「新目标必须在末尾」里的 `ALL[5] == Amplitude` **原样成立**\
         （＝既有六个目标的下标一个都没动）"
    );
    assert_eq!(ModTarget::ALL[6], ModTarget::Tune);
    assert_eq!(ModTarget::Tune.index(), AmpegParam::COUNT + 1);
    assert_eq!(ModTarget::Tune.name(), "tune");
    assert_eq!(ModTarget::Tune.ampeg(), None);
    assert!(!ModTarget::Tune.is_time(), "`tune_onccN` 的单位是音分");
    assert_eq!(ModTarget::Tune.unit(), "cents");
    assert_eq!(
        ModTarget::Tune.delta_range(),
        (-9600.0, 9600.0),
        "⭐ `tune` 的域随被别名的 `pitch_onccN`（±9600 音分）"
    );
    println!(
        "[engine-sfz/S106] `ModTarget`：COUNT = {}、`ALL[5]` = {:?}、`ALL[6]` = {:?}；\
         `Tune.unit()` = {:?}、`Tune.delta_range()` = {:?}",
        ModTarget::COUNT,
        ModTarget::ALL[5].name(),
        ModTarget::ALL[6].name(),
        ModTarget::Tune.unit(),
        ModTarget::Tune.delta_range(),
    );

    // ⭐ 尺寸（`size_of` 现读，⛔ 不手抄）。
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S106] size_of: PreparedRegion={region} SfzVoice={voice} \
         SfzVoicePool={pool} EngineRuntime={runtime}（门槛 192 KiB = {}；余量 = {}）",
        192 * 1024,
        192 * 1024 - runtime,
    );
    assert_eq!(
        region, 6160,
        "⭐ `#116` ⛔ 没有新增任何每区域字段（基准 `tune` 早在 `rate_per_note` 里、\
         调制项早在 `cc_mods` 里）⇒ `PreparedRegion` **＋0**"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（仍是 40 B）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0（仍是 1712 B）");
    assert_eq!(
        runtime, 180_144,
        "⛔ `EngineRuntime` 必须 ＋0（仍是 180144 B）"
    );
    assert!(runtime < 192 * 1024, "⛔ `EngineRuntime` 必须 < 192 KiB");
}

/// ⭐ S107（任务单 `#116`；判据 §2）：**解析与域** —— 四种写法读得进、越界／畸形响亮
/// `Err`（逐字错误文本）、缺省 ⇒ 无调制（与接线前**逐位相同**）。
#[test]
fn s107_tune_parses_its_domain_errs_are_loud_and_absence_is_a_no_op() {
    // ---- ① 合法值读得进（四种写法；目标必须是 `Tune`；域是 ±9600 **音分**） ----
    let instrument = SfzInstrument::load(TUNE_FORMS_FIXTURE.to_owned(), &Default::default())
        .expect("合法写法必须解析成功");
    let readings: Vec<(ModTarget, u8, f32, u8)> = instrument
        .with_instrument(|parsed| {
            parsed.regions()[0]
                .cc_modulations()
                .iter()
                .map(|item| (item.target, item.cc, item.delta, item.curve))
                .collect()
        })
        .expect("重解析");
    println!(
        "[engine-sfz/S107] `(target, cc, delta, curve)` 读数 = {readings:?}\
         （`tune_smoothcc5` / `tune_stepcc6` 的表行不存在 ⇒ 必须不在表里）"
    );
    assert_eq!(
        readings,
        vec![
            (ModTarget::Tune, 1, 1200.0, 0),
            (ModTarget::Tune, 2, -2400.0, 0),
            (ModTarget::Tune, 4, 600.0, 0),
        ],
        "⭐ 三条调制项：`_onccN` / `_ccN` / 裸 `ccN` 归 Delta（曲线下标缺省 0）；\
         ⛔ `tune_curvecc3` 只有曲线、没有 delta ⇒ 按裁决 4 **不产生**调制项；\
         ⛔ `tune_smoothcc5` / `tune_stepcc6`（`tune` 页没有这两行）不识别 ⇒ 一个字节都不进表"
    );
    assert_eq!(
        readings[1].2, -2400.0,
        "⭐ 有牙：`−2400` 音分**超出** `tune` 自身的 ±100（语料最大值的量级）⇒ \
         域必须是 ±9600，否则这一行会响亮 `Err`"
    );
    assert_eq!(
        instrument
            .with_instrument(|parsed| parsed.regions()[0].tune)
            .expect("重解析"),
        25,
        "⭐ 静态 `tune=25` 必须读进 `Region::tune`（⛔ 不被 `tune*` 族的识别吞掉）"
    );

    // ---- ② 越界／畸形 ⇒ 响亮 `Err`（原文错误文本） ----
    for (label, text, needle) in [
        (
            "delta = 9601 越界（tune 的 ±9600 上界）",
            "<region> sample=a.wav tune_oncc1=9601\n",
            "line 1: `tune_oncc1` value 9601 out of range -9600..=9600",
        ),
        (
            "delta = -9601 越界",
            "<region> sample=a.wav tune_oncc1=-9601\n",
            "line 1: `tune_oncc1` value -9601 out of range -9600..=9600",
        ),
        (
            "delta 非数",
            "<region> sample=a.wav tune_oncc1=abc\n",
            "line 1: `tune_oncc1` expects a number, got `abc`",
        ),
        (
            "曲线下标 256 越界",
            "<region> sample=a.wav tune_curvecc1=256\n",
            "line 1: `tune_curvecc1` value 256 out of range 0..=255",
        ),
        (
            "曲线下标非整数",
            "<region> sample=a.wav tune_curvecc1=x\n",
            "line 1: `tune_curvecc1` expects an integer, got `x`",
        ),
        (
            "CC 号 300 越界",
            "<region> sample=a.wav tune_oncc300=10\n",
            "line 1: `tune_oncc300` value 300 out of range 0..=255",
        ),
        // ⭐ ⭐ **逐目标域的对照腿**：`amplitude` 的域**没有**被 `tune` 抬高。
        (
            "`amplitude` 仍是 ±100（域⛔ 不共享）",
            "<region> sample=a.wav amplitude_oncc1=101\n",
            "line 1: `amplitude_oncc1` value 101 out of range -100..=100",
        ),
        (
            "`ampeg_attack` 仍是 ±100",
            "<region> sample=a.wav ampeg_attack_oncc1=101\n",
            "line 1: `ampeg_attack_oncc1` value 101 out of range -100..=100",
        ),
    ] {
        let error = SfzInstrument::load(text.to_owned(), &Default::default())
            .expect_err(&format!("{label} 必须响亮 Err"));
        let shown = format!("{error}");
        println!("[engine-sfz/S107] {label} ⇒ `{shown}`");
        assert!(
            shown.contains(needle),
            "⭐ {label}：错误文本必须逐字含 `{needle}`（实得 `{shown}`）"
        );
    }

    // ---- ③ 域内边界都读得进（闭区间） ----
    for (value, want) in [(9600.0f32, 9600.0f32), (-9600.0, -9600.0), (0.0, 0.0)] {
        let text = format!("<region> sample=a.wav tune_oncc1={value}\n");
        let loaded = SfzInstrument::load(text, &Default::default())
            .unwrap_or_else(|error| panic!("边界值 {value} 必须合法：{error}"));
        let delta = loaded
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].delta)
            .expect("重解析");
        assert_eq!(delta, want, "⭐ 闭区间端点必须原样读进");
    }

    // ---- ④ 缺省 ⇒ 无调制：`cc = None` 与任何探针**逐位相同**（与接线前同口径） ----
    let sample = InMemorySample::sine(TUNE_SINE_HZ, TUNE_SAMPLE_HZ, TUNE_PCM_FRAMES);
    let plain = prepare_with(TUNE_BASE_ONLY_FIXTURE, &sample);
    assert!(
        plain.regions()[0].cc_modulations().is_empty(),
        "⭐ 缺省 ⇒ 空表（一项都不进 `cc_mods`）"
    );
    assert_eq!(
        plain.regions()[0].tune_ratio_with_cc(None),
        1.0,
        "⭐ 无探针 ⇒ 乘子恰 1.0"
    );
    let mut arms: Vec<Vec<u32>> = Vec::new();
    for cc_value in [0u8, 1, 63, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc_value } else { 0 } };
        assert_eq!(
            plain.regions()[0]
                .tune_ratio_with_cc(Some(&probe))
                .to_bits(),
            1.0f32.to_bits(),
            "⭐ cc = {cc_value}：空表 ⇒ 乘子逐位是 1.0（`0.0f32.exp2()`）"
        );
        let mut out = vec![0.0f32; BLOCK];
        plain.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        arms.push(bits(&out));
    }
    assert!(
        arms.windows(2).all(|pair| pair[0] == pair[1]),
        "⭐ 缺省 ⇒ 任意 CC 值给出**逐位相同**的输出（一项算术都不多做）"
    );
    let mut legacy = vec![0.0f32; BLOCK];
    let legacy_frames = plain.render_block_into(60, 127, &mut legacy);
    assert_eq!(
        arms[0],
        bits(&legacy),
        "⭐ 新入口（`cc = Some`）与旧入口（`cc = None`）**逐位相同**；写入 {legacy_frames} 帧"
    );
}

/// ⭐ S108（任务单 `#116`；判据 §3）：**音高真的变了，且逐位等于公式**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ [`TUNE_OCTAVE_FIXTURE`]（`key=60 pitch_keycenter=60 tune_oncc1=1200`）经
/// **摊平表**渲染 512 帧的输出；单位 ＝
/// ① **速率乘子**（无量纲，`1.0` ＝ 不变）＋
/// ② **输出帧下标**（首次为负的那一帧；源半周期 `≈ 54.545` 帧）＋
/// ③ **上升零交叉次数**（个）。
///
/// 公式（`yeban_sfz::modulation` §6.4）：`ratio = 2 ^ (delta × curve0(cc) / 1200)`，
/// `curve0(cc) = cc/127`（缺省线性 `0 → 1`）；`+1200` 音分 ⇒ **一个八度** ⇒ `2.0`。
#[test]
fn s108_tune_really_shifts_the_rate_and_matches_the_formula() {
    let sample = InMemorySample::sine(TUNE_SINE_HZ, TUNE_SAMPLE_HZ, TUNE_PCM_FRAMES);
    let plan = prepare_with(TUNE_OCTAVE_FIXTURE, &sample);
    assert_eq!(plan.regions()[0].cc_modulations().len(), 1);
    let mods = plan.regions()[0].cc_modulations().to_vec();
    let half_period_source = TUNE_SAMPLE_HZ / (2.0 * TUNE_SINE_HZ);
    println!(
        "[engine-sfz/S108] 源几何：{TUNE_SINE_HZ} Hz @ {TUNE_SAMPLE_HZ} Hz ⇒ 周期 = {:.6} 帧、\
         半周期 = {half_period_source:.6} 帧（源下标 55 处首次为负）",
        TUNE_SAMPLE_HZ / TUNE_SINE_HZ
    );

    let mut seen: Vec<(u8, f32, Option<usize>, usize)> = Vec::new();
    for cc in [0u8, 37, 63, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        let ratio = plan.regions()[0].tune_ratio_with_cc(Some(&probe));
        let mut out = vec![0.0f32; BLOCK];
        let written = plan.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        assert_eq!(written, BLOCK);

        // ⭐ 逐位等于公式：`2 ^ (delta × curve0(cc) / 1200)`（`curve0(cc) == cc/127`）。
        let want = ((1200.0f32 * (f32::from(cc) / 127.0)) / 1200.0).exp2();
        assert_eq!(
            ratio.to_bits(),
            want.to_bits(),
            "⭐ cc = {cc}：乘子必须逐位等于公式（实测 {ratio:.9} / {:#010x}，\
             公式 {want:.9} / {:#010x}）",
            ratio.to_bits(),
            want.to_bits()
        );
        // ⭐ 非循环论证的第二条：直接读表里的 `delta` 与烘焙曲线，按同一条公式再算一次。
        let cents = mods[0].delta * mods[0].curve.value_at(f32::from(cc));
        let from_table = (cents / 1200.0).exp2();
        assert_eq!(
            ratio.to_bits(),
            from_table.to_bits(),
            "⭐ cc = {cc}：乘子必须等于「表里的 delta × 曲线」算出的比（{cents} 音分）"
        );

        let first = tune_first_negative(&out);
        let crossings = tune_rising_crossings(&out);
        println!(
            "[engine-sfz/S108] cc = {cc:3}：delta×curve = {cents:8.3} 音分 ⇒ 乘子 = {ratio:.9}\
             （{:#010x}）；首次为负 = {first:?}；上升零交叉 = {crossings}",
            ratio.to_bits()
        );
        seen.push((cc, ratio, first, crossings));
    }
    // ⭐ 有牙（可读量）：`+1200` 音分是一个八度 ⇒ 输出周期**减半** ⇒
    // 同一个下穿地标从源下标 `55` 提前到 `28`（`⌈54.545/2⌉`）。
    assert_eq!(
        seen[0].2,
        Some(55),
        "⭐ cc = 0 ⇒ 乘子 1.0 ⇒ 首次为负仍在源下标 55"
    );
    assert_eq!(
        seen[3].2,
        Some(28),
        "⭐ cc = 127 ⇒ 乘子 2.0 ⇒ 首次为负提前到 28（半周期 54.545/2 → ⌈27.27⌉）"
    );
    assert_ne!(
        seen[0].2, seen[3].2,
        "⭐ 两个 CC 值必须给出不同的零交叉位置（音高真的动了）"
    );
    assert_eq!(seen[0].1, 1.0, "⭐ cc = 0 ⇒ 乘子恰 1.0");
    assert_eq!(seen[3].1, 2.0, "⭐ cc = 127 ⇒ 乘子恰 2.0（一个八度）");
    // ⭐ 上升零交叉次数：周期减半 ⇒ 512 帧里约翻倍（整数效应 ⇒ 用 `≥ 2n − 1` 的有牙不等式）。
    assert!(
        seen[3].3 >= 2 * seen[0].3 - 1,
        "⭐ cc = 127 的上升零交叉次数（{}）必须约为 cc = 0（{}）的两倍",
        seen[3].3,
        seen[0].3
    );
    println!(
        "[engine-sfz/S108] 可读量对账：乘子 1.0 → 2.0；首次为负 55 → 28；\
         上升零交叉 {} → {}",
        seen[0].3, seen[3].3
    );
}

/// ⭐ S109（任务单 `#116`；判据 §4 —— **本单核心**）：**三条路一致** —— 同一 CC 下
/// 离线 ／ 摊平 ／ 实时**位模式逐位相同**（`cc ∈ {0, 37, 100, 127}`）。
#[test]
fn s109_the_three_paths_agree_bit_for_bit_for_tune() {
    const HZ: f32 = 48_000.0;
    const VELOCITY: u8 = 127;
    const FRAMES: usize = 512;
    let sample = InMemorySample::sine(TUNE_SINE_HZ, TUNE_SAMPLE_HZ, TUNE_PCM_FRAMES);
    let instrument = SfzInstrument::load(TUNE_OCTAVE_FIXTURE.to_owned(), &Default::default())
        .expect("夹具必须解析成功");
    let plan = prepare_with(TUNE_OCTAVE_FIXTURE, &sample);
    assert_eq!(plan.regions()[0].cc_modulations().len(), 1);
    let mut arms: Vec<Vec<u32>> = Vec::new();
    for cc_value in [0u8, 37, 100, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc_value } else { 0 } };
        let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);
        let mut offline = vec![0.0f32; FRAMES];
        let written_offline = instrument
            .render_note_into_with_cc(&sample, 60, VELOCITY, cc_arg, &mut offline, HZ)
            .expect("离线渲染");
        let mut flat = vec![0.0f32; FRAMES];
        let written_flat = plan.render_block_into_with_cc(60, VELOCITY, cc_arg, &mut flat);
        let mut pool = SfzVoicePool::new(HZ);
        assert_eq!(
            pool.trigger_note(&plan, 60, VELOCITY, u64::MAX, 1.0, None),
            1,
            "单区域夹具 ⇒ 恰好建 1 个声部"
        );
        let mut realtime = vec![0.0f32; FRAMES];
        pool.render_into_with_cc(&plan, 0, &mut realtime, cc_arg);
        assert_eq!(written_offline, FRAMES);
        assert_eq!(written_flat, FRAMES);
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ cc = {cc_value}：离线 → 摊平"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ cc = {cc_value}：摊平 → 实时"
        );
        assert_eq!(
            bits(&offline),
            bits(&realtime),
            "⭐ cc = {cc_value}：三条路同值"
        );
        println!(
            "[engine-sfz/S109] cc = {cc_value:3}：离线 / 摊平 / 实时 逐位相同（指纹 = \
             0x{:016x}）；非零帧 = {}",
            fnv1a_64(&realtime),
            nonzero_frames(&realtime)
        );
        arms.push(bits(&realtime));
    }
    // ⭐ 反空判腿：`cc = 0` 与 `cc = 127` 的实时输出**必须逐位不同**。
    assert_ne!(
        arms[0], arms[3],
        "⭐ 反空判腿：cc = 0（乘子 1.0）与 cc = 127（乘子 2.0）必须逐位不同"
    );
    assert!(
        arms.iter().all(|arm| nonzero_frames_from_bits(arm) > 0),
        "⭐ 四条臂都必须真的出声（⛔ 挡住「静默不发声也算三条路一致」）"
    );
}

/// ⭐ 位模式里的**非零 `f32`** 个数（`bits()` 之后仍要数"真的出声"）。
fn nonzero_frames_from_bits(words: &[u32]) -> usize {
    words
        .iter()
        .filter(|word| **word != 0.0f32.to_bits())
        .count()
}

/// ⭐ S110（任务单 `#116`；判据 §5／§6）：**反向腿 ＋ 三个承重指纹 ＋ 既有族未扰动**。
#[test]
fn s110_the_reverse_leg_the_three_fingerprints_and_the_existing_families() {
    // ---- ① 三个承重指纹（夹具里没有任何 `tune*` ⇒ 必须逐字不变） ----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan) in [("S37 臂 1", &looped), ("S37 臂 2", &plain)] {
        assert!(
            plan.regions()[0].cc_modulations().is_empty(),
            "⭐ 既有夹具没有 `tune*` ⇒ 表为空"
        );
        assert_eq!(
            plan.regions()[0].tune_ratio_with_cc(Some(&|_| 127)),
            1.0,
            "⭐ 空表 + 探针 ⇒ 乘子恰 1.0（`0.0f32.exp2()`）"
        );
        assert_eq!(plan.regions()[0].tune_ratio_with_cc(None), 1.0);
        let _ = label;
    }
    for (label, plan, end_sample, expected) in [
        ("S37 臂 1", &looped, 200u64, 0xa9de_c8a8_7f69_106cu64),
        ("S37 臂 2", &plain, u64::MAX, 0xd3c2_a820_76bd_8947u64),
    ] {
        let out = render_pool(plan, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!("[engine-sfz/S110] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）");
        let _checked = check_fingerprint(&format!("S110 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let legacy = fnv1a_64(&legacy_block);
    println!(
        "[engine-sfz/S110] S33／S14 广播路径 512 帧 @ (60,127)：指纹 = 0x{legacy:016x}（承重 = \
         0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）；写入 = {legacy_frames}"
    );
    let _checked = check_fingerprint("S110 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    // ⭐ 应绿反向腿：× 1.0000001 ⇒ 指纹必须变（证明上面三条是逐位判据）。
    let scaled: Vec<f32> = legacy_block
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    let scaled_hash = fnv1a_64(&scaled);
    println!("[engine-sfz/S110] 反向腿（× 1.0000001）：0x{scaled_hash:016x} ≠ 0x{legacy:016x}");
    assert_ne!(scaled_hash, legacy, "⭐ 反向腿：乘 1.0000001 后指纹必须变");

    // ---- ② 反向腿：去掉 `tune_oncc1` 那一行 ⇒ 两个 CC 值**逐位相同** ----
    let sample = InMemorySample::sine(TUNE_SINE_HZ, TUNE_SAMPLE_HZ, TUNE_PCM_FRAMES);
    let with_mod = prepare_with(TUNE_OCTAVE_FIXTURE, &sample);
    let without_mod = prepare_with(TUNE_BASE_ONLY_FIXTURE, &sample);
    let render = |plan: &PreparedSfz, cc: u8| -> Vec<u32> {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        let mut out = vec![0.0f32; BLOCK];
        plan.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        bits(&out)
    };
    let mod_zero = render(&with_mod, 0);
    let mod_full = render(&with_mod, 127);
    let plain_zero = render(&without_mod, 0);
    let plain_full = render(&without_mod, 127);
    assert_ne!(mod_zero, mod_full, "⭐ 有那一行 ⇒ 两个 CC 值必须不同");
    assert_eq!(
        plain_zero, plain_full,
        "⭐ 去掉那一行 ⇒ 两个 CC 值**逐位相同**"
    );
    assert_eq!(
        without_mod.regions()[0].tune_ratio_with_cc(Some(&|_| 0)),
        1.0,
        "⭐ 没有 `tune` 项 ⇒ 乘子恒 1.0"
    );
    assert_eq!(
        mod_zero, plain_zero,
        "⭐ 如实登记的读数：cc = 0 时调制项贡献恰 0 音分 ⇒ 与「去掉那一行」逐位相同\
         （所以有牙腿必须用 cc = 127 那一臂）"
    );
    assert_ne!(
        mod_full, plain_full,
        "⭐ 有牙：那一行必须真的改变输出（⛔ 不是探针管道自造的差异）"
    );

    // ---- ③ 既有族未扰动：同一夹具里 `amplitude` 与 `ampeg_attack` 各走自己的公式 ----
    let plan = prepare_with(TUNE_MIXED_FIXTURE, &sample);
    for cc in [0u8, 37, 127] {
        let probe = |controller: u8| -> u8 {
            if controller == 1 || controller == 2 || controller == 3 {
                cc
            } else {
                0
            }
        };
        let (attack, unresolved) =
            plan.regions()[0].ampeg_value_with_cc(AmpegParam::Attack, Some(&probe));
        let want_attack = 0.5f32 + 0.5f32 * (f32::from(cc) / 127.0);
        assert_eq!(unresolved, 0);
        assert_eq!(
            attack.to_bits(),
            want_attack.to_bits(),
            "⭐ cc = {cc}：同一夹具里 `ampeg_attack` 仍走 `0.5 + 0.5 × cc/127`"
        );
        let want_amplitude = (50.0f32 + 50.0f32 * (f32::from(cc) / 127.0)) / 100.0;
        assert_eq!(
            plan.regions()[0]
                .amplitude_gain_with_cc(Some(&probe))
                .to_bits(),
            want_amplitude.to_bits(),
            "⭐ cc = {cc}：`amplitude` 仍走 `(50 + 50 × cc/127)/100`"
        );
        let want_tune = ((1200.0f32 * (f32::from(cc) / 127.0)) / 1200.0).exp2();
        assert_eq!(
            plan.regions()[0].tune_ratio_with_cc(Some(&probe)).to_bits(),
            want_tune.to_bits(),
            "⭐ cc = {cc}：`tune` 走 `2 ^ (1200 × cc/127 / 1200)`，⛔ 三者互不顶替"
        );
        // ⭐ **不串台**：只有 CC2 动时 `tune` 变、`amplitude` / `ampeg_attack` 一动不动。
        let only2 = |controller: u8| -> u8 { if controller == 2 { cc } else { 0 } };
        assert_eq!(
            plan.regions()[0]
                .amplitude_gain_with_cc(Some(&only2))
                .to_bits(),
            0.5f32.to_bits(),
            "⭐ 只有 `tune` 的 CC 动 ⇒ `amplitude` 的读数必须一动不动"
        );
        assert_eq!(
            plan.regions()[0]
                .ampeg_value_with_cc(AmpegParam::Attack, Some(&only2))
                .0
                .to_bits(),
            0.5f32.to_bits(),
            "⭐ 只有 `tune` 的 CC 动 ⇒ `ampeg_attack` 的读数必须一动不动"
        );
        println!(
            "[engine-sfz/S110] 混合夹具 cc = {cc}：ampeg_attack = {attack:.9}、\
             amplitude 因子 = {want_amplitude:.9}、tune 乘子 = {want_tune:.9}"
        );
    }
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#117`：单位显式化（`ModUnit`）＋ `tune` 的 `2^x` 上溢／下溢边界
// ---------------------------------------------------------------------------

/// ⭐ `#117` 单位表：**每个单位类别接受的后缀**（判据里的**独立**期望值 ——
/// ⛔ 不从被测代码抄，用来给 [`ModUnit::suffixes`] 当反空判腿）。
///
/// ⚠ ⭐ **追加修订段（任务单 `#119`）—— 被修订的是本常量的行长 `3` 那一支**
/// （⛔ `#117` 的三行**原文一字未删**，口径同台账第 278 条：保留原文 ＋ 追加修订段 ＋
/// 点名被修订的支）：`#119` 在**末尾**追加第 4 行 `Decibels` —— 它是 `#119` 新开的
/// **第四个**单位类别（`volume` 页表行 Unit ＝ `dB`，裁定见
/// `yeban-sfz/src/modulation.rs` §8.2），后缀接受集与 `Cents` 同款（⛔ 一个都不认）。
const EXPECTED_SUFFIXES: [(ModUnit, &[&str]); 4] = [
    (ModUnit::Seconds, &["", "s", "ms"]),
    (ModUnit::Percent, &["", "%"]),
    // ⭐⭐ `#117`：音分**没有任何**后缀写法（规范里 `cents` 一族只写纯数字）。
    (ModUnit::Cents, &[""]),
    // ⭐⭐ `#119` 的**新增行**（⛔ 加在末尾 ⇒ `#117` 的三行顺序不动）。
    (ModUnit::Decibels, &[""]),
];

/// ⭐ `#117` 单位矩阵的**行**：opcode 名 ＋ 它必须归属的目标 ＋ 期望的单位类别。
///
/// ⭐ ⭐ **追加修订段（任务单 `#118`）—— 被修订的是本常量的**行长 `7`**那一支**
/// （⛔ `#117` 的七行**原文一字未删**，口径同台账第 278 条：保留原文 ＋ 追加修订段 ＋
/// 点名被修订的支）：`#118` 在**末尾**追加第 8 行 `pitch_oncc1` —— 规范表行逐字就是
/// `pitch_onccN`，而它归的**还是** [`ModTarget::Tune`]（同一个调制目标的两个拼写，
/// 裁定与代价见 `yeban-sfz/src/modulation.rs` §7.2）⇒ 矩阵变成 8 × 4 ＝ 32 格。
/// ⚠ **被修订的只有行数与随之而来的接受／拒绝计数**：`#117` 的**前七行逐字未动**、
/// 它们的单位归属一个都没改（判据 `S111` 同时断言**改动前**（前 7 行）＝ `(17, 11)`
/// 与**改动后**（全 8 行）＝ `(18, 14)`，两次读数都从判据里现算）。
///
/// ⚠ ⭐ **追加修订段（任务单 `#119`）—— 被修订的是上一段末尾的**行长 `8`**那一支**
/// （⛔ `#117` 的七行与 `#118` 的第八行**原文一字未删**，口径同台账第 278 条：
/// 保留原文 ＋ 追加修订段 ＋ 点名被修订的支）：`#119` 在**末尾**追加第 9 行
/// `volume_oncc1` —— `volume` 页 Modulation 表里逐字的 delta 行名其实是 `gain_ccN`、
/// 而正文写 "`volume_ccN` is a valid alias for `gain_ccN`" ⇒ 本行取 `volume` 拼写，
/// 单位是新开的 `Decibels`（裁定见 `yeban-sfz/src/modulation.rs` §8.2）⇒ 矩阵变成
/// 9 × 4 ＝ 36 格，接受／拒绝 `(18, 14) → (19, 17)`。
/// ⚠ **被修订的只有行数与随之而来的计数**：`#117`／`#118` 的**前八行逐字未动**、
/// 它们的单位归属一个都没改（判据 `S111` 与 `S113` 同时断言**改动前**（前 8 行）＝
/// `(18, 14)` 与**改动后**（全 9 行）＝ `(19, 17)`，两次读数都从判据里现算）。
const UNIT_MATRIX_ROWS: [(&str, ModTarget, ModUnit); 9] = [
    (
        "ampeg_attack_oncc1",
        ModTarget::Ampeg(AmpegParam::Attack),
        ModUnit::Seconds,
    ),
    (
        "ampeg_hold_oncc1",
        ModTarget::Ampeg(AmpegParam::Hold),
        ModUnit::Seconds,
    ),
    (
        "ampeg_decay_oncc1",
        ModTarget::Ampeg(AmpegParam::Decay),
        ModUnit::Seconds,
    ),
    (
        "ampeg_sustain_oncc1",
        ModTarget::Ampeg(AmpegParam::Sustain),
        ModUnit::Percent,
    ),
    (
        "ampeg_release_oncc1",
        ModTarget::Ampeg(AmpegParam::Release),
        ModUnit::Seconds,
    ),
    ("amplitude_oncc1", ModTarget::Amplitude, ModUnit::Percent),
    ("tune_oncc1", ModTarget::Tune, ModUnit::Cents),
    // ⭐⭐ `#118` 的**新增行**（⛔ 加在末尾 ⇒ `#117` 的七行顺序与读数字典序都不动）。
    ("pitch_oncc1", ModTarget::Tune, ModUnit::Cents),
    // ⭐⭐ `#119` 的**新增行**（⛔ 加在末尾 ⇒ `#117`／`#118` 的八行顺序与读数字典序都不动）。
    ("volume_oncc1", ModTarget::Volume, ModUnit::Decibels),
];

/// ⭐ `#118`：上表里属于 `#117` **改动前**口径的行数（前 7 行）。
///
/// 用它把"改动前"的接受／拒绝计数**在同一份判据里现算一遍**（⛔ 不是手抄一个旧数）：
/// 前 7 行 × 4 后缀 ＝ 28 格 ⇒ `(17, 11)`；全 8 行 × 4 ＝ 32 格 ⇒ `(18, 14)`。
const UNIT_MATRIX_ROWS_BEFORE: usize = 7;

/// ⭐⭐ `#119`：上表里属于 `#118` **改动前**口径的行数（前 8 行）。
///
/// 同 [`UNIT_MATRIX_ROWS_BEFORE`] 的口径：前 8 行 × 4 后缀 ＝ 32 格 ⇒ `(18, 14)`；
/// 全 9 行 × 4 ＝ 36 格 ⇒ `(19, 17)`。两个读数都在判据里**现算**（⛔ 不手抄）。
const UNIT_MATRIX_ROWS_BEFORE_119: usize = 8;

/// ⭐ `#117` 矩阵的四列（后缀）。
const UNIT_MATRIX_SUFFIXES: [&str; 4] = ["", "s", "ms", "%"];

/// ⭐⭐ `#119`：矩阵每格的**取值**（判据里现算，⛔ 不写死在模板里）。
///
/// ⚠ ⭐ **为什么需要它**（这是本单实测出来的一条）**：`#117`／`#118` 的模板是
/// `{name}=50{suffix}` —— 对当时的三类单位都合法。而 `#119` 的 `Decibels` 行的
/// delta 域是 **`-144..=48` dB**（`volume` 页 Modulation 表里被别名的那一行
/// `gain_ccN`）⇒ `50` **越界**，`volume_oncc1=50` 会因**域**（而不是后缀）被拒
/// ⇒ 那一行会给出"4 格全拒"的**假读数**（矩阵量的是**后缀**接受集）。
/// ⇒ 对 `Decibels` 行取 **`48`**（闭区间上界，仍在域内、仍能分辨后缀）。
/// ⚠ **被修订的只是新行的取值**：`#117`／`#118` 的八行仍恒 `50`（⛔ 逐字未动）。
const fn unit_matrix_cell_value(unit: ModUnit) -> f32 {
    match unit {
        ModUnit::Decibels => 48.0,
        ModUnit::Seconds | ModUnit::Percent | ModUnit::Cents => 50.0,
    }
}

/// ⭐ `#117`：读一条**单区域** SFZ 文本里第一个调制项的 `delta`（必须解析成功）。
fn unit_matrix_delta(text: &str) -> f32 {
    let instrument = SfzInstrument::load(text.to_owned(), &Default::default())
        .unwrap_or_else(|error| panic!("`{text}` 必须解析成功：{error}"));
    instrument
        .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].delta)
        .expect("重解析")
}

/// ⭐⭐ `#117` 病态夹具：`items` 条 `tune_onccN=delta`。
///
/// ⚠ 下标逐个不同（`1..=items`）⇒ 归约表里是 `items` 个**独立**的 `(Tune, cc)` 键
/// —— 同一键会被"后者胜"合并，那**凑不出**复合量（`AMPEG_MOD_CAP` 是 20）。
fn tune_compound_fixture(items: usize, delta: i32) -> String {
    let mut text = String::from("<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0");
    for cc in 1..=items {
        text.push_str(&format!(" tune_oncc{cc}={delta}"));
    }
    text.push('\n');
    text
}

/// ⭐ `#117` 夹具用的**斜坡**样本：`pcm[i] = (i + 1) / 1024`。
///
/// ⚠ 与 [`ramp_sample`] 同一形状，但**采样率可给**（病态臂要 `192 kHz` 那一档
/// ⇒ 基率 `4.0` ⇒ `基率 × 有限大乘子` 溢出成 `Inf`）。
/// ⭐ 与正弦夹具的分别：`pcm[0] = 1/1024 ≠ 0` ⇒ "只写了 1 帧"与"一帧没写"
/// 在**非零帧数**与**指纹**上都分得开（`InMemorySample::sine` 的 `pcm[0] == 0` 分不开）。
fn ramp_at(sample_hz: f32, frames: usize) -> InMemorySample {
    InMemorySample {
        pcm: (0..frames)
            .map(|frame| (frame + 1) as f32 / 1024.0)
            .collect(),
        sample_hz,
    }
}

/// ⭐ `#117`：**三条路**（离线 ／ 摊平 ／ 实时）用同一探针渲染 `FRAMES` 帧。
///
/// 返回值：`(离线 written, 离线输出, 摊平 written, 摊平输出, 实时输出)`。
/// ⚠ 实时路的"写入帧数"没有对外读数（`render_into_with_cc` 返回 `()`）
/// ⇒ 这一路用**非零帧数**当它的可读量（斜坡样本 ⇒ 可区分"写了"与"退休"）。
fn tune_three_paths(
    instrument: &SfzInstrument,
    plan: &PreparedSfz,
    sample: &InMemorySample,
    items: usize,
    cc_value: u8,
) -> (usize, Vec<f32>, usize, Vec<f32>, Vec<f32>) {
    const FRAMES: usize = 512;
    let controls: Vec<u8> = (1..=items as u8).collect();
    let probe = |controller: u8| -> u8 {
        if controls.contains(&controller) {
            cc_value
        } else {
            0
        }
    };
    let cc_arg: Option<&dyn Fn(u8) -> u8> = Some(&probe);
    let mut offline = vec![0.0f32; FRAMES];
    let written_offline = instrument
        .render_note_into_with_cc(sample, 60, 127, cc_arg, &mut offline, 48_000.0)
        .expect("离线渲染");
    let mut flat = vec![0.0f32; FRAMES];
    let written_flat = plan.render_block_into_with_cc(60, 127, cc_arg, &mut flat);
    let mut pool = SfzVoicePool::new(48_000.0);
    assert_eq!(
        pool.trigger_note(plan, 60, 127, u64::MAX, 1.0, None),
        1,
        "单区域夹具 ⇒ 恰好建 1 个声部"
    );
    let mut realtime = vec![0.0f32; FRAMES];
    pool.render_into_with_cc(plan, 0, &mut realtime, cc_arg);
    (written_offline, offline, written_flat, flat, realtime)
}

/// ⭐ `#117` 一个病态臂：**打印**乘子位型／基率／乘积与三条路各自的读数，
/// 并断言三条路**输出逐位相同**。
///
/// 返回 `(乘子, 离线 written, 摊平 written, 三条路输出的非零帧数, 实时输出)`。
fn tune_boundary_arm(
    label: &str,
    items: usize,
    delta: i32,
    sample_hz: f32,
    cc_value: u8,
) -> (f32, usize, usize, [usize; 3], Vec<f32>) {
    let text = tune_compound_fixture(items, delta);
    let sample = ramp_at(sample_hz, 4096);
    let instrument = SfzInstrument::load(text, &Default::default()).expect("病态夹具必须解析成功");
    let plan = PreparedSfz::prepare(&instrument, &sample, 48_000.0).expect("摊平");
    assert_eq!(
        plan.regions()[0].cc_modulations().len(),
        items,
        "⭐ `{label}`：`items` 个不同 CC ⇒ 表里必须恰好 {items} 项（⛔ 不被合并）"
    );
    let controls: Vec<u8> = (1..=items as u8).collect();
    let probe = |controller: u8| -> u8 {
        if controls.contains(&controller) {
            cc_value
        } else {
            0
        }
    };
    let multiplier = plan.regions()[0].tune_ratio_with_cc(Some(&probe));
    let base_rate = sample_hz / plan.engine_hz();
    let (written_offline, offline, written_flat, flat, realtime) =
        tune_three_paths(&instrument, &plan, &sample, items, cc_value);
    println!(
        "[engine-sfz/S112] {label}：乘子 = {multiplier:?}（{:#010x}，finite={}）基率 = {base_rate:?} \
         乘积 = {:?}（finite={}）⇒ 离线 written={written_offline} 非零={} 指纹=0x{:016x}；\
         摊平 written={written_flat} 非零={} 指纹=0x{:016x}；实时 非零={} 指纹=0x{:016x}",
        multiplier.to_bits(),
        multiplier.is_finite(),
        base_rate * multiplier,
        (base_rate * multiplier).is_finite(),
        nonzero_frames(&offline),
        fnv1a_64(&offline),
        nonzero_frames(&flat),
        fnv1a_64(&flat),
        nonzero_frames(&realtime),
        fnv1a_64(&realtime),
    );
    assert_eq!(
        bits(&offline),
        bits(&flat),
        "⭐ `{label}`：离线 → 摊平必须逐位相同"
    );
    assert_eq!(
        bits(&flat),
        bits(&realtime),
        "⭐ `{label}`：摊平 → 实时必须逐位相同"
    );
    assert_eq!(bits(&offline), bits(&realtime), "⭐ `{label}`：三条路同值");
    (
        multiplier,
        written_offline,
        written_flat,
        [
            nonzero_frames(&offline),
            nonzero_frames(&flat),
            nonzero_frames(&realtime),
        ],
        realtime,
    )
}

/// ⭐ `#117`：按**实现同一条公式**重算 `tune` 乘子（`2 ^ (Σ delta × curve(cc) / 1200)`）。
///
/// ⚠ 在判据里用**同一个二进制里的同一次 `exp2`** 当参照 ⇒ 跨架构稳（`exp2` 是
/// ADR-0001 的超越函数类，⛔ 不硬编码它的位型读数当规范常数）。
/// 求和的次序与 [`yeban_sfz::modulation::cc_value_with_baked_and_vel2`] 一致
/// （`0.0` 起、逐项 `+`；默认曲线在 `cc` 处的值 ＝ `cc / 127`）。
fn tune_multiplier_reference(items: usize, delta: f32, cc_value: u8) -> f32 {
    let curve = f32::from(cc_value) / 127.0;
    let mut cents = 0.0f32;
    for _ in 0..items {
        cents += delta * curve;
    }
    (cents / 1200.0).exp2()
}

/// ⭐ S111（任务单 `#117`；判据 §2／§3.1／§3.2／§3.6）：**单位显式化** ——
/// `ModUnit` 是唯一事实源、`tune` 拒 `%`、`ampeg_*`／`amplitude` 的接受集未动、
/// 单位 × 后缀矩阵**从判据里打印**。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 七条调制 opcode 的**接受／拒绝**（布尔）与读出的 `delta`（`f32`）；
/// 单位 ＝ 格（7 × 4 ＝ 28 格）＋ 字节（`size_of`）。
#[test]
fn s111_the_unit_is_explicit_and_tune_rejects_the_percent_suffix() {
    // ---- ① `ModUnit` 是**唯一**事实源：三个类别 × 后缀集 ＋ 逐目标归属 ----
    assert_eq!(
        core::mem::size_of::<ModUnit>(),
        1,
        "⭐ `ModUnit` 必须落在既有对齐空隙里（1 B）"
    );
    for (unit, expected) in EXPECTED_SUFFIXES {
        assert_eq!(
            unit.suffixes(),
            expected,
            "⭐ `{unit:?}` 的接受后缀必须逐字是 {expected:?}"
        );
    }
    for (name, target, unit) in UNIT_MATRIX_ROWS {
        assert_eq!(target.mod_unit(), unit, "⭐ `{name}` 必须归 `{unit:?}`");
        // ⭐ 既有契约**逐字未变**：`is_time()` ⇔ `Seconds`、`unit()` 是同一事实源的字符串。
        assert_eq!(
            target.is_time(),
            unit == ModUnit::Seconds,
            "⭐ `{name}`：`is_time()` 必须仍等价于「单位 == 秒」"
        );
        assert_eq!(
            target.unit(),
            match unit {
                ModUnit::Seconds => "seconds",
                ModUnit::Percent => "%",
                ModUnit::Cents => "cents",
                // ⭐⭐ `#119`：**新增的第四个**单位类别。⛔ `#117` 的三个臂**一字未动**；
                // 本臂是编译器强制补的（`match` 必须穷尽）⇒ 它的返回值与
                // `ModTarget::unit()` 的 `dB` 臂逐字相同。
                ModUnit::Decibels => "dB",
            },
            "⭐ `{name}`：`unit()` 必须仍返回规范表行 Unit 列的字面"
        );
    }

    // ---- ② `tune_oncc1=50%` ⇒ **响亮 `Err`**（`#116` 之前被静默读成 50 音分） ----
    let error = SfzInstrument::load(
        "<region> sample=a.wav tune_oncc1=50%\n".to_owned(),
        &Default::default(),
    )
    .expect_err("⭐ `tune`（音分）⛔ 不接受 `%` ⇒ 必须响亮 `Err`");
    let shown = format!("{error}");
    println!("[engine-sfz/S111] `tune_oncc1=50%` ⇒ `{shown}`");
    assert!(
        shown.contains("line 1: `tune_oncc1` expects a number, got `50%`"),
        "⭐ `%` 在音分目标上必须走 `InvalidFloat` 的原文出口（实得 `{shown}`）"
    );

    // ---- ③ 单位 × 后缀矩阵（7 目标 × 4 后缀 ＝ 28 格）：**打印** ＋ 逐格断言 ----
    println!(
        "[engine-sfz/S111] 单位矩阵（行 ＝ 目标，列 ＝ 后缀 {}）",
        UNIT_MATRIX_SUFFIXES
            .iter()
            .map(|suffix| format!("\"{suffix}\""))
            .collect::<Vec<_>>()
            .join(" / ")
    );
    let mut accepted_cells = 0usize;
    let mut rejected_cells = 0usize;
    // ⭐ `#118`：**同一份判据里现算"改动前"口径**（前 [`UNIT_MATRIX_ROWS_BEFORE`] 行）。
    let mut accepted_before = 0usize;
    let mut rejected_before = 0usize;
    // ⭐⭐ `#119`：**同一份判据里现算 `#118` 口径**（前 [`UNIT_MATRIX_ROWS_BEFORE_119`] 行）。
    let mut accepted_before_119 = 0usize;
    let mut rejected_before_119 = 0usize;
    for (row, (name, target, unit)) in UNIT_MATRIX_ROWS.into_iter().enumerate() {
        let before = row < UNIT_MATRIX_ROWS_BEFORE;
        let before_119 = row < UNIT_MATRIX_ROWS_BEFORE_119;
        let expected = EXPECTED_SUFFIXES
            .iter()
            .find(|(candidate, _)| *candidate == unit)
            .map(|(_, suffixes)| *suffixes)
            .expect("单位类别必须在期望表里");
        let mut cells: Vec<String> = Vec::new();
        // ⭐⭐ `#119`：每格的取值由 [`unit_matrix_cell_value`] 现算（`#117`／`#118` 的八行
        // 仍恒 `50`；`Decibels` 行取 `48` —— 它的域上界，理由见该函数的文档）。
        let cell_value = unit_matrix_cell_value(unit);
        for suffix in UNIT_MATRIX_SUFFIXES {
            let text = format!(
                "<region> sample=a.wav key=60 pitch_keycenter=60 {name}={cell_value}{suffix}\n"
            );
            let outcome = SfzInstrument::load(text.clone(), &Default::default());
            if expected.contains(&suffix) {
                accepted_cells += 1;
                if before {
                    accepted_before += 1;
                }
                if before_119 {
                    accepted_before_119 += 1;
                }
                let want = if unit == ModUnit::Seconds && suffix == "ms" {
                    cell_value * 1.0e-3_f32
                } else {
                    cell_value
                };
                let delta = unit_matrix_delta(&text);
                assert_eq!(
                    delta.to_bits(),
                    want.to_bits(),
                    "⭐ `{name}={cell_value}{suffix}` 必须读成 {want}（实得 {delta}）"
                );
                // 目标必须真的归到期望的那一类（⛔ 不是"碰巧读进去"）。
                let read_target = SfzInstrument::load(text, &Default::default())
                    .expect("已解析")
                    .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].target)
                    .expect("重解析");
                assert_eq!(read_target, target, "⭐ `{name}` 归约出的目标必须逐字相同");
                cells.push(format!("Ok({delta})"));
            } else {
                rejected_cells += 1;
                if before {
                    rejected_before += 1;
                }
                if before_119 {
                    rejected_before_119 += 1;
                }
                let rejected = outcome.expect_err(&format!(
                    "⭐ `{name}={cell_value}{suffix}`（单位 {unit:?}）必须**响亮** `Err`\
                     （⛔ 不静默当成 {cell_value}）"
                ));
                let rejected_text = format!("{rejected}");
                assert!(
                    rejected_text.contains(&format!(
                        "line 1: `{name}` expects a number, got `{cell_value}{suffix}`"
                    )),
                    "⭐ `{name}={cell_value}{suffix}`：必须逐字走 `InvalidFloat`\
                     （实得 `{rejected_text}`）"
                );
                cells.push(format!("Err({suffix:?})"));
            }
        }
        println!(
            "[engine-sfz/S111] `{name}`（{}，单位 {unit:?}）× 后缀 ⇒ {}",
            target.name(),
            cells.join(" | ")
        );
    }
    println!(
        "[engine-sfz/S111] 接受／拒绝计数：改动前（前 {UNIT_MATRIX_ROWS_BEFORE} 行 × {} 后缀 ＝ {} 格）\
         ＝ ({accepted_before}, {rejected_before})；`#118` 口径（前 {UNIT_MATRIX_ROWS_BEFORE_119} 行 × {} \
         后缀 ＝ {} 格）＝ ({accepted_before_119}, {rejected_before_119})；改动后（{} 行 × {} 后缀 ＝ {} 格）\
         ＝ ({accepted_cells}, {rejected_cells})",
        UNIT_MATRIX_SUFFIXES.len(),
        UNIT_MATRIX_ROWS_BEFORE * UNIT_MATRIX_SUFFIXES.len(),
        UNIT_MATRIX_SUFFIXES.len(),
        UNIT_MATRIX_ROWS_BEFORE_119 * UNIT_MATRIX_SUFFIXES.len(),
        UNIT_MATRIX_ROWS.len(),
        UNIT_MATRIX_SUFFIXES.len(),
        UNIT_MATRIX_ROWS.len() * UNIT_MATRIX_SUFFIXES.len(),
    );
    assert_eq!(
        (accepted_before, rejected_before),
        (17, 11),
        "⭐ `#117` 的改动前读数（前 7 行 × 4 ＝ 28 格）必须**现算**出来仍是 17 接受／11 拒绝"
    );
    assert_eq!(
        (accepted_before_119, rejected_before_119),
        (18, 14),
        "⭐ `#118` 的改动后读数（前 8 行 × 4 ＝ 32 格）必须**现算**出来仍是 18 接受／14 拒绝"
    );
    assert_eq!(
        (accepted_cells, rejected_cells),
        (19, 17),
        "⭐⭐ `#119` 的改动后读数（9 行 × 4 ＝ 36 格）：新增 `volume_oncc1`（Decibels）\
         ⇒ 恰多 1 格接受（`\"\"`）与 3 格拒绝（`s`／`ms`／`%`）—— \
         ⛔ `#117`／`#118` 的八行读数**未被扰动**（上一条断言现算）"
    );

    // ---- ④ 反空判腿：三支的既有接受集**仍未动**（⛔ 不是一刀切） ----
    for (label, text, want) in [
        (
            "秒支仍认 `s`",
            "<region> sample=a.wav ampeg_attack_oncc1=50s\n",
            50.0f32,
        ),
        (
            "秒支仍认 `ms`",
            "<region> sample=a.wav ampeg_attack_oncc1=50ms\n",
            50.0f32 * 1.0e-3_f32,
        ),
        (
            "秒支仍认无后缀",
            "<region> sample=a.wav ampeg_attack_oncc1=50\n",
            50.0f32,
        ),
        (
            "百分比支仍认 `%`（`ampeg_sustain`）",
            "<region> sample=a.wav ampeg_sustain_oncc1=50%\n",
            50.0f32,
        ),
        (
            "百分比支仍认 `%`（`amplitude`）",
            "<region> sample=a.wav amplitude_oncc1=50%\n",
            50.0f32,
        ),
        (
            "百分比支仍认无后缀",
            "<region> sample=a.wav amplitude_oncc1=50\n",
            50.0f32,
        ),
    ] {
        let delta = unit_matrix_delta(text);
        println!("[engine-sfz/S111] 反空判腿 · {label} ⇒ `{delta}`");
        assert_eq!(delta.to_bits(), want.to_bits(), "⭐ 反空判腿 · {label}");
    }
    // ⚠ **如实登记的读数**（任务单 §3.1 的原文与事实不符的那一格）：派单方把
    // `ampeg_attackcc1=50%` 列进"仍然接受"的反空判腿 —— 实测它**在 `#117` 之前
    // 就不是**接受的：`ampeg_attack` 的单位是**秒**，`#104` 起的时间支只认
    // `s`/`ms`，`%` 一直落 `InvalidFloat`（判据 `S111` 的注入实测把这一格在
    // **改动前**的构建上也跑了一遍：两边的读数都是 `Err`）。⇒ 本判据按**事实**登记，
    // 反空判腿改用上面六个**真正**覆盖三支的格子。
    let already = SfzInstrument::load(
        "<region> sample=a.wav ampeg_attack_oncc1=50%\n".to_owned(),
        &Default::default(),
    );
    let already_shown = format!("{}", already.expect_err("秒支的 `%` 必须拒绝"));
    println!(
        "[engine-sfz/S111] 如实登记：`ampeg_attack_oncc1=50%` ⇒ `{already_shown}`（改动前同）"
    );
    assert!(
        already_shown.contains("expects a number, got `50%`"),
        "⭐ 秒支的 `%` 必须是同一条响亮出口"
    );

    // ---- ⑤ 尺寸（`size_of` 现读，⛔ 不手抄） ----
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S111] size_of: PreparedRegion={region} SfzVoice={voice} \
         SfzVoicePool={pool} EngineRuntime={runtime}（< 192 KiB = {}）",
        192 * 1024
    );
    assert_eq!(
        region, 6160,
        "⭐ `#117` 没新增任何每区域字段 ⇒ `PreparedRegion` ＋0"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（仍是 40 B）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0（仍是 1712 B）");
    assert_eq!(
        runtime, 180_144,
        "⛔ `EngineRuntime` 必须 ＋0（仍是 180144 B）"
    );
}

/// ⭐ S112（任务单 `#117`；判据 §3.3／§3.4 —— **本单核心**）：**`2^x` 的上溢／下溢
/// 病态夹具** ＋ 三条路一致 ＋ 反向腿 ＋ 三个承重指纹。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ 六份病态夹具的**乘子**（无量纲）与**三条路各自的输出**；
/// 单位 ＝ 写入帧数（帧）／非零帧数（帧）／FNV-1a 64（逐位指纹）。
#[test]
fn s112_the_overflow_boundary_has_a_pathological_fixture_across_three_paths() {
    // ---- ①② `≥16 × 9600` ⇒ 乘子 `Inf`（`2^128` 上溢）：三条路**全退休** ----
    let (inf_multiplier, written_offline, written_flat, nonzero, _) =
        tune_boundary_arm("① 16×9600 cc127（2^128 ⇒ Inf）", 16, 9600, 48_000.0, 127);
    assert!(
        !inf_multiplier.is_finite(),
        "⭐ 16 × 9600 ＝ 153600 音分 ⇒ `2^128` 在 `f32` 上是 `Inf`（实得 {inf_multiplier}）"
    );
    assert_eq!(
        (written_offline, written_flat, nonzero),
        (0, 0, [0, 0, 0]),
        "⭐ 乘子非有限 ⇒ 三条路**全退休**（既有谓词）"
    );

    // ---- ③ 有限大乘子（`cc=126`）⇒ `position` 超过 `usize::MAX`：
    //      `#117` 之前三条路**都 panic**（`index + 1` 溢出）；现在**各写 1 帧且逐位相同** ----
    let (finite_multiplier, written_offline, written_flat, nonzero, _) =
        tune_boundary_arm("② 16×9600 cc126（有限 1.69e38）", 16, 9600, 48_000.0, 126);
    assert_eq!(
        finite_multiplier.to_bits(),
        tune_multiplier_reference(16, 9600.0, 126).to_bits(),
        "⭐ 乘子必须逐位等于公式 `2 ^ (Σ 9600 × 126/127 / 1200)`（实测 {finite_multiplier:?}，\
         位型 {:#010x}）⇒ 它是**有限**的 ⇒ 守卫**必须放行**",
        finite_multiplier.to_bits()
    );
    assert!(
        finite_multiplier.is_finite() && finite_multiplier > 1.0e38,
        "⭐ 有牙：这一档乘子必须**有限但极大**（实测 {finite_multiplier:?}）"
    );
    assert_eq!(
        (written_offline, written_flat, nonzero),
        (1, 1, [1, 1, 1]),
        "⭐ 有限大速率：三条路各写**恰好 1 帧**（第一帧）后按「位置越过 PCM」如实退休；\
         ⛔ 不是 panic、⛔ 不是三路分叉"
    );

    // ---- ④ ⭐⭐ **守卫量的口径分叉**（`#116` 的真实缺口）：`192 kHz` 样本 ⇒
    //      基率 `4.0` ⇒ 有限乘子 × 基率**溢出成 `Inf`**：
    //      `#117` 之前**离线／摊平退休而实时放行**（实测：实时拿 `Inf` 冲进逐样本循环）；
    //      现在三条路**同量同谓词** ⇒ 全退休 ----
    let (finite_192k, written_offline, written_flat, nonzero, _) = tune_boundary_arm(
        "③ 192k × 16×9600 cc126（乘积 Inf：三路曾分叉）",
        16,
        9600,
        192_000.0,
        126,
    );
    assert!(
        finite_192k.is_finite() && finite_192k > 0.0,
        "⭐ 乘子有限正数（`2^x` 的有限上界）"
    );
    assert!(
        !(4.0 * finite_192k).is_finite(),
        "⭐ 基率 4.0 × 有限乘子 ⇒ 乘积必须是 `Inf`（否则本臂没有牙）"
    );
    assert_eq!(
        (written_offline, written_flat, nonzero),
        (0, 0, [0, 0, 0]),
        "⭐⭐ 三条路必须**一致退休**（实时路的守卫必须与另两条路同量：速率而非乘子）"
    );

    // ---- ⑤ 20 × (−9600) ⇒ `2^−160` 下溢成**恰 0**：三条路全退休 ----
    let (zero_multiplier, written_offline, written_flat, nonzero, _) =
        tune_boundary_arm("④ 20×(−9600) cc127（2^−160 ⇒ 0）", 20, -9600, 48_000.0, 127);
    assert_eq!(
        zero_multiplier.to_bits(),
        tune_multiplier_reference(20, -9600.0, 127).to_bits(),
        "⭐ 乘子必须逐位等于公式 `2 ^ (Σ 20 × (−9600) / 1200)`"
    );
    assert_eq!(
        zero_multiplier.to_bits(),
        0.0f32.to_bits(),
        "⭐ 乘子必须**恰是 `+0.0`**（下溢到零，⛔ 不是次正规）"
    );
    assert_eq!(
        (written_offline, written_flat, nonzero),
        (0, 0, [0, 0, 0]),
        "⭐ 乘子为零 ⇒ 三条路**全退休**"
    );

    // ---- ⑥ 16 × (−9600) ⇒ `2^−128` ＝ **次正规但非零**：三条路照常出声且逐位相同 ----
    let (subnormal_multiplier, written_offline, _, nonzero, _) = tune_boundary_arm(
        "⑤ 16×(−9600) cc127（2^−128 次正规）",
        16,
        -9600,
        48_000.0,
        127,
    );
    assert_eq!(
        subnormal_multiplier.to_bits(),
        tune_multiplier_reference(16, -9600.0, 127).to_bits(),
        "⭐ 乘子必须逐位等于公式 `2 ^ (Σ 16 × (−9600) / 1200)`"
    );
    assert!(
        subnormal_multiplier.is_finite()
            && subnormal_multiplier > 0.0
            && subnormal_multiplier < f32::MIN_POSITIVE,
        "⭐ 乘子必须是**次正规正数**（{subnormal_multiplier:?}，位型 {:#010x}）",
        subnormal_multiplier.to_bits()
    );
    assert_eq!(
        (written_offline, nonzero),
        (512, [512, 512, 512]),
        "⭐ 极慢速率 ⇒ 三条路都写满 512 帧（位置几乎不动）且逐位相同"
    );

    // ---- ⑦ 对照臂（`1 × 9600` ⇒ 乘子 `256`）：正常档**真的出声**（⛔ 挡住"全退休也算一致"） ----
    let (normal_multiplier, written_offline, written_flat, nonzero, _) =
        tune_boundary_arm("⑥ 1×9600 cc127（对照：乘子 256）", 1, 9600, 48_000.0, 127);
    assert_eq!(
        normal_multiplier.to_bits(),
        tune_multiplier_reference(1, 9600.0, 127).to_bits(),
        "⭐ 乘子必须逐位等于公式 `2 ^ (9600 / 1200)`"
    );
    assert_eq!(
        normal_multiplier, 256.0,
        "⭐ `+9600` 音分 ＝ 八个八度 ⇒ 乘子恰 256"
    );
    assert_eq!(
        (written_offline, written_flat),
        (16, 16),
        "⭐ 速率 256 ⇒ 4096 帧的源在 512 帧窗口里播完（写到源尾）"
    );
    assert!(
        nonzero.iter().all(|count| *count > 0),
        "⭐ 对照臂三条路都必须**真的出声**"
    );

    // ---- ⑧ 反向腿：去掉病态夹具里的项 ⇒ **恢复正常**，且与病态臂逐位不同 ----
    let base_only = ramp_at(48_000.0, 4096);
    let plain_text = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n";
    let plain_instrument =
        SfzInstrument::load(plain_text.to_owned(), &Default::default()).expect("基准夹具必须解析");
    let plain_plan = PreparedSfz::prepare(&plain_instrument, &base_only, 48_000.0).expect("摊平");
    assert!(
        plain_plan.regions()[0].cc_modulations().is_empty(),
        "⭐ 去掉全部 `tune_onccN` ⇒ 空表"
    );
    let (plain_written_offline, plain_offline, plain_written_flat, plain_flat, plain_realtime) =
        tune_three_paths(&plain_instrument, &plain_plan, &base_only, 0, 127);
    assert_eq!(
        (plain_written_offline, plain_written_flat),
        (512, 512),
        "⭐ 反向腿：去掉病态项 ⇒ 恢复正常（速率 1.0，写满 512 帧）"
    );
    assert!(
        nonzero_frames(&plain_offline) > 0
            && nonzero_frames(&plain_flat) > 0
            && nonzero_frames(&plain_realtime) > 0,
        "⭐ 反向腿：三条路都必须**真的出声**"
    );
    assert_eq!(
        bits(&plain_offline),
        bits(&plain_realtime),
        "⭐ 反向腿：去掉病态项后三条路仍逐位相同"
    );
    // ⭐ 有牙：病态臂（全退休的所有输出位型）必须与"恢复正常"的输出**逐位不同**
    // ⇒ ⛔ 挡住"把退休也当成正常出声"。
    assert_ne!(
        bits(&plain_realtime),
        vec![0.0f32.to_bits(); 512],
        "⭐ 有牙：反向腿的输出必须**不是**全零"
    );

    // ---- ⑨ 三个承重指纹（`#117` 的改动必须让它们**逐字不动**） ----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, expected) in [
        ("S37 臂 1", &looped, 200u64, 0xa9de_c8a8_7f69_106cu64),
        ("S37 臂 2", &plain, u64::MAX, 0xd3c2_a820_76bd_8947u64),
    ] {
        let out = render_pool(plan, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!("[engine-sfz/S112] {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）");
        let _checked = check_fingerprint(&format!("S112 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let legacy = fnv1a_64(&legacy_block);
    println!(
        "[engine-sfz/S112] S33／S14 广播路径 512 帧 @ (60,127)：指纹 = 0x{legacy:016x}（承重 = \
         0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）；写入 = {legacy_frames}"
    );
    let _checked = check_fingerprint("S112 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    let scaled: Vec<f32> = legacy_block
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    assert_ne!(
        fnv1a_64(&scaled),
        legacy,
        "⭐ 应绿反向腿：× 1.0000001 ⇒ 指纹必须变"
    );
}

// ---------------------------------------------------------------------------
// ⭐ 任务单 `#118`：`pitch` 族（`tune` 的**别名拼写**，同一个调制目标）
// ---------------------------------------------------------------------------

/// ⭐ `#118` 夹具：`items` 条 `pitch_onccN=delta`。
///
/// ⚠ 下标逐个不同（`1..=items`）⇒ 归约表里是 `items` 个**独立**的 `(Tune, cc)` 键
/// —— 同一键会被"后者胜"合并，那**凑不出**复合量（`AMPEG_MOD_CAP` 是 20）。
/// ⭐ 与 [`tune_compound_fixture`] 的唯一差别是 opcode 拼写（`pitch_` ⇔ `tune_`）
/// —— 这正是本单要证明"同一目标"的那一对拼写。
fn pitch_compound_fixture(items: usize, delta: i32) -> String {
    let mut text = String::from("<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0");
    for cc in 1..=items {
        text.push_str(&format!(" pitch_oncc{cc}={delta}"));
    }
    text.push('\n');
    text
}

/// ⭐ `#118` 四种合法写法 ＋ 两个**必须不被吞掉**的静态邻居
/// （`pitch_keycenter` 是真静态 opcode、`tune` 是基准）＋ 两个**不做**的行
/// （`pitch_smoothccN` / `pitch_stepccN`）。
const PITCH_FORMS_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 tune=25 \
     pitch_oncc1=1200 pitch_cc2=-2400 pitch_curvecc3=9 pitchcc4=600 \
     pitch_smoothcc5=10 pitch_stepcc6=1\n";

/// ⭐ `#118` 可读量夹具：`pitch_oncc1=1200`（一个八度 ⇒ 乘子 `2.0`）。
const PITCH_OCTAVE_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                    amp_veltrack=0 pitch_oncc1=1200\n";
/// ⭐ `#118` 反向腿：同文本**去掉** `pitch_oncc1` 那一行。
const PITCH_BASE_ONLY_FIXTURE: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0\n";
/// ⭐ `#118` 未扰动对照：同一夹具里 `amplitude`（CC1）／`tune`（CC2）／`pitch`（CC3）／
/// `ampeg_attack`（CC4）**各走自己的公式** —— 而 `tune` 与 `pitch` 是**同一个目标**的
/// 两个 CC（⇒ 不同的 CC 号 ⇒ **求和**，这是裁定 §7.2 的机械见证）。
const PITCH_MIXED_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
     amplitude=50 amplitude_oncc1=50 tune_oncc2=1200 pitch_oncc3=1200 \
     ampeg_attack=0.5 ampeg_attack_oncc4=0.5\n";

/// ⭐⭐ S113（任务单 `#118`；判据 §4 八条 —— **本单核心**）：**`pitch` 族是 `tune` 的
/// 别名拼写（同一个调制目标）** ＋ 单位矩阵新增行 ＋ 解析与域 ＋ 真的生效 ＋
/// 三条路一致 ＋ 病态夹具 ＋ 反向腿与三个承重指纹 ＋ 尺寸 ＋ 未做两行的负向登记。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ ① 两个源文件的**源文本**（`contains`，布尔 ＋ 逐字）；② 单位矩阵的**格**
/// （8 行 × 4 后缀 ＝ 32 格）与**接受／拒绝计数**（格）；③ 调制项的
/// `(目标, cc, delta, curve)` 与错误文本；④ **速率乘子**（无量纲）＋ 输出**帧下标**
/// （首次为负）＋ **上升零交叉次数**（个）；⑤ 三条路各自的**输出位模式**与**非零帧数**
/// （帧）；⑥ **三个承重指纹**（FNV-1a 64）；⑦ `size_of`（字节）。
#[test]
fn s113_the_pitch_family_is_the_tune_alias_across_three_paths() {
    const ENGINE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const MODULATION_SOURCE: &str = include_str!("../../yeban-sfz/src/modulation.rs");

    // ---- ① 规范逐字 ＋ 关系裁定（源文本 `contains`，逐字） ----
    for (label, needle) in [
        (
            "`#118` 追加修订段（引擎侧）",
            "⭐ ⭐ **追加修订段（任务单 `#118`）",
        ),
        (
            "被修订的支 ＝ `pitch_oncc*` 那一项",
            "里 **`pitch_oncc*` 这一项**",
        ),
        (
            "`#116` 的登记原文仍在（第 278 条）",
            "⛔ **`pan_oncc*` ／ `volume_oncc*` ／ `cutoff_oncc*` ／ `pitch_oncc*` 那四项",
        ),
        (
            "ARIA 别名句（逐字）",
            "In ARIA, `tune_*ccN` can also be used as an alias for `pitch_*ccN`.",
        ),
        (
            "`pitch_onccN` 的 Range／Unit（逐字）",
            "`pitch_onccN`（Range ＝ **`-9600 to 9600`**、Unit ＝ **cents**）",
        ),
        (
            "`pitch_curveccN`（逐字）",
            "`pitch_curveccN`（Default `0`、Range ＝ `0 to 255`）",
        ),
        (
            "`pitch_smoothccN` 的 Unit（逐字）",
            "`pitch_smoothccN`（float，Default `0`、Unit ＝ **ms**）",
        ),
        (
            "静态 `pitch` 不存在（裁定）",
            "⛔ **规范里没有 `pitch` 这个静态 opcode**",
        ),
        (
            "基准 ＝ 0 音分（裁定）",
            "`pitch_*ccN` 的基准就是 **0 音分**",
        ),
        ("⛔ 不发明 `pitch=`", "⛔ 本单**不发明** `pitch=`"),
        (
            "落地形状：同一个目标的两个拼写",
            "1. **同一个目标的两个拼写**",
        ),
        ("引擎侧：零改动", "**引擎侧零改动**"),
        ("引擎侧：语料**家族子串**口径", "**143** 处 ／ **33** 文件"),
        (
            "引擎侧：语料 **opcode token** 口径",
            "**opcode token**（词边界 ＋ `=`）是 **39** 处 ／",
        ),
        (
            "引擎侧：唯一真用到本族的文件",
            "`assets/samples/karoryfer-bear-sax/Programs/5-bearcussion.sfz`",
        ),
        (
            "引擎侧：`pitch=-1200` 是未知 opcode",
            "⛔ 那是个**未知 opcode**",
        ),
    ] {
        assert!(
            ENGINE_SOURCE.contains(needle),
            "⭐ 引擎侧必须逐字含：{label}（`{needle}`）"
        );
    }
    println!(
        "[engine-sfz/S113] ① 引擎侧源文本：`#118` 修订段 ＋ 规范逐字 ＋ 语料两口径 —— 全部逐字命中"
    );
    // ⭐ 反向腿（⛔ 挡住恒真）：一句**不存在**的登记必须 `contains == false`。
    const ABSENT: &str = "`pitch_oncc*` 那一项仍未做（另开单）";
    assert!(
        !ENGINE_SOURCE.contains(ABSENT),
        "⭐ 反向腿：`{ABSENT}` 必须 `contains == false`（否则上面的 `contains` 判据恒真）"
    );
    for (label, needle) in [
        (
            "§7 标题（同一个目标的两个拼写）",
            "## 7. ⭐⭐ `pitch` 族（任务单 `#118`）—— 与 `tune` 是**同一个目标**的两个拼写",
        ),
        (
            "`pitch_onccN` 表行（逐字）",
            "| `pitch_onccN` | SFZ v2 | N/A | N/A | **-9600 to 9600** | **cents** |",
        ),
        (
            "`pitch_curveccN` 表行（逐字）",
            "| `pitch_curveccN` | SFZ v2 | integer | **0** | **0 to 255** | N/A |",
        ),
        (
            "`pitch_smoothccN` 表行（逐字）",
            "| `pitch_smoothccN` | SFZ v2 | float | **0** | 0 to ? | **ms** |",
        ),
        (
            "`pitch_stepccN` 表行（逐字）",
            "| `pitch_stepccN` | SFZ v2 | N/A | **0** | 0 to ? | N/A |",
        ),
        (
            "别名句（逐字）",
            "> In ARIA, `tune_*ccN` can also be used as an alias for `pitch_*ccN`.",
        ),
        (
            "裁定：`pitch_*ccN` 归 `ModTarget::Tune`",
            "⭐ **裁定：`pitch_*ccN` 归 [`ModTarget::Tune`]**",
        ),
        ("理由：spec 的用词就是 alias", "**规范的用词就是 alias**"),
        ("理由：仓内既有先例", "**仓内既有先例（同一形状）**"),
        ("代价：同一 CC 上不求和", "⇒ 归约到**一个键**、**不求和**"),
        ("代价：语料 39 处／1 文件", "**39** 处（**1** 个文件"),
        (
            "§7.4 未做两行（登记）",
            "### 7.4 ⛔ 本单**不做**的两行（登记，⛔ 不静默忽略）",
        ),
        (
            "识别：五族",
            "`#118` 加上第五族 **`pitch<suffix>`** ⇒ 现在是**五族**",
        ),
        (
            "尺寸：四个全 ＋0",
            "**四个全 ＋0**（判据 `S113` 由 `size_of` 现读）",
        ),
    ] {
        assert!(
            MODULATION_SOURCE.contains(needle),
            "⭐ `yeban-sfz` 侧必须逐字含：{label}（`{needle}`）"
        );
    }
    println!(
        "[engine-sfz/S113] ① `yeban-sfz` 侧源文本：§7（裁定 ＋ 四条表行 ＋ 代价 ＋ 未做两行）—— 全部逐字命中"
    );

    // ---- ② 单位矩阵新增行：**同一个目标、同一个单位类别** ＋ 两个计数都现算 ----
    let mut accepted = 0usize;
    let mut rejected = 0usize;
    // ⭐⭐ `#119`：**同一份判据里现算 `#118` 口径**（前 [`UNIT_MATRIX_ROWS_BEFORE_119`] 行）
    // ⇒ `#118` 登记的 `(18, 14)` 在 `#119` 追加一行之后**仍被逐字钉住**。
    let mut accepted_before_119 = 0usize;
    let mut rejected_before_119 = 0usize;
    for (row, (name, target, unit)) in UNIT_MATRIX_ROWS.into_iter().enumerate() {
        // ⭐⭐ `#119`：取值由 [`unit_matrix_cell_value`] 现算（见它的文档）。
        let cell_value = unit_matrix_cell_value(unit);
        for suffix in UNIT_MATRIX_SUFFIXES {
            let text = format!(
                "<region> sample=a.wav key=60 pitch_keycenter=60 {name}={cell_value}{suffix}\n"
            );
            if SfzInstrument::load(text, &Default::default()).is_ok() {
                accepted += 1;
                if row < UNIT_MATRIX_ROWS_BEFORE_119 {
                    accepted_before_119 += 1;
                }
            } else {
                rejected += 1;
                if row < UNIT_MATRIX_ROWS_BEFORE_119 {
                    rejected_before_119 += 1;
                }
            }
        }
        let _ = (target, unit);
    }
    println!(
        "[engine-sfz/S113] ② 单位矩阵：行数 {} → {} → {}；格数 {} → {} → {}；\
         `#118` 口径接受／拒绝 ({accepted_before_119}, {rejected_before_119})；\
         `#119` 改动后 ({accepted}, {rejected})（逐格 delta 断言在 `S111` 里现算）",
        UNIT_MATRIX_ROWS_BEFORE,
        UNIT_MATRIX_ROWS_BEFORE_119,
        UNIT_MATRIX_ROWS.len(),
        UNIT_MATRIX_ROWS_BEFORE * UNIT_MATRIX_SUFFIXES.len(),
        UNIT_MATRIX_ROWS_BEFORE_119 * UNIT_MATRIX_SUFFIXES.len(),
        UNIT_MATRIX_ROWS.len() * UNIT_MATRIX_SUFFIXES.len(),
    );
    assert_eq!(
        (accepted_before_119, rejected_before_119),
        (18, 14),
        "⭐ `#118` 登记的读数（前 8 行 × 4 后缀 ＝ 32 格 ⇒ 18 接受／14 拒绝）\
         必须**现算**出来仍未变（第 278 条：`#119` 只追加行，⛔ 不扰动前八行）"
    );
    assert_eq!(
        (accepted, rejected),
        (19, 17),
        "⭐⭐ `#119` 改动后：9 行 × 4 后缀 ＝ 36 格 ⇒ 19 接受／17 拒绝\
         （新增 `volume_oncc1`／`Decibels`：1 格接受 ＋ 3 格拒绝）"
    );
    assert_eq!(
        UNIT_MATRIX_ROWS_BEFORE_119 - UNIT_MATRIX_ROWS_BEFORE,
        1,
        "⭐ `#118` 只多**一行**（`pitch_oncc1`），⛔ `#117` 的七行顺序与内容未动"
    );
    assert_eq!(
        UNIT_MATRIX_ROWS.len() - UNIT_MATRIX_ROWS_BEFORE_119,
        1,
        "⭐ `#119` 只多**一行**（`volume_oncc1`），⛔ `#117`／`#118` 的八行顺序与内容未动"
    );
    assert_eq!(
        UNIT_MATRIX_ROWS[UNIT_MATRIX_ROWS_BEFORE],
        ("pitch_oncc1", ModTarget::Tune, ModUnit::Cents),
        "⭐ `#118` 的新增行必须逐字仍是 (`pitch_oncc1`, `Tune`, `Cents`) —— 规范表行的机械后果"
    );
    assert_eq!(
        UNIT_MATRIX_ROWS[UNIT_MATRIX_ROWS_BEFORE_119],
        ("volume_oncc1", ModTarget::Volume, ModUnit::Decibels),
        "⭐⭐ `#119` 的新增行必须逐字是 (`volume_oncc1`, `Volume`, `Decibels`) —— \
         `volume` 页 Modulation 表的被别名行（`gain_ccN`，Unit dB）＋ 正文别名句的机械后果"
    );

    // ---- ③ 解析与域 ----
    let instrument = SfzInstrument::load(PITCH_FORMS_FIXTURE.to_owned(), &Default::default())
        .expect("合法写法必须解析成功");
    let readings: Vec<(ModTarget, u8, f32, u8)> = instrument
        .with_instrument(|parsed| {
            parsed.regions()[0]
                .cc_modulations()
                .iter()
                .map(|item| (item.target, item.cc, item.delta, item.curve))
                .collect()
        })
        .expect("重解析");
    println!(
        "[engine-sfz/S113] ③ `(target, cc, delta, curve)` 读数 = {readings:?}\
         （`pitch_smoothcc5` / `pitch_stepcc6` 的表行有、⛔ 本单不做 ⇒ 必须不在表里）"
    );
    assert_eq!(
        readings,
        vec![
            (ModTarget::Tune, 1, 1200.0, 0),
            (ModTarget::Tune, 2, -2400.0, 0),
            (ModTarget::Tune, 4, 600.0, 0),
        ],
        "⭐ 三条调制项：`_onccN` / `_ccN` / 裸 `ccN` 归 Delta（曲线下标缺省 0）；\
         ⛔ `pitch_curvecc3` 只有曲线、没有 delta ⇒ 按裁决 4 **不产生**调制项；\
         ⛔ `pitch_smoothcc5` / `pitch_stepcc6` 不识别 ⇒ 一个字节都不进表"
    );
    assert_eq!(
        readings[1].2, -2400.0,
        "⭐ 有牙：`−2400` 音分**超出** `tune` 基准自身的 ±100 ⇒ 域必须是 ±9600"
    );
    assert_eq!(
        instrument
            .with_instrument(|parsed| parsed.regions()[0].pitch_keycenter)
            .expect("重解析"),
        60,
        "⭐ `pitch_keycenter`（真静态 opcode）⛔ 必须不被 `pitch` 族识别吞掉"
    );
    assert_eq!(
        instrument
            .with_instrument(|parsed| parsed.regions()[0].tune)
            .expect("重解析"),
        25,
        "⭐ 静态 `tune=25` 必须仍读进 `Region::tune`（⛔ 不被 `pitch` 族抢走）"
    );

    for (label, text, needle) in [
        (
            "`pitch_oncc1=9601` 越界（±9600 上界）",
            "<region> sample=a.wav pitch_oncc1=9601\n",
            "line 1: `pitch_oncc1` value 9601 out of range -9600..=9600",
        ),
        (
            "`pitch_oncc1=-9601` 越界",
            "<region> sample=a.wav pitch_oncc1=-9601\n",
            "line 1: `pitch_oncc1` value -9601 out of range -9600..=9600",
        ),
        (
            "后缀不匹配 `50%`（cents 族无 `%`）",
            "<region> sample=a.wav pitch_oncc1=50%\n",
            "line 1: `pitch_oncc1` expects a number, got `50%`",
        ),
        (
            "后缀不匹配 `50s`",
            "<region> sample=a.wav pitch_oncc1=50s\n",
            "line 1: `pitch_oncc1` expects a number, got `50s`",
        ),
        (
            "后缀不匹配 `50ms`",
            "<region> sample=a.wav pitch_oncc1=50ms\n",
            "line 1: `pitch_oncc1` expects a number, got `50ms`",
        ),
        (
            "非数",
            "<region> sample=a.wav pitch_oncc1=abc\n",
            "line 1: `pitch_oncc1` expects a number, got `abc`",
        ),
        (
            "`Inf` 明文 ⇒ 非有限（响亮 `Err`）",
            "<region> sample=a.wav pitch_oncc1=inf\n",
            "line 1: `pitch_oncc1` must be finite, got `inf`",
        ),
        (
            "`NaN` 明文 ⇒ 非有限（响亮 `Err`）",
            "<region> sample=a.wav pitch_oncc1=nan\n",
            "line 1: `pitch_oncc1` must be finite, got `nan`",
        ),
        (
            "曲线下标 256 越界",
            "<region> sample=a.wav pitch_curvecc1=256\n",
            "line 1: `pitch_curvecc1` value 256 out of range 0..=255",
        ),
        (
            "曲线下标非整数",
            "<region> sample=a.wav pitch_curvecc1=x\n",
            "line 1: `pitch_curvecc1` expects an integer, got `x`",
        ),
        (
            "CC 号 300 越界",
            "<region> sample=a.wav pitch_oncc300=10\n",
            "line 1: `pitch_oncc300` value 300 out of range 0..=255",
        ),
        // ⭐ 域⛔ 不共享（`pitch` 归 `Tune` ⇒ ±9600；既有族仍是 ±100）。
        (
            "`amplitude` 仍是 ±100",
            "<region> sample=a.wav amplitude_oncc1=101\n",
            "line 1: `amplitude_oncc1` value 101 out of range -100..=100",
        ),
        (
            "`ampeg_attack` 仍是 ±100",
            "<region> sample=a.wav ampeg_attack_oncc1=101\n",
            "line 1: `ampeg_attack_oncc1` value 101 out of range -100..=100",
        ),
    ] {
        let error = SfzInstrument::load(text.to_owned(), &Default::default())
            .expect_err(&format!("{label} 必须响亮 Err"));
        let shown = format!("{error}");
        println!("[engine-sfz/S113] ③ {label} ⇒ `{shown}`");
        assert!(
            shown.contains(needle),
            "⭐ {label}：错误文本必须逐字含 `{needle}`（实得 `{shown}`）"
        );
    }
    // 闭区间端点读得进。
    for value in [9600.0f32, -9600.0, 0.0] {
        let text = format!("<region> sample=a.wav pitch_oncc1={value}\n");
        let loaded = SfzInstrument::load(text, &Default::default())
            .unwrap_or_else(|error| panic!("边界值 {value} 必须合法：{error}"));
        let delta = loaded
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].delta)
            .expect("重解析");
        assert_eq!(delta, value, "⭐ 闭区间端点必须原样读进");
    }
    // 缺省 ⇒ 无调制（与接线前**逐位相同**）。
    let sample = InMemorySample::sine(TUNE_SINE_HZ, TUNE_SAMPLE_HZ, TUNE_PCM_FRAMES);
    let plain = prepare_with(PITCH_BASE_ONLY_FIXTURE, &sample);
    assert!(
        plain.regions()[0].cc_modulations().is_empty(),
        "⭐ 缺省 ⇒ 空表（一项都不进 `cc_mods`）"
    );
    let mut absent_arms: Vec<Vec<u32>> = Vec::new();
    for cc_value in [0u8, 1, 63, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc_value } else { 0 } };
        assert_eq!(
            plain.regions()[0]
                .tune_ratio_with_cc(Some(&probe))
                .to_bits(),
            1.0f32.to_bits(),
            "⭐ cc = {cc_value}：空表 ⇒ 乘子逐位是 1.0"
        );
        let mut out = vec![0.0f32; BLOCK];
        plain.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        absent_arms.push(bits(&out));
    }
    assert!(
        absent_arms.windows(2).all(|pair| pair[0] == pair[1]),
        "⭐ 缺省 ⇒ 任意 CC 值给出**逐位相同**的输出（与接线前同口径）"
    );

    // ---- ④ 真的生效：乘子逐位等于公式 ＋ 两个可读量 ----
    let plan = prepare_with(PITCH_OCTAVE_FIXTURE, &sample);
    assert_eq!(plan.regions()[0].cc_modulations().len(), 1);
    let mods = plan.regions()[0].cc_modulations().to_vec();
    let mut seen: Vec<(u8, f32, Option<usize>, usize)> = Vec::new();
    for cc in [0u8, 37, 63, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        let ratio = plan.regions()[0].tune_ratio_with_cc(Some(&probe));
        let mut out = vec![0.0f32; BLOCK];
        let written = plan.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        assert_eq!(written, BLOCK);
        let cents = mods[0].delta * mods[0].curve.value_at(f32::from(cc));
        let want = (cents / 1200.0).exp2();
        assert_eq!(
            ratio.to_bits(),
            want.to_bits(),
            "⭐ cc = {cc}：乘子必须逐位等于「表里的 delta × 曲线」算出的比（{cents} 音分）"
        );
        let first = tune_first_negative(&out);
        let crossings = tune_rising_crossings(&out);
        println!(
            "[engine-sfz/S113] ④ cc = {cc:3}：delta×curve = {cents:8.3} 音分 ⇒ 乘子 = {ratio:.9}\
             （{:#010x}）；首次为负 = {first:?}；上升零交叉 = {crossings}",
            ratio.to_bits()
        );
        seen.push((cc, ratio, first, crossings));
    }
    assert_eq!(
        seen[0].2,
        Some(55),
        "⭐ cc = 0 ⇒ 乘子 1.0 ⇒ 首次为负仍在源下标 55"
    );
    assert_eq!(
        seen[3].2,
        Some(28),
        "⭐ cc = 127 ⇒ 乘子 2.0（一个八度）⇒ 首次为负提前到 28"
    );
    assert_ne!(
        seen[0].2, seen[3].2,
        "⭐ 两个 CC 值必须给出不同的零交叉位置（音高真的动了）"
    );
    assert_eq!(seen[0].1, 1.0, "⭐ cc = 0 ⇒ 乘子恰 1.0");
    assert_eq!(seen[3].1, 2.0, "⭐ cc = 127 ⇒ 乘子恰 2.0");
    assert!(
        seen[3].3 >= 2 * seen[0].3 - 1,
        "⭐ cc = 127 的上升零交叉次数（{}）必须约为 cc = 0（{}）的两倍",
        seen[3].3,
        seen[0].3
    );

    // ---- ⑤ 三条路一致（本单核心）＋ 病态夹具（第 284 条） ----
    let octave_instrument =
        SfzInstrument::load(PITCH_OCTAVE_FIXTURE.to_owned(), &Default::default())
            .expect("夹具必须解析成功");
    let mut arms: Vec<Vec<u32>> = Vec::new();
    for cc_value in [0u8, 37, 100, 127] {
        let (written_offline, offline, written_flat, flat, realtime) =
            tune_three_paths(&octave_instrument, &plan, &sample, 1, cc_value);
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ cc = {cc_value}：离线 → 摊平必须逐位相同"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ cc = {cc_value}：摊平 → 实时必须逐位相同"
        );
        assert_eq!(
            (written_offline, written_flat),
            (512, 512),
            "⭐ cc = {cc_value}：两条带写入读数的路都必须写满 512 帧"
        );
        assert!(
            nonzero_frames(&offline) > 0
                && nonzero_frames(&flat) > 0
                && nonzero_frames(&realtime) > 0,
            "⭐ cc = {cc_value}：三条路都必须真的出声（⛔ 挡住「静默不发声也算一致」）"
        );
        println!(
            "[engine-sfz/S113] ⑤ cc = {cc_value:3}：离线 非零={} 指纹=0x{:016x}；摊平 非零={} \
             指纹=0x{:016x}；实时 非零={} 指纹=0x{:016x}",
            nonzero_frames(&offline),
            fnv1a_64(&offline),
            nonzero_frames(&flat),
            fnv1a_64(&flat),
            nonzero_frames(&realtime),
            fnv1a_64(&realtime),
        );
        arms.push(bits(&offline));
    }
    assert_ne!(
        arms[0], arms[3],
        "⭐ 反空判腿：cc = 0（乘子 1.0）与 cc = 127（乘子 2.0）必须逐位不同"
    );

    // ⑤b 病态夹具：极大（`Inf`）／极小（次正规）／恰 `0`／乘积 `Inf`／`delta = 0`。
    let pitch_path = |label: &str,
                      items: usize,
                      delta: i32,
                      sample_hz: f32,
                      cc_value: u8|
     -> (f32, usize, usize, [usize; 3]) {
        let text = pitch_compound_fixture(items, delta);
        let ramp = ramp_at(sample_hz, 4096);
        let instrument =
            SfzInstrument::load(text, &Default::default()).expect("病态夹具必须解析成功");
        let plan = PreparedSfz::prepare(&instrument, &ramp, 48_000.0).expect("摊平");
        assert_eq!(
            plan.regions()[0].cc_modulations().len(),
            items,
            "⭐ `{label}`：{items} 个不同 CC ⇒ 表里必须恰好 {items} 项（⛔ 不被合并）"
        );
        let controls: Vec<u8> = (1..=items as u8).collect();
        let probe = |controller: u8| -> u8 {
            if controls.contains(&controller) {
                cc_value
            } else {
                0
            }
        };
        let multiplier = plan.regions()[0].tune_ratio_with_cc(Some(&probe));
        let (written_offline, offline, written_flat, flat, realtime) =
            tune_three_paths(&instrument, &plan, &ramp, items, cc_value);
        println!(
            "[engine-sfz/S113] ⑤b {label}：乘子 = {multiplier:?}（{:#010x}，finite={}）⇒ \
             离线 written={written_offline} 非零={} 指纹=0x{:016x}；摊平 written={written_flat} \
             非零={} 指纹=0x{:016x}；实时 非零={} 指纹=0x{:016x}",
            multiplier.to_bits(),
            multiplier.is_finite(),
            nonzero_frames(&offline),
            fnv1a_64(&offline),
            nonzero_frames(&flat),
            fnv1a_64(&flat),
            nonzero_frames(&realtime),
            fnv1a_64(&realtime),
        );
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ `{label}`：离线 → 摊平必须逐位相同"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ `{label}`：摊平 → 实时必须逐位相同"
        );
        assert_eq!(bits(&offline), bits(&realtime), "⭐ `{label}`：三条路同值");
        (
            multiplier,
            written_offline,
            written_flat,
            [
                nonzero_frames(&offline),
                nonzero_frames(&flat),
                nonzero_frames(&realtime),
            ],
        )
    };
    // 极大：`2^128` 上溢成 `Inf` ⇒ 三条路全退休。
    let (inf_multiplier, written_offline, written_flat, nonzero) = pitch_path(
        "病态① 16×9600 cc127（2^128 ⇒ Inf）",
        16,
        9600,
        48_000.0,
        127,
    );
    assert!(
        !inf_multiplier.is_finite(),
        "⭐ 16 × 9600 ＝ 153600 音分 ⇒ `2^128` 在 `f32` 上是 `Inf`（实得 {inf_multiplier}）"
    );
    assert_eq!(
        (written_offline, written_flat, nonzero),
        (0, 0, [0, 0, 0]),
        "⭐ 乘子非有限 ⇒ 三条路**全退休**"
    );
    // 有限极大：`cc = 126` ⇒ 有限但 `1.69e38` ⇒ 各写 1 帧且逐位相同（`#117` 的边界）。
    let (finite_multiplier, written_offline, written_flat, nonzero) = pitch_path(
        "病态② 16×9600 cc126（有限 1.69e38）",
        16,
        9600,
        48_000.0,
        126,
    );
    assert_eq!(
        finite_multiplier.to_bits(),
        tune_multiplier_reference(16, 9600.0, 126).to_bits(),
        "⭐ 乘子必须逐位等于公式 `2 ^ (Σ 9600 × 126/127 / 1200)`"
    );
    assert!(
        finite_multiplier.is_finite() && finite_multiplier > 1.0e38,
        "⭐ 有牙：这一档乘子必须**有限但极大**（实测 {finite_multiplier:?}）"
    );
    assert_eq!(
        (written_offline, written_flat, nonzero),
        (1, 1, [1, 1, 1]),
        "⭐ 有限大速率：三条路各写**恰好 1 帧**后按「位置越过 PCM」如实退休"
    );
    // 极小（次正规）：`2^−128` ⇒ 三条路照常出声且逐位相同。
    let (subnormal_multiplier, written_offline, _, nonzero) = pitch_path(
        "病态③ 16×(−9600) cc127（2^−128 次正规）",
        16,
        -9600,
        48_000.0,
        127,
    );
    assert_eq!(
        subnormal_multiplier.to_bits(),
        tune_multiplier_reference(16, -9600.0, 127).to_bits(),
        "⭐ 乘子必须逐位等于公式 `2 ^ (Σ 16 × (−9600) / 1200)`"
    );
    assert!(
        subnormal_multiplier.is_finite()
            && subnormal_multiplier > 0.0
            && subnormal_multiplier < f32::MIN_POSITIVE,
        "⭐ 乘子必须是**次正规正数**（{subnormal_multiplier:?}，位型 {:#010x}）",
        subnormal_multiplier.to_bits()
    );
    assert_eq!(
        (written_offline, nonzero),
        (512, [512, 512, 512]),
        "⭐ 极慢速率 ⇒ 三条路都写满 512 帧且逐位相同"
    );
    // 恰 0：`2^−160` 下溢 ⇒ 三条路全退休。
    let (zero_multiplier, written_offline, written_flat, nonzero) = pitch_path(
        "病态④ 20×(−9600) cc127（2^−160 ⇒ 0）",
        20,
        -9600,
        48_000.0,
        127,
    );
    assert_eq!(
        zero_multiplier.to_bits(),
        tune_multiplier_reference(20, -9600.0, 127).to_bits(),
        "⭐ 乘子必须逐位等于公式"
    );
    assert_eq!(
        zero_multiplier.to_bits(),
        0.0f32.to_bits(),
        "⭐ 乘子必须**恰是 `+0.0`**（下溢到零）"
    );
    assert_eq!(
        (written_offline, written_flat, nonzero),
        (0, 0, [0, 0, 0]),
        "⭐ 乘子为零 ⇒ 三条路**全退休**"
    );
    // 乘积 `Inf`：`192 kHz` 基率 4.0 × 有限大乘子 ⇒ 三条路一致退休（`#117` 曾分叉）。
    let (multiplier_192k, written_offline, written_flat, nonzero) = pitch_path(
        "病态⑤ 192k × 16×9600 cc126（乘积 Inf）",
        16,
        9600,
        192_000.0,
        126,
    );
    assert!(
        multiplier_192k.is_finite() && !(4.0 * multiplier_192k).is_finite(),
        "⭐ 基率 4.0 × 有限乘子 ⇒ 乘积必须是 `Inf`（否则本臂没有牙）"
    );
    assert_eq!(
        (written_offline, written_flat, nonzero),
        (0, 0, [0, 0, 0]),
        "⭐⭐ 三条路必须**一致退休**（同量同谓词）"
    );
    // `delta = 0`（对照）：乘子恰 1.0，且与"去掉那一行"逐位相同。
    let (one_multiplier, written_offline, _, nonzero) =
        pitch_path("对照 1×0 音分 cc127（乘子 1.0）", 1, 0, 48_000.0, 127);
    assert_eq!(one_multiplier, 1.0, "⭐ `delta = 0` ⇒ 乘子恰 1.0");
    assert_eq!((written_offline, nonzero), (512, [512, 512, 512]));

    // ---- ⑥ 反向腿 ＋ 三个承重指纹 ＋ 既有三族未扰动 ----
    let with_mod = prepare_with(PITCH_OCTAVE_FIXTURE, &sample);
    let without_mod = prepare_with(PITCH_BASE_ONLY_FIXTURE, &sample);
    let render = |plan: &PreparedSfz, cc: u8| -> Vec<u32> {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        let mut out = vec![0.0f32; BLOCK];
        plan.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        bits(&out)
    };
    assert_ne!(
        render(&with_mod, 0),
        render(&with_mod, 127),
        "⭐ 有那一行 ⇒ 两个 CC 值必须不同"
    );
    assert_eq!(
        render(&without_mod, 0),
        render(&without_mod, 127),
        "⭐ 去掉那一行 ⇒ 两个 CC 值**逐位相同**"
    );
    assert_eq!(
        without_mod.regions()[0].tune_ratio_with_cc(Some(&|_| 0)),
        1.0,
        "⭐ 没有 `pitch` 项 ⇒ 乘子恒 1.0"
    );
    assert_eq!(
        render(&with_mod, 0),
        render(&without_mod, 0),
        "⭐ 如实登记的读数：cc = 0 时调制项贡献恰 0 音分 ⇒ 与「去掉那一行」逐位相同"
    );
    assert_ne!(
        render(&with_mod, 127),
        render(&without_mod, 127),
        "⭐ 有牙：那一行必须真的改变输出（⛔ 不是探针管道自造的差异）"
    );
    // ⭐ 三个承重指纹（夹具里没有任何 `pitch*`／`tune*` ⇒ 必须逐字不变）。
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain_loop = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, expected) in [
        ("S37 臂 1", &looped, 200u64, 0xa9de_c8a8_7f69_106cu64),
        ("S37 臂 2", &plain_loop, u64::MAX, 0xd3c2_a820_76bd_8947u64),
    ] {
        let out = render_pool(plan, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!("[engine-sfz/S113] ⑥ {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）");
        let _checked = check_fingerprint(&format!("S113 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let legacy = fnv1a_64(&legacy_block);
    println!(
        "[engine-sfz/S113] ⑥ S33／S14 广播路径 512 帧 @ (60,127)：指纹 = 0x{legacy:016x}\
         （承重 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）；写入 = {legacy_frames}"
    );
    let _checked = check_fingerprint("S113 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    let scaled: Vec<f32> = legacy_block
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    assert_ne!(
        fnv1a_64(&scaled),
        legacy,
        "⭐ 应绿反向腿：× 1.0000001 ⇒ 指纹必须变"
    );
    // ⭐ 既有族未扰动 ＋ ⭐ 裁定 §7.2 的机械见证（同一目标 ⇒ 不同 CC 求和）。
    let mixed = prepare_with(PITCH_MIXED_FIXTURE, &sample);
    assert_eq!(
        mixed.regions()[0].cc_modulations().len(),
        4,
        "⭐ 混合夹具四条调制项：`amplitude_oncc1` / `tune_oncc2` / `pitch_oncc3` / `ampeg_attack_oncc4`"
    );
    for cc in [0u8, 37, 127] {
        let want_attack = 0.5f32 + 0.5f32 * (f32::from(cc) / 127.0);
        let want_amplitude = (50.0f32 + 50.0f32 * (f32::from(cc) / 127.0)) / 100.0;
        let cents = 1200.0f32 * (f32::from(cc) / 127.0);
        let only_pitch = |controller: u8| -> u8 { if controller == 3 { cc } else { 0 } };
        let only_tune = |controller: u8| -> u8 { if controller == 2 { cc } else { 0 } };
        let both = |controller: u8| -> u8 {
            if controller == 2 || controller == 3 {
                cc
            } else {
                0
            }
        };
        let ratio_pitch = mixed.regions()[0].tune_ratio_with_cc(Some(&only_pitch));
        let ratio_tune = mixed.regions()[0].tune_ratio_with_cc(Some(&only_tune));
        let ratio_both = mixed.regions()[0].tune_ratio_with_cc(Some(&both));
        assert_eq!(
            ratio_pitch.to_bits(),
            (cents / 1200.0).exp2().to_bits(),
            "⭐ cc = {cc}：只有 `pitch_oncc3` 动 ⇒ 乘子 ＝ `2 ^ (1200 × cc/127 / 1200)`"
        );
        assert_eq!(
            ratio_tune.to_bits(),
            ratio_pitch.to_bits(),
            "⭐⭐ **裁定的机械见证**：`tune_oncc2` 与 `pitch_oncc3` 是**同一个目标** \
             ⇒ 同一 CC 值给出**逐位相同**的乘子"
        );
        assert_eq!(
            ratio_both.to_bits(),
            ((cents + cents) / 1200.0).exp2().to_bits(),
            "⭐⭐ 同一目标 + **不同 CC 号** ⇒ 两项**求和**（⛔ 不是「后者胜」）"
        );
        // ⭐ 未扰动：只有 `pitch`／`tune` 的 CC 动 ⇒ `amplitude` 与 `ampeg_attack` 一动不动。
        let probe_all = |controller: u8| -> u8 {
            if controller == 1 || controller == 4 {
                cc
            } else {
                0
            }
        };
        let (attack, unresolved) =
            mixed.regions()[0].ampeg_value_with_cc(AmpegParam::Attack, Some(&probe_all));
        assert_eq!(unresolved, 0);
        assert_eq!(
            attack.to_bits(),
            want_attack.to_bits(),
            "⭐ cc = {cc}：`ampeg_attack` 仍走 `0.5 + 0.5 × cc/127`"
        );
        assert_eq!(
            mixed.regions()[0]
                .amplitude_gain_with_cc(Some(&probe_all))
                .to_bits(),
            want_amplitude.to_bits(),
            "⭐ cc = {cc}：`amplitude` 仍走 `(50 + 50 × cc/127)/100`"
        );
        assert_eq!(
            mixed.regions()[0]
                .amplitude_gain_with_cc(Some(&only_pitch))
                .to_bits(),
            0.5f32.to_bits(),
            "⭐ 只有 `pitch` 的 CC 动 ⇒ `amplitude` 的读数必须一动不动"
        );
        assert_eq!(
            mixed.regions()[0]
                .ampeg_value_with_cc(AmpegParam::Attack, Some(&only_pitch))
                .0
                .to_bits(),
            0.5f32.to_bits(),
            "⭐ 只有 `pitch` 的 CC 动 ⇒ `ampeg_attack` 的读数必须一动不动"
        );
        println!(
            "[engine-sfz/S113] ⑥ 混合夹具 cc = {cc}：ampeg_attack = {attack:.9}、\
             amplitude 因子 = {want_amplitude:.9}、`pitch` 单独 ⇒ tune 乘子 = {ratio_pitch:.9}、\
             `tune` 单独 ⇒ {ratio_tune:.9}、两者同时 ⇒ {ratio_both:.9}（＝平方）"
        );
    }

    // ---- ⑦ 尺寸（`size_of` 现读，⛔ 不手抄）→ 四个全 ＋0 ----
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S113] ⑦ size_of: PreparedRegion={region} SfzVoice={voice} \
         SfzVoicePool={pool} EngineRuntime={runtime}（门槛 192 KiB = {}；余量 = {}）",
        192 * 1024,
        192 * 1024 - runtime,
    );
    assert_eq!(
        region, 6160,
        "⭐ `#118` 没新增任何每区域字段 ⇒ `PreparedRegion` ＋0"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（仍是 40 B）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0（仍是 1712 B）");
    assert_eq!(
        runtime, 180_144,
        "⛔ `EngineRuntime` 必须 ＋0（仍是 180144 B）"
    );
    assert!(runtime < 192 * 1024, "⛔ `EngineRuntime` 必须 < 192 KiB");

    // ---- ⑧ 负向：`pitch_smoothccN` / `pitch_stepccN`（规范有、⛔ 本单不做） ----
    // ⭐ 今天的行为（⛔ 一字不改）：两个名字落不进识别 ⇒ **未知 opcode 忽略**。
    for name in [
        "pitch_smoothcc1",
        "pitch_stepcc1",
        "tune_smoothcc1",
        "tune_stepcc1",
    ] {
        let text = format!("<region> sample=a.wav key=60 pitch_keycenter=60 {name}=10\n");
        let loaded = SfzInstrument::load(text, &Default::default())
            .unwrap_or_else(|error| panic!("`{name}` 必须被忽略而不是报错：{error}"));
        let count = loaded
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations().len())
            .expect("重解析");
        println!(
            "[engine-sfz/S113] ⑧ `{name}=10` 单独出现 ⇒ 调制项数 = {count}（＝未知 opcode 忽略）"
        );
        assert_eq!(count, 0, "⭐ `{name}` ⛔ 不进调制表（本单不做、登记在案）");
    }
    // ⭐ 有牙：`pitch_curveccN`（表里有、**本单做**）必须**真的被识别**（合并进同一键），
    // 而 `pitch_smoothccN` 必须**仍被忽略** —— 同一个夹具里只有这两者能分辨。
    let with_curve = SfzInstrument::load(
        "<region> sample=a.wav pitch_oncc1=100 pitch_curvecc1=9\n".to_owned(),
        &Default::default(),
    )
    .expect("解析");
    assert_eq!(
        with_curve
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].curve)
            .expect("重解析"),
        9,
        "⭐ `pitch_curveccN` 是本族（表行逐字 `0 to 255`）⇒ 曲线下标必须合并进同一个键"
    );
    let with_smooth = SfzInstrument::load(
        "<region> sample=a.wav pitch_oncc1=100 pitch_smoothcc1=9\n".to_owned(),
        &Default::default(),
    )
    .expect("解析");
    assert_eq!(
        with_smooth
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations().len())
            .expect("重解析"),
        1,
        "⭐ 只有 `pitch_oncc1` 那一项进表"
    );
    assert_eq!(
        with_smooth
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].curve)
            .expect("重解析"),
        0,
        "⭐ `pitch_smoothccN` ⛔ 本单不做、今天被当未知 opcode 忽略 ⇒ 曲线下标必须仍缺省 0\
         （⛔ 不是静默吃掉那个 9）"
    );
}

// ---------------------------------------------------------------------------
// ⭐⭐ 任务单 `#119`：`volume` 族的 CC 调制（第三个单位类别 dB）
// ---------------------------------------------------------------------------

/// ⭐ `#119` 四种合法写法 ＋ 三个**必须不被吞掉**的邻居：
/// * 静态 `volume=-6` 是**基准**（⛔ 不是本族的目标）；
/// * `global_volume_oncc7` 是**另一个** opcode（`global_volume` 的调制，语料 47 处）；
/// * `gain_oncc8` 是规范 Modulation 表里**逐字的 delta 行名**（⛔ 本单不识别，§8.4）。
///
/// 另加两个**不做**的行 `volume_smoothcc5` ／ `volume_stepcc6`。
///
/// ⭐ ⭐ **追加修订段（任务单 `#121`，⛔ 上面原文一字未删）**：上面「语料 47 处」的**归属错了** ——
/// ⭐ **原登记**「`global_volume_oncc7` 是另一个 opcode（`global_volume` 的调制，语料 **47** 处）」
/// ⇒ ⭐ **实测**：`global_volume_onccN` 家族 **0** 次 ／ **0** 文件；那 **47** 处**全是
/// `lfo*_volume_onccN`（47 次 ／ 30 文件）**。**口径** ＝ 剥 `//` 注释 ＋ 行首/空白边界 token
/// ＋ **收 `$` 宏名**；**命令** ＝ `cargo test -p yeban-engine --test sfz_instrument s115 -- --nocapture`
/// （逐名展开见引擎侧 `#121` 修订段与 `yeban-sfz/src/modulation.rs` §8.4.1）。
const VOLUME_FORMS_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 volume=-6 \
     volume_oncc1=12 volume_cc2=-24 volume_curvecc3=9 volumecc4=6 \
     volume_smoothcc5=10 volume_stepcc6=1 global_volume_oncc7=3 gain_oncc8=3\n";

/// ⭐ `#119` 可读量夹具：`volume=0`（基准 0 dB ⇒ `volume_gain = 1.0`）
/// ＋ `volume_oncc1=6`（+6 dB ⇒ 乘子 `2 ^ (6 × log2(10) / 20)` ≈ `1.9952621`）。
const VOLUME_DB_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 \
                                  amp_veltrack=0 volume=0 volume_oncc1=6\n";

/// ⭐ `#119` 反向腿：同文本**去掉** `volume_oncc1` 那一行（基准 `volume=0` 仍在）。
const VOLUME_BASE_ONLY_FIXTURE: &str =
    "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 volume=0\n";

/// ⭐ `#119` 未扰动对照：同一夹具里 `volume`（CC1）／`amplitude`（CC2）／`tune`（CC3）／
/// `ampeg_attack`（CC4）**各走自己的公式**（⛔ 四条不同 CC ⇒ 互不干扰）。
const VOLUME_MIXED_FIXTURE: &str = "<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0 \
     volume=0 volume_oncc1=6 amplitude=50 amplitude_oncc2=50 tune_oncc3=1200 \
     ampeg_attack=0.5 ampeg_attack_oncc4=0.5\n";

/// ⭐⭐ `#119` 病态夹具：`items` 条 `volume_onccN=delta`（单位 **dB**）。
///
/// ⚠ 下标逐个不同（`1..=items`）⇒ 归约表里是 `items` 个**独立**的 `(Volume, cc)` 键
/// —— 同一键会被"后者胜"合并，那**凑不出**复合量（`AMPEG_MOD_CAP` 是 20）。
fn volume_compound_fixture(items: usize, delta: i32) -> String {
    let mut text = String::from("<region> sample=a.wav key=60 pitch_keycenter=60 amp_veltrack=0");
    for cc in 1..=items {
        text.push_str(&format!(" volume_oncc{cc}={delta}"));
    }
    text.push('\n');
    text
}

/// ⭐ `#119`：按**实现同一条公式**重算 `volume` 乘子
/// （`2 ^ (Σ delta × curve(cc) × log2(10) / 20)`）。
///
/// ⚠ 与 [`tune_multiplier_reference`] 同款：在判据里用**同一个二进制里的同一次 `exp2`**
/// 当参照 ⇒ 跨架构稳（`exp2` 是 ADR-0001 的超越函数类，⛔ 不硬编码位型当规范常数）。
fn volume_multiplier_reference(items: usize, delta: f32, cc_value: u8) -> f32 {
    let curve = f32::from(cc_value) / 127.0;
    let mut decibels = 0.0f32;
    for _ in 0..items {
        decibels += delta * curve;
    }
    (decibels * std::f32::consts::LOG2_10 / 20.0).exp2()
}

/// ⭐⭐ `#119` 一个病态臂：**打印**乘子位型／基增益／乘积与三条路各自的读数，
/// 并断言三条路**输出逐位相同**（第 284 条）。
///
/// 返回 `(乘子, 离线 written, 摊平 written, 三条路输出的非零帧数, 实时输出)`。
fn volume_boundary_arm(
    label: &str,
    items: usize,
    delta: i32,
    sample_hz: f32,
    cc_value: u8,
) -> (f32, usize, usize, [usize; 3], Vec<f32>) {
    let text = volume_compound_fixture(items, delta);
    let sample = ramp_at(sample_hz, 4096);
    let instrument = SfzInstrument::load(text, &Default::default()).expect("病态夹具必须解析成功");
    let plan = PreparedSfz::prepare(&instrument, &sample, 48_000.0).expect("摊平");
    assert_eq!(
        plan.regions()[0].cc_modulations().len(),
        items,
        "⭐ `{label}`：`items` 个不同 CC ⇒ 表里必须恰好 {items} 项（⛔ 不被合并）"
    );
    let controls: Vec<u8> = (1..=items as u8).collect();
    let probe = |controller: u8| -> u8 {
        if controls.contains(&controller) {
            cc_value
        } else {
            0
        }
    };
    let multiplier = plan.regions()[0].volume_ratio_with_cc(Some(&probe));
    let base_gain = plan.regions()[0].gain_at(60, 127);
    let (written_offline, offline, written_flat, flat, realtime) =
        tune_three_paths(&instrument, &plan, &sample, items, cc_value);
    println!(
        "[engine-sfz/S114] {label}：乘子 = {multiplier:?}（{:#010x}，finite={}）基增益(无探针) = \
         {base_gain:?} 乘积 = {:?}（finite={}）⇒ 离线 written={written_offline} 非零={} \
         指纹=0x{:016x}；摊平 written={written_flat} 非零={} 指纹=0x{:016x}；实时 非零={} \
         指纹=0x{:016x}",
        multiplier.to_bits(),
        multiplier.is_finite(),
        base_gain * multiplier,
        (base_gain * multiplier).is_finite(),
        nonzero_frames(&offline),
        fnv1a_64(&offline),
        nonzero_frames(&flat),
        fnv1a_64(&flat),
        nonzero_frames(&realtime),
        fnv1a_64(&realtime),
    );
    assert_eq!(
        bits(&offline),
        bits(&flat),
        "⭐ `{label}`：离线 → 摊平必须逐位相同"
    );
    assert_eq!(
        bits(&flat),
        bits(&realtime),
        "⭐ `{label}`：摊平 → 实时必须逐位相同"
    );
    assert_eq!(bits(&offline), bits(&realtime), "⭐ `{label}`：三条路同值");
    (
        multiplier,
        written_offline,
        written_flat,
        [
            nonzero_frames(&offline),
            nonzero_frames(&flat),
            nonzero_frames(&realtime),
        ],
        realtime,
    )
}

/// ⭐ `#119`：对**位型切片**做 FNV-1a 64（只留下 [`bits`] 结果的地方打印指纹用；
/// 逐字节口径与 [`fnv1a_64`] 的 `to_le_bytes` 相同）。
fn fnv1a_64_from_bits(words: &[u32]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for word in words {
        for byte in word.to_le_bytes() {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }
    hash
}

/// ⭐⭐ S114（任务单 `#119`；判据 §4 八条 —— **本单核心**）：**`volume` 族的 CC 调制
/// ＝ 第三个单位类别（dB）** ＋ 单位矩阵新增行 ＋ 解析与域 ＋ 真的生效 ＋
/// 三条路一致 ＋ 病态夹具（第 284 条） ＋ 反向腿与三个承重指纹 ＋ 尺寸 ＋
/// 未做行的负向登记。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ ① 两个源文件的**源文本**（`contains`，布尔 ＋ 逐字）；② 单位矩阵的**格**
/// （9 行 × 4 后缀 ＝ 36 格）与**接受／拒绝计数**（格）；③ 调制项的
/// `(目标, cc, delta, curve)` 与错误文本；④ **线性增益乘子**（无量纲）与
/// 三条路各自的**输出位模式**／**非零帧数**（帧）；⑤ **三个承重指纹**（FNV-1a 64）；
/// ⑥ `size_of`（字节）。
#[test]
fn s114_the_volume_family_is_the_third_unit_category_across_three_paths() {
    const ENGINE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const MODULATION_SOURCE: &str = include_str!("../../yeban-sfz/src/modulation.rs");

    // ---- ① 规范逐字 ＋ 单位裁定（源文本 `contains`，逐字） ----
    for (label, needle) in [
        (
            "`#119` 追加修订段（引擎侧）",
            "⭐ ⭐ **追加修订段（任务单 `#119`）",
        ),
        (
            "被修订的支 ＝ `volume_oncc*` 那一项",
            "里 **`volume_oncc*` 这一项**",
        ),
        (
            "`#116`／`#118` 的登记原文仍在（第 278 条）",
            "⛔ **`pan_oncc*` ／ `cutoff_oncc*` 那两项整条有效**",
        ),
        (
            "静态 `volume` 表行（逐字）",
            "| volume | SFZ v1 | float | 0 | -144 to 6 | dB |",
        ),
        (
            "Modulation 表逐字的 delta 行（`gain_ccN`）",
            "| gain_ccN |  | float | 0 | -144 to 48 | dB |",
        ),
        (
            "别名句（逐字）",
            "`volume_ccN` is a valid alias for `gain_ccN`",
        ),
        (
            "⛔ 没有 `volume_onccN` 行（裁定）",
            "该页 **Modulation 表里⛔ 没有 `volume_onccN` 行**",
        ),
        ("新单位类别（落地形状）", "新变体 `ModUnit::Decibels`"),
        ("引擎侧：语料 `volume_onccN`", "**2** 次 ／ **2** 文件"),
        ("引擎侧：静态 `volume=`", "**8504** 次 ／ **284** 文件"),
        (
            "引擎侧：家族子串口径（第 274 条）",
            "**49** 次 ／ **32** 文件",
        ),
        (
            "引擎侧：唯一真用到本族的文件",
            "`assets/samples/karoryfer-black-and-blue-basses/Programs/controls/`",
        ),
        ("引擎侧：四族并集仍 15", "**四族**并集最大仍 **15**"),
        ("引擎侧：尺寸四个全 ＋0", "`SfzVoice` 仍 **40 B**"),
    ] {
        assert!(
            ENGINE_SOURCE.contains(needle),
            "⭐ 引擎侧必须逐字含：{label}（`{needle}`）"
        );
    }
    println!(
        "[engine-sfz/S114] ① 引擎侧源文本：`#119` 修订段 ＋ 规范逐字 ＋ 语料四口径 —— 全部逐字命中"
    );
    // ⭐ 反向腿（⛔ 挡住恒真）：一句**不存在**的登记必须 `contains == false`。
    const ABSENT: &str = "`volume_oncc*` 那一项仍未做（另开单）";
    assert!(
        !ENGINE_SOURCE.contains(ABSENT),
        "⭐ 反向腿：`{ABSENT}` 必须 `contains == false`（否则上面的 `contains` 判据恒真）"
    );
    for (label, needle) in [
        (
            "§8 标题（第三个单位类别）",
            "## 8. ⭐⭐ `volume` 族（任务单 `#119`）—— **第三个单位类别**（dB）",
        ),
        (
            "静态 `volume` 表行（逐字）",
            "| `volume` | SFZ v1 | float | **0** | \\-144 to 6 | **dB** |",
        ),
        (
            "`gain_ccN` 表行（逐字）",
            "| `gain_ccN` |  | float | **0** | **-144 to 48** | **dB** |",
        ),
        (
            "`volume_curveccN` 表行（逐字）",
            "| `volume_curveccN` | SFZ v2 | integer | **0** | **0 to 255** | N/A |",
        ),
        (
            "`volume_smoothccN` 表行（逐字）",
            "| `volume_smoothccN` | SFZ v2 | N/A | N/A |  | N/A |",
        ),
        (
            "`volume_stepccN` 表行（逐字）",
            "| `volume_stepccN` | SFZ v2 | N/A | N/A |  | N/A |",
        ),
        (
            "别名句（逐字）",
            "`volume_ccN` is a valid alias for `gain_ccN`",
        ),
        (
            "裁定：新开第四类 `Decibels`",
            "⭐ **裁定：`volume` 族的 `delta` 单位类别是**新变体 [`ModUnit::Decibels`]**",
        ),
        ("域裁定（-144..=48 dB）", "`-144.0 ..= 48.0` dB"),
        ("⛔ `gain_ccN` 不做", "⛔ **本单不识别**"),
        (
            "第 280 条：`#116` 的原句仍在（历史）",
            "assert_eq!(ModTarget::ALL[ModTarget::COUNT - 1], ModTarget::Tune);",
        ),
        (
            "第 280 条：它已标为历史的原句",
            "⛔ **原句（历史，⛔ 不再作为断言）**",
        ),
    ] {
        assert!(
            MODULATION_SOURCE.contains(needle),
            "⭐ `yeban-sfz` 侧必须逐字含：{label}（`{needle}`）"
        );
    }
    println!(
        "[engine-sfz/S114] ① `yeban-sfz` 侧源文本：§8（裁定 ＋ 五条表行 ＋ 别名句 ＋ 域 ＋ \
         未做行 ＋ 第 280 条的历史原句）—— 全部逐字命中"
    );

    // ---- ② 目标枚举 ＋ 单位矩阵新增行：两个计数都现算 ----
    assert_eq!(ModTarget::COUNT, ModTarget::ALL.len());
    assert_eq!(
        ModTarget::COUNT,
        8,
        "⭐ `#119` 加上 `Volume` ⇒ 目标数是 8（`#104`～`#118` 的七个**下标未动**）"
    );
    assert_eq!(
        ModTarget::ALL[7],
        ModTarget::Volume,
        "⭐ 新增目标必须逐字是 `ALL[7] == Volume`（加在末尾 ⇒ 既有七个下标一个都没动）"
    );
    assert_eq!(ModTarget::ALL[5], ModTarget::Amplitude, "`#115` 的读数未动");
    assert_eq!(
        ModTarget::ALL[6],
        ModTarget::Tune,
        "`#116`／`#118` 的读数未动"
    );
    assert_eq!(ModTarget::Volume.index(), AmpegParam::COUNT + 2);
    assert_eq!(ModTarget::Volume.name(), "volume");
    assert_eq!(ModTarget::Volume.ampeg(), None);
    assert!(
        !ModTarget::Volume.is_time(),
        "⭐ `volume_onccN` 的单位是 dB ⇒ `is_time()` 必须是 `false`\
         （⛔ **不动** `#104` 的 `is_time()` 契约）"
    );
    assert_eq!(ModTarget::Volume.mod_unit(), ModUnit::Decibels);
    assert_eq!(ModTarget::Volume.unit(), "dB");
    assert_eq!(
        ModTarget::Volume.delta_range(),
        (-144.0, 48.0),
        "⭐ 域随被别名的那一行（`gain_ccN`：`-144 to 48` dB）"
    );
    assert_eq!(ModUnit::Decibels.suffixes(), &[""]);
    assert_eq!(
        core::mem::size_of::<ModUnit>(),
        1,
        "⭐ 第四个变体仍落在 1 B（⛔ 不进任何定长容器）"
    );
    let mut accepted = 0usize;
    let mut rejected = 0usize;
    let mut accepted_before_119 = 0usize;
    let mut rejected_before_119 = 0usize;
    for (row, (name, _target, unit)) in UNIT_MATRIX_ROWS.into_iter().enumerate() {
        // ⭐⭐ `#119`：取值由 [`unit_matrix_cell_value`] 现算（见它的文档）。
        let cell_value = unit_matrix_cell_value(unit);
        for suffix in UNIT_MATRIX_SUFFIXES {
            let text = format!(
                "<region> sample=a.wav key=60 pitch_keycenter=60 {name}={cell_value}{suffix}\n"
            );
            if SfzInstrument::load(text, &Default::default()).is_ok() {
                accepted += 1;
                if row < UNIT_MATRIX_ROWS_BEFORE_119 {
                    accepted_before_119 += 1;
                }
            } else {
                rejected += 1;
                if row < UNIT_MATRIX_ROWS_BEFORE_119 {
                    rejected_before_119 += 1;
                }
            }
        }
    }
    println!(
        "[engine-sfz/S114] ② 单位矩阵：行数 {} → {}（新增 `volume_oncc1`／`Decibels`）；\
         接受／拒绝：改动前 (17, 11) → `#118` 口径 ({accepted_before_119}, {rejected_before_119}) \
         → 改动后 ({accepted}, {rejected})",
        UNIT_MATRIX_ROWS_BEFORE_119,
        UNIT_MATRIX_ROWS.len(),
    );
    assert_eq!(
        (accepted_before_119, rejected_before_119),
        (18, 14),
        "⭐ `#118` 口径（前 8 行 × 4 ＝ 32 格）必须**现算**出来仍未变"
    );
    assert_eq!(
        (accepted, rejected),
        (19, 17),
        "⭐⭐ `#119` 改动后（9 行 × 4 ＝ 36 格）⇒ 19 接受／17 拒绝\
         （新增行：1 格接受 `\"\"` ＋ 3 格拒绝 `s`／`ms`／`%`）"
    );
    assert_eq!(
        UNIT_MATRIX_ROWS[UNIT_MATRIX_ROWS_BEFORE_119],
        ("volume_oncc1", ModTarget::Volume, ModUnit::Decibels),
        "⭐ 新增行必须逐字是 (`volume_oncc1`, `Volume`, `Decibels`)"
    );

    // ---- ③ 解析与域 ----
    let instrument = SfzInstrument::load(VOLUME_FORMS_FIXTURE.to_owned(), &Default::default())
        .expect("合法写法必须解析成功");
    let readings: Vec<(ModTarget, u8, f32, u8)> = instrument
        .with_instrument(|parsed| {
            parsed.regions()[0]
                .cc_modulations()
                .iter()
                .map(|item| (item.target, item.cc, item.delta, item.curve))
                .collect()
        })
        .expect("重解析");
    println!(
        "[engine-sfz/S114] ③ `(target, cc, delta, curve)` 读数 = {readings:?}\
         （`volume_smoothcc5` / `volume_stepcc6` / `global_volume_oncc7` / `gain_oncc8` \
         的表行不在本单 ⇒ 必须不进表）"
    );
    assert_eq!(
        readings,
        vec![
            (ModTarget::Volume, 1, 12.0, 0),
            (ModTarget::Volume, 2, -24.0, 0),
            (ModTarget::Volume, 4, 6.0, 0),
        ],
        "⭐ 三条调制项：`_onccN` / `_ccN` / 裸 `ccN` 归 Delta（曲线下标缺省 0）；\
         ⛔ `volume_curvecc3` 只有曲线、没有 delta ⇒ 按裁决 4 **不产生**调制项；\
         ⛔ `volume_smoothcc5` / `volume_stepcc6` / `global_volume_oncc7` / `gain_oncc8` \
         不识别 ⇒ 一个字节都不进表"
    );
    assert_eq!(
        readings[1].2, -24.0,
        "⭐ 有牙：`−24` dB **超出** `volume` 基准表行的 `-144 to 6` 上界，但**在**\
         被别名行 `gain_ccN` 的 `-144 to 48` 之内 ⇒ 域必须随 `gain_ccN`"
    );
    assert_eq!(
        instrument
            .with_instrument(|parsed| parsed.regions()[0].volume)
            .expect("重解析"),
        -6.0,
        "⭐ 静态 `volume=-6` 必须仍读进 `Region::volume`（⛔ 不被本族识别吞掉）"
    );

    for (label, text, needle) in [
        (
            "`volume_oncc1=49` 越界（`gain_ccN` 的 +48 上界）",
            "<region> sample=a.wav volume_oncc1=49\n",
            "line 1: `volume_oncc1` value 49 out of range -144..=48",
        ),
        (
            "`volume_oncc1=-145` 越界",
            "<region> sample=a.wav volume_oncc1=-145\n",
            "line 1: `volume_oncc1` value -145 out of range -144..=48",
        ),
        (
            "后缀不匹配 `50%`（dB 族无 `%`）",
            "<region> sample=a.wav volume_oncc1=50%\n",
            "line 1: `volume_oncc1` expects a number, got `50%`",
        ),
        (
            "后缀不匹配 `50s`",
            "<region> sample=a.wav volume_oncc1=50s\n",
            "line 1: `volume_oncc1` expects a number, got `50s`",
        ),
        (
            "后缀不匹配 `50ms`",
            "<region> sample=a.wav volume_oncc1=50ms\n",
            "line 1: `volume_oncc1` expects a number, got `50ms`",
        ),
        (
            "非数",
            "<region> sample=a.wav volume_oncc1=abc\n",
            "line 1: `volume_oncc1` expects a number, got `abc`",
        ),
        (
            "`Inf` 明文 ⇒ 非有限（响亮 `Err`）",
            "<region> sample=a.wav volume_oncc1=inf\n",
            "line 1: `volume_oncc1` must be finite, got `inf`",
        ),
        (
            "`NaN` 明文 ⇒ 非有限（响亮 `Err`）",
            "<region> sample=a.wav volume_oncc1=nan\n",
            "line 1: `volume_oncc1` must be finite, got `nan`",
        ),
        (
            "曲线下标 256 越界",
            "<region> sample=a.wav volume_curvecc1=256\n",
            "line 1: `volume_curvecc1` value 256 out of range 0..=255",
        ),
        (
            "曲线下标非整数",
            "<region> sample=a.wav volume_curvecc1=x\n",
            "line 1: `volume_curvecc1` expects an integer, got `x`",
        ),
        (
            "CC 号 300 越界",
            "<region> sample=a.wav volume_oncc300=10\n",
            "line 1: `volume_oncc300` value 300 out of range 0..=255",
        ),
        // ⭐ 域⛔ 不共享（`volume` 归 `Decibels` ⇒ `-144..=48`；既有族仍是 ±100）。
        (
            "`amplitude` 仍是 ±100",
            "<region> sample=a.wav amplitude_oncc1=101\n",
            "line 1: `amplitude_oncc1` value 101 out of range -100..=100",
        ),
        (
            "`tune` 仍是 ±9600",
            "<region> sample=a.wav tune_oncc1=9601\n",
            "line 1: `tune_oncc1` value 9601 out of range -9600..=9600",
        ),
    ] {
        let error = SfzInstrument::load(text.to_owned(), &Default::default())
            .expect_err(&format!("{label} 必须响亮 Err"));
        let shown = format!("{error}");
        println!("[engine-sfz/S114] ③ {label} ⇒ `{shown}`");
        assert!(
            shown.contains(needle),
            "⭐ {label}：错误文本必须逐字含 `{needle}`（实得 `{shown}`）"
        );
    }
    // 闭区间端点读得进。
    for value in [48.0f32, -144.0, 0.0] {
        let text = format!("<region> sample=a.wav volume_oncc1={value}\n");
        let loaded = SfzInstrument::load(text, &Default::default())
            .unwrap_or_else(|error| panic!("边界值 {value} 必须合法：{error}"));
        let delta = loaded
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].delta)
            .expect("重解析");
        assert_eq!(delta, value, "⭐ 闭区间端点必须原样读进");
    }
    // 缺省 ⇒ 无调制（与接线前**逐位相同**）。
    let sample = InMemorySample::sine(TUNE_SINE_HZ, TUNE_SAMPLE_HZ, TUNE_PCM_FRAMES);
    let plain = prepare_with(VOLUME_BASE_ONLY_FIXTURE, &sample);
    assert!(
        plain.regions()[0].cc_modulations().is_empty(),
        "⭐ 缺省 ⇒ 空表（一项都不进 `cc_mods`）"
    );
    let mut absent_arms: Vec<Vec<u32>> = Vec::new();
    for cc_value in [0u8, 1, 63, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc_value } else { 0 } };
        assert_eq!(
            plain.regions()[0]
                .volume_ratio_with_cc(Some(&probe))
                .to_bits(),
            1.0f32.to_bits(),
            "⭐ cc = {cc_value}：空表 ⇒ 乘子逐位是 1.0"
        );
        let mut out = vec![0.0f32; BLOCK];
        plain.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        absent_arms.push(bits(&out));
    }
    assert!(
        absent_arms.windows(2).all(|pair| pair[0] == pair[1]),
        "⭐ 缺省 ⇒ 任意 CC 值给出**逐位相同**的输出（与接线前同口径）"
    );

    // ---- ④ 真的生效：乘子逐位等于公式 ＋ 两个 CC 值输出不同 ----
    let plan = prepare_with(VOLUME_DB_FIXTURE, &sample);
    assert_eq!(plan.regions()[0].cc_modulations().len(), 1);
    let mods = plan.regions()[0].cc_modulations().to_vec();
    let mut seen: Vec<(u8, f32, u64)> = Vec::new();
    for cc in [0u8, 37, 63, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        let ratio = plan.regions()[0].volume_ratio_with_cc(Some(&probe));
        let mut out = vec![0.0f32; BLOCK];
        let written = plan.render_block_into_with_cc(60, 127, Some(&probe), &mut out);
        assert_eq!(written, BLOCK);
        let decibels = mods[0].delta * mods[0].curve.value_at(f32::from(cc));
        let want = (decibels * std::f32::consts::LOG2_10 / 20.0).exp2();
        assert_eq!(
            ratio.to_bits(),
            want.to_bits(),
            "⭐ cc = {cc}：乘子必须逐位等于「表里的 delta(dB) × 曲线」算出的比\
             （{decibels} dB ＝ {decibels} 分贝）"
        );
        assert_eq!(
            ratio.to_bits(),
            volume_multiplier_reference(1, mods[0].delta, cc).to_bits(),
            "⭐ cc = {cc}：与判据里按实现同一条公式重算的参照逐位相同"
        );
        println!(
            "[engine-sfz/S114] ④ cc = {cc:3}：delta×curve = {decibels:8.4} dB ⇒ 乘子 = \
             {ratio:.9}（{:#010x}）输出非零帧 = {}、指纹 = 0x{:016x}",
            ratio.to_bits(),
            nonzero_frames(&out),
            fnv1a_64(&out),
        );
        seen.push((cc, ratio, fnv1a_64(&out)));
    }
    assert_eq!(seen[0].1, 1.0, "⭐ cc = 0 ⇒ 乘子恰 1.0（0 dB）");
    assert!(
        (seen[3].1 - 1.995_262_1).abs() < 1.0e-6,
        "⭐ cc = 127、delta = 6 dB ⇒ 乘子 ≈ 1.9952621（实得 {}）",
        seen[3].1
    );
    assert_ne!(
        seen[0].2, seen[3].2,
        "⭐ 两个 CC 值（0 与 127）必须给出**不同**的输出（音量真的动了）"
    );
    assert!(
        seen[0].1 < seen[3].1,
        "⭐ +6 dB 必须是**放大**（乘子 > 1.0）—— ⛔ 不是方向反了"
    );

    // ---- ⑤ 三条路一致（本单核心）＋ 病态夹具（第 284 条） ----
    let db_instrument = SfzInstrument::load(VOLUME_DB_FIXTURE.to_owned(), &Default::default())
        .expect("夹具必须解析成功");
    let mut arms: Vec<Vec<u32>> = Vec::new();
    for cc_value in [0u8, 37, 100, 127] {
        let (written_offline, offline, written_flat, flat, realtime) =
            tune_three_paths(&db_instrument, &plan, &sample, 1, cc_value);
        assert_eq!(
            bits(&offline),
            bits(&flat),
            "⭐ cc = {cc_value}：离线 → 摊平必须逐位相同"
        );
        assert_eq!(
            bits(&flat),
            bits(&realtime),
            "⭐ cc = {cc_value}：摊平 → 实时必须逐位相同"
        );
        assert_eq!(
            (written_offline, written_flat),
            (512, 512),
            "⭐ cc = {cc_value}：两条带写入读数的路都必须写满 512 帧"
        );
        assert!(
            nonzero_frames(&offline) > 0
                && nonzero_frames(&flat) > 0
                && nonzero_frames(&realtime) > 0,
            "⭐ cc = {cc_value}：三条路都必须真的出声（⛔ 挡住「静默不发声也算一致」）"
        );
        println!(
            "[engine-sfz/S114] ⑤ cc = {cc_value:3}：离线 非零={} 指纹=0x{:016x}；摊平 非零={} \
             指纹=0x{:016x}；实时 非零={} 指纹=0x{:016x}",
            nonzero_frames(&offline),
            fnv1a_64(&offline),
            nonzero_frames(&flat),
            fnv1a_64(&flat),
            nonzero_frames(&realtime),
            fnv1a_64(&realtime),
        );
        arms.push(bits(&offline));
    }
    assert_ne!(
        arms[0], arms[3],
        "⭐ 反空判腿：cc = 0（乘子 1.0）与 cc = 127（乘子 ≈ 2.0）必须逐位不同"
    );

    // ⑤b 病态夹具：`Inf`／有限极大／次正规／恰 `0`（下溢）／`delta = 0`。
    //     ⚠ 阈值：上溢发生在 `dB × log2(10) / 20 > 128` ⇒ `|dB| > 1541.4`；
    //     下溢到 `0` 发生在 `dB < −149 × 20 / log2(10) = −897.1`。
    let (inf_multiplier, _wo, _wf, nz, _) =
        volume_boundary_arm("① 20×48 dB cc127（≈2^159 ⇒ Inf）", 20, 48, 48_000.0, 127);
    assert!(
        inf_multiplier.is_infinite(),
        "⭐ ① 20 条 × 48 dB × 满量程 ⇒ 乘子必须是 `Inf`（实得 {inf_multiplier:?}）"
    );
    assert!(nz.iter().all(|count| *count > 0), "⭐ ① 三条路都写出非零帧");
    let (finite_multiplier, wo, wf, nz, _) = volume_boundary_arm(
        "② 20×38 dB cc127（≈2^126 ⇒ 有限极大）",
        20,
        38,
        48_000.0,
        127,
    );
    assert!(
        finite_multiplier.is_finite() && finite_multiplier > 1.0e30,
        "⭐ ② 必须是**有限极大**（实得 {finite_multiplier:?}）"
    );
    assert_eq!((wo, wf), (512, 512), "⭐ ② 两条带写入读数的路都写满");
    assert!(nz.iter().all(|count| *count > 0));
    let (subnormal, wo, wf, nz, _) = volume_boundary_arm(
        "③ 20×(−39) dB cc127（≈2^−130 ⇒ 次正规）",
        20,
        -39,
        48_000.0,
        127,
    );
    assert!(
        subnormal > 0.0 && subnormal < f32::MIN_POSITIVE,
        "⭐ ③ 必须是**正次正规**（实得 {subnormal:?}，`MIN_POSITIVE` = {:?}）",
        f32::MIN_POSITIVE
    );
    assert_eq!((wo, wf), (512, 512));
    assert!(
        nz.iter().all(|count| *count > 0),
        "⭐ ③ 次正规乘子仍必须写出非零帧"
    );
    let (underflow, wo, wf, nz, _) =
        volume_boundary_arm("④ 20×(−48) dB cc127（≈2^−159 ⇒ 0）", 20, -48, 48_000.0, 127);
    assert_eq!(underflow, 0.0, "⭐ ④ 必须**下溢到恰 0**");
    assert_eq!((wo, wf), (512, 512));
    assert!(
        nz.iter().all(|count| *count == 0),
        "⭐ ④ 乘子 0 ⇒ 三条路都全零（⛔ 不是「写不进去」）"
    );
    let (zero_delta, wo, wf, nz, _) = volume_boundary_arm(
        "⑤ 20×0 dB cc127（delta = 0 ⇒ 乘子恰 1.0）",
        20,
        0,
        48_000.0,
        127,
    );
    assert_eq!(zero_delta, 1.0, "⭐ ⑤ `delta = 0` ⇒ 乘子**恰** 1.0");
    assert_eq!((wo, wf), (512, 512));
    assert!(nz.iter().all(|count| *count > 0));

    // ---- ⑥ 反向腿 ＋ 三个承重指纹 ＋ 既有族未扰动 ----
    let with_line = prepare_with(VOLUME_DB_FIXTURE, &sample);
    let without_line = prepare_with(VOLUME_BASE_ONLY_FIXTURE, &sample);
    assert_eq!(
        without_line.regions()[0].cc_modulations().len(),
        0,
        "⭐ 反向腿夹具必须**没有**调制项"
    );
    let mut with_arms: Vec<Vec<u32>> = Vec::new();
    let mut without_arms: Vec<Vec<u32>> = Vec::new();
    for cc_value in [0u8, 127] {
        let probe = |controller: u8| -> u8 { if controller == 1 { cc_value } else { 0 } };
        let mut a = vec![0.0f32; BLOCK];
        let mut b = vec![0.0f32; BLOCK];
        with_line.render_block_into_with_cc(60, 127, Some(&probe), &mut a);
        without_line.render_block_into_with_cc(60, 127, Some(&probe), &mut b);
        with_arms.push(bits(&a));
        without_arms.push(bits(&b));
    }
    assert_ne!(
        with_arms[0], with_arms[1],
        "⭐ 有那一行 ⇒ 两个 CC 值必须**不同**"
    );
    assert_eq!(
        without_arms[0], without_arms[1],
        "⭐ **反向腿**：去掉 `volume_oncc1` 那一行 ⇒ 两个 CC 值**逐位相同**"
    );
    assert_eq!(
        without_line.regions()[0]
            .volume_ratio_with_cc(Some(&|_| 127))
            .to_bits(),
        1.0f32.to_bits(),
        "⭐ 反向腿：空表 ⇒ 乘子逐位 1.0"
    );
    println!(
        "[engine-sfz/S114] ⑥ 反向腿：有那一行 ⇒ cc=0/127 指纹 0x{:016x}/0x{:016x}（不同）；\
         去掉那一行 ⇒ 0x{:016x}/0x{:016x}（逐位相同）",
        fnv1a_64_from_bits(&with_arms[0]),
        fnv1a_64_from_bits(&with_arms[1]),
        fnv1a_64_from_bits(&without_arms[0]),
        fnv1a_64_from_bits(&without_arms[1]),
    );

    // ⭐ 三个承重指纹（夹具里没有任何 `volume*`／`amplitude*`／`tune*`／`pitch*` ⇒ 必须逐字不变）。
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain_loop = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, expected) in [
        ("S37 臂 1", &looped, 200u64, 0xa9de_c8a8_7f69_106cu64),
        ("S37 臂 2", &plain_loop, u64::MAX, 0xd3c2_a820_76bd_8947u64),
    ] {
        let out = render_pool(plan, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!("[engine-sfz/S114] ⑥ {label}：指纹 = 0x{actual:016x}（承重 = 0x{expected:016x}）");
        let _checked = check_fingerprint(&format!("S114 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let legacy = fnv1a_64(&legacy_block);
    println!(
        "[engine-sfz/S114] ⑥ S33／S14 广播路径 512 帧 @ (60,127)：指纹 = 0x{legacy:016x}\
         （承重 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}）；写入 = {legacy_frames}"
    );
    let _checked = check_fingerprint("S114 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    let scaled: Vec<f32> = legacy_block
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    assert_ne!(
        fnv1a_64(&scaled),
        legacy,
        "⭐ 应绿反向腿：× 1.0000001 ⇒ 指纹必须变"
    );
    // ⭐ 既有族未扰动：只有 `volume` 的 CC 动 ⇒ `amplitude`／`tune`／`ampeg_attack` 一动不动。
    let mixed = prepare_with(VOLUME_MIXED_FIXTURE, &sample);
    assert_eq!(
        mixed.regions()[0].cc_modulations().len(),
        4,
        "⭐ 混合夹具四条调制项：`volume_oncc1` / `amplitude_oncc2` / `tune_oncc3` / `ampeg_attack_oncc4`"
    );
    for cc in [0u8, 37, 127] {
        let want_attack = 0.5f32 + 0.5f32 * (f32::from(cc) / 127.0);
        let want_amplitude = (50.0f32 + 50.0f32 * (f32::from(cc) / 127.0)) / 100.0;
        let want_volume =
            (6.0f32 * (f32::from(cc) / 127.0) * std::f32::consts::LOG2_10 / 20.0).exp2();
        let cents = 1200.0f32 * (f32::from(cc) / 127.0);
        let only_volume = |controller: u8| -> u8 { if controller == 1 { cc } else { 0 } };
        assert_eq!(
            mixed.regions()[0]
                .volume_ratio_with_cc(Some(&only_volume))
                .to_bits(),
            want_volume.to_bits(),
            "⭐ cc = {cc}：只有 `volume_oncc1` 动 ⇒ 乘子 ＝ `2 ^ (6 × cc/127 × log2(10) / 20)`"
        );
        assert_eq!(
            mixed.regions()[0]
                .amplitude_gain_with_cc(Some(&only_volume))
                .to_bits(),
            0.5f32.to_bits(),
            "⭐ 只有 `volume` 的 CC 动 ⇒ `amplitude` 的读数必须一动不动"
        );
        assert_eq!(
            mixed.regions()[0]
                .ampeg_value_with_cc(AmpegParam::Attack, Some(&only_volume))
                .0
                .to_bits(),
            0.5f32.to_bits(),
            "⭐ 只有 `volume` 的 CC 动 ⇒ `ampeg_attack` 的读数必须一动不动"
        );
        assert_eq!(
            mixed.regions()[0]
                .tune_ratio_with_cc(Some(&only_volume))
                .to_bits(),
            1.0f32.to_bits(),
            "⭐ 只有 `volume` 的 CC 动 ⇒ `tune` 的乘子必须一动不动（仍是 1.0）"
        );
        // 反过来：只有 `amplitude`／`tune`／`ampeg` 的 CC 动 ⇒ `volume` 乘子一动不动。
        let others = |controller: u8| -> u8 {
            if controller == 2 || controller == 3 || controller == 4 {
                cc
            } else {
                0
            }
        };
        assert_eq!(
            mixed.regions()[0]
                .volume_ratio_with_cc(Some(&others))
                .to_bits(),
            1.0f32.to_bits(),
            "⭐ 只有别的族的 CC 动 ⇒ `volume` 的乘子必须一动不动"
        );
        assert_eq!(
            mixed.regions()[0]
                .amplitude_gain_with_cc(Some(&others))
                .to_bits(),
            want_amplitude.to_bits(),
            "⭐ cc = {cc}：`amplitude` 仍走 `(50 + 50 × cc/127)/100`"
        );
        assert_eq!(
            mixed.regions()[0]
                .ampeg_value_with_cc(AmpegParam::Attack, Some(&others))
                .0
                .to_bits(),
            want_attack.to_bits(),
            "⭐ cc = {cc}：`ampeg_attack` 仍走 `0.5 + 0.5 × cc/127`"
        );
        assert_eq!(
            mixed.regions()[0]
                .tune_ratio_with_cc(Some(&others))
                .to_bits(),
            (cents / 1200.0).exp2().to_bits(),
            "⭐ cc = {cc}：`tune` 仍走 `2 ^ (1200 × cc/127 / 1200)`"
        );
        println!(
            "[engine-sfz/S114] ⑥ 混合夹具 cc = {cc}：volume 乘子 = {want_volume:.9}、\
             amplitude 因子 = {want_amplitude:.9}、ampeg_attack = {want_attack:.9}、\
             tune 乘子 = {:.9}",
            (cents / 1200.0).exp2()
        );
    }

    // ---- ⑦ 尺寸（`size_of` 现读，⛔ 不手抄）→ 四个全 ＋0 ----
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S114] ⑦ size_of: PreparedRegion={region} SfzVoice={voice} \
         SfzVoicePool={pool} EngineRuntime={runtime}（门槛 192 KiB = {}；余量 = {}）；\
         零分配场景见 `rt_zero_alloc` 的 `[sfz-volume]`",
        192 * 1024,
        192 * 1024 - runtime,
    );
    assert_eq!(
        region, 6160,
        "⭐ `#119` 没新增任何每区域字段（`volume` 基准早在 `volume_gain` 里、乘子是栈上值）\
         ⇒ `PreparedRegion` ＋0"
    );
    assert_eq!(voice, 40, "⛔ `SfzVoice` 必须 ＋0（仍是 40 B）");
    assert_eq!(pool, 1712, "⛔ `SfzVoicePool` 必须 ＋0（仍是 1712 B）");
    assert_eq!(
        runtime, 180_144,
        "⛔ `EngineRuntime` 必须 ＋0（仍是 180144 B）"
    );
    assert!(runtime < 192 * 1024, "⛔ `EngineRuntime` 必须 < 192 KiB");

    // ---- ⑧ 负向：本单**不做**的行（规范有、或有别的实体）今天必须被忽略 ----
    for name in [
        "volume_smoothcc1",
        "volume_stepcc1",
        "gain_cc1",
        "gain_oncc1",
        "gain_curvecc1",
        "global_volume_oncc1",
        "master_volume_oncc1",
        "group_volume_oncc1",
        // ⭐⭐ 任务单 `#119`（判据 §4.8）：**不属本单**、也**不被本单的改动影响**的邻居
        // —— 它们与 `volume` 前缀**不相交** ⇒ 今天的"未知 opcode 忽略"行为**一字未变**。
        // ⛔ 这里把**今天的行为**钉住（⛔ 不是"哪天变成识别到了但静默丢弃"）。
        "cutoff_oncc1",
        "cutoff_cc1",
        "pan_oncc1",
        "pan_cc1",
        "pitch_smoothcc1",
        "pitch_stepcc1",
        "tune_smoothcc1",
        "tune_stepcc1",
    ] {
        let text = format!("<region> sample=a.wav key=60 pitch_keycenter=60 {name}=10\n");
        let loaded = SfzInstrument::load(text, &Default::default())
            .unwrap_or_else(|error| panic!("`{name}` 必须被忽略而不是报错：{error}"));
        let count = loaded
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations().len())
            .expect("重解析");
        println!(
            "[engine-sfz/S114] ⑧ `{name}=10` 单独出现 ⇒ 调制项数 = {count}（＝未知 opcode 忽略）"
        );
        assert_eq!(count, 0, "⭐ `{name}` ⛔ 不进调制表（本单不做、登记在案）");
    }
    // ⭐ 有牙：`volume_curveccN`（表里有、**本单做**）必须**真的被识别**（合并进同一键），
    // 而 `volume_smoothccN` 必须**仍被忽略** —— 同一个夹具里只有这两者能分辨。
    let with_curve = SfzInstrument::load(
        "<region> sample=a.wav volume_oncc1=6 volume_curvecc1=9\n".to_owned(),
        &Default::default(),
    )
    .expect("解析");
    assert_eq!(
        with_curve
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].curve)
            .expect("重解析"),
        9,
        "⭐ `volume_curveccN` 是本族（表行逐字 `0 to 255`）⇒ 曲线下标必须合并进同一个键"
    );
    let with_smooth = SfzInstrument::load(
        "<region> sample=a.wav volume_oncc1=6 volume_smoothcc1=9\n".to_owned(),
        &Default::default(),
    )
    .expect("解析");
    assert_eq!(
        with_smooth
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations().len())
            .expect("重解析"),
        1,
        "⭐ 只有 `volume_oncc1` 那一项进表"
    );
    assert_eq!(
        with_smooth
            .with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].curve)
            .expect("重解析"),
        0,
        "⭐ `volume_smoothccN` ⛔ 本单不做、今天被当未知 opcode 忽略 ⇒ 曲线下标必须仍缺省 0\
         （⛔ 不是静默吃掉那个 9）"
    );
    // ⭐ 有牙②：`volumeccN`（裸 SFZ1 形）**真的被识别**，而它的邻居 `gain_onccN` 不被识别。
    let bare = SfzInstrument::load(
        "<region> sample=a.wav volumecc1=6 gain_oncc1=6\n".to_owned(),
        &Default::default(),
    )
    .expect("解析");
    assert_eq!(
        bare.with_instrument(|parsed| parsed.regions()[0].cc_modulations().len())
            .expect("重解析"),
        1,
        "⭐ `volumeccN`（裸）识别、`gain_onccN`（规范逐字的行名）⛔ 不识别 ⇒ 恰 1 项"
    );
    assert_eq!(
        bare.with_instrument(|parsed| parsed.regions()[0].cc_modulations()[0].target)
            .expect("重解析"),
        ModTarget::Volume,
        "⭐ 那一项必须归 `ModTarget::Volume`"
    );
}

// ---------------------------------------------------------------------------
// ⭐⭐ 任务单 `#121`：`#119` 三格错数的修订（台账第 278 条）＋ `#120` 的"规范无"依据
// ---------------------------------------------------------------------------

/// ⭐ `#121` 的**就地重算口径**（与 `crates/yeban-engine/src/sfz_instrument.rs` 的 `#121`
/// 修订段**逐字同一口径**）：`assets/samples/**/*.sfz` 逐行**剥 `//` 注释** ⇒ 取**行首或
/// 空白边界**的 opcode token ⇒ token 里 `volume_oncc` 之后的尾巴必须是**数字**或 **`$` 宏名**
/// （⭐ **收 `$` 宏名**：`volume_oncc$F2_DIS` **算**本族的一个键 —— 解析器就是这么读的）。
///
/// 对象 ＝ ① 三格的**逐名重算**（opcode 名 × 出现次数 × 文件数）；② 三份源文本里的 `#121`
/// 修订段（`contains`，逐字）；③ `#120` 的"规范无 Modulation 表"依据 ＋ 反向腿；
/// ④ `size_of`（字节）＋ 既有承重指纹与 `S114` 反向腿的字面量仍在。
#[test]
fn s115_the_three_revised_volume_counters_and_the_scope_absence() {
    use std::collections::{BTreeMap, BTreeSet};

    const ENGINE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");
    const MODULATION_SOURCE: &str = include_str!("../../yeban-sfz/src/modulation.rs");
    const SELF_SOURCE: &str = include_str!("sfz_instrument.rs");

    fn is_token_byte(byte: u8) -> bool {
        byte.is_ascii_alphanumeric() || byte == b'_' || byte == b'$'
    }
    fn is_volume_suffix(suffix: &str) -> bool {
        match suffix.strip_prefix('$') {
            Some(macro_name) => {
                !macro_name.is_empty()
                    && macro_name
                        .bytes()
                        .all(|b| b.is_ascii_alphanumeric() || b == b'_')
            }
            None => !suffix.is_empty() && suffix.bytes().all(|b| b.is_ascii_digit()),
        }
    }

    // ---- ① 三格的**原句仍在**（第 278 条：⛔ 不许删改原句）＋ 三条**修订句**逐字在 ----
    for (label, needle) in [
        (
            "① 原句（`global_volume_onccN` 一族 47 次 ／ 32 文件）",
            "`global_volume_onccN` 一族（**另外三个** opcode） | **47** 次 ／ **32** 文件 |",
        ),
        (
            "② 原句（家族子串 49 次 ／ 32 文件）",
            "**49** 次 ／ **32** 文件 —— 那 **47** 处差额**全是别的 opcode**",
        ),
        (
            "③ 原句（裸 `volume_onccN` 2 次 ／ 2 文件）",
            "| `volume_onccN`（**裸**；⛔ 规范 Modulation 表无此行） | **2** 次 ／ **2** 文件 |",
        ),
    ] {
        assert!(
            ENGINE_SOURCE.contains(needle),
            "⛔ 原句必须一字未删（第 278 条）：{label}"
        );
    }
    for (label, needle) in [
        (
            "① 修订句",
            "原登记「`global_volume_onccN` 一族 **47** 次 ／ **32** 文件」 ⇒ ⭐ **实测**",
        ),
        (
            "② 修订句",
            "原登记「家族子串 **49** 次 ／ **32** 文件」 ⇒ ⭐ **实测 50 次 ／ 33 文件**",
        ),
        (
            "③ 修订句",
            "原登记「裸 `volume_onccN` **2** 次 ／ **2** 文件」 ⇒ ⭐ **实测 3 次 ／ 3 文件**",
        ),
    ] {
        assert!(
            ENGINE_SOURCE.contains(needle),
            "⭐ 修订句必须逐字在：{label}"
        );
    }
    assert!(
        ENGINE_SOURCE.contains("⭐ ⭐ **追加修订段（任务单 `#121`）"),
        "⭐ 「有修订段」本身必须是可判事实（第 280 条）"
    );
    let caliber_marks = ENGINE_SOURCE.matches("口径 ＝ 剥 `//` 注释").count();
    assert!(
        caliber_marks >= 3,
        "⭐ 三条修订里**每条**都要写口径（实测 {caliber_marks} 处，要求 ≥ 3）"
    );
    let command_marks = ENGINE_SOURCE.matches("命令 ＝").count();
    assert!(
        command_marks >= 3,
        "⭐ 三条修订里**每条**都要写依据命令（实测 {command_marks} 处，要求 ≥ 3）"
    );
    assert!(
        ENGINE_SOURCE.contains("**收 `$` 宏名**"),
        "⭐ 口径裁定（收 `$` 宏名）必须逐字可判"
    );
    assert!(
        ENGINE_SOURCE
            .contains("cargo test -p yeban-engine --test sfz_instrument s115 -- --nocapture"),
        "⭐ 依据命令必须逐字可判"
    );
    println!(
        "[engine-sfz/S115] ① 三格原句仍在 ＋ 三条修订句逐字在 ＋ 口径标记 {caliber_marks} 处 ＋ \
         命令标记 {command_marks} 处"
    );

    // ---- ② 就地重算（与修订段同一口径）：逐名打印 ＋ 逐档断言 ----
    let corpus_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets/samples");
    let mut paths: Vec<std::path::PathBuf> = Vec::new();
    let mut stack = vec![corpus_root.clone()];
    while let Some(dir) = stack.pop() {
        let entries = std::fs::read_dir(&dir)
            .unwrap_or_else(|error| panic!("⭐ 语料目录 {dir:?} 必须存在：{error}"));
        for entry in entries {
            let path = entry.expect("目录项").path();
            if path.is_dir() {
                stack.push(path);
            } else if path.extension().and_then(|extension| extension.to_str()) == Some("sfz") {
                paths.push(path);
            }
        }
    }
    paths.sort();
    assert_eq!(
        paths.len(),
        1398,
        "⭐ 分母 ＝ `find assets/samples -name '*.sfz' | wc -l` ⇒ 必须与 `#121` 修订段一致"
    );

    let mut occurrences: BTreeMap<String, usize> = BTreeMap::new();
    let mut files_of: BTreeMap<String, BTreeSet<usize>> = BTreeMap::new();
    let mut substring_total = 0usize;
    let mut substring_files = 0usize;
    for (index, path) in paths.iter().enumerate() {
        let text = std::fs::read_to_string(path)
            .unwrap_or_else(|error| panic!("⭐ 读 {path:?} 失败：{error}"));
        let mut file_has_substring = false;
        for raw in text.lines() {
            let line = raw.split("//").next().unwrap_or("");
            let bytes = line.as_bytes();
            let mut cursor = 0usize;
            while cursor < bytes.len() {
                if !is_token_byte(bytes[cursor]) {
                    cursor += 1;
                    continue;
                }
                let start = cursor;
                while cursor < bytes.len() && is_token_byte(bytes[cursor]) {
                    cursor += 1;
                }
                if start != 0 && !bytes[start - 1].is_ascii_whitespace() {
                    continue;
                }
                let token = &line[start..cursor];
                let Some(at) = token.find("volume_oncc") else {
                    continue;
                };
                if !is_volume_suffix(&token[at + "volume_oncc".len()..]) {
                    continue;
                }
                *occurrences.entry(token.to_owned()).or_default() += 1;
                files_of.entry(token.to_owned()).or_default().insert(index);
            }
            let hits = line.matches("volume_oncc").count();
            substring_total += hits;
            if hits > 0 {
                file_has_substring = true;
            }
        }
        if file_has_substring {
            substring_files += 1;
        }
    }

    let mut bare: BTreeMap<String, usize> = BTreeMap::new();
    let mut prefixed: BTreeMap<String, usize> = BTreeMap::new();
    for (name, count) in &occurrences {
        if name.starts_with("volume_oncc") {
            bare.insert(name.clone(), *count);
        } else {
            prefixed.insert(name.clone(), *count);
        }
    }
    let files_for = |names: &BTreeMap<String, usize>| -> usize {
        let mut set = BTreeSet::new();
        for name in names.keys() {
            set.extend(files_of[name].iter().copied());
        }
        set.len()
    };
    let bare_total: usize = bare.values().sum();
    let prefixed_total: usize = prefixed.values().sum();
    let bare_files = files_for(&bare);
    let prefixed_files = files_for(&prefixed);

    let ordered = |names: &BTreeMap<String, usize>| -> Vec<(String, usize, usize)> {
        let mut rows: Vec<(String, usize, usize)> = names
            .iter()
            .map(|(name, count)| (name.clone(), *count, files_of[name].len()))
            .collect();
        rows.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
        rows
    };
    for (tier, names) in [
        ("① 前缀族（`*_volume_onccN`）", &prefixed),
        ("③ 裸 `volume_onccN`", &bare),
    ] {
        for (name, count, files) in ordered(names) {
            println!(
                "[engine-sfz/S115] ② {tier}：`{name}` = {count} 次 ／ {files} 文件\
                 （第 287 条：逐个完整 opcode 名 ＋ 各自计数）"
            );
        }
    }
    println!(
        "[engine-sfz/S115] ② 三档：裸 {bare_total} 次 ／ {bare_files} 文件；\
         前缀 {prefixed_total} 次 ／ {prefixed_files} 文件；\
         家族子串 {substring_total} 次 ／ {substring_files} 文件（分母 {} 份 `.sfz`）",
        paths.len()
    );

    assert_eq!(bare_total, 3, "⭐ 裸档实测 3 次（原登记 2）");
    assert_eq!(bare_files, 3, "⭐ 裸档实测 3 文件（原登记 2）");
    assert_eq!(prefixed_total, 47, "⭐ 前缀档实测 47 次（原登记 47，✓）");
    assert_eq!(
        prefixed_files, 30,
        "⭐ 前缀档实测 30 文件（原登记 32 ⇒ ⛔ 复现不出）"
    );
    assert_eq!(substring_total, 50, "⭐ 家族子串实测 50 次（原登记 49）");
    assert_eq!(substring_files, 33, "⭐ 家族子串实测 33 文件（原登记 32）");
    assert_eq!(
        bare_total + prefixed_total,
        substring_total,
        "⭐ 家族子串 ＝ 裸 ＋ 前缀（口径自洽）"
    );
    assert_eq!(
        bare.get("volume_oncc24").copied(),
        Some(2),
        "⭐ 裸档逐名：`volume_oncc24` 2 次"
    );
    assert_eq!(
        bare.get("volume_oncc$F2_DIS").copied(),
        Some(1),
        "⭐ 裸档逐名：`volume_oncc$F2_DIS` 1 次（宏名形式 —— 按裁定算本族）"
    );
    assert!(
        bare.keys().all(|name| name.starts_with("volume_oncc")),
        "⭐⭐ **有牙**：裸档里的名字必须**全部**以 `volume_oncc` 开头 ⇒ \
         谁把 `lfo*_volume_onccN` 的行数**再算成本族**，这一条与 `bare_total == 3` 至少一条会红\
         （实测裸档名字 = {:?}）",
        bare.keys().collect::<Vec<_>>()
    );
    assert!(
        prefixed
            .keys()
            .all(|name| name.starts_with("lfo") && name.contains("_volume_oncc")),
        "⭐ 前缀档实测**全是** `lfo*_volume_onccN`（9 个名字），实测 = {:?}",
        prefixed.keys().collect::<Vec<_>>()
    );
    assert!(
        !prefixed.keys().any(|name| name.starts_with("global_volume")
            || name.starts_with("master_volume")
            || name.starts_with("group_volume")),
        "⭐⭐ `global_volume_onccN` ／ `master_volume_onccN` ／ `group_volume_onccN` \
         实测**各 0 次 ／ 0 文件** ⇒ ⛔ 一个都不许出现在前缀档里"
    );
    assert_eq!(
        prefixed.len(),
        9,
        "⭐ 第 287 条：前缀族共 9 个完整 opcode 名"
    );
    assert_eq!(
        bare.len() + prefixed.len(),
        11,
        "⭐ 第 287 条：家族子串共 11 个完整 opcode 名（9 个 `lfo*` ＋ 2 个裸）"
    );

    // ⭐ 引擎侧修订段的**逐名表**必须与本判据**现算**出来的表**逐字相同**
    // （⛔ 不手抄：期望串就是从这次重算生成的）。
    let mut all_names = prefixed.clone();
    all_names.extend(bare.clone());
    let expected_enumeration = ordered(&all_names)
        .iter()
        .map(|(name, count, files)| format!("`{name}` = {count}／{files}"))
        .collect::<Vec<_>>()
        .join("、");
    assert!(
        ENGINE_SOURCE.contains(&expected_enumeration),
        "⭐⭐ 引擎侧 `#121` 修订段的逐名表必须与就地重算逐字相同：{expected_enumeration}"
    );
    println!("[engine-sfz/S115] ② 逐名表与引擎侧修订段逐字相同：{expected_enumeration}");

    // ---- ③ `#120`：**规范无 Modulation 表** 的依据 ＋ 反向腿（段内不许出现欠账话术） ----
    const SCOPE_MARK: &str = "### 8.5 ⭐ 作用域音量三 opcode（任务单 `#120`）";
    const SCOPE_END: &str = "\n//! # 实时安全";
    let scope_start = MODULATION_SOURCE
        .find(SCOPE_MARK)
        .expect("⭐ `#120` 的 §8.5 登记必须存在");
    let tail = &MODULATION_SOURCE[scope_start..];
    let scope_end = tail
        .find(SCOPE_END)
        .expect("⭐ §8.5 之后必须仍有 `# 实时安全` 一节（段边界可判）");
    let scope = &tail[..scope_end];
    assert!(
        scope.contains("**规范无 Modulation 表**"),
        "⭐⭐ `#120` 的依据必须逐字写「规范无 Modulation 表」"
    );
    assert!(
        scope.contains("无任何 `_onccN` 行") && scope.contains("**三页各只有一张表**"),
        "⭐ 依据必须是「三页各只有一张表 ＋ 无任何 `_onccN` 行」（⛔ 不是「规范有」）"
    );
    for needle in [
        "https://sfzformat.com/opcodes/global_volume/",
        "https://sfzformat.com/opcodes/master_volume/",
        "https://sfzformat.com/opcodes/group_volume/",
        "| global_volume | ARIA | float | 0 | -144 to 6 | dB |",
        "| master_volume | ARIA | float | 0 | -144 to 6 | dB |",
        "| group_volume | ARIA | float | 0 | -144 to 6 | dB |",
        "Scopes::get",
        "crates/yeban-sfz/src/instrument.rs:1550-1555",
        "**需要新面**",
        "header",
    ] {
        assert!(scope.contains(needle), "⭐ §8.5 必须逐字含：`{needle}`");
    }
    assert!(
        !scope.contains("规范有"),
        "⭐⭐ **反向腿**：`#120` 的依据⛔ 不许写成「规范有」（那是「欠着活儿」的框）"
    );
    assert!(
        !scope.contains("另开单") && !scope.contains("本单不做"),
        "⭐ **反向腿**：`#120` ⛔ 不许登记成「另开单」／「本单不做」式的欠账 ⇒ 只能是「规范无 ＋ 需要新面」"
    );
    assert!(
        MODULATION_SOURCE.contains("另开单"),
        "⭐ **非真空**：整份模块文档里确实有「另开单」（§8.4 的原文）⇒ 上面那条段内反向腿不是恒真"
    );
    println!(
        "[engine-sfz/S115] ③ `#120`：§8.5 「规范无 Modulation 表」＋ 三页各一张表 ＋ \
         `Scopes::get` 扁平 first-match ⇒ **需要新面**；段内反向腿（规范有／另开单／本单不做）全 false"
    );

    // ---- ④ 测试文件侧的机械针：S114 那一行与夹具文档的修订 ＋ 原句仍在 ----
    // ⚠ 这里的判据读的是**本文件自己** ⇒ 期望串在运行期拼出来（R84：⛔ 不把期望字面量
    //   直接写进 `contains` 实参 —— 否则判据读的正是它自己、恒真）。
    let row_revision_mark = concat!("⭐ `#121` 修订：本行 ① 的", "语料四口径里");
    assert!(
        SELF_SOURCE.contains(row_revision_mark),
        "⭐ `S114` 那一行的四口径必须带 `#121` 修订（原句仍在该行里）"
    );
    let row_original_mark = concat!(
        "家族子串 **49**／**32**、`global_volume",
        "_onccN` **47**／**32**"
    );
    assert!(
        SELF_SOURCE.contains(row_original_mark),
        "⛔ `S114` 那一行的四个原登记读数必须一字未删"
    );
    let fixture_revision_mark = concat!(
        "⭐ ⭐ **追加修订段（任务单 `#121`，",
        "⛔ 上面原文一字未删）**"
    );
    assert!(
        SELF_SOURCE.contains(fixture_revision_mark),
        "⭐ `VOLUME_FORMS_FIXTURE` 的文档必须带 `#121` 修订段"
    );
    assert!(
        SELF_SOURCE.contains(concat!("（`global_volume` 的调制，语料 47 ", "处）")),
        "⛔ 夹具文档的原句必须一字未删"
    );

    // ---- ⑤ `S114` 的反向腿 ＋ 三个承重指纹：字面量仍在（真值由 `S114` 现跑） ----
    let absent_literal = concat!("`volume_oncc*` 那一项仍未做", "（另开单）");
    assert!(
        SELF_SOURCE.contains(absent_literal),
        "⭐⭐ `S114` 的 `ABSENT` 反向腿字面量必须**一字未动**"
    );
    assert!(
        SELF_SOURCE.contains(concat!("必须被忽略", "而不是报错"))
            && SELF_SOURCE.contains("不进调制表（本单不做、登记在案）"),
        "⭐⭐ `S114` 的「必须被忽略」断言必须一字未动"
    );
    for prefix in [
        "global_volume_oncc",
        "master_volume_oncc",
        "group_volume_oncc",
    ] {
        let quoted = format!("\"{prefix}1\",");
        assert!(
            SELF_SOURCE.contains(&quoted),
            "⭐ `S114` 的负向表必须仍逐字列出 `{prefix}1`"
        );
    }
    for fingerprint in ["a9dec8a87f69106c", "d3c2a82076bd8947", "a933ddab286bdf5e"] {
        let quoted = format!("0x{fingerprint}");
        assert!(
            SELF_SOURCE.contains(&quoted),
            "⭐ 承重指纹必须逐字仍在（真值由 `S114` 现跑）：{quoted}"
        );
    }

    // ---- ⑥ 尺寸（`size_of` 现读）：本单只改文档 ＋ 计数 ⇒ 四个全 ＋0 ----
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S115] ⑥ size_of: PreparedRegion={region} SfzVoice={voice} \
         SfzVoicePool={pool} EngineRuntime={runtime}（门槛 192 KiB = {}）",
        192 * 1024
    );
    assert_eq!(
        (region, voice, pool, runtime),
        (6160, 40, 1712, 180_144),
        "⛔ `#121` 只改文档 ＋ 计数 ⇒ 四个尺寸读数全 ＋0"
    );
}

// ---------------------------------------------------------------------------
// ⭐⭐ 任务单 `#123`：`ampeg_attack` 三档计数的**口径**（就地重算 ＋ 矩阵 ＋ 展开档）
// ---------------------------------------------------------------------------

/// ⭐⭐ S116（任务单 `#123`；台账第 274／278／289 条）：**`ampeg_attack` 三档计数的口径
/// 就地可判 ＋ 口径矩阵（≥6 档）＋ `#include` 展开档 ＋ 反向腿与三个承重指纹＋四个尺寸**。
///
/// # 三档口径（与 `crates/yeban-engine/src/sfz_instrument.rs` 的 `#123` 修订段**逐字同一口径**）
///
/// * ① **家族子串** ＝ 裸子串 `ampeg_attack`，**任意位置**、**⛔ 不剥注释**、大小写敏感；
/// * ② **不剥注释 token** ＝ `\bampeg_attack\b\s*=`（左边界 ＝ 行首或**任一非
///   `[A-Za-z0-9_]` 字节**，⭐ 含 `/`）、**⛔ 不剥注释**；
/// * ③ **剥注释 token** ＝ 同 ②，但每行先截掉 `//` 到行尾。
///
/// # 量什么（对象 ＋ 单位，先说再跑）
///
/// 对象 ＝ ① 三档的**匹配次数 ／ 含匹配的文件数**（分母 ＝ `assets/samples/**/*.sfz`
/// **1398** 份）；② 六档以上口径矩阵的每一格；③ `#include` **展开后**的两档（解析器尺）；
/// ④ 三个承重 `FNV-1a 64` 指纹与 `× 1.0000001` 的反向腿；⑤ `size_of` 四个读数（**字节**）。
#[test]
fn s116_the_ampeg_attack_three_tiers_name_their_caliber() {
    use std::collections::BTreeMap;
    use yeban_sfz::{IncludeResolver, ParseLimits};

    const ENGINE_SOURCE: &str = include_str!("../src/sfz_instrument.rs");

    /// ⭐ 左边界用的"词字节"：`\b` 在 Rust 正则里的含义（字母 / 数字 / `_`）。
    fn is_token_byte(byte: u8) -> bool {
        byte.is_ascii_alphanumeric() || byte == b'_'
    }

    /// 数**一行**里的 `\bampeg_attack\b\s*=`（左边界 ＝ 行首或任一非词字节，⭐ 含 `/`）。
    fn token_hits_in_line(line: &str) -> usize {
        let bytes = line.as_bytes();
        let needle = b"ampeg_attack";
        let mut hits = 0usize;
        let mut cursor = 0usize;
        while cursor + needle.len() <= bytes.len() {
            if &bytes[cursor..cursor + needle.len()] == needle {
                let left_ok = cursor == 0 || !is_token_byte(bytes[cursor - 1]);
                let right = cursor + needle.len();
                let right_ok = right >= bytes.len() || !is_token_byte(bytes[right]);
                if left_ok && right_ok {
                    let mut probe = right;
                    while probe < bytes.len() && bytes[probe].is_ascii_whitespace() {
                        probe += 1;
                    }
                    if probe < bytes.len() && bytes[probe] == b'=' {
                        hits += 1;
                    }
                }
                cursor += needle.len();
            } else {
                cursor += 1;
            }
        }
        hits
    }

    /// 数**一行**里的 `(^|\s)ampeg_attack\s*=`（⭐ 左边界**只收行首与空白** —— 这正是
    /// `#122` 用的那一档，它把 `//ampeg_attack=0.001` 挡在门外）。
    fn token_hits_whitespace_boundary(line: &str) -> usize {
        let bytes = line.as_bytes();
        let needle = b"ampeg_attack";
        let mut hits = 0usize;
        let mut cursor = 0usize;
        while cursor + needle.len() <= bytes.len() {
            if &bytes[cursor..cursor + needle.len()] == needle {
                let left_ok = cursor == 0 || bytes[cursor - 1].is_ascii_whitespace();
                if left_ok {
                    let mut probe = cursor + needle.len();
                    while probe < bytes.len() && bytes[probe].is_ascii_whitespace() {
                        probe += 1;
                    }
                    if probe < bytes.len() && bytes[probe] == b'=' {
                        hits += 1;
                    }
                }
                cursor += needle.len();
            } else {
                cursor += 1;
            }
        }
        hits
    }

    /// 剥掉 `/* */` 块注释（⭐ 语料里一个都没有 ⇒ 读数与只剥 `//` 的那一档同值）。
    fn strip_c_comments(text: &str) -> String {
        let mut out = String::with_capacity(text.len());
        let mut rest = text;
        while let Some(start) = rest.find("/*") {
            out.push_str(&rest[..start]);
            match rest[start + 2..].find("*/") {
                Some(end) => rest = &rest[start + 2 + end + 2..],
                None => rest = "",
            }
        }
        out.push_str(rest);
        out
    }

    // ---- ① 修订段与三档口径行必须逐字可判（台账第 278 条：原句仍在 ＋ 修订段点名被修订的支） ----
    let checks = [
        ("`#123` 追加修订段", "⭐ ⭐ **追加修订段（任务单 `#123`）"),
        (
            "`#123` 新一节",
            "# ⭐⭐ `ampeg_attack` 三档计数的**口径**（任务单 `#123`）",
        ),
        ("被修订的支①（`#113` 那一行）", "① `#113` 节语料表里"),
        (
            "被修订的支②③（两行「三档对照」）",
            "节语料表里「三档对照（`ampeg_attack`）",
        ),
        ("被修订的支④（`#112` 那一格）", "④ `#112` 节语料表里"),
        ("① 家族子串的口径行", "| ① 家族**子串** |"),
        ("② 不剥注释 token 的口径行", "| ② **不剥注释** token |"),
        ("③ 剥注释 token 的口径行", "| ③ **剥注释** token |"),
        ("原句仍在：家族子串", "家族子串 **2828**"),
        ("原句仍在：不剥注释 token 的值", "**844**"),
        ("原句仍在：剥注释 token 的值", "剥注释 token 835"),
        ("②−③ 那 9 行的左边界成因", "`(^|\\s)` 型左边界**不收**它"),
        ("9 行的逐文件逐行号钉住", "`snaremic_basic` :63"),
        ("矩阵第 ④ 档（`#122` 的 2819）", "**2819**"),
        ("矩阵第 ⑤ 档（空白左边界）", "| ⑤ |"),
        ("矩阵第 ⑥⑦ 档（`#include` 展开）", "| ⑥ |"),
        ("矩阵第 ⑧ 档（宏名 / 跨行）", "| ⑧ |"),
        ("第 ⑧ 档的口径陷阱读数", "**2786**"),
        ("口径陷阱的成因（`//****` 横幅）", "分隔横幅"),
        ("`#include` 展开档的尺子", "第 ⑥⑦ 档的尺子"),
        ("单位警告（次数 ≠ 行数）", "**匹配次数**与"),
        ("跨单可比性的口径声明句", "本台账的 `ampeg_attack` 三档口径"),
        (
            "点名 `#122` 换错了两档",
            "`#122` 的两把尺子各自**换错了一档**",
        ),
    ];
    let check_count = checks.len();
    for (label, needle) in checks {
        assert!(
            ENGINE_SOURCE.contains(needle),
            "⭐ 必须逐字含：{label}（`{needle}`）"
        );
    }
    assert!(
        !ENGINE_SOURCE.contains("844 与 2828 都复现不出"),
        "⭐ **有牙反向腿**：模块头里**没有**的句子必须 `contains == false`（否则判据恒真）"
    );
    println!(
        "[engine-sfz/S116] ① 模块头：`#123` 修订段 ＋ 新一节 ＋ 三档口径行 ＋ {check_count} 条逐字针 —— 全部命中"
    );

    // ---- ② 分母 / 文件集合（对象 ＝ 文件数） ----
    let corpus_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets/samples");
    let mut all_files: Vec<std::path::PathBuf> = Vec::new();
    let mut stack = vec![corpus_root.clone()];
    while let Some(dir) = stack.pop() {
        let entries = std::fs::read_dir(&dir)
            .unwrap_or_else(|error| panic!("⭐ 语料目录 {dir:?} 必须存在：{error}"));
        for entry in entries {
            let path = entry.expect("目录项").path();
            if path.is_dir() {
                stack.push(path);
            } else {
                all_files.push(path);
            }
        }
    }
    all_files.sort();
    let paths: Vec<std::path::PathBuf> = all_files
        .iter()
        .filter(|path| path.extension().and_then(|e| e.to_str()) == Some("sfz"))
        .cloned()
        .collect();
    let sfzh = all_files
        .iter()
        .filter(|path| path.extension().and_then(|e| e.to_str()) == Some("sfzh"))
        .count();
    let upper = all_files
        .iter()
        .filter(|path| {
            path.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.ends_with(".SFZ") || n.ends_with(".Sfz"))
        })
        .count();
    println!(
        "[engine-sfz/S116] ② 文件集合：`assets/samples/**` 下 {} 个文件，其中 `.sfz` **{}** 份、\
         `.sfzh` **{sfzh}** 份、大写扩展名 **{upper}** 份",
        all_files.len(),
        paths.len()
    );
    assert_eq!(
        paths.len(),
        1398,
        "⭐ 分母必须 = `find assets/samples -name '*.sfz' | wc -l` = 1398"
    );
    assert_eq!(
        sfzh, 0,
        "⭐ 本仓 `assets/samples/**` 下没有 `.sfzh` ⇒ 扩展名集合不产生差别"
    );
    assert_eq!(
        upper, 0,
        "⭐ 本仓 `assets/samples/**` 下没有大写 `.SFZ` 扩展名"
    );
    let repo_root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let mut elsewhere: Vec<std::path::PathBuf> = Vec::new();
    for sub in ["crates", "spikes"] {
        let mut stack = vec![repo_root.join(sub)];
        while let Some(dir) = stack.pop() {
            let Ok(entries) = std::fs::read_dir(&dir) else {
                continue;
            };
            for entry in entries {
                let path = entry.expect("目录项").path();
                if path.is_dir() {
                    stack.push(path);
                } else if let Some(ext) = path.extension().and_then(|e| e.to_str())
                    && (ext.eq_ignore_ascii_case("sfz") || ext.eq_ignore_ascii_case("sfzh"))
                {
                    elsewhere.push(path);
                }
            }
        }
    }
    assert!(
        elsewhere.is_empty(),
        "⭐ `crates/**` 与 `spikes/**` 下必须 **0** 个 `.sfz`／`.sfzh`（实测 {elsewhere:?}）\
         ⇒ 「文件集合」这一档在本仓只剩 `assets/samples/**` 一种选择"
    );

    // ---- ③ 就地重算三档 ＋ 口径矩阵（每格都现算） ----
    let mut substring_raw = 0usize;
    let mut substring_raw_files = 0usize;
    let mut substring_stripped = 0usize;
    let mut substring_stripped_files = 0usize;
    let mut token_raw = 0usize;
    let mut token_raw_files = 0usize;
    let mut token_stripped = 0usize;
    let mut token_stripped_files = 0usize;
    let mut token_ws_raw = 0usize;
    let mut token_ws_raw_files = 0usize;
    let mut token_ws_stripped = 0usize;
    let mut token_ws_stripped_files = 0usize;
    let mut c_comment_substring = 0usize;
    let mut c_comment_substring_files = 0usize;
    let mut ci_substring = 0usize;
    let mut ci_token = 0usize;
    let mut macro_name = 0usize;
    let mut cross_line = 0usize;
    let mut hit_lines_raw = 0usize;
    let mut comment_only: BTreeMap<String, Vec<usize>> = BTreeMap::new();

    for path in &paths {
        let text = std::fs::read_to_string(path)
            .unwrap_or_else(|error| panic!("⭐ 读 {path:?} 失败：{error}"));
        let relative = path
            .strip_prefix(&corpus_root)
            .expect("⭐ 语料根")
            .to_string_lossy()
            .replace('\\', "/");
        let stripped: String = text
            .split('\n')
            .map(|line| line.split("//").next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        let lowered = text.to_lowercase();

        let raw_hits = text.matches("ampeg_attack").count();
        substring_raw += raw_hits;
        if raw_hits > 0 {
            substring_raw_files += 1;
        }
        let stripped_hits = stripped.matches("ampeg_attack").count();
        substring_stripped += stripped_hits;
        if stripped_hits > 0 {
            substring_stripped_files += 1;
        }
        let c_hits = strip_c_comments(&text).matches("ampeg_attack").count();
        c_comment_substring += c_hits;
        if c_hits > 0 {
            c_comment_substring_files += 1;
        }
        ci_substring += lowered.matches("ampeg_attack").count();
        ci_token += lowered.split('\n').map(token_hits_in_line).sum::<usize>();
        macro_name += text.matches("ampeg_attack$").count();

        let mut file_token_raw = 0usize;
        let mut file_token_stripped = 0usize;
        let mut file_ws_raw = 0usize;
        let mut file_ws_stripped = 0usize;
        let lines: Vec<&str> = text.split('\n').collect();
        for (index, raw_line) in lines.iter().enumerate() {
            let code = raw_line.split("//").next().unwrap_or("");
            let with_comments = token_hits_in_line(raw_line);
            let without_comments = token_hits_in_line(code);
            file_token_raw += with_comments;
            file_token_stripped += without_comments;
            file_ws_raw += token_hits_whitespace_boundary(raw_line);
            file_ws_stripped += token_hits_whitespace_boundary(code);
            if with_comments > without_comments {
                comment_only
                    .entry(relative.clone())
                    .or_default()
                    .push(index + 1);
            }
            if raw_line.contains("ampeg_attack") {
                hit_lines_raw += 1;
            }
        }
        token_raw += file_token_raw;
        if file_token_raw > 0 {
            token_raw_files += 1;
        }
        token_stripped += file_token_stripped;
        if file_token_stripped > 0 {
            token_stripped_files += 1;
        }
        token_ws_raw += file_ws_raw;
        if file_ws_raw > 0 {
            token_ws_raw_files += 1;
        }
        token_ws_stripped += file_ws_stripped;
        if file_ws_stripped > 0 {
            token_ws_stripped_files += 1;
        }
        for pair in lines.windows(2) {
            if pair[0].trim_end().ends_with("ampeg_attack") && pair[1].trim_start().starts_with('=')
            {
                cross_line += 1;
            }
        }
    }

    println!(
        "[engine-sfz/S116] ① 家族子串（裸子串 `ampeg_attack`、任意位置、⛔ 不剥注释、\
         大小写敏感）：{substring_raw} 次 ／ {substring_raw_files} 文件（分母 {} 份 `.sfz`）",
        paths.len()
    );
    println!(
        "[engine-sfz/S116] ② 不剥注释 token（左边界 `\\b` ＝ 行首或任一非 `[A-Za-z0-9_]` 字节，\
         ⛔ 不剥注释）：{token_raw} 次 ／ {token_raw_files} 文件"
    );
    println!(
        "[engine-sfz/S116] ③ 剥注释 token（同 ②，每行先截掉 `//`）：{token_stripped} 次 ／ \
         {token_stripped_files} 文件"
    );
    assert_eq!(
        (substring_raw, substring_raw_files),
        (2828, 368),
        "⭐ ① 家族子串（⛔ 不剥注释）＝ 2828 次 ／ 368 文件"
    );
    assert_eq!(
        (token_raw, token_raw_files),
        (844, 318),
        "⭐ ② 不剥注释 token ＝ 844 次 ／ 318 文件"
    );
    assert_eq!(
        (token_stripped, token_stripped_files),
        (835, 310),
        "⭐ ③ 剥注释 token ＝ 835 次 ／ 310 文件"
    );

    // ---- ④ 口径矩阵第 ④⑤⑧ 档（⭐ 每格都现算） ----
    println!(
        "[engine-sfz/S116] ④ 子串、剥 `//` 注释（⭐ `#122` 勘察到的那个数就是这一档）：\
         {substring_stripped} 次 ／ {substring_stripped_files} 文件"
    );
    assert_eq!(
        (substring_stripped, substring_stripped_files),
        (2819, 360),
        "⭐ ④ 剥注释子串 ＝ 2819 次 ／ 360 文件（⛔ 不是登记口径）"
    );
    println!(
        "[engine-sfz/S116] ⑤ token、左边界 `(^|\\s)`（行首或空白）：⛔ 不剥注释 {token_ws_raw} 次 ／ \
         {token_ws_raw_files} 文件；剥注释 {token_ws_stripped} 次 ／ {token_ws_stripped_files} 文件"
    );
    assert_eq!(
        (token_ws_raw, token_ws_raw_files),
        (835, 310),
        "⭐ ⑤ 空白左边界档：`//ampeg_attack=0.001` **被挡住** ⇒ 不剥注释也只得 835"
    );
    assert_eq!(
        token_ws_raw, token_ws_stripped,
        "⭐ ⑤ 左边界只收空白 ⇒ 「剥／不剥注释」两档**同值**（这正是 `#122` 复现不出 844 的原因）"
    );
    println!(
        "[engine-sfz/S116] ⑧ 宏名位 `ampeg_attack$VAR=`：{macro_name} 处；跨行\
         （`ampeg_attack` 换行后再 `=`）：{cross_line} 处；大小写不敏感子串：{ci_substring} 次、\
         token：{ci_token} 次；⚠ 也剥 `/* */`（**陷阱档**）：{c_comment_substring} 次 ／ \
         {c_comment_substring_files} 文件"
    );
    assert_eq!(
        macro_name, 0,
        "⭐ ⑧ 语料里没有 `ampeg_attack$VAR=` 形式的宏名 opcode"
    );
    assert_eq!(
        cross_line, 0,
        "⭐ ⑧ 语料里没有跨行的 `ampeg_attack` 换行 `=`"
    );
    assert_eq!(ci_substring, substring_raw, "⭐ ⑧ 语料里没有其它大小写拼写");
    assert_eq!(ci_token, token_raw, "⭐ ⑧ 语料里没有其它大小写拼写");
    assert_eq!(
        (c_comment_substring, c_comment_substring_files),
        (2786, 359),
        "⚠ ⑧ **口径陷阱**：SFZ **没有**块注释语法（解析器只认 `//`）—— 语料里那 **18** 处 `/*` \
         字节**全部**落在 `//****…` 分隔横幅里；一个**不容错**（找不到 `*/` 就一直剥到文末）的\
         天真剥法会在 **9** 个文件里把整份文件吞掉（共丢 **42** 处 ＝ 2828 − 2786）\
         ⇒ ⛔ 本档不是三档的候选，登记它只为点名这个会静默改读数的坑"
    );
    assert_eq!(
        hit_lines_raw, substring_raw,
        "⚠ 单位警告（台账第 271／274 条）：本仓 `ampeg_attack` 的**匹配次数**与**命中行数**\
         偶然同值（各 {hit_lines_raw}）⇒ ⛔ 两个单位不可互换，登记一律用「次数 ／ 文件数」"
    );

    // ---- ⑤ ②−③ 的 9 行：逐文件逐行号钉住 ----
    let comment_only_lines: usize = comment_only.values().map(Vec::len).sum();
    println!(
        "[engine-sfz/S116] ②−③ 的差额逐文件逐行：{comment_only_lines} 行 ／ {} 文件",
        comment_only.len()
    );
    for (file, lines) in &comment_only {
        println!("[engine-sfz/S116]   ②−③：{file}:{lines:?}（内容 `//ampeg_attack=0.001`）");
    }
    assert_eq!(
        token_raw - token_stripped,
        9,
        "⭐ ②−③ 必须恰为 9（同一批 9 行注释里的 opcode 文本）"
    );
    assert_eq!(comment_only_lines, 9, "⭐ 那 9 行必须逐行可判");
    assert_eq!(
        comment_only.len(),
        9,
        "⭐ 那 9 行分布在 **9** 个文件（`virtuosity-drums/Programs/mappings/`）里"
    );
    for name in [
        "kickmic_all.sfz",
        "kickmic_basic.sfz",
        "lofi_all.sfz",
        "mid_all.sfz",
        "oh_all.sfz",
        "oh_basic.sfz",
        "room_all.sfz",
        "snaremic_all.sfz",
        "snaremic_basic.sfz",
    ] {
        let key = format!("virtuosity-drums/Programs/mappings/{name}");
        assert_eq!(
            comment_only.get(&key).map(Vec::len),
            Some(1),
            "⭐ `{key}` 必须恰有 **1** 行注释里的 opcode 文本"
        );
    }
    assert_eq!(
        token_raw_files - token_stripped_files,
        8,
        "⭐ 有 **8** 个文件**只**在注释里出现本 token（第 9 个 `oh_all.sfz` 另有正文命中）"
    );

    // ---- ⑥ `#include` 展开档（解析器尺） ----
    let limits = ParseLimits::default();
    let mut expanded_substring = 0usize;
    let mut expanded_substring_files = 0usize;
    let mut expanded_token = 0usize;
    let mut expanded_token_files = 0usize;
    let (mut resolved_ok, mut resolve_err, mut parse_err) = (0usize, 0usize, 0usize);
    for path in &paths {
        let parent = path.parent().expect("⭐ 父目录");
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .expect("⭐ 文件名");
        let Ok(resolver) = IncludeResolver::new(parent, limits) else {
            resolve_err += 1;
            continue;
        };
        match resolver.resolve(name) {
            Ok(sources) => {
                resolved_ok += 1;
                let text: String = sources
                    .iter()
                    .map(|source| source.text.as_str())
                    .collect::<Vec<_>>()
                    .join("\n");
                let hits = text.matches("ampeg_attack").count();
                expanded_substring += hits;
                if hits > 0 {
                    expanded_substring_files += 1;
                }
                let tokens: usize = text.split('\n').map(token_hits_in_line).sum();
                expanded_token += tokens;
                if tokens > 0 {
                    expanded_token_files += 1;
                }
                if yeban_sfz::parse_sources(&sources, &limits).is_err() {
                    parse_err += 1;
                }
            }
            Err(_) => resolve_err += 1,
        }
    }
    println!(
        "[engine-sfz/S116] ⑥⑦ `#include` 展开档（解析器尺：`IncludeResolver::resolve` ＋ \
         `SfzSource::text` 顺序拼接）：resolve 成功 {resolved_ok} ／ include 解析失败 \
         {resolve_err} ／ 其中 `parse_sources` 报错 {parse_err}"
    );
    println!(
        "[engine-sfz/S116] ⑥ 展开后**子串**（⛔ 不剥注释）：{expanded_substring} 次 ／ \
         {expanded_substring_files} 文件"
    );
    println!(
        "[engine-sfz/S116] ⑦ 展开后 **token**（左边界 `\\b`，⛔ 不剥注释）：{expanded_token} 次 ／ \
         {expanded_token_files} 文件"
    );
    assert_eq!(
        resolve_err, 107,
        "⭐ include 解析失败数必须与 `yeban-sfz/src/control.rs` 登记的 **107** 逐字一致"
    );
    assert_eq!(
        (expanded_substring, expanded_substring_files),
        (5144, 353),
        "⭐ ⑥ `#include` 展开后的子串 ＝ 5144 次 ／ 353 文件"
    );
    assert_eq!(
        (expanded_token, expanded_token_files),
        (1000, 315),
        "⭐ ⑦ `#include` 展开后的 token ＝ 1000 次 ／ 315 文件"
    );
    assert!(
        expanded_substring > substring_raw,
        "⭐ 展开档会把被 include 的文件在每个引用它的根文件里**再数一遍** ⇒ 读数更大\
         （{expanded_substring} > {substring_raw}）⇒ ⛔ 展开**不是**三档的母体"
    );

    // ---- ⑦ 三个承重指纹 ＋ `× 1.0000001` 反向腿 ----
    let looped = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60 loop_mode=loop_continuous \
         loop_start=100 loop_end=164\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    let plain = prepare_with(
        "<region> sample=a.wav key=60 pitch_keycenter=60\n",
        &ramp_sample(LOOP_PCM_FRAMES),
    );
    for (label, plan, end_sample, expected) in [
        (
            "S37 loop_continuous ＋ end_sample = 200",
            &looped,
            200u64,
            0xa9de_c8a8_7f69_106cu64,
        ),
        (
            "S37 no_loop ＋ end_sample = u64::MAX",
            &plain,
            u64::MAX,
            0xd3c2_a820_76bd_8947u64,
        ),
    ] {
        let out = render_pool(plan, end_sample, BLOCK);
        let actual = fnv1a_64(&out);
        println!("[engine-sfz/S116] 承重指纹 {label}：0x{actual:016x}（承重 = 0x{expected:016x}）");
        let _checked = check_fingerprint(&format!("S116 {label}"), actual, expected);
    }
    let broadcast = prepare(TWO_MATCH_ONE_MISS);
    let mut legacy_block = vec![0.0f32; BLOCK];
    let legacy_frames = broadcast.render_block_into(60, 127, &mut legacy_block);
    let legacy = fnv1a_64(&legacy_block);
    println!(
        "[engine-sfz/S116] 承重指纹 S33／S14 广播路径 512 帧 @ (60,127)：0x{legacy:016x}\
         （承重 = 0x{NO_LOOP_FIXTURE_FINGERPRINT:016x}，写入 {legacy_frames} 帧）"
    );
    let _checked = check_fingerprint("S116 广播路径", legacy, NO_LOOP_FIXTURE_FINGERPRINT);
    let scaled: Vec<f32> = legacy_block
        .iter()
        .map(|sample| sample * 1.000_000_1)
        .collect();
    let scaled_hash = fnv1a_64(&scaled);
    println!(
        "[engine-sfz/S116] 反向腿（× 1.0000001）：0x{scaled_hash:016x} ≠ 0x{legacy:016x}\
         （广播路径写入 {legacy_frames} 帧）"
    );
    assert_ne!(
        scaled_hash, legacy,
        "⭐ 反向腿：乘 1.0000001 后指纹必须变（证明上面三条是逐位判据）"
    );

    // ---- ⑧ 尺寸（`size_of` 现读）：本单只改文档 ＋ 判据 ⇒ 四个全 ＋0 ----
    let region = core::mem::size_of::<PreparedRegion>();
    let voice = core::mem::size_of::<SfzVoice>();
    let pool = core::mem::size_of::<SfzVoicePool>();
    let runtime = core::mem::size_of::<yeban_engine::rt::EngineRuntime>();
    println!(
        "[engine-sfz/S116] ⑧ size_of: PreparedRegion={region} SfzVoice={voice} \
         SfzVoicePool={pool} EngineRuntime={runtime}（门槛 192 KiB = {}）",
        192 * 1024
    );
    assert_eq!(
        (region, voice, pool, runtime),
        (6160, 40, 1712, 180_144),
        "⛔ `#123` 只改文档 ＋ 判据 ⇒ 四个尺寸读数全 ＋0"
    );
}
